/**
 * Application bootstrap service
 */

import { authService } from '@domains/authentication/services/AuthenticationService';
import { initializeNetworkMonitor, cleanupNetworkMonitor } from '@infra/connection/networkMonitor';
import { initializeOptimisticUpdates } from '@infra/optimistic/optimisticUpdates';
import { initializeSocket, cleanupSocket } from '@infra/socket/SocketService';

import { BOOTSTRAP_STEPS } from './constants';

import type { AppBootstrapState, BootstrapStep } from './types';
import type { QueryClient } from '@tanstack/react-query';

export class AppBootstrapService {
  private state: AppBootstrapState = {
    isLoading: true,
    currentStep: 'initialization',
    error: null,
    steps: [...BOOTSTRAP_STEPS],
    flags: {
      firstTimeSetupRequired: false
    }
  };

  private listeners: Array<(state: AppBootstrapState) => void> = [];
  private isInitialized = false;

  subscribe(listener: (state: AppBootstrapState) => void): () => void {
    this.listeners.push(listener);
    return () => {
      const index = this.listeners.indexOf(listener);
      if (index > -1) {
        this.listeners.splice(index, 1);
      }
    };
  }

  getState(): AppBootstrapState {
    return { ...this.state };
  }

  private notify() {
    this.listeners.forEach(listener => listener(this.getState()));
  }

  private updateStep(step: BootstrapStep, completed: boolean, error?: string) {
    this.state.currentStep = step;
    const stepIndex = this.state.steps.findIndex(s => s.step === step);
    if (stepIndex !== -1) {
      this.state.steps[stepIndex] = {
        ...this.state.steps[stepIndex],
        completed,
        error
      };
    }
    if (error) {
      this.state.error = error;
      this.state.currentStep = 'error';
    }
    this.notify();
  }

  async bootstrap(queryClient: QueryClient): Promise<void> {
    // GUARD: Prevent duplicate bootstrap in React StrictMode
    if (this.isInitialized) {
      console.warn('[Bootstrap] Already initialized, skipping duplicate bootstrap');
      return;
    }

    try {
      this.state.isLoading = true;
      this.state.error = null;
      this.notify();

      // Initialize
      this.updateStep('initialization', false);
      await new Promise(resolve => setTimeout(resolve, 500));
      this.updateStep('initialization', true);

      // Check auth - detect first-time setup
      this.updateStep('auth-check', false);
      try {
        const isFirstTime = await authService.checkFirstTime();

        if (isFirstTime) {
          this.state.flags.firstTimeSetupRequired = true;
        } else {
          this.state.flags.firstTimeSetupRequired = false;
        }

        this.updateStep('auth-check', true);
      } catch (error) {
        console.error('❌ [Bootstrap] Auth check failed:', error);
        this.updateStep('auth-check', false, 'Failed to check authentication status');
        throw error;
      }

      // Initialize advanced real-time systems
      this.updateStep('socket-connection', false);
      try {
        // Initialize network monitoring first
        initializeNetworkMonitor(queryClient);

        // Initialize optimistic updates service
        initializeOptimisticUpdates(queryClient);

        // Initialize socket with React Query integration
        await initializeSocket(queryClient);

        this.updateStep('socket-connection', true);
      } catch (socketError) {
        console.error('❌ [Bootstrap] Real-time systems initialization failed:', socketError);
        this.updateStep('socket-connection', false, 'Failed to initialize real-time systems');
        throw socketError;
      }

      // TEMPORARILY DISABLED: Cache warming needs refactoring
      // See AGENTS.md "Known Issues" section for details
      // TODO: Refactor to use domain services instead of raw fetch()
      this.updateStep('data-loading', false);
      this.updateStep('data-loading', true);
      
      /* DISABLED - Needs refactoring to use httpClient and domain services
      try {
        console.log('🔥 [Bootstrap] Starting intelligent cache warming');
        await initializeCacheWarming(queryClient);
        console.log('[Bootstrap] Cache warming completed');
        this.updateStep('data-loading', true);
      } catch (warmingError) {
        console.warn('⚠️ [Bootstrap] Cache warming failed, continuing without prefetch:', warmingError);
        this.updateStep('data-loading', true);
      }
      */

      // Complete
      this.updateStep('complete', true);
      this.state.isLoading = false;
      this.isInitialized = true;
      this.notify();

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Bootstrap failed';
      this.updateStep('error', false, errorMessage);
      this.state.isLoading = false;
      this.isInitialized = false; // Allow retry after error
    }
  }

  /**
   * Cleanup resources on app shutdown
   */
  public cleanup(): void {
    cleanupSocket();
    cleanupNetworkMonitor();
    this.isInitialized = false; // Allow re-initialization after cleanup
  }

  retry(queryClient: QueryClient): void {
    this.state.steps = this.state.steps.map(step => ({
      ...step,
      completed: false,
      error: undefined
    }));

    this.isInitialized = false; // Reset flag to allow retry
    void this.bootstrap(queryClient);
  }
}

export const appBootstrapService = new AppBootstrapService();

/**
 * Application bootstrap constants
 */
import type { BootstrapStepInfo } from './types';

export const BOOTSTRAP_STEPS: BootstrapStepInfo[] = [
  {
    step: 'initialization',
    label: 'Initializing Application',
    completed: false
  },
  {
    step: 'auth-check',
    label: 'Checking Authentication',
    completed: false
  },
  {
    step: 'socket-connection',
    label: 'Connecting to Server',
    completed: false
  },
  {
    step: 'data-loading',
    label: 'Loading Data',
    completed: false
  },
  {
    step: 'complete',
    label: 'Ready',
    completed: false
  }
];

export const BOOTSTRAP_TIMEOUT = 30000; // 30 seconds

/**
 * Loading messages for each bootstrap step
 */
export const LOADING_MESSAGES = {
  initialization: 'Initializing Application',
  'auth-check': 'Checking Authentication',
  'socket-connection': 'Connecting to Server',
  'data-loading': 'Loading Data',
  complete: 'Ready'
} as const;

/**
 * App Bootstrap Module
 * 
 * Modern, industry-standard bootstrap system for application initialization
 */

// Core service
export { AppBootstrapService, appBootstrapService } from './AppBootstrapService';

// React hooks
export { 
  useAppBootstrap, 
  useAppReady,
} from './useAppBootstrap';

// Types
export type {
  AppBootstrapState,
  BootstrapStep,
  BootstrapStepInfo,
  BootstrapError,
  UseAppBootstrapResult,
  UseAppBootstrapReturn,
} from './types';

// Constants
export { BOOTSTRAP_STEPS } from './constants';

/**
 * Application bootstrap types
 */

export interface AppBootstrapState {
  isLoading: boolean;
  currentStep: BootstrapStep;
  error: string | null;
  steps: BootstrapStepInfo[];
  flags: {
    firstTimeSetupRequired: boolean;
  };
}

export type BootstrapStep = 
  | 'initialization'
  | 'auth-check'
  | 'socket-connection'
  | 'data-loading'
  | 'complete'
  | 'error';

export interface BootstrapStepInfo {
  step: BootstrapStep;
  label: string;
  completed: boolean;
  error?: string;
}

export interface UseAppBootstrapReturn {
  isLoading: boolean;
  currentStep: BootstrapStep;
  error: string | null;
  steps: BootstrapStepInfo[];
  retry: () => void;
}

// Enhanced bootstrap error interface
export interface BootstrapError {
  message: string;
  step: BootstrapStep;
  code: string;
  retryable: boolean;
  details?: Record<string, any>;
}

// Bootstrap initialization result for detailed error handling
export interface BootstrapInitializationResult {
  completedSteps: BootstrapStep[];
  errors: BootstrapError[];
  isComplete: boolean;
  timestamp: Date;
}

// Modern interface used by the new hook
export interface UseAppBootstrapResult {
  isReady: boolean;
  isLoading: boolean;
  isError: boolean;
  error: string | BootstrapError | null;
  currentStep: BootstrapStep;
  context: string;
  state: 'initializing' | 'loading' | 'error' | 'retrying' | 'complete';
  progress: number;
  canRetry: boolean;
  completedSteps: BootstrapStep[];
  initializationResult: BootstrapInitializationResult | null;
  retry: () => void;
  flags: {
    firstTimeSetupRequired: boolean;
  };
}

/**
 * App Bootstrap Hook
 *
 * React hook for managing application initialization state.
 * Provides clean integration between bootstrap service and React components.
 */

import { useState, useEffect } from 'react';

import { useQueryClient } from '@tanstack/react-query';

import { appBootstrapService } from './AppBootstrapService';

import type { 
  AppBootstrapState,
  BootstrapStep,
  UseAppBootstrapResult,
  BootstrapInitializationResult,
  BootstrapError
} from './types';

// UseAppBootstrapResult is now defined in types.ts for centralized type management

/**
 * Main bootstrap hook for application initialization
 */
export function useAppBootstrap(): UseAppBootstrapResult {
  const queryClient = useQueryClient();
  const [bootstrapState, setBootstrapState] = useState<AppBootstrapState>(
    appBootstrapService.getState()
  );

  useEffect(() => {
    // Subscribe to bootstrap state changes
    const unsubscribe = appBootstrapService.subscribe(setBootstrapState);
    
    // Start bootstrap process if not already started
    if (bootstrapState.currentStep === 'initialization' && bootstrapState.isLoading) {
      void appBootstrapService.bootstrap(queryClient);
    }

    return unsubscribe;
  }, [queryClient, bootstrapState.currentStep, bootstrapState.isLoading]);

  // Generate context message for loading screen
  const getContextMessage = (step: BootstrapStep): string => {
    switch (step) {
      case 'initialization':
        return 'Initializing application...';
      case 'auth-check':
        return 'Checking authentication...';
      case 'socket-connection':
        return 'Establishing real-time connection...';
      case 'data-loading':
        return 'Loading workspace data...';
      case 'complete':
        return 'Ready!';
      case 'error':
        return bootstrapState.error ?? 'Initialization failed';
      default:
        return 'Starting up...';
    }
  };

  // Calculate progress based on completed steps
  const stepOrder: BootstrapStep[] = ['initialization', 'auth-check', 'socket-connection', 'data-loading', 'complete'];
  const currentStepIndex = stepOrder.indexOf(bootstrapState.currentStep);
  const progress = currentStepIndex >= 0 ? Math.round((currentStepIndex / (stepOrder.length - 1)) * 100) : 0;
  
  // Get completed steps
  const completedSteps = bootstrapState.steps
    .filter(step => step.completed)
    .map(step => step.step);

  // Determine overall state
  const getOverallState = (): 'initializing' | 'loading' | 'error' | 'retrying' | 'complete' => {
    if (bootstrapState.currentStep === 'error') return 'error';
    if (bootstrapState.currentStep === 'complete') return 'complete';
    if (bootstrapState.isLoading) return 'loading';
    return 'initializing';
  };

  // Create initialization result for detailed error handling
  const initializationResult: BootstrapInitializationResult | null = {
    completedSteps,
    errors: bootstrapState.steps
      .filter(step => step.error)
      .map(step => ({
        message: step.error!,
        step: step.step,
        code: 'BOOTSTRAP_ERROR',
        retryable: true
      })) as BootstrapError[],
    isComplete: bootstrapState.currentStep === 'complete',
    timestamp: new Date()
  };

  return {
    isReady: !bootstrapState.isLoading && bootstrapState.currentStep === 'complete',
    isLoading: bootstrapState.isLoading,
    isError: bootstrapState.currentStep === 'error',
    error: bootstrapState.error,
    currentStep: bootstrapState.currentStep,
    context: getContextMessage(bootstrapState.currentStep),
    state: getOverallState(),
    progress,
    canRetry: bootstrapState.currentStep === 'error',
    completedSteps,
    initializationResult,
    retry: () => appBootstrapService.retry(queryClient),
    flags: bootstrapState.flags
  };
}

/**
 * Simplified hook for components that just need to know if app is ready
 * ARCHITECTURAL IMPROVEMENT: Lightweight alternative for simple use cases
 */
export function useAppReady(): boolean {
  const { isReady } = useAppBootstrap();
  return isReady;
}

/**
 * Application Error Boundary
 *
 * Error recovery component for graceful failure handling.
 * Catches React errors and provides recovery options.
 */

import type { ErrorInfo, ReactNode } from 'react';
import React, { Component } from 'react';

import { AlertTriangle, RefreshCw, Home, Bug, ExternalLink } from 'lucide-react';

import { env } from '@shared/config/environment';

import type { AppInitializationError } from '@shared/errors/AppError';


interface AppErrorBoundaryProps {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
  onRetry?: () => void;
}

interface AppErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
  errorId: string;
}

export class AppErrorBoundary extends Component<AppErrorBoundaryProps, AppErrorBoundaryState> {
  constructor(props: AppErrorBoundaryProps) {
    super(props);
    
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      errorId: this.generateErrorId()
    };
  }

  static getDerivedStateFromError(error: Error): Partial<AppErrorBoundaryState> {
    return {
      hasError: true,
      error,
      errorId: Date.now().toString(36) + Math.random().toString(36).substr(2)
    };
  }

  override componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    this.setState({
      error,
      errorInfo
    });

    // Log error for debugging
    console.error('🛑 [ERROR BOUNDARY] React error caught:', {
      error: error.message,
      stack: error.stack,
      componentStack: errorInfo.componentStack,
      errorId: this.state.errorId
    });

    // Call custom error handler if provided
    if (this.props.onError) {
      this.props.onError(error, errorInfo);
    }

    // In production, you might want to send this to an error reporting service
    if (env.isProd()) {
      this.reportError(error, errorInfo);
    }
  }

  private generateErrorId(): string {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  private reportError(error: Error, errorInfo: ErrorInfo): void {
    // TODO: Send to error reporting service (Sentry, LogRocket, etc.)
    console.log('📊 [ERROR REPORTING] Error would be reported to monitoring service:', {
      message: error.message,
      stack: error.stack,
      componentStack: errorInfo.componentStack,
      userAgent: navigator.userAgent,
      timestamp: new Date().toISOString(),
      errorId: this.state.errorId
    });
  }

  private handleRetry = (): void => {
    if (this.props.onRetry) {
      this.props.onRetry();
    }
    
    // Reset error boundary state
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      errorId: this.generateErrorId()
    });
  };

  private handleReload = (): void => {
    window.location.reload();
  };

  private handleGoHome = (): void => {
    window.location.href = '/';
  };

  private copyErrorDetails = (): void => {
    const errorDetails = {
      errorId: this.state.errorId,
      message: this.state.error?.message,
      stack: this.state.error?.stack,
      timestamp: new Date().toISOString(),
      userAgent: navigator.userAgent,
      componentStack: this.state.errorInfo?.componentStack
    };

    navigator.clipboard.writeText(JSON.stringify(errorDetails, null, 2))
      .then(() => {
        alert('Error details copied to clipboard');
      })
      .catch(() => {
        alert('Failed to copy error details');
      });
  };

  override render() {
    if (this.state.hasError) {
      // Custom fallback component if provided
      if (this.props.fallback) {
        return this.props.fallback;
      }

      // Default error UI
      return (
        <div className="min-h-screen bg-gradient-to-br from-red-50 to-orange-100 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-2xl p-8 w-full max-w-lg">
            {/* Error Icon and Title */}
            <div className="text-center mb-6">
              <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <AlertTriangle className="w-8 h-8 text-red-500" />
              </div>
              
              <h1 className="text-2xl font-bold text-gray-900 mb-2">
                Something went wrong
              </h1>
              
              <p className="text-gray-600">
                The application encountered an unexpected error and needs to recover.
              </p>
            </div>

            {/* Error Details */}
            <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6">
              <div className="flex items-start space-x-3">
                <Bug className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
                <div className="flex-1 min-w-0">
                  <h4 className="text-sm font-medium text-red-800 mb-1">
                    Error Details
                  </h4>
                  <p className="text-sm text-red-700 break-words">
                    {this.state.error?.message ?? 'Unknown error occurred'}
                  </p>
                  <p className="text-xs text-red-600 mt-2">
                    Error ID: {this.state.errorId}
                  </p>
                </div>
              </div>
            </div>

            {/* Debug Information (Development Only) */}
            {env.isDev() && this.state.error?.stack && (
              <details className="mb-6">
                <summary className="text-sm text-gray-600 cursor-pointer hover:text-gray-800 mb-2">
                  🔧 Stack Trace (Development)
                </summary>
                <pre className="text-xs text-gray-700 p-3 bg-gray-100 rounded-lg overflow-auto max-h-40">
                  {this.state.error.stack}
                </pre>
                {this.state.errorInfo?.componentStack && (
                  <>
                    <summary className="text-sm text-gray-600 cursor-pointer hover:text-gray-800 mt-3 mb-2">
                      🧩 Component Stack
                    </summary>
                    <pre className="text-xs text-gray-700 p-3 bg-gray-100 rounded-lg overflow-auto max-h-40">
                      {this.state.errorInfo.componentStack}
                    </pre>
                  </>
                )}
              </details>
            )}

            {/* Recovery Actions */}
            <div className="space-y-3 mb-6">
              {/* Primary Recovery Action */}
              {this.props.onRetry && (
                <button
                  onClick={this.handleRetry}
                  className="btn-primary w-full flex items-center justify-center space-x-2 py-3"
                >
                  <RefreshCw className="w-4 h-4" />
                  <span>Try Again</span>
                </button>
              )}

              {/* Secondary Recovery Actions */}
              <div className="grid grid-cols-2 gap-3">
                <button
                  onClick={this.handleReload}
                  className="btn-cancel flex items-center justify-center space-x-2"
                >
                  <RefreshCw className="w-4 h-4" />
                  <span>Reload Page</span>
                </button>

                <button
                  onClick={this.handleGoHome}
                  className="btn-cancel flex items-center justify-center space-x-2"
                >
                  <Home className="w-4 h-4" />
                  <span>Go Home</span>
                </button>
              </div>
            </div>

            {/* Support Actions */}
            <div className="border-t border-gray-200 pt-6">
              <h3 className="text-sm font-medium text-gray-700 mb-3">Need Help?</h3>
              
              <div className="space-y-2">
                <button
                  onClick={this.copyErrorDetails}
                  className="w-full text-left px-3 py-2 text-sm text-gray-600 hover:bg-gray-50 rounded-lg transition-colors flex items-center space-x-2"
                >
                  <ExternalLink className="w-4 h-4" />
                  <span>Copy error details for support</span>
                </button>
                
                <p className="text-xs text-gray-500">
                  If this error persists, please contact your system administrator with the error ID above.
                </p>
              </div>
            </div>

            {/* Footer */}
            <div className="mt-6 text-center border-t border-gray-200 pt-4">
              <p className="text-xs text-gray-500">
                Odysseus Laboratory Management System
              </p>
            </div>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

/**
 * Bootstrap-specific error component for initialization failures
 */
interface BootstrapErrorProps {
  error: AppInitializationError;
  onRetry?: () => void;
  canRetry?: boolean;
}

export function BootstrapError({ error, onRetry, canRetry }: BootstrapErrorProps) {
  return (
    <div className="bg-red-50 border border-red-200 rounded-lg p-6">
      <div className="flex items-start space-x-4">
        <AlertTriangle className="w-6 h-6 text-red-500 flex-shrink-0" />
        <div className="flex-1">
          <h3 className="text-lg font-medium text-red-800 mb-2">
            Initialization Failed
          </h3>
          <p className="text-red-700 mb-3">
            {error.message}
          </p>
          <div className="text-sm text-red-600 mb-4">
            <p>Phase: <span className="font-mono">{error.phase}</span></p>
            <p>Code: <span className="font-mono">{error.code}</span></p>
          </div>
          
          {canRetry && error.retryable && onRetry && (
            <button
              onClick={onRetry}
              className="btn-danger inline-flex items-center space-x-2"
            >
              <RefreshCw className="w-4 h-4" />
              <span>Retry Initialization</span>
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

// Named exports only - no default export needed

/**
 * Error Boundary Components
 */

export { AppErrorBoundary } from './AppErrorBoundary';

/**
 * Application Components
 */

// Layout components
export * from './layout';

// Boundary components  
export * from './boundaries';

import { useState, lazy } from 'react';

import { LogOut, UserRound, Menu, Plus, Edit, Trash2, Copy, Scissors, ClipboardPaste, X, Cog } from 'lucide-react';

import { useAuthStore } from '@domains/authentication';
import { SearchContainer } from '@domains/search/ui/components/SearchContainer';
import odysseusLogo from '@shared/assets/frozen-odysseus-logo.png';
import xcellbioLogo from '@shared/assets/frozen-xcellbio-logo.png';
import { parsePositionKey, type PositionKey } from '@shared/types/grid';
import { SuspenseBoundary } from '@shared/ui';
import { TankIcon } from '@shared/ui/components/icons/TankIcon';
import { ModalSkeleton } from '@shared/ui/components/loading/LoadingSkeletons';
import { PreloadHelpers } from '@shared/utils/lazy/PreloadHelpers';

import type { TubeData } from '@domains/tubes/types';
// Assets - using ES6 imports for proper module resolution

// Lazy load modals for code splitting
const AdminSettingsModal = lazy(() =>
  import('@domains/admin').then(m => ({
    default: m.AdminSettingsModal
  }))
);

const StorageManagementModal = lazy(() =>
  import('@domains/tubes/ui/components/modals/StorageManagementModal').then(m => ({
    default: m.StorageManagementModal
  }))
);

const UserSettingsModal = lazy(() =>
  import('@domains/authentication/ui/components/UserSettingsModal').then(m => ({
    default: m.UserSettingsModal
  }))
);

// Create preload hooks for anticipatory loading
const useLazyAdminSettings = PreloadHelpers.createHook(
  () => import('@domains/admin')
);

const useLazyStorageManagement = PreloadHelpers.createHook(
  () => import('@domains/tubes/ui/components/modals/StorageManagementModal')
);

const useLazyUserSettings = PreloadHelpers.createHook(
  () => import('@domains/authentication/ui/components/UserSettingsModal')
);

interface HeaderProps {
  selectedPositions?: Set<PositionKey>;
  _onEditTube?: (tubeId: string) => void;
  onClearSelection?: () => void;
  tubes?: TubeData[];
  // Grid controller actions passed from parent
  gridController?: {
    openModal: () => void;
    copy: () => void;
    cut: () => void;
    paste: () => void;
    delete: () => void;
    canPaste: boolean;
    getCopyLabel: () => string;
    getCutLabel: () => string;
    getPasteLabel: () => string;
    selection: {
      hasFilledSelection: boolean;
      isMixed: boolean;
      filledCount: number;
      emptyCount: number;
    };
  };
}

export function AppHeader({
selectedPositions = new Set(),
_onEditTube,
onClearSelection,
tubes = [],
  gridController
}: HeaderProps) {
  const { isAuthenticated, user, logout } = useAuthStore();

  // Lazy loading hooks for modal preloading
  const { triggerProps: adminSettingsTriggerProps } = useLazyAdminSettings();
  const { triggerProps: storageManagementTriggerProps } = useLazyStorageManagement();
  const { triggerProps: userSettingsTriggerProps } = useLazyUserSettings();

  const [showAdminPanel, setShowAdminPanel] = useState(false);
  const [showStorageManagement, setShowStorageManagement] = useState(false);
  const [showUserSettings, setShowUserSettings] = useState(false);
  const [showHamburgerMenu, setShowHamburgerMenu] = useState(false);

  const handleLogout = () => {
    // Socket cleanup is now handled centrally by AppBootstrapService
    void logout();
  };

  // Selection analysis for contextual controls
  const selectionAnalysis = (() => {
    if (!selectedPositions || selectedPositions.size === 0 || !tubes) {
      return { hasSelection: false, selectedTubes: [], emptyPositions: new Set(), filledPositions: new Set(), hasEmpty: false, hasFilled: false, isMixed: false };
    }

    const selectedTubes = Array.from(selectedPositions || [])
      .map(key => {
        const { tankId, rackId, boxId, position } = parsePositionKey(key);
        return tubes.find(t =>
          t.location.tankId === tankId &&
          t.location.rackId === rackId &&
          t.location.boxId === boxId &&
          t.location.position === position
        );
      })
      .filter((tube): tube is TubeData => tube !== undefined);

    const emptyPositions = new Set(
      Array.from(selectedPositions || []).filter(key => {
        const { tankId, rackId, boxId, position } = parsePositionKey(key);
        return !tubes.find(t =>
          t.location.tankId === tankId &&
          t.location.rackId === rackId &&
          t.location.boxId === boxId &&
          t.location.position === position
        );
      })
    );

    const filledPositions = new Set(
      Array.from(selectedPositions || []).filter(key => !emptyPositions.has(key))
    );

    const hasEmpty = emptyPositions.size > 0;
    const hasFilled = filledPositions.size > 0;

    const result = {
      hasSelection: true,
      selectedTubes,
      emptyPositions,
      filledPositions,
      hasEmpty,
      hasFilled,
      isMixed: hasEmpty && hasFilled,
    };

    return result;
  })();

  return (
    <header className="bg-gradient-to-r from-frost to-ice-400 border-b border-ice-400/20 px-4 py-0.5">
      <div className="flex justify-between items-center">
        {/* Far Left: Logos */}
        <div className="flex items-center space-x-4">
          <img
            src={xcellbioLogo}
            alt="XcellBio"
            className="h-8 w-auto opacity-90 drop-shadow-md drop-shadow-[0_0_4px_rgba(255,255,255,0.25)]"
          />
          <img
            src={odysseusLogo}
            alt="Odysseus"
            className="h-8 w-auto opacity-90 scale-x-[1.4] mt-1 drop-shadow-md drop-shadow-[0_0_4px_rgba(255,255,255,0.25)]"
          />
        </div>

        {/* Right Side: Controls + Search + Hamburger */}
        <div className="flex items-center gap-3">
          {/* Compact Single-Row Control Buttons */}
          {selectionAnalysis.hasSelection && gridController && (
            <div className="flex items-center space-x-2">
              {/* Unified Modal Button - Context-aware label, single action (Minty Frost) */}
              <button
                onClick={gridController.openModal}
                className="btn-header-control-compact-edit"
                title={
                  gridController.selection.isMixed
                    ? 'Add tubes to mixed selection (overwrite prompt will appear)'
                    : gridController.selection.hasFilledSelection
                    ? 'Edit selected tube(s)'
                    : 'Add new tube(s) to selected position(s)'
                }
              >
                {gridController.selection.hasFilledSelection && !gridController.selection.isMixed ? (
                  <Edit className="w-3 h-3 mr-1" />
                ) : (
                  <Plus className="w-3 h-3 mr-1" />
                )}
                {gridController.selection.isMixed
                  ? (gridController.selection.emptyCount + gridController.selection.filledCount === 1
                      ? 'Add Tube'
                      : `Add ${gridController.selection.emptyCount + gridController.selection.filledCount} Tubes`)
                  : gridController.selection.hasFilledSelection
                  ? (gridController.selection.filledCount === 1
                      ? 'Edit Tube'
                      : `Edit ${gridController.selection.filledCount} Tubes`)
                  : (gridController.selection.emptyCount === 1
                      ? 'Add Tube'
                      : `Add ${gridController.selection.emptyCount} Tubes`)}
              </button>

              {/* Delete Tube(s) - Only for filled positions */}
              {selectionAnalysis.hasFilled && gridController && (
                <button
                  onClick={gridController.delete}
                  className="btn-header-control-compact-danger"
                >
                  <Trash2 className="w-3 h-3 mr-1" />
                  Delete {selectionAnalysis.selectedTubes.length === 1 ? 'Tube' : `${selectionAnalysis.selectedTubes.length} Tubes`}
                </button>
              )}

              {/* Separator */}
              {selectionAnalysis.hasFilled && <div className="w-0.5 h-4 bg-white/60 mx-1"></div>}

              {/* Copy/Cut - Only for filled positions */}
              {selectionAnalysis.hasFilled && gridController && (
                <>
                  <button
                  onClick={gridController.copy}
                  className="btn-header-control-compact-copy"
                  >
                  <Copy className="w-3 h-3 mr-1" />
                  {gridController.getCopyLabel()}
                  </button>
                  <button
                  onClick={gridController.cut}
                  className="btn-header-control-compact-cut"
                  >
                  <Scissors className="w-3 h-3 mr-1" />
                  {gridController.getCutLabel()}
                  </button>
                </>
              )}

              {/* Paste - Show when clipboard has data and user has selection (Icy Blue) */}
              {gridController?.canPaste && selectionAnalysis.hasSelection && (
                <button
                onClick={gridController.paste}
                className="btn-header-control-compact-copy"
                >
                <ClipboardPaste className="w-3 h-3 mr-1" />
                {gridController.getPasteLabel()}
                </button>
              )}

              {/* Clear Selection */}
              <button
                onClick={onClearSelection}
                className="btn-header-control-compact-secondary"
              >
                <X className="w-3 h-3 mr-1" />
                Clear
              </button>
            </div>
          )}

          {/* Search Container */}
          <div className="flex-shrink-0">
            <SearchContainer />
          </div>

          {/* Hamburger Menu */}
          <div className="relative">
          <button
            onClick={() => setShowHamburgerMenu(!showHamburgerMenu)}
            className="btn-header-menu text-white"
          >
            <Menu size={20} />
          </button>

          {/* Hamburger Menu Dropdown */}
          {showHamburgerMenu && (
            <div className="absolute top-10 right-0 bg-white rounded-lg shadow-xl border border-gray-200 py-1 z-50 w-auto whitespace-nowrap">
              {/* User Info at Top */}
              {isAuthenticated && user && (
                <>
                  <div className="px-4 py-1.5 bg-gray-50 border-b border-gray-100">
                    <div className="flex items-center space-x-2 text-sm">
                      <UserRound size={20} className="text-action-hover" />
                      <span className="text-action-hover font-semibold">{user.username}</span>
                    </div>
                  </div>
                </>
              )}

              {/* User Settings */}
              <button
                {...userSettingsTriggerProps}
                onClick={() => {
                  setShowUserSettings(true);
                  setShowHamburgerMenu(false);
                }}
                className="menu-item"
              >
                <Cog size={20} />
                <span>{user?.role === 'admin' ? 'User Settings' : 'Settings'}</span>
              </button>

              {/* Storage Management */}
              <button
                {...storageManagementTriggerProps}
                onClick={() => {
                  setShowStorageManagement(true);
                  setShowHamburgerMenu(false);
                }}
                className="menu-item"
              >
                <TankIcon size={20} />
                <span>Manage Storage</span>
              </button>

              {/* Admin Settings - Only show to admins */}
              {user?.role === 'admin' && (
                <button
                  {...adminSettingsTriggerProps}
                  onClick={() => {
                    setShowAdminPanel(true);
                    setShowHamburgerMenu(false);
                  }}
                  className="menu-item text-danger-hover"
                >
                  <Cog size={20} />
                  <span>Admin Settings</span>
                </button>
              )}

              <hr className="my-0.5" />
              <div className="bg-gray-50">
                <button
                  onClick={() => {
                    handleLogout();
                    setShowHamburgerMenu(false);
                  }}
                  className="menu-item"
                >
                  <LogOut size={20} />
                  <span>Logout</span>
                </button>
              </div>
            </div>
          )}
          </div>
        </div>
      </div>

      {/* Storage Management Modal */}
      {showStorageManagement && (
        <SuspenseBoundary
          fallback={<ModalSkeleton size="lg" />}
          name="StorageManagementModal"
        >
          <StorageManagementModal
            isOpen={showStorageManagement}
            onClose={() => setShowStorageManagement(false)}
          />
        </SuspenseBoundary>
      )}

      {/* Admin Settings Modal */}
      {showAdminPanel && (
        <SuspenseBoundary
          fallback={<ModalSkeleton size="lg" />}
          name="AdminSettingsModal"
        >
          <AdminSettingsModal
            isOpen={showAdminPanel}
            onClose={() => setShowAdminPanel(false)}
          />
        </SuspenseBoundary>
      )}

      {/* User Settings Modal */}
      {showUserSettings && (
        <SuspenseBoundary
          fallback={<ModalSkeleton size="lg" />}
          name="UserSettingsModal"
        >
          <UserSettingsModal
            isOpen={showUserSettings}
            onClose={() => setShowUserSettings(false)}
          />
        </SuspenseBoundary>
      )}
    </header>
  );
}

/**
 * App Loader Component
 *
 * Loading screen with detailed progress feedback and error recovery options.
 */

import React from 'react';

import { Loader2, AlertCircle, RefreshCw, CheckCircle2, Clock } from 'lucide-react';

import { env } from '@shared/config/environment';

import { LOADING_MESSAGES } from '../../bootstrap/constants';

import type { UseAppBootstrapResult } from '../../bootstrap/types';

interface AppLoaderProps {
  context: UseAppBootstrapResult;
  onRetry?: () => void;
  onCancel?: () => void;
}

export function AppLoader({ context, onRetry, onCancel }: AppLoaderProps) {
  const { state, progress, currentStep, error, canRetry, completedSteps } = context;

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-2xl p-8 w-full max-w-md">
        {/* Header */}
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4">
            {state === 'error' ? (
              <AlertCircle className="w-8 h-8 text-red-500" />
            ) : state === 'retrying' ? (
              <RefreshCw className="w-8 h-8 text-orange-500 animate-spin" />
            ) : (
              <Loader2 className="w-8 h-8 text-blue-500 animate-spin" />
            )}
          </div>
          
          <h1 className="text-2xl font-bold text-gray-900 mb-2">
            Odysseus
          </h1>
          
          <p className="text-gray-600">
            {state === 'error' 
              ? 'Initialization Failed'
              : state === 'retrying'
              ? 'Retrying Connection...'
              : 'Starting Application...'
            }
          </p>
        </div>

        {/* Progress Section */}
        {state !== 'error' && (
          <div className="mb-6">
            {/* Progress Bar */}
            <div className="bg-gray-200 rounded-full h-3 mb-4 overflow-hidden">
              <div 
                className="bg-gradient-to-r from-blue-500 to-blue-600 h-full rounded-full transition-all duration-300 ease-out"
                style={{ width: `${progress}%` }}
              />
            </div>

            {/* Progress Text */}
            <div className="flex justify-between items-center text-sm text-gray-600 mb-4">
              <span>{progress}% Complete</span>
              <span>{completedSteps.length} steps done</span>
            </div>

            {/* Current Step */}
            {currentStep && (
              <div className="flex items-center space-x-3 p-3 bg-blue-50 rounded-lg">
                <div className="flex-shrink-0">
                  {state === 'retrying' ? (
                    <RefreshCw className="w-4 h-4 text-orange-500 animate-spin" />
                  ) : (
                    <Loader2 className="w-4 h-4 text-blue-500 animate-spin" />
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-gray-900 truncate">
                    {LOADING_MESSAGES[currentStep as keyof typeof LOADING_MESSAGES] || 'Processing...'}
                  </p>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Completed Steps (Success Indicators) */}
        {completedSteps.length > 0 && state !== 'error' && (
          <div className="mb-6">
            <h3 className="text-sm font-medium text-gray-700 mb-3">Completed:</h3>
            <div className="space-y-2">
              {completedSteps.slice(-3).map((step) => ( // Show last 3 completed steps
                <div key={step} className="flex items-center space-x-2 text-sm text-green-700">
                  <CheckCircle2 className="w-4 h-4" />
                  <span className="capitalize">{step} loaded successfully</span>
                </div>
              ))}
              {completedSteps.length > 3 && (
                <div className="text-xs text-gray-500 pl-6">
                  ... and {completedSteps.length - 3} more
                </div>
              )}
            </div>
          </div>
        )}

        {/* Error State */}
        {state === 'error' && error && (
          <div className="mb-6">
            <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-4">
              <div className="flex items-start space-x-3">
                <AlertCircle className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
                <div className="flex-1">
                  <h4 className="text-sm font-medium text-red-800 mb-1">
                    {typeof error === 'string' ? error : error.message}
                  </h4>
                  {typeof error === 'object' && (
                    <p className="text-sm text-red-700">
                      Step: {error.step} ({error.code})
                    </p>
                  )}
                  {typeof error === 'object' && error.retryable && (
                    <p className="text-xs text-red-600 mt-2">
                      This error can be retried. Check your internet connection and try again.
                    </p>
                  )}
                </div>
              </div>
            </div>

            {/* Error Details (Debug Info) */}
            {env.isDev() && typeof error === 'object' && error.details && (
              <details className="mb-4">
                <summary className="text-xs text-gray-500 cursor-pointer hover:text-gray-700">
                  Debug Information
                </summary>
                <pre className="text-xs text-gray-600 mt-2 p-2 bg-gray-50 rounded overflow-auto">
                  {JSON.stringify(error.details, null, 2)}
                </pre>
              </details>
            )}
          </div>
        )}

        {/* Action Buttons */}
        <div className="flex space-x-3">
          {state === 'error' && canRetry && onRetry && (
            <button
              onClick={onRetry}
              className="btn-primary flex-1 flex items-center justify-center space-x-2"
            >
              <RefreshCw className="w-4 h-4" />
              <span>Try Again</span>
            </button>
          )}

          {onCancel && (
            <button
              onClick={onCancel}
              className="btn-cancel"
            >
              Cancel
            </button>
          )}
        </div>

        {/* Loading Timeout Warning */}
        {state === 'initializing' && progress === 0 && (
          <div className="mt-6 p-3 bg-yellow-50 border border-yellow-200 rounded-lg">
            <div className="flex items-start space-x-2">
