export { Dashboard } from './Dashboard';
export { AppHeader } from './AppHeader';  
export { AppLoader } from './AppLoader';

/**
 * Bootstrap Context - Single Source of Truth for Bootstrap State
 *
 * ARCHITECTURAL SOLUTION: Prevents duplicate bootstrap processes
 * Only App.tsx calls useAppBootstrap hook, all other components consume via context
 *
 * Singleton service pattern via React Context
 */
import type { ReactNode } from 'react';
import React, { createContext, useContext } from 'react';

import type { UseAppBootstrapResult } from '@app/bootstrap';

interface BootstrapContextValue extends UseAppBootstrapResult {}

const BootstrapContext = createContext<BootstrapContextValue | null>(null);

interface BootstrapProviderProps {
  value: UseAppBootstrapResult;
  children: ReactNode;
}

/**
 * Provider component - used only in App.tsx
 */
export function BootstrapProvider({ value, children }: BootstrapProviderProps) {
  return (
    <BootstrapContext.Provider value={value}>
      {children}
    </BootstrapContext.Provider>
  );
}

/**
 * Consumer hook - replaces direct useAppBootstrap() calls
 * ARCHITECTURAL IMPROVEMENT: Prevents duplicate bootstrap processes
 */
export function useBootstrapContext(): UseAppBootstrapResult {
  const context = useContext(BootstrapContext);
  
  if (!context) {
    throw new Error(
      'useBootstrapContext must be used within a BootstrapProvider. ' +
      'This hook should replace direct useAppBootstrap() calls to prevent duplicate bootstrap processes.'
    );
  }
  
  return context;
}

/**
 * Legacy compatibility - components can still check bootstrap readiness
 * but don't trigger new bootstrap processes
 */
export function useAppReady(): boolean {
  const { isReady } = useBootstrapContext();
  return isReady;
}

/**
 * Grid Hooks
 * Reusable custom hooks for grid functionality
 */

export { useGridPosition } from './useGridPosition';
export { useGridController } from './useGridController';
export { useGridDragSelection } from './useGridDragSelection';
export { useGridKeyboardNavigation } from './useGridKeyboardNavigation';
export { useGridFontSizing } from './useGridFontSizing';

/**
 * Grid Controller Hook
 * Grid actions with clipboard integration
 *
 * Uses modalStore for all modal operations
 */

import React from 'react';

import { tubeDataToCreateRequest } from '@odysseus/shared-schemas';

import { useModalStore } from '@app/stores/modalStore';
import { useStorageStore } from '@domains/storage';
import { useTubesByLocation } from '@domains/tubes/hooks';
import { useTubeStore } from '@domains/tubes/stores/tubeStore';
import { useGridUiStore } from '@shared/stores/gridUiStore';
import { toPositionKey, parsePositionKey, type PositionKey } from '@shared/types/grid';
import { getSelectionRange } from '@shared/utils/coordinates';
import { writeClipboardOS, readClipboardOS } from '@shared/utils/gridClipboard';
import { notifications } from '@shared/utils/notifications';
import { validatePasteOperation } from '@shared/utils/pasteValidation';

import type { ClipboardData } from '@shared/types/clipboard';
import type {
  GridControllerProps,
  GridControllerReturn,
  TubeClipboardItem
} from '@shared/types/grid';



export const useGridController = ({
  tankId,
  rackId,
  boxId,
  selectedPositions,
  onSelectionChange,
  resolveTubeIdAtPosition,
  onDeleteTubes,
  onPasteTubes
}: GridControllerProps): GridControllerReturn => {
  const ctx = React.useMemo(() => ({ tankId, rackId, boxId }), [tankId, rackId, boxId]);

  // ✅ FIXED: Individual Zustand selectors for reactivity
  // When clipboard changes, this hook MUST re-render so copyPositions/cutPositions memos recalculate
  const clipboard = useGridUiStore(state => state.clipboard);
  const setClipboard = useGridUiStore(state => state.setClipboard);
  const setMousePositionStore = useGridUiStore(state => state.setMousePosition);

  const modalService = useModalStore();
  const { getBox } = useStorageStore();

  // Click timer for double-click detection
  const clickTimerRef = React.useRef<NodeJS.Timeout | null>(null);

  // Cleanup timer on unmount
  React.useEffect(() => {
    return () => {
      if (clickTimerRef.current) {
        clearTimeout(clickTimerRef.current);
      }
    };
  }, []);

  // Grid context menu state
  const [contextMenu, setContextMenu] = React.useState({
    isOpen: false,
    x: 0,
    y: 0
  });
  
  // Get tube data for the current location
  const { data: tubes = [] } = useTubesByLocation(tankId, rackId, boxId);
  
  // Create a lookup map for position -> tubeId resolution
  const positionToTubeMap = React.useMemo(() => {
    const map = new Map<number, string>();
    tubes.forEach(tube => {
      if (tube.location.position) {
        map.set(tube.location.position, tube.id);
      }
    });
    return map;
  }, [tubes]);

  // Default tube resolution if not provided
  const resolveTube = React.useMemo(
    () => resolveTubeIdAtPosition || ((position: number) => positionToTubeMap.get(position) || null),
    [resolveTubeIdAtPosition, positionToTubeMap]
  );

  const handlePositionClick = (position: number, event: React.MouseEvent, gridSize: number = 9) => {
    // Clear any pending click timer
    if (clickTimerRef.current) {
      clearTimeout(clickTimerRef.current);
      clickTimerRef.current = null;
    }

    const positionKey = toPositionKey(ctx, position);
    const isAlreadySelected = selectedPositions.has(positionKey);
    const hasMultipleSelected = selectedPositions.size > 1;

    // Capture event properties immediately (React synthetic event pooling fix)
    const shiftKey = event.shiftKey;
    const ctrlKey = event.ctrlKey;
    const metaKey = event.metaKey;
    const hasModifierKey = shiftKey || ctrlKey || metaKey;

    // Clone selectedPositions to avoid stale closure
    const currentSelectedPositions = new Set(selectedPositions);

    // Only delay when clicking already-selected position in multi-selection
    // This prevents double-click from deselecting the group (Windows Explorer pattern)
    const shouldDelay = isAlreadySelected && hasMultipleSelected && !hasModifierKey;

    const executeSelection = () => {
      // Read anchor fresh from store
      const currentAnchor = useTubeStore.getState().selectionAnchor;
      const { setSelectionAnchor } = useTubeStore.getState();

      const newSelection = new Set<PositionKey>();

      if (shiftKey && currentAnchor !== null) {
        // Shift+Click: Range selection from anchor to current position
        const rangePositions = getSelectionRange(currentAnchor, position, gridSize);
        rangePositions.forEach(pos => {
          newSelection.add(toPositionKey(ctx, pos));
        });
        // Keep existing selection if Ctrl is also held
        if (ctrlKey || metaKey) {
          currentSelectedPositions.forEach(key => newSelection.add(key));
        }
      } else if (ctrlKey || metaKey) {
        // Ctrl+Click: Toggle individual position
        currentSelectedPositions.forEach(key => newSelection.add(key));
        if (newSelection.has(positionKey)) {
          newSelection.delete(positionKey);
        } else {
          newSelection.add(positionKey);
        }
        // Update anchor for potential Shift+Ctrl combinations
        setSelectionAnchor(position);
      } else {
        // Single click: Replace selection with just this position
        newSelection.add(positionKey);
        setSelectionAnchor(position);
      }

      onSelectionChange(newSelection);
    };

    if (shouldDelay) {
      // Delay to distinguish from double-click (Windows Explorer, macOS Finder pattern)
      clickTimerRef.current = setTimeout(executeSelection, 200);
    } else {
      // Execute immediately for instant feedback
      executeSelection();
    }
  };

  // Helper: Analyze selected positions (empty vs filled)
  const selectionAnalysis = React.useMemo(() => {
    let filledCount = 0;
    let emptyCount = 0;

    Array.from(selectedPositions).forEach(positionKey => {
      const { position } = parsePositionKey(positionKey);
      if (resolveTube(position) !== null) {
        filledCount++;
      } else {
        emptyCount++;
      }
    });

    return {
      filledCount,
      emptyCount,
      hasFilledSelection: filledCount > 0,
      hasEmptySelection: emptyCount > 0,
      isMixed: filledCount > 0 && emptyCount > 0,
      allFilled: filledCount > 0 && emptyCount === 0,
      allEmpty: emptyCount > 0 && filledCount === 0
    };
  }, [selectedPositions, resolveTube]);

  // Unified modal opener - single source of truth for selection-based modal logic
  const openModal = React.useCallback(() => {
    const positions = Array.from(selectedPositions);

    if (selectionAnalysis.isMixed || selectionAnalysis.allEmpty) {
      // Mixed or all empty - open create modal
      modalService.showTubeEditorModal({
        mode: 'add',
        positions,
        rackId,
        boxId
      });
    } else if (selectionAnalysis.allFilled) {
      // All filled - open edit modal
      const selectedTubeIds = Array.from(selectedPositions)
        .map(positionKey => {
          const { position } = parsePositionKey(positionKey);
          return resolveTube(position);
        })
        .filter((tubeId): tubeId is string => tubeId !== null);

      if (selectedTubeIds.length === 0) return;

      if (selectedTubeIds.length === 1) {
        modalService.showTubeEditorModal({
          mode: 'edit',
          tubeId: selectedTubeIds[0]
        });
      } else {
        modalService.showTubeEditorModal({
          mode: 'batch',
          tubeIds: selectedTubeIds,
          preserveSelection: true  // Maintain multi-selection after batch operation
        });
      }
    }
  }, [selectionAnalysis, selectedPositions, modalService, rackId, boxId, resolveTube]);

  const handlePositionDoubleClick = (position: number) => {
    // CRITICAL: Clear pending click timer to prevent selection change during modal
    if (clickTimerRef.current) {
      clearTimeout(clickTimerRef.current);
      clickTimerRef.current = null;
    }

    const positionKey = toPositionKey(ctx, position);

    // Double-click on multi-selection opens batch mode
    if (selectedPositions.has(positionKey) && selectedPositions.size > 1) {
      openModal();
      return;
    }

    // Single position double-click - existing logic
    const tubeId = resolveTube(position);
    if (tubeId) {
      // Filled position - open edit modal
      modalService.showTubeEditorModal({
        mode: 'edit',
        tubeId
      });
    } else {
      // Empty position - open add modal
      modalService.showTubeEditorModal({
        mode: 'add',
        positions: [positionKey],
        rackId,
        boxId
      });
    }
  };

  const handleBulkSelection = (positions: number[]) => {
    const positionKeys = positions.map(pos => toPositionKey(ctx, pos));
    const newSelection = new Set(positionKeys);
    onSelectionChange(newSelection);
  };

  const isPositionSelected = React.useCallback((position: number) => {
    const positionKey = toPositionKey(ctx, position);
    return selectedPositions.has(positionKey);
  }, [ctx, selectedPositions]);

  // Helper: Get selected positions in current box
  const selectedPositionsInThisBox = React.useCallback((): number[] => {
    const positions: number[] = [];
    selectedPositions.forEach((key) => {
      const { tankId: t, rackId: r, boxId: b, position } = parsePositionKey(key);
      if (t === tankId && r === rackId && b === boxId) {
        positions.push(position);
      }
    });
    return positions.sort((a, b) => a - b);
  }, [selectedPositions, tankId, rackId, boxId]);

  // Copy operation
  const copy = React.useCallback(async () => {
    const positions = selectedPositionsInThisBox();
    if (positions.length === 0) return;

    const items: TubeClipboardItem[] = positions
      .map((position) => {
        const tubeId = resolveTube(position);
        return tubeId ? { tubeId, fromPosition: position } : null;
      })
      .filter((item): item is TubeClipboardItem => item !== null);

    if (items.length === 0) return;

    const clipboardData: ClipboardData = {
      tubes: items.map(item => tubes.find(t => t.id === item.tubeId)!).filter(Boolean),
      operation: 'copy',
      timestamp: new Date(),
      sourceLocation: ctx,
    };

    setClipboard(clipboardData);
    await writeClipboardOS(clipboardData);

    // Show copy notification
    notifications.copy(`Copied ${items.length} tube${items.length > 1 ? 's' : ''}`);
  }, [selectedPositionsInThisBox, resolveTube, tubes, ctx, setClipboard]);

  // Cut operation (copy + delete)
  const cut = React.useCallback(async () => {
    const positions = selectedPositionsInThisBox();
    if (positions.length === 0) return;

    const items: TubeClipboardItem[] = positions
      .map((position) => {
        const tubeId = resolveTube(position);
        return tubeId ? { tubeId, fromPosition: position } : null;
      })
      .filter((item): item is TubeClipboardItem => item !== null);

    if (items.length === 0) return;

    const clipboardData: ClipboardData = {
      tubes: items.map(item => tubes.find(t => t.id === item.tubeId)!).filter(Boolean),
      operation: 'cut',
      timestamp: new Date(),
      sourceLocation: ctx,
    };

    setClipboard(clipboardData);
    await writeClipboardOS(clipboardData);

    // Show cut notification - Light Amber
    notifications.cut(`Cut ${items.length} tube${items.length > 1 ? 's' : ''}`);

    // Note: Tubes are NOT deleted here - they'll be deleted after successful paste
    // Clear selection after cut
    onSelectionChange(new Set());
  }, [selectedPositionsInThisBox, resolveTube, tubes, ctx, setClipboard, onSelectionChange]);

  // Paste operation - dual-mode behavior
  // 1. Fill Mode: More targets than clipboard → Repeat pattern (Excel fill handle)
  // 2. Spatial Pattern Mode: Equal/fewer targets → Preserve 2D layout
  const paste = React.useCallback(async (options?: { targetStart?: number }) => {
    let clipData = clipboard;

    // Try OS clipboard if no in-app clipboard
    if (!clipData) {
      clipData = await readClipboardOS();
      if (clipData) setClipboard(clipData);
    }

    if (!clipData || clipData.tubes.length === 0) return;

    // Determine target positions
    const selectedPositions = selectedPositionsInThisBox();

    // Two paste modes based on selection size
    const shouldFillTargets = selectedPositions.length > clipData.tubes.length;

    let tubesToPaste: ReturnType<typeof tubeDataToCreateRequest>[];

    if (shouldFillTargets) {
      // Fill Mode: Repeat clipboard pattern across all selected positions
      // Matches Excel's fill handle behavior
      tubesToPaste = selectedPositions.map((targetPos, i) => {
        const sourceTube = clipData.tubes[i % clipData.tubes.length];
        return tubeDataToCreateRequest(sourceTube, {
          tankId: ctx.tankId,
          rackId: ctx.rackId,
          boxId: ctx.boxId,
          position: targetPos
        });
      });
    } else {
      // Spatial Pattern Mode: Preserve relative positioning of clipboard items
      // Matches Excel's copy/paste of multi-cell ranges
      const anchorPosition = selectedPositions.length > 0
        ? Math.min(...selectedPositions)
        : options?.targetStart;

      if (anchorPosition === undefined) return;

      // Validate paste operation across different grid configurations
      const sourceGridConfig = getBox(
        (clipData.sourceLocation || ctx).tankId,
        (clipData.sourceLocation || ctx).rackId,
        (clipData.sourceLocation || ctx).boxId
      )?.gridConfig;

      const targetGridConfig = getBox(tankId, rackId, boxId)?.gridConfig;

      // Perform validation if both grid configs are available
      if (sourceGridConfig && targetGridConfig) {
        const sourcePositions = clipData.tubes.map(tube => tube.location.position);
        const validation = validatePasteOperation(
          sourcePositions,
          anchorPosition,
          sourceGridConfig,
          targetGridConfig
        );

        // Show warning modal if validation failed
        if (!validation.isValid) {
          const userConfirmed = await new Promise<boolean>((resolve) => {
            modalService.showOverwriteConfirm({
              title: 'Paste Warning',
              message: validation.warnings.join('\n\n') + '\n\nDo you want to continue?',
              confirmText: 'Paste Anyway',
              onConfirm: () => {
                modalService.hideOverwriteConfirm();
                resolve(true);
              },
              onCancel: () => {
                modalService.hideOverwriteConfirm();
                resolve(false);
              }
            });
          });

          if (!userConfirmed) {
            // User cancelled - clear clipboard and exit
            return;
          }
        }
      }

      const sourcePositions = clipData.tubes.map(tube => tube.location.position);
      const minSourcePosition = Math.min(...sourcePositions);

      tubesToPaste = clipData.tubes.map((sourceTube) => {
        const relativePosition = sourceTube.location.position - minSourcePosition;
        const newPosition = anchorPosition + relativePosition;

        return tubeDataToCreateRequest(sourceTube, {
          tankId: ctx.tankId,
          rackId: ctx.rackId,
          boxId: ctx.boxId,
          position: newPosition
        });
      });
    }

    // Detect position conflicts before paste
    const conflictingPositions = tubesToPaste.filter(tubeData => {
      const existingTube = tubes.find(t =>
        t.location.tankId === tubeData.location.tankId &&
        t.location.rackId === tubeData.location.rackId &&
        t.location.boxId === tubeData.location.boxId &&
        t.location.position === tubeData.location.position
      );
      return existingTube !== undefined;
    });

    // If conflicts detected, ask user for confirmation
    if (conflictingPositions.length > 0) {
      const conflictingTubes = conflictingPositions.map(tubeData => {
        return tubes.find(t =>
          t.location.tankId === tubeData.location.tankId &&
          t.location.rackId === tubeData.location.rackId &&
          t.location.boxId === tubeData.location.boxId &&
          t.location.position === tubeData.location.position
        )!;
      });

      const userConfirmed = await new Promise<boolean>((resolve) => {
        modalService.showOverwriteConfirm({
          title: 'Overwrite Confirmation',
          message: `${conflictingPositions.length} position${conflictingPositions.length > 1 ? 's are' : ' is'} already occupied. Do you want to overwrite ${conflictingPositions.length > 1 ? 'these tubes' : 'this tube'}?`,
          confirmText: 'Overwrite',
          onConfirm: () => {
            modalService.hideOverwriteConfirm();
            resolve(true);
          },
          onCancel: () => {
            modalService.hideOverwriteConfirm();
            resolve(false);
          }
        });
      });

      if (!userConfirmed) {
        // User cancelled - exit without pasting
        return;
      }

      // User confirmed - delete conflicting tubes first (atomic operation)
      const conflictingTubeIds = conflictingTubes.map(t => t.id);
      if (onDeleteTubes && conflictingTubeIds.length > 0) {
        await onDeleteTubes(conflictingTubeIds, true); // Silent delete - notification comes from paste
      }
    }

    // Call paste mutation
    if (onPasteTubes) {
      await onPasteTubes(tubesToPaste);
    }

    // Delete source tubes after successful paste (cut operation only)
    if (clipData.operation === 'cut') {
      const tubeIds = clipData.tubes.map(tube => tube.id).filter(Boolean);
      if (onDeleteTubes && tubeIds.length > 0) {
        // Silent delete - notification handled below
        await onDeleteTubes(tubeIds, true);
      }

      // Show moved notification for cut operations - Light Amber (matches cut)
      notifications.move(`Moved ${tubesToPaste.length} tube${tubesToPaste.length > 1 ? 's' : ''}`);
    } else {
      // Show pasted notification for copy operations - Icy Blue (matches copy)
      notifications.paste(`Pasted ${tubesToPaste.length} tube${tubesToPaste.length > 1 ? 's' : ''}`);
    }

    // Clear clipboard after successful paste (both copy and cut)
    setClipboard(null);
  }, [clipboard, selectedPositionsInThisBox, setClipboard, onPasteTubes, onDeleteTubes, ctx, getBox, tankId, rackId, boxId, modalService, tubes]);

  // Delete operation with confirmation modal
  const deleteSelectedTubes = React.useCallback(async () => {
    const positions = selectedPositionsInThisBox();
    if (positions.length === 0) return;

    const tubeIds = positions
      .map(position => resolveTube(position))
      .filter((tubeId): tubeId is string => tubeId !== null);

    if (tubeIds.length === 0) return;

    // Show delete confirmation modal (confirm before destructive action)
    modalService.showDeleteConfirm({
      title: `Delete ${tubeIds.length} Tube${tubeIds.length > 1 ? 's' : ''}`,
      message: `Are you sure you want to delete ${tubeIds.length} tube${tubeIds.length > 1 ? 's' : ''}? This action cannot be undone.`,
      onConfirm: async () => {
        if (onDeleteTubes) {
          await onDeleteTubes(tubeIds);
        }

        // Clear selection after successful delete
        onSelectionChange(new Set());

        // Close confirmation modal
        modalService.hideDeleteConfirm();
      },
      onCancel: () => {
        // Just close the modal, keep selection
        modalService.hideDeleteConfirm();
      }
    });
  }, [selectedPositionsInThisBox, resolveTube, onDeleteTubes, onSelectionChange, modalService]);

  // Mouse position handler
  const setMousePosition = (position: { x: number; y: number } | null) => {
    setMousePositionStore(position);
  };

  // Label methods for UI
  const getCopyLabel = () => {
    const count = selectedPositionsInThisBox().length;
    if (count === 0) return 'Copy';
    if (count === 1) return 'Copy Tube';
    return `Copy ${count} Tubes`;
  };

  const getCutLabel = () => {
    const count = selectedPositionsInThisBox().length;
    if (count === 0) return 'Cut';
    if (count === 1) return 'Cut Tube';
    return `Cut ${count} Tubes`;
  };

  const getPasteLabel = () => {
    const count = clipboard?.tubes?.length || 0;
    if (count === 0) return 'Paste';
    if (count === 1) return 'Paste Tube';
    return `Paste ${count} Tubes`;
  };

  // Action methods
  const actions = {
    select: (position: number) => {
      const positionKey = toPositionKey(ctx, position);
      const newSelection = new Set(selectedPositions);
      newSelection.add(positionKey);
      onSelectionChange(newSelection);
    },
    deselect: (position: number) => {
      const positionKey = toPositionKey(ctx, position);
      const newSelection = new Set(selectedPositions);
      newSelection.delete(positionKey);
      onSelectionChange(newSelection);
    },
    toggle: (position: number) => {
      const positionKey = toPositionKey(ctx, position);
      const newSelection = new Set(selectedPositions);
      if (newSelection.has(positionKey)) {
        newSelection.delete(positionKey);
      } else {
        newSelection.add(positionKey);
      }
      onSelectionChange(newSelection);
    },
    clear: () => {
      onSelectionChange(new Set());
    },
    add: () => {
      // Convert selected positions to array for add operation
      const positions = Array.from(selectedPositions);

      if (positions.length === 0) return;

      modalService.showTubeEditorModal({
        mode: 'add',
        positions,
        rackId,
        boxId
      });
    },
    edit: () => {
      // Get tube IDs from selected positions for batch edit
      const selectedTubeIds = Array.from(selectedPositions)
        .map(positionKey => {
          const { position } = parsePositionKey(positionKey);
          return resolveTube(position);
        })
        .filter((tubeId): tubeId is string => tubeId !== null);

      if (selectedTubeIds.length === 0) return;

      if (selectedTubeIds.length === 1) {
        modalService.showTubeEditorModal({
          mode: 'edit',
          tubeId: selectedTubeIds[0]
        });
      } else {
        modalService.showTubeEditorModal({
          mode: 'batch',
          tubeIds: selectedTubeIds,
          preserveSelection: true  // Maintain multi-selection after batch operation
        });
      }
    },
    copy,
    cut,
    paste,
    delete: deleteSelectedTubes,
  };

  // Grid context menu methods (domain-driven architecture)
  const showContextMenu = React.useCallback((x: number, y: number) => {
    setContextMenu({ isOpen: true, x, y });
  }, []);

  const hideContextMenu = React.useCallback(() => {
    setContextMenu({ isOpen: false, x: 0, y: 0 });
  }, []);

  return {
    handlePositionClick,
    handlePositionDoubleClick,
    handleBulkSelection,
    isPositionSelected,
    setMousePosition,
    openModal,
    copy,
    cut,
    paste,
    delete: deleteSelectedTubes,
    actions,
    // Grid selection operations state
    clipboard: {
      hasData: Boolean(clipboard?.tubes?.length),
      count: clipboard?.tubes?.length || 0,
      cutPositions: React.useMemo(() => {
        if (clipboard?.operation === 'cut') {
          return new Set(clipboard.tubes.map(tube => 
            toPositionKey(clipboard.sourceLocation || ctx, tube.location.position)
          ));
        }
        return new Set<PositionKey>();
      }, [clipboard, ctx]),
      copyPositions: React.useMemo(() => {
        if (clipboard?.operation === 'copy') {
          return new Set(clipboard.tubes.map(tube =>
            toPositionKey(clipboard.sourceLocation || ctx, tube.location.position)
          ));
        }
        return new Set<PositionKey>();
      }, [clipboard, ctx]),
    },
    // Grid context menu state
    contextMenu: {
      isOpen: contextMenu.isOpen,
      x: contextMenu.x,
      y: contextMenu.y,
      show: showContextMenu,
      hide: hideContextMenu,
    },
    // Grid selection state
    selection: {
      hasFilledSelection: selectionAnalysis.hasFilledSelection,
      isMixed: selectionAnalysis.isMixed,
      filledCount: selectionAnalysis.filledCount,
      emptyCount: selectionAnalysis.emptyCount,
    },
    getCopyLabel,
    getCutLabel,
    getPasteLabel,
  };
};

/**
 * useGridDragSelection Hook
 *
 * Rectangular drag selection with RAF throttling for performance.
 * Extracted from TubeGrid for reusability and testability.
 */

import { useState, useRef, useEffect, useCallback } from 'react';

import { getGridTotalPositions } from '@domains/storage';
import { useTubeStore } from '@domains/tubes';
import { toPositionKey, type PositionContext, type PositionKey } from '@shared/types/grid';
import { getPositionsInRectangle, positionToCoordinates } from '@shared/utils/coordinates';

import type { GridConfiguration } from '@odysseus/shared-schemas';

/**
 * Hook Props Interface
 */
export interface UseGridDragSelectionProps {
  gridConfig: GridConfiguration;
  selectedPositions: Set<PositionKey>;
  onSelectionChange: (positions: Set<PositionKey>) => void;
  ctx: PositionContext;
}

/**
 * Hook Return Interface
 */
export interface UseGridDragSelectionReturn {
  isDragging: boolean;
  dragPreview: Set<PositionKey>;
  handleMouseDown: (position: number, event: React.MouseEvent) => void;
  handleMouseMove: (position: number) => void;
}

/**
 * Custom hook for RAF-throttled rectangular drag selection
 *
 * @param props - Grid configuration and selection handlers
 * @returns Drag selection state and handlers
 */
export function useGridDragSelection(
  props: UseGridDragSelectionProps
): UseGridDragSelectionReturn {
  const { gridConfig, selectedPositions, onSelectionChange, ctx } = props;

  // Performance optimization: RAF throttling for drag selection
  const rafIdRef = useRef<number | null>(null);
  const pendingPositionRef = useRef<number | null>(null);

  // Use refs for transient drag state to prevent stale closures in RAF callbacks
  const dragStartPositionRef = useRef<number | null>(null);
  const isDragWithCtrlRef = useRef<boolean>(false);

  // UI-related state only
  const [isDragging, setIsDragging] = useState(false);
  const [dragPreview, setDragPreview] = useState<Set<PositionKey>>(new Set()); // CSS-only preview

  /**
   * Dynamic drag selection based on grid configuration
   */
  const handleMouseDown = useCallback((position: number, event: React.MouseEvent) => {
    if (event.button !== 0) return;
    dragStartPositionRef.current = position;
    isDragWithCtrlRef.current = event.ctrlKey;
  }, []);

  /**
   * Process selection preview (called by RAF throttle) - NO React state updates, just preview
   */
  const processSelectionUpdate = useCallback((position: number) => {
    // Read from ref (always latest) instead of captured state (stale in closures)
    const dragStart = dragStartPositionRef.current;
    const withCtrl = isDragWithCtrlRef.current;

    if (dragStart !== null && dragStart !== position) {
      if (!isDragging) {
        setIsDragging(true);
      }

      // Calculate rectangular selection using coordinate utilities
      const newSelection = new Set<PositionKey>();
      const startCoords = positionToCoordinates(dragStart, gridConfig.cols);
      const endCoords = positionToCoordinates(position, gridConfig.cols);
      const positionsInRectangle = getPositionsInRectangle(startCoords, endCoords, gridConfig.cols);

      positionsInRectangle.forEach((pos: number) => {
        if (pos >= 1 && pos <= getGridTotalPositions(gridConfig)) {
          newSelection.add(toPositionKey(ctx, pos));
        }
      });

      // Ctrl extends selection, otherwise replace
      if (withCtrl) {
        // Extend: Add drag selection to existing selection
        selectedPositions.forEach(key => newSelection.add(key));
      }
      // No Ctrl: newSelection already contains only drag rectangle (replaces existing)

      // PERFORMANCE: Only update preview state, NOT actual selection
      setDragPreview(newSelection);
      // Actual selection updated on mouseup
    }
    rafIdRef.current = null;
  }, [isDragging, gridConfig, selectedPositions, ctx]);

  /**
   * RAF-throttled mouse move handler
   */
  const handleMouseMove = useCallback((position: number) => {
    pendingPositionRef.current = position;

    if (rafIdRef.current === null) {
      const rafId = requestAnimationFrame(() => {
        if (pendingPositionRef.current !== null) {
          processSelectionUpdate(pendingPositionRef.current);
        }
      });
      rafIdRef.current = rafId;
    }
  }, [processSelectionUpdate]);

  /**
   * Cleanup RAF on unmount
   */
  useEffect(() => {
    return () => {
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
      }
    };
  }, []);

  /**
   * Handle mouse up to end drag and commit selection
   */
  useEffect(() => {
    const handleMouseUp = () => {
      // Cancel any pending RAF to prevent stale callbacks from firing
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
        rafIdRef.current = null;
      }
      pendingPositionRef.current = null;

      // Commit drag preview to actual selection
      if (isDragging && dragPreview.size > 0) {
        onSelectionChange(dragPreview);
        setDragPreview(new Set()); // Clear preview
      }

      // Update selection anchor to last position in drag for future Shift+Click
      if (isDragging && dragStartPositionRef.current !== null) {
        const { setSelectionAnchor } = useTubeStore.getState();
        setSelectionAnchor(dragStartPositionRef.current);
      }

      setIsDragging(false);
      dragStartPositionRef.current = null;
      isDragWithCtrlRef.current = false;
    };

    document.addEventListener('mouseup', handleMouseUp);
    return () => document.removeEventListener('mouseup', handleMouseUp);
  }, [isDragging, dragPreview, onSelectionChange]);

  return {
    isDragging,
    dragPreview,
    handleMouseDown,
    handleMouseMove
  };
}

/**
 * useGridFontSizing Hook
 *
 * Dynamic font size calculation based on grid dimensions and configuration.
 * Extracted from TubeGrid for reusability and testability.
 * Includes debounced resize handling for performance.
 */

import { useState, useEffect, type RefObject } from 'react';

import type { GridConfiguration } from '@odysseus/shared-schemas';

/**
 * Grid Font Sizes Interface
 */
export interface GridFontSizes {
  cellFont: number;
  donorFont: number;
  positionFont: number;
}

/**
 * Hook Props Interface
 */
export interface UseGridFontSizingProps {
  gridRef: RefObject<HTMLDivElement>;
  gridConfig: GridConfiguration;
}

/**
 * Hook Return Interface
 */
export interface UseGridFontSizingReturn {
  fontSize: GridFontSizes;
}

/**
 * Custom hook for dynamic grid font sizing
 *
 * Calculates optimal font sizes based on:
 * - Grid container dimensions
 * - Grid configuration (rows/cols)
 * - Responsive viewport changes
 *
 * Features:
 * - Automatic recalculation on resize (debounced)
 * - Scales appropriately for different grid sizes
 * - Maintains readable text at all sizes
 *
 * @param props - Grid ref and configuration
 * @returns Font sizes for different grid elements
 */
export function useGridFontSizing(
  props: UseGridFontSizingProps
): UseGridFontSizingReturn {
  const { gridRef, gridConfig } = props;

  const [fontSize, setFontSize] = useState<GridFontSizes>({
    cellFont: 10,
    donorFont: 8,
    positionFont: 8
  });

  /**
   * Calculate font sizes for all grid positions
   */
  useEffect(() => {
    const calculateFontSizes = () => {
      if (!gridRef.current) return;

      // Get grid container dimensions
      const rect = gridRef.current.getBoundingClientRect();
      const containerWidth = rect.width;
      const containerHeight = rect.height;

      // Calculate approximate cell size
      const cellWidth = containerWidth / gridConfig.cols;
      const cellHeight = containerHeight / gridConfig.rows;
      const containerSize = Math.min(cellWidth, cellHeight);

      // Base scaling factor from grid configuration (larger grids = smaller text)
      const gridScale = Math.max(0.7, Math.min(1.0, 9 / Math.max(gridConfig.rows, gridConfig.cols)));

      // Calculate font sizes based on container size and grid scale
      const baseFontSize = Math.max(9, Math.min(16, containerSize * 0.14 * gridScale));

      setFontSize({
        cellFont: Math.round(baseFontSize),
        donorFont: Math.round(baseFontSize * 0.8),
        positionFont: Math.round(baseFontSize * 0.85)
      });
    };

    calculateFontSizes();

    // Recalculate on window resize (debounced)
    let timeoutId: NodeJS.Timeout;
    const handleResize = () => {
      clearTimeout(timeoutId);
      timeoutId = setTimeout(calculateFontSizes, 100);
    };

    window.addEventListener('resize', handleResize);
    return () => {
      window.removeEventListener('resize', handleResize);
      clearTimeout(timeoutId);
    };
  }, [gridRef, gridConfig.rows, gridConfig.cols]);

  return {
    fontSize
  };
}

/**
 * useGridKeyboardNavigation Hook
 *
 * Keyboard navigation and shortcuts for grid components
 * Extracted from TubeGrid for reusability and testability
 */

import { useCallback } from 'react';

import { getGridTotalPositions } from '@domains/storage';
import { useTubeStore } from '@domains/tubes';
import { toPositionKey } from '@shared/types/grid';
import { getSelectionRange } from '@shared/utils/coordinates';

import type { GridConfiguration } from '@odysseus/shared-schemas';
import type { ClipboardData } from '@shared/types/clipboard';
import type { GridControllerReturn, PositionContext, PositionKey } from '@shared/types/grid';



/**
 * Hook Props Interface
 */
export interface UseGridKeyboardNavigationProps {
  gridConfig: GridConfiguration;
  focusedPosition: number;
  setFocusedPosition: (position: number) => void;
  selectedPositions: Set<PositionKey>;
  onSelectionChange: (positions: Set<PositionKey>) => void;
  controller: GridControllerReturn;
  ctx: PositionContext;
  setClipboard: (data: ClipboardData | null) => void;
}

/**
 * Hook Return Interface
 */
export interface UseGridKeyboardNavigationReturn {
  handleGridKeyDown: (event: React.KeyboardEvent) => void;
}

/**
 * Custom hook for grid keyboard navigation and shortcuts
 *
 * Implements industry-standard keyboard patterns:
 * - Arrow keys: Navigation (with wrapping)
 * - Shift+Arrow: Range selection
 * - Space: Toggle selection
 * - Enter: Open modal
 * - Delete: Delete selected
 * - Ctrl+A: Select all
 * - Escape: Clear selection and clipboard
 * - Ctrl+C/X/V: Copy/Cut/Paste
 *
 * @param props - Grid configuration, focus state, and action handlers
 * @returns Keyboard event handler
 */
export function useGridKeyboardNavigation(
  props: UseGridKeyboardNavigationProps
): UseGridKeyboardNavigationReturn {
  const {
    gridConfig,
    focusedPosition,
    setFocusedPosition,
    selectedPositions,
    onSelectionChange,
    controller,
    ctx,
    setClipboard
  } = props;

  /**
   * Handle keyboard shortcuts for grid navigation
   */
  const handleGridKeyDown = useCallback((event: React.KeyboardEvent) => {
    const { key, shiftKey, ctrlKey, metaKey } = event;

    // Arrow key navigation with wrapping (1D index pattern)
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(key)) {
      event.preventDefault();

      // Convert current position to 0-based index
      const currentIndex = focusedPosition - 1;
      let newIndex = currentIndex;

      // Apply movement based on arrow key
      switch (key) {
        case 'ArrowUp':
          newIndex = currentIndex - gridConfig.cols;
          break;
        case 'ArrowDown':
          newIndex = currentIndex + gridConfig.cols;
          break;
        case 'ArrowLeft':
          newIndex = currentIndex - 1;
          break;
        case 'ArrowRight':
          newIndex = currentIndex + 1;
          break;
      }

      // Apply wrapping using modulo (handles negative indices correctly)
      const totalPositions = getGridTotalPositions(gridConfig);
      newIndex = ((newIndex % totalPositions) + totalPositions) % totalPositions;

      // Convert back to 1-based position
      const newPosition = newIndex + 1;

      if (newPosition >= 1 && newPosition <= totalPositions) {
        setFocusedPosition(newPosition);

        // Shift+Arrow: Extend selection
        if (shiftKey) {
          const currentAnchor = useTubeStore.getState().selectionAnchor || focusedPosition;
          const rangePositions = getSelectionRange(currentAnchor, newPosition, gridConfig.cols);
          const newSelection = new Set<PositionKey>();
          rangePositions.forEach(pos => {
            newSelection.add(toPositionKey(ctx, pos));
          });
          onSelectionChange(newSelection);
          // Don't update anchor during range selection - keeps extending from original position
        } else {
          // Arrow without Shift: Move selection to new position
          const positionKey = toPositionKey(ctx, newPosition);
          onSelectionChange(new Set([positionKey]));
          useTubeStore.getState().setSelectionAnchor(newPosition);
        }
      }
      return;
    }

    // Space bar - toggle selection on focused position
    if (key === ' ') {
      event.preventDefault();
      controller.actions.toggle(focusedPosition);
      return;
    }

    // Enter key - open appropriate modal
    if (key === 'Enter') {
      event.preventDefault();
      if (selectedPositions.size > 0) {
        controller.openModal();
      } else {
        // If nothing selected, select focused position and open modal
        const positionKey = toPositionKey(ctx, focusedPosition);
        onSelectionChange(new Set([positionKey]));
        setTimeout(() => controller.openModal(), 0);
      }
      return;
    }

    // Delete key - delete selected tubes with confirmation
    if (key === 'Delete') {
      event.preventDefault();
      if (selectedPositions.size > 0) {
        void controller.actions.delete();
      }
      return;
    }

    // Ctrl+A / Cmd+A - select all
    if (key === 'a' && (ctrlKey || metaKey)) {
      event.preventDefault();
      const allPositions = new Set<PositionKey>();
      const totalPositions = getGridTotalPositions(gridConfig);
      for (let i = 1; i <= totalPositions; i++) {
        allPositions.add(toPositionKey(ctx, i));
      }
      onSelectionChange(allPositions);
      return;
    }

    // Escape - clear selection and clipboard
    if (key === 'Escape') {
      event.preventDefault();
      controller.actions.clear();
      setClipboard(null);
      return;
    }

    // Ctrl+C - Copy
    if (key === 'c' && (ctrlKey || metaKey)) {
      event.preventDefault();
      void controller.actions.copy();
      return;
    }

    // Ctrl+X - Cut
    if (key === 'x' && (ctrlKey || metaKey)) {
      event.preventDefault();
      void controller.actions.cut();
      return;
    }

    // Ctrl+V - Paste
    if (key === 'v' && (ctrlKey || metaKey)) {
      event.preventDefault();
      void (async () => {
        try {
          await controller.actions.paste();
        } catch (error) {
          console.error('Paste operation failed:', error);
          // Error notification already shown by paste handler
        }
      })();
      return;
    }
  }, [
    focusedPosition,
    selectedPositions,
    controller,
    gridConfig,
    ctx,
    onSelectionChange,
    setFocusedPosition,
    setClipboard
  ]);

  return {
    handleGridKeyDown
  };
}

/**
 * Grid Position Hook
 * Manages grid position state and mouse position coordination
 */

import { useGridUiStore } from '@shared/stores/gridUiStore';

interface GridPositionProps {
  _tankId: string;
  _rackId: string;
  _boxId: string;
  gridSize: number;
  onPositionChange?: (position: number) => void;
}

interface GridPositionReturn {
  currentPosition: number | null;
  setPosition: (position: number) => void;
  setMousePosition: (position: { x: number; y: number } | null) => void;
  validatePosition: (position: number) => boolean;
}

export const useGridPosition = ({
  _tankId,
  _rackId,
  _boxId,
  gridSize,
  onPositionChange
}: GridPositionProps): GridPositionReturn => {
  const { setMousePosition: setMousePositionStore } = useGridUiStore();

  const setPosition = (position: number) => {
    onPositionChange?.(position);
  };

  const setMousePosition = (position: { x: number; y: number } | null) => {
    setMousePositionStore(position);
  };

  const validatePosition = (position: number) => {
    return position >= 1 && position <= gridSize * gridSize;
  };

  return {
    currentPosition: null,
    setPosition,
    setMousePosition,
    validatePosition
  };
};

