 * Application Hooks
 */

export * from './useFieldResolver';
export * from './useFieldResolverQuery';
export * from './useSimpleFieldResolver';
export * from './useTubesWithFieldResolver';

/**
 * Field Resolver React Hook - Application Layer
 * 
 * Application layer integration that provides React components with access to
 * the field resolution domain service. This hook abstracts the domain service
 * complexity and provides a React-friendly interface for field access.
 * 
 * Architecture Benefits:
 * - Clean separation between domain logic and presentation layer
 * - Consistent field access patterns across all React components
 * - Centralized dependency injection for field resolution service
 * - Performance optimization through memoization and caching
 * - Type-safe field access with TypeScript integration
 */

import { useCallback, useMemo, useRef } from 'react';

import { 
  TubeFieldAccessService 
} from '@domains/tubes/services/TubeFieldAccessService';
import { env } from '@shared/config';
import { DomainError } from '@shared/domain/errors/DomainError';


import { 
  getFieldResolverApplicationService 
} from '../services/FieldResolverService';

import type {
  FieldResolver,
  FieldResolutionOptions,
  FieldResolutionResult
} from '@domains/tubes/types/FieldResolver';
import type { ValidTubeFieldKey } from '@infra/configuration/fieldPathMapping';
import type { TubeData } from '@shared/types/tubeTypes';

/**
 * Hook configuration options
 */
export interface UseFieldResolverOptions {
  /** Custom field resolver instance (for testing or specialized configurations) */
  resolver?: FieldResolver;
  /** Enable performance monitoring and logging */
  enableMetrics?: boolean;
  /** Default options for field resolution */
  defaultResolutionOptions?: FieldResolutionOptions;
}

/**
 * Hook return interface - React-optimized field resolution API
 * Extends FieldResolver to ensure full compatibility
 */
export interface FieldResolverHook extends FieldResolver {
  /** Resolve a single field value from tube data */
  getValue: <T = any>(
    tube: TubeData, 
    fieldKey: ValidTubeFieldKey | string, 
    options?: FieldResolutionOptions
  ) => T | undefined;
  
  /** Resolve field values from multiple tube data objects */
  getValues: <T = any>(
    tubes: TubeData[], 
    fieldKey: ValidTubeFieldKey | string, 
    options?: FieldResolutionOptions
  ) => (T | undefined)[];
  
  /** Check if a field has a meaningful value */
  hasValue: (
    tube: TubeData, 
    fieldKey: ValidTubeFieldKey | string
  ) => boolean;
  
  /** Get detailed field resolution information */
  resolveField: <T = any>(
    tube: TubeData, 
    fieldKey: ValidTubeFieldKey | string
  ) => FieldResolutionResult<T>;
  
  /** Get the nested path for a field key */
  getFieldPath: (fieldKey: ValidTubeFieldKey | string) => string;
  
  /** Check if a field key is valid */
  isValidField: (fieldKey: string) => boolean;
  
  /** Get all available field keys */
  getAvailableFields: () => string[];
  
  /** Access to the underlying resolver instance */
  resolver: FieldResolver;
  
  /** Performance metrics (if enabled) */
  metrics?: ReturnType<TubeFieldAccessService['getPerformanceMetrics']>;
}

/**
 * React Hook: useFieldResolver
 * 
 * Provides React components with access to field resolution capabilities.
 * Automatically handles memoization and performance optimization for React
 * rendering cycles.
 * 
 * Usage Examples:
 * ```tsx
 * function TubeDisplay({ tube }: { tube: TubeData }) {
 *   const { getValue, hasValue } = useFieldResolver();
 *   
 *   const cellType = getValue(tube, 'cellType');
 *   const hasConcentration = hasValue(tube, 'concentration');
 *   
 *   return (
 *     <div>
 *       <div>Cell Type: {cellType || 'Unknown'}</div>
 *       {hasConcentration && <div>Has concentration data</div>}
 *     </div>
 *   );
 * }
 * ```
 */
export function useFieldResolver(
  options: UseFieldResolverOptions = {}
): FieldResolverHook {
  const {
    resolver: customResolver,
    enableMetrics = false,
    defaultResolutionOptions = {}
  } = options;

  // Get resolver instance (memoized for performance)
  const resolver = useMemo(() => {
    if (customResolver) {
      return customResolver;
    }
    
    try {
      // Use the properly initialized field resolver service
      const fieldResolverService = getFieldResolverApplicationService();
      return fieldResolverService.getFieldResolver();
    } catch (error) {
      throw new DomainError(
        'Field resolver system not initialized. Ensure bootstrap process completed before using useFieldResolver.',
        'RESOLVER_NOT_INITIALIZED',
        { originalError: error }
      );
    }
  }, [customResolver]);

  // Ref to track if metrics are enabled (avoid re-creating callbacks)
  const metricsEnabledRef = useRef(enableMetrics);
  metricsEnabledRef.current = enableMetrics;

  // Memoized getValue function with default options merged
  const getValue = useCallback(<T = any>(
    tube: TubeData, 
    fieldKey: ValidTubeFieldKey | string, 
    options: FieldResolutionOptions = {}
  ): T | undefined => {
    const mergedOptions = { ...defaultResolutionOptions, ...options };
    
    try {
      return resolver.getValue<T>(tube, fieldKey, mergedOptions);
    } catch (error) {
      // In React context, we generally want to handle errors gracefully
      if (env.isDev()) {
        console.warn(`Field resolution failed for key '${fieldKey}':`, error);
      }
      
      // Return default value instead of throwing in React components
      return mergedOptions.defaultValue as T;
    }
  }, [resolver, defaultResolutionOptions]);

  // Memoized getValues function for bulk operations
  const getValues = useCallback(<T = any>(
    tubes: TubeData[], 
    fieldKey: ValidTubeFieldKey | string, 
    options: FieldResolutionOptions = {}
  ): (T | undefined)[] => {
    const mergedOptions = { ...defaultResolutionOptions, ...options };
    
    try {
      return resolver.getValues<T>(tubes, fieldKey, mergedOptions);
    } catch (error) {
      if (env.isDev()) {
        console.warn(`Bulk field resolution failed for key '${fieldKey}':`, error);
      }
      
      // Return array of default values on error
      return tubes.map(() => mergedOptions.defaultValue as T);
    }
  }, [resolver, defaultResolutionOptions]);

  // Memoized hasValue function
  const hasValue = useCallback((
    tube: TubeData, 
    fieldKey: ValidTubeFieldKey | string
  ): boolean => {
    try {
      return resolver.hasValue(tube, fieldKey);
    } catch (error) {
      if (env.isDev()) {
        console.warn(`hasValue check failed for key '${fieldKey}':`, error);
      }
      return false;
    }
  }, [resolver]);

  // Memoized resolveField function for detailed resolution
  const resolveField = useCallback(<T = any>(
    tube: TubeData, 
    fieldKey: ValidTubeFieldKey | string
  ): FieldResolutionResult<T> => {
    try {
      return resolver.resolveField<T>(tube, fieldKey);
    } catch (error) {
      if (env.isDev()) {
        console.warn(`Field resolution details failed for key '${fieldKey}':`, error);
      }
      
      return {
        value: undefined,
        resolved: false,
        resolvedPath: '',
        exists: false
      };
    }
  }, [resolver]);

  // Memoized getFieldPath function
  const getFieldPath = useCallback((
    fieldKey: ValidTubeFieldKey | string
  ): string => {
    try {
      return resolver.getFieldPath(fieldKey);
    } catch (error) {
      if (env.isDev()) {
        console.warn(`getFieldPath failed for key '${fieldKey}':`, error);
      }
      return fieldKey; // Fallback to field key itself
    }
  }, [resolver]);

  // Memoized isValidField function
  const isValidField = useCallback((fieldKey: string): boolean => {
    return resolver.isValidField(fieldKey);
  }, [resolver]);

  // Memoized getAvailableFields function
  const getAvailableFields = useCallback((): string[] => {
    return resolver.getAvailableFields();
  }, [resolver]);

  // Get performance metrics if enabled and supported
  const metrics = useMemo(() => {
    if (!enableMetrics) return undefined;
    
    if (resolver instanceof TubeFieldAccessService) {
      return resolver.getPerformanceMetrics();
    }
    
    return undefined;
  }, [resolver, enableMetrics]);

  return {
    getValue,
    getValues,
    hasValue,
    resolveField,
    getFieldPath,
    isValidField,
    getAvailableFields,
    validateConfiguration: () => resolver.validateConfiguration(),
    resolver,
    metrics
  };
}

/**
 * Field Resolver Props Interface
 * For components that need field resolver capabilities through props
 */
export interface WithFieldResolverProps {
  fieldResolver: FieldResolverHook;
}

/**
 * Development utilities for debugging field resolution
 */
export const FieldResolverDevUtils = {
  /**
   * Log all field resolutions for a tube (development only)
   */
  logAllFields(
    tube: TubeData, 
    resolver: FieldResolverHook,
    prefix: string = 'Field Resolution'
  ): void {
    if (!env.isDev()) return;
    
    const fields = resolver.getAvailableFields();
    const results: Record<string, any> = {};
    
    fields.forEach(fieldKey => {
      const resolution = resolver.resolveField(tube, fieldKey);
      results[fieldKey] = {
        value: resolution.value,
        resolved: resolution.resolved,
        path: resolution.resolvedPath,
        exists: resolution.exists
      };
    });
    
    console.group(`${prefix} - Tube ID: ${tube.id}`);
    console.table(results);
    console.groupEnd();
  },
  
  /**
   * Validate that all expected fields can be resolved
   */
  validateFieldResolution(
    tube: TubeData,
    resolver: FieldResolverHook,
    expectedFields: (ValidTubeFieldKey | string)[]
  ): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    
    expectedFields.forEach(fieldKey => {
      if (!resolver.isValidField(fieldKey)) {
        errors.push(`Invalid field key: ${fieldKey}`);
        return;
      }
      
      try {
        const resolution = resolver.resolveField(tube, fieldKey);
        if (!resolution.resolved && resolution.exists) {
          errors.push(`Field '${fieldKey}' exists but could not be resolved`);
        }
      } catch (error) {
        errors.push(`Field '${fieldKey}' threw error: ${error instanceof Error ? error.message : String(error)}`);
      }
    });
    
    return {
      valid: errors.length === 0,
      errors
    };
  }
};

/**
 * React Query + Field Resolver Integration Hook - Phase 1
 * 
 * Combines React Query server state management with simple field resolver
 * for unified, type-safe data access patterns.
 * 
 * This replaces the legacy field resolver system with a lightweight,
 * Zod-compatible implementation focused on Phase 1 needs.
 */

import { useMemo } from 'react';

import { formatResearcherDropdownDisplay } from '@odysseus/shared-schemas';

import { useActiveResearchersQuery } from '@domains/researchers';
import { useTubesQuery } from '@domains/tubes/hooks/useTubesQuery';

import { useSimpleFieldResolver, type SimpleFieldResolver } from './useSimpleFieldResolver';

import type { Researcher } from '@odysseus/shared-schemas';
import type { TubeData } from '@shared/types/tubeTypes';


/**
 * Enhanced data access interface combining React Query with field resolution
 */
export interface UseFieldResolverQueryResult extends SimpleFieldResolver {
  /** React Query tubes data with field resolver integration */
  tubes: {
    data: TubeData[] | undefined;
    isLoading: boolean;
    error: Error | null;
    refetch: () => void;
    /** Get field values from all tubes */
    getFieldValues: <T>(fieldPath: string) => T[];
    /** Find tubes where field has specific value */
    findByFieldValue: <T>(fieldPath: string, value: T) => TubeData[];
    /** Get unique values for a field across all tubes */
    getUniqueFieldValues: <T>(fieldPath: string) => T[];
    /** Analyze conflicts in selected tubes */
    analyzeConflicts: <T>(selectedTubes: TubeData[], fieldPath: string) => {
      hasConflict: boolean;
      values: (T | undefined)[];
      commonValue: T | undefined;
      totalSelected: number;
      withValue: number;
    };
    /** Check if any of the specified fields have conflicts across selected tubes */
    hasAnyConflicts: (selectedTubes: TubeData[], fieldPaths: string[]) => boolean;
  };

  /** React Query researchers data */
  researchers: {
    data: Researcher[] | undefined;
    isLoading: boolean;
    error: Error | null;
    refetch: () => void;
    /** Get active researchers only */
    activeResearchers: Researcher[];
    /** Find researcher by name (case insensitive) */
    findByName: (name: string) => Researcher | undefined;
    /** Get all researcher names sorted */
    getNames: () => string[];
  };

  /** Combined loading state */
  isLoading: boolean;

  /** Combined error state */
  hasErrors: boolean;
  errors: (Error | null)[];
}

/**
 * Hook that combines React Query data fetching with field resolver capabilities
 * 
 * Usage:
 * ```tsx
 * function TubeAnalysisPanel() {
 *   const { tubes, getTubeValue, researchers } = useFieldResolverQuery();
 *   
 *   if (tubes.isLoading) return <LoadingSpinner />;
 *   
 *   const cellTypes = tubes.getUniqueFieldValues('sample.cellType');
 *   const tcells = tubes.findByFieldValue('sample.cellType', 'T-cells');
 *   
 *   return (
 *     <div>
 *       <h3>Cell Types: {cellTypes.join(', ')}</h3>
 *       <p>T-cells count: {tcells.length}</p>
 *     </div>
 *   );
 * }
 * ```
 */
export function useFieldResolverQuery(): UseFieldResolverQueryResult {
  // Get React Query data
  const tubesQuery = useTubesQuery();
  const researchersQuery = useActiveResearchersQuery();

  // Get simple field resolver capabilities
  const fieldResolver = useSimpleFieldResolver();

  // Enhanced tube utilities
  const tubeUtils = useMemo(() => {
    const tubes = tubesQuery.data ?? [];

    return {
      data: tubesQuery.data,
      isLoading: tubesQuery.isLoading,
      error: tubesQuery.error,
      refetch: tubesQuery.refetch,

      getFieldValues: <T>(fieldPath: string): T[] => {
        return fieldResolver.getTubeValues<T>(tubes, fieldPath).filter(v => v !== undefined) as T[];
      },

      findByFieldValue: <T>(fieldPath: string, value: T): TubeData[] => {
        return fieldResolver.findTubesByFieldValue(tubes, fieldPath, value);
      },

      getUniqueFieldValues: <T>(fieldPath: string): T[] => {
        return fieldResolver.getUniqueTubeValues<T>(tubes, fieldPath);
      },

      analyzeConflicts: <T>(selectedTubes: TubeData[], fieldPath: string) => {
        return fieldResolver.analyzeFieldConflicts<T>(selectedTubes, fieldPath);
      },

      /** Check if any of the specified fields have conflicts across selected tubes */
      hasAnyConflicts: (selectedTubes: TubeData[], fieldPaths: string[]): boolean => {
        if (selectedTubes.length <= 1) return false;
        return fieldPaths.some(fieldPath =>
          fieldResolver.analyzeFieldConflicts(selectedTubes, fieldPath).hasConflict
        );
      }
    };
  }, [tubesQuery, fieldResolver]);

  // Enhanced researcher utilities
  const researcherUtils = useMemo(() => {
    const researchers = researchersQuery.data ?? [];

    return {
      data: researchersQuery.data,
      isLoading: researchersQuery.isLoading,
      error: researchersQuery.error,
      refetch: researchersQuery.refetch,

      activeResearchers: researchers, // Already filtered to active only

      findByName: (name: string) => {
        return researchers.find(r => {
          const fullName = formatResearcherDropdownDisplay(r);
          return fullName.toLowerCase().includes(name.toLowerCase());
        });
      },

      getNames: () => {
        return researchers.map(r => formatResearcherDropdownDisplay(r)).sort();
      }
    };
  }, [researchersQuery]);

  // Combined loading and error states
  const isLoading = tubesQuery.isLoading || researchersQuery.isLoading;
  const errors = useMemo(() => [tubesQuery.error, researchersQuery.error], [tubesQuery.error, researchersQuery.error]);
  const hasErrors = errors.some(error => error !== null);

  return useMemo(() => ({
    // Simple field resolver capabilities
    ...fieldResolver,

    // Enhanced data access
    tubes: tubeUtils,
    researchers: researcherUtils,

    // Combined states
    isLoading,
    hasErrors,
    errors
  }), [fieldResolver, tubeUtils, researcherUtils, isLoading, hasErrors, errors]);
}

/**
 * Lightweight version focused only on tubes with field resolution
 */
export function useFieldResolverTubes() {
  const tubesQuery = useTubesQuery();
  const fieldResolver = useSimpleFieldResolver();

  return useMemo(() => {
    const tubes = tubesQuery.data ?? [];

    return {
      // React Query state
      tubes: tubesQuery.data,
      isLoading: tubesQuery.isLoading,
      error: tubesQuery.error,
      refetch: tubesQuery.refetch,

      // Field resolver functions
      getValue: fieldResolver.getTubeValue,
      getValues: fieldResolver.getTubeValues,
      hasValue: fieldResolver.tubeHasValue,
      
      // Field-based utilities
      getFieldValues: <T>(fieldPath: string): T[] => {
        return fieldResolver.getTubeValues<T>(tubes, fieldPath).filter(v => v !== undefined) as T[];
      },

      findByFieldValue: <T>(fieldPath: string, value: T): TubeData[] => {
        return fieldResolver.findTubesByFieldValue(tubes, fieldPath, value);
      },

      getUniqueFieldValues: <T>(fieldPath: string): T[] => {
        return fieldResolver.getUniqueTubeValues<T>(tubes, fieldPath);
      },

      // Conflict analysis for TubeInfoPanel
      analyzeFieldConflicts: <T>(selectedTubes: TubeData[], fieldPath: string) => {
        return fieldResolver.analyzeFieldConflicts<T>(selectedTubes, fieldPath);
      }
    };
  }, [tubesQuery, fieldResolver]);
}

/**
 * Simple Field Resolver Hook - Phase 1 Implementation
 *
 * A lightweight field resolver that works with our new Zod-based data structures.
 * Provides dynamic field access without the complexity of the legacy system.
 */

import { useCallback, useMemo } from 'react';

import { normalizeDateString } from '@shared/utils/dateUtils';

import type { TubeData } from '@shared/types/tubeTypes';

/**
 * Two-state conflict analysis result
 * Treats empty as a distinct value - empty vs filled = conflict
 */
export interface FieldConflictAnalysis<T = any> {
  /** State of the field across selected items */
  state: 'common' | 'conflict';

  /** Whether field has conflicting values (backward compatibility) */
  hasConflict: boolean;

  /** Common value if state is 'common', undefined if 'conflict' */
  commonValue: T | undefined;

  /** All unique values found (including empty treated as distinct value) */
  values: (T | undefined)[];

  /** Total number of items analyzed */
  totalSelected: number;

  /** Count of items with non-empty values */
  withValue: number;

  /** Count of items with empty values */
  withoutValue: number;

  /** Distribution of values (value -> count) */
  distribution: Map<T | undefined, number>;
}

/**
 * Simple field resolver interface
 */
export interface SimpleFieldResolver {
  /** Get a field value from tube data using dot notation */
  getTubeValue: <T = any>(tube: TubeData, fieldPath: string) => T | undefined;

  /** Get field values from multiple tubes */
  getTubeValues: <T = any>(tubes: TubeData[], fieldPath: string) => (T | undefined)[];

  /** Check if a tube has a meaningful value for a field */
  tubeHasValue: (tube: TubeData, fieldPath: string) => boolean;

  /** Get unique values for a field across all tubes */
  getUniqueTubeValues: <T = any>(tubes: TubeData[], fieldPath: string) => T[];

  /** Find tubes where field has specific value */
  findTubesByFieldValue: <T = any>(tubes: TubeData[], fieldPath: string, value: T) => TubeData[];

  /** Analyze field conflicts in selected tubes using three-state model */
  analyzeFieldConflicts: <T = any>(tubes: TubeData[], fieldPath: string) => FieldConflictAnalysis<T>;
}

/**
 * Get nested property value using dot notation
 */
function getNestedValue(obj: any, path: string): any {
  if (!obj || !path) return undefined;
  
  return path.split('.').reduce((current, key) => {
    return current && typeof current === 'object' ? current[key] : undefined;
  }, obj);
}

/**
 * Check if a value is meaningful (not null, undefined, or empty string)
 */
function hasValue(value: any): boolean {
  return value !== undefined && value !== null && value !== '';
}

/**
 * Hook providing simple field resolution for new Zod-based data structures
 */
export function useSimpleFieldResolver(): SimpleFieldResolver {
  const getTubeValue = useCallback(<T = any>(tube: TubeData, fieldPath: string): T | undefined => {
    try {
      return getNestedValue(tube, fieldPath) as T;
    } catch (error) {
      console.warn(`Failed to get tube value for field '${fieldPath}':`, error);
      return undefined;
    }
  }, []);

  const getTubeValues = useCallback(<T = any>(tubes: TubeData[], fieldPath: string): (T | undefined)[] => {
    return tubes.map(tube => getTubeValue<T>(tube, fieldPath));
  }, [getTubeValue]);

  const tubeHasValue = useCallback((tube: TubeData, fieldPath: string): boolean => {
    const value = getTubeValue(tube, fieldPath);
    return hasValue(value);
  }, [getTubeValue]);

  const getUniqueTubeValues = useCallback(<T = any>(tubes: TubeData[], fieldPath: string): T[] => {
    const allValues = getTubeValues<T>(tubes, fieldPath);
    const filteredValues = allValues.filter((value): value is T => 
      value !== undefined && value !== null && value !== ''
    );
    const uniqueValues = filteredValues.filter((value, index, array) => 
      array.indexOf(value) === index
    );
    return uniqueValues;
  }, [getTubeValues]);

  const findTubesByFieldValue = useCallback(<T = any>(
    tubes: TubeData[], 
    fieldPath: string, 
    value: T
  ): TubeData[] => {
    return tubes.filter(tube => {
      const fieldValue = getTubeValue<T>(tube, fieldPath);
      return fieldValue === value;
    });
  }, [getTubeValue]);

  const analyzeFieldConflicts = useCallback(<T = any>(
    tubes: TubeData[],
    fieldPath: string
  ): FieldConflictAnalysis<T> => {
    if (tubes.length === 0) {
      return {
        state: 'common',
        hasConflict: false,
        values: [],
        commonValue: undefined,
        totalSelected: 0,
        withValue: 0,
        withoutValue: 0,
        distribution: new Map()
      };
    }

    const allValues = getTubeValues<T>(tubes, fieldPath);

    // Count empty vs non-empty (for metadata only)
    const nonEmptyValues = allValues.filter((value): value is T => hasValue(value));
    const emptyCount = allValues.length - nonEmptyValues.length;

    // Special handling for date fields to avoid timezone comparison bugs
    const isDateField = fieldPath === 'sample.date' || fieldPath.endsWith('.date');

    let normalizedValues: (T | undefined)[];
    const distribution = new Map<T | undefined, number>();

    if (isDateField) {
      // Normalize all dates to YYYY-MM-DD strings for comparison
      normalizedValues = allValues.map(v =>
        hasValue(v) ? (normalizeDateString(v as any) as T) : undefined
      );
    } else {
      // Use raw values for non-date fields
      normalizedValues = allValues.map(v => hasValue(v) ? v : undefined);
    }

    // Build distribution map (including undefined for empty values)
    normalizedValues.forEach(value => {
      distribution.set(value, (distribution.get(value) || 0) + 1);
    });

    // Two-state logic: All identical = COMMON, any difference = CONFLICT
    const uniqueValues = Array.from(new Set(normalizedValues));

    let state: 'common' | 'conflict';
    let commonValue: T | undefined;

    if (uniqueValues.length === 1) {
      // All values are identical (including all empty)
      state = 'common';
      commonValue = uniqueValues[0];
    } else {
      // Values differ (including empty vs non-empty)
      state = 'conflict';
      commonValue = undefined;
    }

    return {
      state,
      hasConflict: state === 'conflict',
      values: uniqueValues,
      commonValue,
      totalSelected: tubes.length,
      withValue: nonEmptyValues.length,
      withoutValue: emptyCount,
      distribution
    };
  }, [getTubeValues]);

  return useMemo(() => ({
    getTubeValue,
    getTubeValues,
    tubeHasValue,
    getUniqueTubeValues,
    findTubesByFieldValue,
    analyzeFieldConflicts
  }), [
    getTubeValue,
    getTubeValues,
    tubeHasValue,
    getUniqueTubeValues,
    findTubesByFieldValue,
    analyzeFieldConflicts
  ]);
}

/**
 * Common field paths for tube data (for type safety)
 */
export const TUBE_FIELD_PATHS = {
  // Location fields
  tankId: 'location.tankId',
  rackId: 'location.rackId',
  boxId: 'location.boxId',
  position: 'location.position',
  
  // Sample fields
  cellType: 'sample.cellType',
  donorInternalId: 'sample.donorInternalId',
  donorSourceId: 'sample.donorSourceId',
  concentration: 'sample.concentration',
  concentrationUnit: 'sample.concentrationUnit',
  date: 'sample.date',
  media: 'sample.media',
  cultureCondition: 'sample.cultureCondition',
  lotNumber: 'sample.lotNumber',
  notes: 'sample.notes',

  // Researcher ID (foreign key)
  researcherId: 'researcherId',

  // Timestamps
  createdAt: 'timestamps.createdAt',
  updatedAt: 'timestamps.updatedAt',
} as const;

export type TubeFieldPath = typeof TUBE_FIELD_PATHS[keyof typeof TUBE_FIELD_PATHS];

/**
 * Type-safe tube field resolver
 */
export interface TypeSafeTubeResolver {
  getValue<K extends keyof typeof TUBE_FIELD_PATHS>(tube: TubeData, field: K): any;
  getValues<K extends keyof typeof TUBE_FIELD_PATHS>(tubes: TubeData[], field: K): any[];
  hasValue<K extends keyof typeof TUBE_FIELD_PATHS>(tube: TubeData, field: K): boolean;
}

/**
 * Hook providing type-safe field resolution using predefined paths
 */
export function useTypeSafeTubeResolver(): TypeSafeTubeResolver {
  const { getTubeValue, getTubeValues, tubeHasValue } = useSimpleFieldResolver();
  
  return useMemo(() => ({
    getValue: <K extends keyof typeof TUBE_FIELD_PATHS>(tube: TubeData, field: K) => {
      return getTubeValue(tube, TUBE_FIELD_PATHS[field]);
    },
    getValues: <K extends keyof typeof TUBE_FIELD_PATHS>(tubes: TubeData[], field: K) => {
      return getTubeValues(tubes, TUBE_FIELD_PATHS[field]);
    },
    hasValue: <K extends keyof typeof TUBE_FIELD_PATHS>(tube: TubeData, field: K) => {
      return tubeHasValue(tube, TUBE_FIELD_PATHS[field]);
    }
  }), [getTubeValue, getTubeValues, tubeHasValue]);
}

/**
 * Simplified React Query + Field Resolver Integration Hook - Phase 1
 * 
 * Provides tubes data from React Query with simple field resolver capabilities.
 * Uses the new simple field resolver that works with Zod schemas.
