/**
 * MODAL STORE
 * 
 * Declarative modal API with complete lifecycle management.
 * Replaces old Zustand-based system with type-safe, scalable architecture.
 */

import { create } from 'zustand';

import { type PositionKey } from '@shared/types/grid';

interface DeleteConfirmState {
  isOpen: boolean;
  title: string;
  message: string;
  onConfirm: () => void;
  onCancel: () => void;
  previousFocusElement?: HTMLElement | null;
}

interface OverwriteConfirmState {
  isOpen: boolean;
  title: string;
  message: string;
  confirmText?: string;
  onConfirm: () => void;
  onCancel: () => void;
  previousFocusElement?: HTMLElement | null;
}

interface TubeEditorModalState {
  isOpen: boolean;
  mode: 'add' | 'edit' | 'batch';
  tubeId?: string;        // Single edit mode - tube ID only
  tubeIds?: string[];     // Batch edit mode - tube IDs only
  positions?: PositionKey[];   // Add mode - position keys
  rackId?: string;
  boxId?: string;
  previousFocusElement?: HTMLElement | null;
  preserveSelection?: boolean;  // Don't restore focus to specific position (for batch operations)
}

interface LocalModalState {
  deleteConfirm: DeleteConfirmState;
  overwriteConfirm: OverwriteConfirmState;
  tubeEditorModal: TubeEditorModalState;
}

interface ModalActions {
  showDeleteConfirm: (config: {
    title: string;
    message: string;
    onConfirm: () => void;
    onCancel?: () => void;
  }) => void;
  hideDeleteConfirm: () => void;

  showOverwriteConfirm: (config: {
    title: string;
    message: string;
    confirmText?: string;
    onConfirm: () => void;
    onCancel?: () => void;
  }) => void;
  hideOverwriteConfirm: () => void;

  showTubeEditorModal: (config: {
    mode: 'add' | 'edit' | 'batch';
    tubeId?: string;        // Single edit mode
    tubeIds?: string[];     // Batch edit mode
    positions?: PositionKey[];   // Add mode
    rackId?: string;
    boxId?: string;
    preserveSelection?: boolean;  // Don't restore focus to specific position (for batch operations)
  }) => void;
  hideTubeEditorModal: () => void;

  hideAllModals: () => void;
}

const initialDeleteConfirm: DeleteConfirmState = {
  isOpen: false,
  title: '',
  message: '',
  onConfirm: () => {},
  onCancel: () => {}
};

const initialOverwriteConfirm: OverwriteConfirmState = {
  isOpen: false,
  title: '',
  message: '',
  onConfirm: () => {},
  onCancel: () => {}
};

const initialTubeEditorModal: TubeEditorModalState = {
  isOpen: false,
  mode: 'add'
};

/**
 * Global modal store
 */
const modalStore = create<LocalModalState & ModalActions>((set, get) => ({
  // Initial state
  deleteConfirm: initialDeleteConfirm,
  overwriteConfirm: initialOverwriteConfirm,
  tubeEditorModal: initialTubeEditorModal,

  // Delete confirmation actions
  showDeleteConfirm: (config) => {
    // Capture focus BEFORE modal opens (before React renders)
    const previousFocusElement = document.activeElement as HTMLElement;

    set({
      deleteConfirm: {
        isOpen: true,
        title: config.title,
        message: config.message,
        onConfirm: config.onConfirm,
        onCancel: config.onCancel || (() => get().hideDeleteConfirm()),
        previousFocusElement
      }
    });
  },

  hideDeleteConfirm: () => {
    set({ deleteConfirm: initialDeleteConfirm });
  },

  // Overwrite confirmation actions
  showOverwriteConfirm: (config) => {
    // Capture focus BEFORE modal opens (before React renders)
    const previousFocusElement = document.activeElement as HTMLElement;

    set({
      overwriteConfirm: {
        isOpen: true,
        title: config.title,
        message: config.message,
        confirmText: config.confirmText,
        onConfirm: config.onConfirm,
        onCancel: config.onCancel || (() => get().hideOverwriteConfirm()),
        previousFocusElement
      }
    });
  },

  hideOverwriteConfirm: () => {
    set({ overwriteConfirm: initialOverwriteConfirm });
  },

  // Tube modal actions
  showTubeEditorModal: (config) => {
    // Capture focus BEFORE modal opens (before React renders)
    // For batch operations with preserveSelection, don't capture focus element
    const previousFocusElement = config.preserveSelection
      ? null
      : document.activeElement as HTMLElement;

    set({
      tubeEditorModal: {
        isOpen: true,
        mode: config.mode,
        tubeId: config.tubeId,
        tubeIds: config.tubeIds,
        positions: config.positions,
        rackId: config.rackId,
        boxId: config.boxId,
        previousFocusElement,
        preserveSelection: config.preserveSelection
      }
    });
  },

  hideTubeEditorModal: () => {
    set({ tubeEditorModal: initialTubeEditorModal });
  },

  // Utility to hide all modals
  hideAllModals: () => {
    set({
      deleteConfirm: initialDeleteConfirm,
      overwriteConfirm: initialOverwriteConfirm,
      tubeEditorModal: initialTubeEditorModal
    });
  }
}));

/**
 * Hook for accessing modal store
 */
export const useModalStore = () => {
  const state = modalStore();
  
  return {
    // State
    deleteConfirm: state.deleteConfirm,
    overwriteConfirm: state.overwriteConfirm,
    tubeEditorModal: state.tubeEditorModal,
    
    // Actions
    showDeleteConfirm: state.showDeleteConfirm,
    hideDeleteConfirm: state.hideDeleteConfirm,
    showOverwriteConfirm: state.showOverwriteConfirm,
    hideOverwriteConfirm: state.hideOverwriteConfirm,
    showTubeEditorModal: state.showTubeEditorModal,
    hideTubeEditorModal: state.hideTubeEditorModal,
    hideAllModals: state.hideAllModals
  };
};

import { useState } from 'react';

import { Undo2, Redo2, History, Trash2 } from 'lucide-react';

import type { HistoryAction } from '@shared/types/clipboard';

interface UndoRedoControlsProps {
  canUndo: boolean;
  canRedo: boolean;
  undoStack: HistoryAction[];
  redoStack: HistoryAction[];
  onUndo: () => void;
  onRedo: () => void;
  onClearHistory: () => void;
  className?: string;
}

export function HistoryControls({
  canUndo,
  canRedo,
  undoStack,
  redoStack,
  onUndo,
  onRedo,
  onClearHistory,
  className = ''
}: UndoRedoControlsProps) {
  const [showHistory, setShowHistory] = useState(false);

  const lastUndoOperation = undoStack[undoStack.length - 1];
  const nextRedoOperation = redoStack[0];

  const formatOperationDescription = (operation: HistoryAction) => {
    const time = new Date(operation.timestamp).toLocaleTimeString([], { 
      hour: '2-digit', 
      minute: '2-digit' 
    });
    return `${operation.description} (${time})`;
  };

  const getOperationIcon = (type: HistoryAction['type']) => {
    switch (type) {
      case 'create': return '➕';
      case 'update': return '✏️';
      case 'delete': return '🗑️';
      case 'bulk-update': return '🔄';
      case 'bulk-delete': return '🗑️';
      default: return '•';
    }
  };

  return (
    <div className={`relative ${className}`}>
      {/* Main controls */}
      <div className="flex items-center space-x-1 bg-white rounded-lg shadow-sm border border-gray-200 p-1">
        {/* Undo button */}
        <button
          onClick={onUndo}
          disabled={!canUndo}
          className="btn btn-sm btn-secondary flex items-center space-x-1 disabled:opacity-50 disabled:cursor-not-allowed"
          title={lastUndoOperation ? `Undo: ${lastUndoOperation.description}` : 'Nothing to undo'}
        >
          <Undo2 size={14} />
          <span className="hidden sm:inline">Undo</span>
        </button>

        {/* Redo button */}
        <button
          onClick={onRedo}
          disabled={!canRedo}
          className="btn btn-sm btn-secondary flex items-center space-x-1 disabled:opacity-50 disabled:cursor-not-allowed"
          title={nextRedoOperation ? `Redo: ${nextRedoOperation.description}` : 'Nothing to redo'}
        >
          <Redo2 size={14} />
          <span className="hidden sm:inline">Redo</span>
        </button>

        {/* History toggle */}
        <button
          onClick={() => setShowHistory(!showHistory)}
          className="btn btn-sm btn-secondary"
          title="View operation history"
        >
          <History size={14} />
        </button>

        {/* Clear history */}
        {(undoStack.length > 0 || redoStack.length > 0) && (
          <button
            onClick={onClearHistory}
            className="btn btn-sm text-red-600 hover:bg-red-50"
            title="Clear operation history"
          >
            <Trash2 size={14} />
          </button>
        )}
      </div>

      {/* Operation summary */}
      {(canUndo || canRedo) && (
        <div className="mt-1 text-xs text-gray-500 text-center">
          {canUndo && (
            <span>Next: {lastUndoOperation?.description}</span>
          )}
          {canUndo && canRedo && <span> • </span>}
          {canRedo && (
            <span>Redo: {nextRedoOperation?.description}</span>
          )}
        </div>
      )}

      {/* History dropdown */}
      {showHistory && (
        <div className="absolute top-full left-0 mt-2 bg-white rounded-lg shadow-lg border border-gray-200 p-3 min-w-80 z-50">
          <div className="flex items-center justify-between mb-3">
            <h3 className="font-semibold text-gray-900">Operation History</h3>
            <button
              onClick={() => setShowHistory(false)}
              className="text-gray-400 hover:text-gray-600"
            >
              ×
            </button>
          </div>

          {undoStack.length === 0 && redoStack.length === 0 ? (
            <div className="text-center text-gray-500 py-4">
              No operations in history
            </div>
          ) : (
            <div className="space-y-2 max-h-64 overflow-y-auto">
              {/* Future operations (redo stack) */}
              {redoStack.map((operation, _index) => (
                <div
                  key={`redo-${operation.id}`}
                  className="flex items-center space-x-3 p-2 rounded bg-blue-50 border border-blue-200"
                >
                  <span className="text-blue-600">{getOperationIcon(operation.type)}</span>
                  <div className="flex-1 min-w-0">
                    <div className="text-sm text-blue-800 truncate">
                      {formatOperationDescription(operation)}
                    </div>
                    <div className="text-xs text-blue-600">
                      {operation.data.after?.tubes?.length || 0} tube(s) • Will redo
                    </div>
                  </div>
                </div>
              ))}

              {/* Current divider */}
              {redoStack.length > 0 && undoStack.length > 0 && (
                <div className="flex items-center space-x-2 py-2">
                  <div className="flex-1 h-px bg-gray-300" />
                  <span className="text-xs text-gray-500 font-medium">Current State</span>
                  <div className="flex-1 h-px bg-gray-300" />
                </div>
              )}

              {/* Past operations (undo stack) */}
              {undoStack.slice().reverse().map((operation, index) => (
                <div
                  key={`undo-${operation.id}`}
                  className={`flex items-center space-x-3 p-2 rounded ${
                    index === 0 
                      ? 'bg-green-50 border border-green-200' 
                      : 'bg-gray-50 border border-gray-200'
                  }`}
                >
                  <span className={index === 0 ? 'text-green-600' : 'text-gray-500'}>
                    {getOperationIcon(operation.type)}
                  </span>
                  <div className="flex-1 min-w-0">
                    <div className={`text-sm truncate ${
                      index === 0 ? 'text-green-800' : 'text-gray-700'
                    }`}>
                      {formatOperationDescription(operation)}
                    </div>
                    <div className={`text-xs ${
                      index === 0 ? 'text-green-600' : 'text-gray-500'
                    }`}>
                      {operation.data.after?.tubes?.length || 0} tube(s)
                      {index === 0 && ' • Last operation'}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* History actions */}
          {(undoStack.length > 0 || redoStack.length > 0) && (
            <div className="mt-3 pt-3 border-t border-gray-200">
              <button
                onClick={() => {
                  onClearHistory();
                  setShowHistory(false);
                }}
                className="w-full btn btn-sm text-red-600 hover:bg-red-50"
              >
                <Trash2 size={14} className="mr-2" />
                Clear All History
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

