export const adminService = new AdminService();

import { useState, useEffect, lazy, Suspense } from 'react';

import { DEFAULT_SECURITY_CONFIG } from '@odysseus/shared-schemas';
import { X, Shield, Activity, AlertTriangle, Save, RefreshCw, Cog, Gauge, UsersRound } from 'lucide-react';

import { useFocusTrap } from '@shared/hooks/useFocusTrap';
import { ResearcherIcon } from '@shared/ui/components/icons';
import { notifications } from '@shared/utils';

import { adminService } from '../../services/AdminService';

import { TabSkeleton } from './TabSkeleton';

import type { SecurityConfig, AdminUser, SystemMetrics, SyncStatus } from '@odysseus/shared-schemas';

// Lazy-load tab components for code splitting
const SecurityTab = lazy(() =>
  import('./tabs/SecurityTab').then(m => ({ default: m.SecurityTab }))
);
const UserManagementTab = lazy(() =>
  import('./tabs/UserManagementTab').then(m => ({ default: m.UserManagementTab }))
);
const ResearcherManagementTab = lazy(() =>
  import('./tabs/ResearcherManagementTab').then(m => ({ default: m.ResearcherManagementTab }))
);
const SystemConfigTab = lazy(() =>
  import('./tabs/SystemConfigTab').then(m => ({ default: m.SystemConfigTab }))
);
const MonitoringTab = lazy(() =>
  import('./tabs/MonitoringTab').then(m => ({ default: m.MonitoringTab }))
);

interface AdminSettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function AdminSettingsModal({ isOpen, onClose }: AdminSettingsModalProps) {
  const [activeTab, setActiveTab] = useState<'security' | 'users' | 'researchers' | 'system' | 'monitoring'>('system');
  const [config, setConfig] = useState<SecurityConfig>(DEFAULT_SECURITY_CONFIG);
  const [originalConfig, setOriginalConfig] = useState<SecurityConfig>(DEFAULT_SECURITY_CONFIG);
  const [isSaving, setSaving] = useState(false);
  const [users, setUsers] = useState<AdminUser[]>([]);
  const [systemStats, setSystemStats] = useState<SystemMetrics | null>(null);
  const [syncStatus, setSyncStatus] = useState<SyncStatus | null>(null);
  const [inviteCode, setInviteCode] = useState<string>('');

  // Focus trap (only active when modal is open)
  const trapRef = useFocusTrap({
    isOpen,
    restoreFocus: true,
    autoFocusFirstInput: false // Focus first focusable element (tab button)
  });

  // Load current configuration and data
  useEffect(() => {
    if (isOpen) {
      // SessionManager handles authentication automatically
      void loadConfiguration();
      void loadUsers();
      void loadSystemStats();
      void loadSyncStatus();
    }
  }, [isOpen]);

  const loadConfiguration = async () => {
    try {
      const response = await adminService.getSecurityConfig();

      if (response.success && response.config) {
        // Merge with defaults to ensure all fields are present
        const loadedConfig = { ...DEFAULT_SECURITY_CONFIG, ...response.config };
        setConfig(loadedConfig);
        setOriginalConfig(loadedConfig); // Store original for change tracking
      }
    } catch (error) {
      console.error('Failed to load configuration:', error);
      // Keep defaults on error
      setConfig(DEFAULT_SECURITY_CONFIG);
      setOriginalConfig(DEFAULT_SECURITY_CONFIG);
    }
  };

  const loadUsers = async () => {
    try {
      const response = await adminService.getUsers();

      if (response.success && Array.isArray(response.users)) {
        setUsers(response.users);
      } else {
        // API returned unsuccessfully or invalid data - set empty array as fallback
        setUsers([]);
        console.warn('Failed to load users: API returned unsuccessful response or invalid data format');
      }
    } catch (error) {
      console.error('Failed to load users:', error);
      setUsers([]);
    }
  };

  const loadSystemStats = async () => {
    try {
      const response = await adminService.getMetrics();

      if (response.success && response.data) {
        setSystemStats({
          totalTubes: response.data.totalTubes || 0,
          totalUsers: response.data.totalUsers || 1,
          totalResearchers: response.data.totalResearchers || 0,
          lastBackup: new Date().toISOString(),
        });
      }
    } catch (error) {
      console.error('Failed to load system stats:', error);
      setSystemStats({
        totalTubes: 0,
        totalUsers: 1,
        totalResearchers: 0,
        lastBackup: new Date().toISOString(),
      });
    }
  };

  const saveConfiguration = async () => {
    // SessionManager handles authentication automatically

    // Calculate only the fields that actually changed
    const changes: Partial<SecurityConfig> = {};
    Object.keys(config).forEach(key => {
      const configKey = key as keyof SecurityConfig;
      if (config[configKey] !== originalConfig[configKey]) {
        (changes as any)[configKey] = config[configKey];
      }
    });

    setSaving(true);
    try {
      const response = await adminService.updateSecurityConfig(changes);

      if (response.success) {
        notifications.success('Security configuration updated successfully');
        // Update original config to reflect saved state
        setOriginalConfig(config);
        // Close modal after successful save
        onClose();
      } else {
        notifications.error('Failed to update security configuration');
      }
    } catch (error) {
      console.error('Failed to save configuration:', error);
      notifications.error('Failed to update security configuration');
    } finally {
      setSaving(false);
    }
  };

  const loadSyncStatus = async () => {
    try {
      const { httpClient } = await import('@infra/api/httpClient');
      const response = await httpClient.get<{ success: boolean; sync: SyncStatus }>('/admin/sync-status');

      if (response.data.success) {
        setSyncStatus(response.data.sync);
      }
    } catch (error) {
      console.error('Failed to load sync status:', error);
      setSyncStatus(null);
    }
  };

  const createInviteCode = async (role: 'admin' | 'user' = 'user') => {
    try {
      const { httpClient } = await import('@infra/api/httpClient');
      const response = await httpClient.post<{ success: boolean; inviteCode: string }>('/admin/create-invite', { role });

      if (response.data.success) {
        setInviteCode(response.data.inviteCode);
        notifications.success('Invite code created successfully!');
      } else {
        notifications.error('Failed to create invite code');
      }
    } catch (error) {
      console.error('Failed to create invite code:', error);
      notifications.error('Failed to create invite code');
    }
  };

  const handleConfigChange = (field: keyof SecurityConfig, value: boolean | number | string) => {
    setConfig(prev => ({ ...prev, [field]: value }));
  };

  if (!isOpen) return null;

  // Check if there are any unsaved changes
  const hasChanges = Object.keys(config).some(key => {
    const configKey = key as keyof SecurityConfig;
    return config[configKey] !== originalConfig[configKey];
  });

  const tabs = [
    { id: 'system', label: 'System', icon: Gauge },
    { id: 'security', label: 'Security', icon: Shield },
    { id: 'users', label: 'User Management', icon: UsersRound },
    { id: 'researchers', label: 'Researcher Management', icon: ResearcherIcon },
    { id: 'monitoring', label: 'Monitoring', icon: Activity },
  ] as const;

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-[2px] flex items-center justify-center z-50 animate-in fade-in duration-[180ms]">
      <div ref={trapRef} className="bg-white rounded-2xl shadow-2xl border border-gray-200 w-full max-w-5xl h-[85vh] mx-4 overflow-hidden animate-slide-up-fade flex flex-col">
        {/* Header */}
        <div className="bg-gradient-to-r from-danger-hover via-danger-bg to-danger-hover px-6 py-3 text-white flex-shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <Cog className="w-6 h-6" />
              <div>
                <h2 className="text-lg font-bold">Admin Settings</h2>
                <p className="text-white/80 text-xs">Security & System Configuration</p>
              </div>
            </div>
            <button
              onClick={onClose}
              className="btn-header-menu text-white/80 hover:text-white hover:bg-danger-hover/50"
            >
              <X size={20} />
            </button>
          </div>
        </div>

        <div className="flex flex-1 min-h-0">
          {/* Sidebar */}
          <div className="w-48 bg-gray-50 border-r border-gray-200 p-4">
            <nav className="space-y-2">
              {tabs.map(tab => {
                const Icon = tab.icon;
                return (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id)}
                    className={`nav-tab ${
                      activeTab === tab.id
                        ? 'bg-danger-light text-danger-hover border border-danger-border'
                        : 'text-gray-600 hover:bg-gray-100 hover:text-gray-900'
                    }`}
                  >
                    <Icon size={tab.id === 'researchers' ? 24 : 20} />
                    <span className="font-medium text-sm">{tab.label}</span>
                  </button>
                );
              })}
            </nav>
          </div>

          {/* Content with Lazy-Loaded Tabs */}
          <div className="flex-1 overflow-y-auto min-w-0">
            <div className="p-6 min-w-0">
              {activeTab === 'security' && (
                <Suspense fallback={<TabSkeleton />}>
                  <SecurityTab
                    config={config}
                    onChange={handleConfigChange}
                  />
                </Suspense>
              )}

              {activeTab === 'users' && (
                <Suspense fallback={<TabSkeleton />}>
                  <UserManagementTab
                    users={users}
                    onUserUpdate={loadUsers}
                    inviteCode={inviteCode}
                    onCreateInvite={createInviteCode}
                  />
                </Suspense>
              )}

              {activeTab === 'researchers' && (
                <Suspense fallback={<TabSkeleton />}>
                  <ResearcherManagementTab
                    onResearcherUpdate={loadSystemStats}
                  />
                </Suspense>
              )}

              {activeTab === 'system' && (
                <Suspense fallback={<TabSkeleton />}>
                  <SystemConfigTab
                    config={config}
                    stats={systemStats}
                    syncStatus={syncStatus}
                    onChange={handleConfigChange}
                    onRefreshSync={loadSyncStatus}
                  />
                </Suspense>
              )}

              {activeTab === 'monitoring' && (
                <Suspense fallback={<TabSkeleton />}>
                  <MonitoringTab />
                </Suspense>
              )}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="border-t border-gray-200 px-6 py-3 bg-gray-50 flex-shrink-0">
          <div className="flex items-center justify-between gap-4">
            <div className="flex items-center space-x-2 text-xs text-gray-600 flex-shrink min-w-0">
              <AlertTriangle size={14} className="alert-warning-icon flex-shrink-0" />
              <span className="truncate">Changes apply to all users immediately</span>
            </div>
            <div className="flex space-x-2 flex-shrink-0">
              <button
                onClick={onClose}
                className="btn-cancel"
              >
                Cancel
              </button>
              <button
                onClick={saveConfiguration}
                disabled={isSaving || !hasChanges}
                className="btn btn-primary flex items-center space-x-2 text-sm px-3 py-1.5 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isSaving ? <RefreshCw size={14} className="animate-spin" /> : <Save size={14} />}
                <span>{isSaving ? 'Saving...' : 'Save Changes'}</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * Audit Log Filter Panel Component
 *
 * Provides comprehensive filtering UI for audit logs with:
 * - Multi-select action filters grouped by entity
 * - Entity type filters with color-coded pills
 * - Username search
 * - Date range presets and custom dates
 * - Active filters summary with quick removal
 */

import React, { useState, useMemo, useCallback } from 'react';

import { ChevronDown, ChevronRight, X } from 'lucide-react';

export interface AuditFilterState {
  actions?: string[];
  entityTypes?: string[];
  username?: string;
  dateFrom?: string;
  dateTo?: string;
  datePreset?: string;
}

interface AuditLogFilterPanelProps {
  filters: AuditFilterState;
  onChange: (filters: AuditFilterState) => void;
  onApply: () => void;
  onClear: () => void;
}

// Filter chip component - styled based on action type
interface FilterChipProps {
  label: string;
  isSelected: boolean;
  onClick: () => void;
  actionValue?: string;
}

function FilterChip({ label, isSelected, onClick, actionValue }: FilterChipProps) {
  // Determine badge class based on action type
  const getActionBadgeClass = () => {
    if (!actionValue) return '';
    if (actionValue.includes('created')) return 'badge-action-created';
    if (actionValue.includes('updated')) return 'badge-action-updated';
    if (actionValue.includes('moved')) return 'badge-action-moved';
    if (actionValue.includes('deleted')) return 'badge-action-deleted';
    if (actionValue.includes('deactivated')) return 'badge-action-deleted';
    // Check unlinked BEFORE linked to avoid matching both
    if (actionValue.includes('unlinked') || actionValue.includes('logged_out')) return 'badge-action-logout';
    if (actionValue.includes('linked') || actionValue.includes('logged_in') || actionValue.includes('reactivated')) return 'badge-action-login';
    if (actionValue.includes('changed')) return 'badge-action-updated';
    return 'bg-gray-100 text-gray-700 border border-gray-300';
  };

  const badgeClass = getActionBadgeClass();

  return (
    <button
      onClick={onClick}
      className={`
        px-1.5 py-0.5 rounded text-[10px] font-medium transition-all
        ${isSelected ? 'ring-2 ring-action ring-offset-1' : 'opacity-80 hover:opacity-100'}
        ${badgeClass || (isSelected ? 'bg-action text-white shadow-sm hover:bg-action-hover' : 'bg-gray-100 text-gray-700 hover:bg-gray-200 border border-gray-300')}
      `}
    >
      {label}
    </button>
  );
}

// Entity type pill with color coding - uses exact table badge styles
interface EntityPillProps {
  label: string;
  entityType: string;
  isSelected: boolean;
  onClick: () => void;
}

function EntityPill({ label, entityType, isSelected, onClick }: EntityPillProps) {
  const getBadgeClass = () => {
    if (entityType === 'tube') return 'badge-entity-tube';
    if (entityType === 'user') return 'badge-entity-user';
    if (entityType === 'researcher') return 'badge-entity-researcher';
    if (entityType === 'storage') return 'badge-entity-tank';
    return 'badge';
  };

  return (
    <button
      onClick={onClick}
      className={`
        ${getBadgeClass()}
        transition-all cursor-pointer
        ${isSelected ? 'ring-2 ring-action ring-offset-1' : 'opacity-70 hover:opacity-100'}
      `}
    >
      {label}
    </button>
  );
}

// Active filter chip component
interface ActiveFilterChipProps {
  label: string;
  onRemove: () => void;
}

function ActiveFilterChip({ label, onRemove }: ActiveFilterChipProps) {
  return (
    <button
      onClick={onRemove}
      className="flex items-center gap-1 px-2 py-0.5 rounded text-xs bg-slate-600 text-white hover:bg-slate-700 transition-all"
      title={`Remove ${label}`}
    >
      <span>{label}</span>
      <X className="w-2.5 h-2.5" />
    </button>
  );
}

// Collapsible section component
interface CollapsibleSectionProps {
  title: string;
  count: number;
  isOpen: boolean;
  onToggle: () => void;
  children: React.ReactNode;
}

function CollapsibleSection({ title, count, isOpen, onToggle, children }: CollapsibleSectionProps) {
  return (
    <div className="border-b border-gray-200 last:border-b-0">
      <button
        onClick={onToggle}
        className="w-full flex items-center justify-between py-2 px-2 hover:bg-gray-50 transition-colors"
      >
        <div className="flex items-center space-x-2">
          {isOpen ? <ChevronDown className="w-3.5 h-3.5 text-gray-500" /> : <ChevronRight className="w-3.5 h-3.5 text-gray-500" />}
          <span className="text-sm font-semibold text-gray-900">{title}</span>
        </div>
        {count > 0 && (
          <span className="px-2 py-0.5 bg-blue-100 text-blue-700 rounded-full text-xs font-medium">
            {count}
          </span>
        )}
      </button>
      {isOpen && (
        <div className="px-4 pb-3">
          {children}
        </div>
      )}
    </div>
  );
}

export function AuditLogFilterPanel({ filters, onChange, onApply, onClear }: AuditLogFilterPanelProps) {
  // Collapsible section state
  const [openSections, setOpenSections] = useState({
    actions: false,
    entityTypes: true,
    user: true,
    date: false,
    // Action subsections
    tubeActions: false,
    storageActions: false,
    userActions: false,
    researcherActions: false,
  });

  // Action definitions grouped by entity
  const actionGroups = {
    tube: [
      { value: 'tube_created', label: 'Created' },
      { value: 'tube_updated', label: 'Updated' },
      { value: 'tube_moved', label: 'Moved' },
      { value: 'tube_deleted', label: 'Deleted' },
      { value: 'tube_bulk_updated', label: 'Bulk Updated' },
    ],
    storage: [
      { value: 'tank_created', label: 'Tank Created' },
      { value: 'tank_updated', label: 'Tank Updated' },
      { value: 'tank_deleted', label: 'Tank Deleted' },
      { value: 'rack_created', label: 'Rack Created' },
      { value: 'rack_updated', label: 'Rack Updated' },
      { value: 'rack_deleted', label: 'Rack Deleted' },
      { value: 'box_created', label: 'Box Created' },
      { value: 'box_updated', label: 'Box Updated' },
      { value: 'box_deleted', label: 'Box Deleted' },
      { value: 'lab_name_changed', label: 'Lab Name Changed' },
    ],
    researcher: [
      { value: 'researcher_created', label: 'Created' },
      { value: 'researcher_updated', label: 'Updated' },
      { value: 'researcher_deactivated', label: 'Deactivated' },
      { value: 'researcher_reactivated', label: 'Reactivated' },
    ],
    user: [
      { value: 'user_created', label: 'Created' },
      { value: 'user_logged_in', label: 'Login' },
      { value: 'user_logged_out', label: 'Logout' },
      { value: 'user_role_changed', label: 'Role Changed' },
      { value: 'user_password_changed', label: 'Password Changed' },
      { value: 'user_linked_to_researcher', label: 'Linked' },
      { value: 'user_unlinked_from_researcher', label: 'Unlinked' },
      { value: 'user_deleted', label: 'Deleted' },
    ],
  };

  // Entity types - reordered to match action sections
  const entityTypes = useMemo(() => [
    { value: 'tube', label: 'Tube' },
    { value: 'storage', label: 'Storage' },
    { value: 'user', label: 'User' },
    { value: 'researcher', label: 'Researcher' },
  ], []);

  // Date presets
  const datePresets = [
    { value: 'today', label: 'Today' },
    { value: 'last7days', label: 'Last 7 Days' },
    { value: 'last30days', label: 'Last 30 Days' },
    { value: 'last6months', label: 'Last 6 Months' },
    { value: 'lastyear', label: 'Last Year' },
    { value: 'alltime', label: 'All Time' },
  ];

  // Toggle action in multi-select
  const toggleAction = useCallback((action: string) => {
    const actions = filters.actions ?? [];
    const newActions = actions.includes(action)
      ? actions.filter(a => a !== action)
      : [...actions, action];
    onChange({ ...filters, actions: newActions.length > 0 ? newActions : undefined });
  }, [filters, onChange]);

  // Toggle entity type in multi-select
  const toggleEntityType = useCallback((entityType: string) => {
    const entityTypes = filters.entityTypes ?? [];
    const newEntityTypes = entityTypes.includes(entityType)
      ? entityTypes.filter(e => e !== entityType)
      : [...entityTypes, entityType];
    onChange({ ...filters, entityTypes: newEntityTypes.length > 0 ? newEntityTypes : undefined });
  }, [filters, onChange]);

  // Apply date preset
  const applyDatePreset = (preset: string) => {
    const now = new Date();
    let dateFrom: Date | undefined;

    switch (preset) {
      case 'today':
        dateFrom = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        break;
      case 'last7days':
        dateFrom = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        break;
      case 'last30days':
        dateFrom = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        break;
      case 'last6months':
        dateFrom = new Date(now.getTime() - 180 * 24 * 60 * 60 * 1000);
        break;
      case 'lastyear':
        dateFrom = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000);
        break;
      case 'alltime':
        onChange({ ...filters, dateFrom: undefined, dateTo: undefined, datePreset: preset });
        return;
    }

    onChange({
      ...filters,
      dateFrom: dateFrom?.toISOString().slice(0, 16),
      dateTo: undefined,
      datePreset: preset
    });
  };

  // Toggle section
  const toggleSection = (section: keyof typeof openSections) => {
    setOpenSections(prev => ({ ...prev, [section]: !prev[section] }));
  };

  // Count active filters per section
  const getSectionCount = (section: string): number => {
    switch (section) {
      case 'actions':
        return filters.actions?.length ?? 0;
      case 'entityTypes':
        return filters.entityTypes?.length ?? 0;
      case 'user':
        return filters.username ? 1 : 0;
      case 'date':
        return (filters.dateFrom ? 1 : 0) + (filters.dateTo ? 1 : 0);
      default:
        return 0;
    }
  };

  // Count actions per entity group
  const getEntityActionCount = (entity: string): number => {
    if (!filters.actions) return 0;
    const prefix = entity === 'storage' ? ['tank_', 'rack_', 'box_', 'lab_'] : [`${entity}_`];
    return filters.actions.filter(action => prefix.some(p => action.startsWith(p))).length;
  };

  // Build active filters list
  const activeFilters = useMemo(() => {
    const result: Array<{ label: string; onRemove: () => void }> = [];

    // Action filters
    filters.actions?.forEach(action => {
      const allActions = [
        ...actionGroups.tube,
        ...actionGroups.storage,
        ...actionGroups.researcher,
        ...actionGroups.user,
      ];
      const actionDef = allActions.find(a => a.value === action);
      if (actionDef) {
        result.push({
          label: actionDef.label,
          onRemove: () => toggleAction(action)
        });
      }
    });

    // Entity type filters
    filters.entityTypes?.forEach(entityType => {
      const entity = entityTypes.find(e => e.value === entityType);
      if (entity) {
        result.push({
          label: entity.label,
          onRemove: () => toggleEntityType(entityType)
        });
      }
    });

    // Username filter
    if (filters.username) {
      result.push({
        label: `User: ${filters.username}`,
        onRemove: () => onChange({ ...filters, username: undefined })
      });
    }

    // Date filters
    if (filters.dateFrom) {
      result.push({
        label: `From: ${filters.dateFrom.slice(0, 10)}`,
        onRemove: () => onChange({ ...filters, dateFrom: undefined })
      });
    }

    if (filters.dateTo) {
      result.push({
        label: `To: ${filters.dateTo.slice(0, 10)}`,
        onRemove: () => onChange({ ...filters, dateTo: undefined })
      });
    }

    return result;
  }, [filters, actionGroups.tube, actionGroups.storage, actionGroups.researcher, actionGroups.user, entityTypes, toggleAction, toggleEntityType, onChange]);

  const hasActiveFilters = activeFilters.length > 0;

  return (
    <div className="bg-gray-50 rounded-lg border border-gray-200">
      {/* Header */}
      <div className="p-3 border-b border-gray-200 bg-white rounded-t-lg">
        <h4 className="text-sm font-bold text-gray-900">Filters</h4>
      </div>

      {/* Filter Sections - 2x2 Grid Layout */}
      <div className="max-h-96 overflow-y-auto">
        {/* Row 1: User and Item */}
        <div className="grid grid-cols-2 gap-0 border-b border-gray-200">
          {/* USER SECTION */}
          <CollapsibleSection
            title="User"
            count={getSectionCount('user')}
            isOpen={openSections.user}
            onToggle={() => toggleSection('user')}
          >
            <input
              type="text"
              placeholder="Filter by username"
              value={filters.username ?? ''}
              onChange={(e) => onChange({ ...filters, username: e.target.value || undefined })}
              className="w-full px-2 py-1.5 text-xs border border-gray-300 rounded focus:ring-2 focus:ring-action-focus focus:border-action-focus"
            />
          </CollapsibleSection>

          {/* ITEM SECTION */}
          <CollapsibleSection
            title="Item"
            count={getSectionCount('entityTypes')}
            isOpen={openSections.entityTypes}
            onToggle={() => toggleSection('entityTypes')}
          >
            <div className="flex flex-wrap gap-2">
              {entityTypes.map(entity => (
                <EntityPill
                  key={entity.value}
                  label={entity.label}
                  entityType={entity.value}
                  isSelected={filters.entityTypes?.includes(entity.value) ?? false}
                  onClick={() => toggleEntityType(entity.value)}
                />
              ))}
            </div>
          </CollapsibleSection>
        </div>

        {/* Row 2: Action and Date */}
        <div className="grid grid-cols-2 gap-0">
          {/* ACTION SECTION */}
          <CollapsibleSection
            title="Action"
            count={getSectionCount('actions')}
            isOpen={openSections.actions}
            onToggle={() => toggleSection('actions')}
          >
          <div className="space-y-3">
            {/* Tube */}
            <div>
              <button
                onClick={() => toggleSection('tubeActions')}
                className="flex items-center space-x-1 mb-2 hover:text-action transition-colors"
              >
                {openSections.tubeActions ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
                <span className="text-xs font-medium text-gray-700">Tube</span>
                {getEntityActionCount('tube') > 0 && (
                  <span className="px-1.5 py-0.5 bg-blue-100 text-blue-700 rounded-full text-xs">
                    {getEntityActionCount('tube')}
                  </span>
                )}
              </button>
              {openSections.tubeActions && (
                <div className="flex flex-wrap gap-1 ml-4">
                  {actionGroups.tube.map(action => (
                    <FilterChip
                      key={action.value}
                      label={action.label}
                      actionValue={action.value}
                      isSelected={filters.actions?.includes(action.value) ?? false}
                      onClick={() => toggleAction(action.value)}
                    />
                  ))}
                </div>
              )}
            </div>

            {/* Storage */}
            <div>
              <button
                onClick={() => toggleSection('storageActions')}
                className="flex items-center space-x-1 mb-2 hover:text-action transition-colors"
              >
                {openSections.storageActions ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
                <span className="text-xs font-medium text-gray-700">Storage</span>
                {getEntityActionCount('storage') > 0 && (
                  <span className="px-1.5 py-0.5 bg-blue-100 text-blue-700 rounded-full text-xs">
                    {getEntityActionCount('storage')}
                  </span>
                )}
              </button>
              {openSections.storageActions && (
                <div className="ml-4 space-y-1">
                  {/* Tank actions */}
                  <div className="flex flex-wrap gap-1">
                    <FilterChip
                      label="Tank Created"
                      actionValue="tank_created"
                      isSelected={filters.actions?.includes('tank_created') ?? false}
                      onClick={() => toggleAction('tank_created')}
                    />
                    <FilterChip
                      label="Tank Updated"
                      actionValue="tank_updated"
                      isSelected={filters.actions?.includes('tank_updated') ?? false}
                      onClick={() => toggleAction('tank_updated')}
                    />
                    <FilterChip
                      label="Tank Deleted"
                      actionValue="tank_deleted"
                      isSelected={filters.actions?.includes('tank_deleted') ?? false}
                      onClick={() => toggleAction('tank_deleted')}
                    />
                  </div>
                  {/* Rack actions */}
                  <div className="flex flex-wrap gap-1">
                    <FilterChip
                      label="Rack Created"
                      actionValue="rack_created"
                      isSelected={filters.actions?.includes('rack_created') ?? false}
                      onClick={() => toggleAction('rack_created')}
                    />
                    <FilterChip
                      label="Rack Updated"
                      actionValue="rack_updated"
                      isSelected={filters.actions?.includes('rack_updated') ?? false}
                      onClick={() => toggleAction('rack_updated')}
                    />
                    <FilterChip
                      label="Rack Deleted"
                      actionValue="rack_deleted"
                      isSelected={filters.actions?.includes('rack_deleted') ?? false}
                      onClick={() => toggleAction('rack_deleted')}
                    />
                  </div>
                  {/* Box actions */}
                  <div className="flex flex-wrap gap-1">
                    <FilterChip
                      label="Box Created"
                      actionValue="box_created"
                      isSelected={filters.actions?.includes('box_created') ?? false}
                      onClick={() => toggleAction('box_created')}
                    />
                    <FilterChip
                      label="Box Updated"
                      actionValue="box_updated"
                      isSelected={filters.actions?.includes('box_updated') ?? false}
                      onClick={() => toggleAction('box_updated')}
                    />
                    <FilterChip
                      label="Box Deleted"
                      actionValue="box_deleted"
                      isSelected={filters.actions?.includes('box_deleted') ?? false}
                      onClick={() => toggleAction('box_deleted')}
                    />
                  </div>
                  {/* Lab name change */}
                  <div className="flex flex-wrap gap-1">
                    <FilterChip
                      label="Lab Name Changed"
                      actionValue="lab_name_changed"
                      isSelected={filters.actions?.includes('lab_name_changed') ?? false}
                      onClick={() => toggleAction('lab_name_changed')}
                    />
                  </div>
                </div>
              )}
            </div>

            {/* User */}
            <div>
              <button
                onClick={() => toggleSection('userActions')}
                className="flex items-center space-x-1 mb-2 hover:text-action transition-colors"
              >
                {openSections.userActions ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
                <span className="text-xs font-medium text-gray-700">User</span>
                {getEntityActionCount('user') > 0 && (
                  <span className="px-1.5 py-0.5 bg-blue-100 text-blue-700 rounded-full text-xs">
                    {getEntityActionCount('user')}
                  </span>
                )}
              </button>
              {openSections.userActions && (
                <div className="flex flex-wrap gap-1 ml-4">
                  {actionGroups.user.map(action => (
                    <FilterChip
                      key={action.value}
                      label={action.label}
                      actionValue={action.value}
                      isSelected={filters.actions?.includes(action.value) ?? false}
                      onClick={() => toggleAction(action.value)}
                    />
                  ))}
                </div>
              )}
            </div>

            {/* Researcher */}
            <div>
              <button
                onClick={() => toggleSection('researcherActions')}
                className="flex items-center space-x-1 mb-2 hover:text-action transition-colors"
              >
                {openSections.researcherActions ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
                <span className="text-xs font-medium text-gray-700">Researcher</span>
                {getEntityActionCount('researcher') > 0 && (
                  <span className="px-1.5 py-0.5 bg-blue-100 text-blue-700 rounded-full text-xs">
                    {getEntityActionCount('researcher')}
                  </span>
                )}
              </button>
              {openSections.researcherActions && (
                <div className="flex flex-wrap gap-1 ml-4">
                  {actionGroups.researcher.map(action => (
                    <FilterChip
                      key={action.value}
                      label={action.label}
                      actionValue={action.value}
                      isSelected={filters.actions?.includes(action.value) ?? false}
                      onClick={() => toggleAction(action.value)}
                    />
                  ))}
                </div>
              )}
            </div>
          </div>
        </CollapsibleSection>

          {/* DATE SECTION */}
          <CollapsibleSection
            title="Date Range"
            count={getSectionCount('date')}
            isOpen={openSections.date}
            onToggle={() => toggleSection('date')}
          >
          <div className="space-y-3">
            {/* Quick Presets */}
            <div>
              <div className="text-xs font-medium text-gray-600 mb-2">Quick Ranges</div>
              <div className="flex flex-wrap gap-1" role="group" aria-label="Quick date range presets">
                {datePresets.map(preset => (
                  <button
                    key={preset.value}
                    onClick={() => applyDatePreset(preset.value)}
                    className={`
                      px-2 py-1 text-xs rounded border transition-all
                      ${filters.datePreset === preset.value
                        ? 'bg-action text-white border-action shadow-sm'
                        : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'
                      }
                    `}
                  >
                    {preset.label}
                  </button>
                ))}
              </div>
            </div>

            {/* Custom Date Range */}
            <fieldset className="border-0 p-0 m-0">
              <legend className="text-xs font-medium text-gray-600 mb-1">Custom Range</legend>
              <div className="space-y-2">
                <div>
                  <label htmlFor="audit-date-from" className="sr-only">From date</label>
                  <input
                    id="audit-date-from"
                    type="datetime-local"
                    value={filters.dateFrom || ''}
                    onChange={(e) => onChange({ ...filters, dateFrom: e.target.value || undefined, datePreset: undefined })}
                    className="w-full px-2 py-1.5 text-xs border border-gray-300 rounded focus:ring-2 focus:ring-action-focus focus:border-action-focus"
                    placeholder="From"
                    aria-label="Filter start date and time"
                  />
                </div>
                <div>
                  <label htmlFor="audit-date-to" className="sr-only">To date</label>
                  <input
                    id="audit-date-to"
                    type="datetime-local"
                    value={filters.dateTo || ''}
                    onChange={(e) => onChange({ ...filters, dateTo: e.target.value || undefined })}
                    className="w-full px-2 py-1.5 text-xs border border-gray-300 rounded focus:ring-2 focus:ring-action-focus focus:border-action-focus"
                    placeholder="To"
                    aria-label="Filter end date and time"
                  />
                </div>
              </div>
            </fieldset>
          </div>
          </CollapsibleSection>
        </div>
      </div>

      {/* Active Filters Footer */}
      {hasActiveFilters && (
        <div className="px-3 py-2 bg-slate-50 border-t border-slate-200">
          <div className="flex items-center justify-between mb-2">
            <span className="text-xs font-medium text-slate-700">Active Filters:</span>
            <button
              onClick={onClear}
              className="px-2 py-1 text-xs text-red-600 hover:text-red-800 hover:bg-red-100 rounded transition-colors font-medium"
            >
              Clear All
            </button>
          </div>
          <div className="flex flex-wrap gap-1">
            {activeFilters.map((filter, idx) => (
              <ActiveFilterChip
                key={`${filter.label}-${idx}`}
                label={filter.label}
                onRemove={filter.onRemove}
              />
            ))}
          </div>
        </div>
      )}

      {/* Action Buttons */}
      <div className="flex justify-end gap-2 p-3 border-t border-gray-200 bg-white rounded-b-lg">
        <button
          onClick={onClear}
          className="btn-refresh-compact flex items-center space-x-1"
        >
          <span>Cancel</span>
        </button>
        <button
          onClick={onApply}
          className="btn-refresh-compact flex items-center space-x-1 bg-action text-white border-action hover:bg-action-hover"
        >
          <span>Apply Filters</span>
        </button>
      </div>
    </div>
  );
}

/**
 * Audit Log Viewer Component
 *
 * Displays audit log entries with filtering and pagination.
 * Shows detailed activity tracking for compliance and debugging.
 */

import React, { useState, useEffect, useCallback } from 'react';

import { refrigeratorFreezer } from '@lucide/lab';
import { RefreshCw, SlidersHorizontal, ChevronLeft, ChevronRight, X, Archive, TestTube, UserRound, Icon, Rows3, Box } from 'lucide-react';


import { adminService } from '@domains/admin/services/AdminService';
import { formatAuditDetails } from '@domains/admin/utils/auditLogFormatters';
import { ResearcherIcon } from '@shared/ui/components/icons';

import { AuditLogFilterPanel, type AuditFilterState } from './AuditLogFilterPanel';

import type { AuditLogEntry, AuditLogFilters } from '@odysseus/shared-schemas';

interface AuditLogViewerProps {
  /** Optional initial filters */
  initialFilters?: Partial<AuditLogFilters>;
  /** Optional callback when filters change */
  onFiltersChange?: (filters: AuditLogFilters) => void;
}

export function AuditLogViewer({ initialFilters = {}, onFiltersChange }: AuditLogViewerProps) {
  const [entries, setEntries] = useState<AuditLogEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [filters, setFilters] = useState<AuditLogFilters>({
    limit: 50,
    offset: 0,
    ...initialFilters,
  });

  const [pagination, setPagination] = useState({
    total: 0,
    limit: 50,
    offset: 0,
    hasMore: false,
  });

  const [showFilters, setShowFilters] = useState(false);
  const [tempFilters, setTempFilters] = useState<AuditFilterState>({});
  const [includeArchive, setIncludeArchive] = useState(false);

  // Load audit log entries
  const loadAuditLog = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const result = await adminService.searchAuditLogs(filters, includeArchive);
      setEntries(result.entries);
      setPagination(result.pagination);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load audit log');
      console.error('Failed to load audit log:', err);
    } finally {
      setLoading(false);
    }
  }, [filters, includeArchive]);

  useEffect(() => {
    void loadAuditLog();
  }, [loadAuditLog]);

  // Apply filters - convert multi-select to single action for backend
  const applyFilters = () => {
    const newFilters: AuditLogFilters = {
      limit: filters.limit,
      offset: 0,
      username: tempFilters.username,
      action: tempFilters.actions?.[0], // Backend only supports single action currently
      entityType: tempFilters.entityTypes?.[0], // Backend only supports single entity type currently
      dateFrom: tempFilters.dateFrom,
      dateTo: tempFilters.dateTo,
    };
    setFilters(newFilters);
    setShowFilters(false);
    onFiltersChange?.(newFilters);
  };

  // Clear filters
  const clearFilters = () => {
    const resetFilters = {
      limit: 50,
      offset: 0,
    };
    setFilters(resetFilters);
    setTempFilters({});
    onFiltersChange?.(resetFilters);
  };

  // Pagination
  const goToNextPage = () => {
    if (pagination.hasMore) {
      setFilters(prev => ({ ...prev, offset: (prev.offset ?? 0) + (prev.limit ?? 50) }));
    }
  };

  const goToPreviousPage = () => {
    if ((filters.offset ?? 0) > 0) {
      setFilters(prev => ({ ...prev, offset: Math.max(0, (prev.offset ?? 0) - (prev.limit ?? 50)) }));
    }
  };

  // Format timestamp
  const formatTimestamp = (timestamp: string | Date) => {
    const date = typeof timestamp === 'string' ? new Date(timestamp) : timestamp;
    return date.toLocaleString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
  };

  // Format action for display - simple verb
  const formatAction = (action: string) => {
    // Special cases for clearer display
    if (action === 'user_logged_in') return 'Login';
    if (action === 'user_logged_out') return 'Logout';
    if (action === 'user_linked_to_researcher') return 'Linked';
    if (action === 'user_unlinked_from_researcher') return 'Unlinked';
    if (action === 'user_password_changed') return 'Updated';
    if (action === 'user_role_changed') return 'Updated';
    if (action === 'tube_bulk_updated') return 'Bulk Updated';

    // Remove entity type prefix and capitalize (e.g., "tube_created" → "Created")
    const parts = action.split('_');
    if (parts.length > 1) {
      // Take the action part (after entity type)
      return parts[parts.length - 1].charAt(0).toUpperCase() + parts[parts.length - 1].slice(1);
    }
    return action.charAt(0).toUpperCase() + action.slice(1);
  };

  // Get action badge class based on type
  const getActionBadgeClass = (action: string) => {
    if (action.includes('created')) return 'badge-action-created';
    if (action.includes('updated')) return 'badge-action-updated';
    if (action.includes('password_changed')) return 'badge-action-updated';
    if (action.includes('role_changed')) return 'badge-action-updated';
    if (action.includes('moved')) return 'badge-action-moved';
    if (action.includes('deleted')) return 'badge-action-deleted';
    if (action.includes('deactivated')) return 'badge-action-deleted';
    if (action.includes('unlinked')) return 'badge-action-logout';
    if (action.includes('logged_in')) return 'badge-action-login';
    if (action.includes('logged_out')) return 'badge-action-logout';
    if (action.includes('linked')) return 'badge-action-login';
    if (action.includes('reactivated')) return 'badge-action-login';
    return 'badge-action-default';
  };

  // Format entity type for display
  const formatEntityType = (entityType: string) => {
    return entityType.charAt(0).toUpperCase() + entityType.slice(1);
  };

  // Get entity badge class
  const getEntityBadgeClass = (entityType: string) => {
    if (entityType === 'tube') return 'badge-entity-tube';
    if (entityType === 'user') return 'badge-entity-user';
    if (entityType === 'researcher') return 'badge-entity-researcher';
    if (entityType === 'tank') return 'badge-entity-tank';
    if (entityType === 'rack') return 'badge-entity-rack';
    if (entityType === 'box') return 'badge-entity-box';
    if (entityType === 'lab') return 'badge-entity-lab';
    return 'badge-entity-default';
  };

  // Get entity icon component
  const getEntityIcon = (entityType: string) => {
    switch (entityType) {
      case 'tube': return TestTube;
      case 'user': return UserRound;
      case 'researcher': return 'researcher'; // Custom component
      case 'tank': return 'tank'; // Custom from @lucide/lab
      case 'rack': return Rows3;
      case 'box': return Box;
      default: return null;
    }
  };

  const hasActiveFilters = Object.keys(tempFilters).some(
    key => key !== 'datePreset' && tempFilters[key as keyof AuditFilterState]
  );

  const currentPage = Math.floor((filters.offset ?? 0) / (filters.limit ?? 50)) + 1;
  const totalPages = Math.ceil((pagination?.total ?? 0) / (filters.limit ?? 50));

  return (
    <div className="space-y-3">
      {/* Header with Filters */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <h4 className="text-base font-semibold text-gray-900">Audit Log</h4>
          <span className="text-xs text-gray-500">
            ({(pagination?.total || 0).toLocaleString()} total entries)
          </span>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setIncludeArchive(!includeArchive)}
            className={`btn-refresh-compact flex items-center space-x-1 ${
              includeArchive ? 'bg-action text-white border-action hover:bg-action-hover' : ''
            }`}
            title={includeArchive ? 'Currently showing active + archived logs' : 'Currently showing active logs only'}
          >
            <Archive size={12} />
            <span>{includeArchive ? 'With Archive' : 'Active Only'}</span>
          </button>

          {hasActiveFilters && (
            <button
              onClick={clearFilters}
              className="flex items-center gap-1 px-2 py-1 text-xs text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded"
            >
              <X className="w-3 h-3" />
              Clear Filters
            </button>
          )}

          <button
            onClick={() => setShowFilters(!showFilters)}
            className={`btn-refresh-compact flex items-center space-x-1 ${
              showFilters ? 'bg-action text-white border-action hover:bg-action-hover' : ''
            }`}
          >
            <SlidersHorizontal size={12} />
            <span>Filters</span>
          </button>

          <button
            onClick={loadAuditLog}
            className="btn-refresh-compact flex items-center space-x-1"
          >
            <RefreshCw size={12} />
            <span>Refresh</span>
          </button>
        </div>
      </div>

      {/* Filter Panel */}
      {showFilters && (
        <AuditLogFilterPanel
          filters={tempFilters}
          onChange={setTempFilters}
          onApply={applyFilters}
          onClear={clearFilters}
        />
      )}

      {/* Loading State */}
      {loading && (
        <div className="text-center py-8 text-sm text-gray-500">
          Loading audit log...
        </div>
      )}

      {/* Error State */}
      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-3 py-2 rounded text-sm">
          {error}
        </div>
      )}

      {/* Audit Log Table */}
      {!loading && !error && entries && entries.length > 0 && (
        <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>
                  <th className="px-2 py-2 text-left font-semibold text-gray-700 w-32">Timestamp</th>
                  <th className="px-2 py-2 text-left font-semibold text-gray-700 w-24">User</th>
                  <th className="px-2 py-2 text-left font-semibold text-gray-700 w-20">Item</th>
                  <th className="px-2 py-2 text-left font-semibold text-gray-700">Details</th>
                  <th className="px-2 py-2 text-left font-semibold text-gray-700 w-24">Action</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {entries.map((entry) => (
                  <tr key={entry.id} className="hover:bg-gray-50">
                    <td className="px-2 py-2 whitespace-nowrap text-gray-600">
                      {formatTimestamp(entry.timestamp)}
                    </td>
                    <td className="px-2 py-2 whitespace-nowrap">
                      <span className="font-medium text-gray-900">{entry.username}</span>
                    </td>
                    <td className="px-2 py-2 whitespace-nowrap">
                      {entry.entityType ? (
                        <span className={`${getEntityBadgeClass(entry.entityType)} gap-1`}>
                          {(() => {
                            const icon = getEntityIcon(entry.entityType);
                            if (icon === 'researcher') {
                              return <ResearcherIcon size={12} />;
                            } else if (icon === 'tank') {
                              return <Icon iconNode={refrigeratorFreezer} size={12} />;
                            } else if (icon && typeof icon !== 'string') {
                              const IconComponent = icon;
                              return <IconComponent size={12} />;
                            }
                            return null;
                          })()}
                          {formatEntityType(entry.entityType)}
                        </span>
                      ) : (
                        <span className="text-gray-400 text-xs">-</span>
                      )}
                    </td>
                    <td className="px-2 py-2 text-gray-700 max-w-md truncate" title={formatAuditDetails(entry)}>
                      {formatAuditDetails(entry)}
                    </td>
                    <td className="px-2 py-2 whitespace-nowrap">
                      <span className={getActionBadgeClass(entry.action)}>
                        {formatAction(entry.action)}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!loading && !error && (!entries || entries.length === 0) && (
        <div className="text-center py-8 text-sm text-gray-500">
          No audit log entries found.
        </div>
      )}

      {/* Pagination */}
      {!loading && entries && entries.length > 0 && (
        <div className="flex items-center justify-between text-xs text-gray-600">
          <div>
            Showing {(filters.offset ?? 0) + 1} - {Math.min((filters.offset ?? 0) + (entries?.length ?? 0), pagination?.total ?? 0)} of {(pagination?.total ?? 0).toLocaleString()}
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={goToPreviousPage}
              disabled={(filters.offset ?? 0) === 0}
              className="p-1 rounded hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>

            <span className="px-2">
              Page {currentPage} of {totalPages || 1}
            </span>

            <button
              onClick={goToNextPage}
              disabled={!pagination?.hasMore}
              className="p-1 rounded hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Audit Retention Settings Component
 *
 * Displays retention policy, metrics, and manual archival controls.
 * Admin-only component for managing audit log retention.
 * Supports collapsed and expanded views for space efficiency.
 */

import React, { useState, useEffect } from 'react';

import { RefreshCw, Archive, Download, FileClock, AlertTriangle, CheckCircle, Clock, ChevronDown, ChevronUp } from 'lucide-react';

import { adminService } from '@domains/admin/services/AdminService';

interface RetentionMetrics {
  activeTable: {
    count: number;
    oldestEntry: Date | null;
    newestEntry: Date | null;
    retentionDays: number;
  };
  archiveTable: {
    count: number;
    oldestEntry: Date | null;
    retentionDays: number;
  };
  nextArchivalDate: Date | null;
  performanceWarning: boolean;
}

interface RetentionPolicy {
  activeRetentionDays: number;
  totalRetentionDays: number;
  archiveRetentionDays: number;
  enableAutoArchival: boolean;
  activeTableWarningThreshold: number;
}

interface AuditRetentionSettingsProps {
  /** Start in collapsed mode */
  defaultCollapsed?: boolean;
}

export function AuditRetentionSettings({ defaultCollapsed = true }: AuditRetentionSettingsProps) {
  const [metrics, setMetrics] = useState<RetentionMetrics | null>(null);
  const [policy, setPolicy] = useState<RetentionPolicy | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [archiving, setArchiving] = useState(false);
  const [archiveResult, setArchiveResult] = useState<{ archived: number; deleted: number } | null>(null);
  const [isCollapsed, setIsCollapsed] = useState(defaultCollapsed);

  // Load metrics and policy
  const loadData = async () => {
    try {
      setLoading(true);
      setError(null);

      const [metricsResult, policyResult] = await Promise.all([
        adminService.getRetentionMetrics(),
        adminService.getRetentionPolicy(),
      ]);

      setMetrics(metricsResult.data);
      setPolicy(policyResult.data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load retention data');
      console.error('Failed to load retention data:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadData();
  }, []);

  // Manually trigger archival
  const runArchival = async () => {
    try {
      setArchiving(true);
      setArchiveResult(null);
      setError(null);

      const result = await adminService.runManualArchival();
      setArchiveResult({
        archived: result.data.archived,
        deleted: result.data.deleted,
      });

      // Reload metrics after archival
      await loadData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to run archival');
      console.error('Failed to run archival:', err);
    } finally {
      setArchiving(false);
    }
  };

  // Export archived logs
  const exportArchive = async () => {
    try {
      const blob = await adminService.exportArchivedLogs();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `audit-archive-${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to export archive');
      console.error('Failed to export archive:', err);
    }
  };

  // Format date
  const formatDate = (date: Date | string | null) => {
    if (!date) return '-';
    const d = typeof date === 'string' ? new Date(date) : date;
    return d.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  };

  // Format number with commas
  const formatNumber = (num: number) => {
    return num.toLocaleString();
  };

  // Determine status
  const getStatus = (): 'healthy' | 'warning' | 'critical' => {
    if (!metrics) return 'healthy';
    if (metrics.performanceWarning) return 'warning';
    return 'healthy';
  };

  const status = getStatus();

  // Status display
  const statusConfig = {
    healthy: {
      icon: CheckCircle,
      text: 'Healthy',
      alertClass: 'alert-success',
      iconClass: 'alert-success-icon',
      headingClass: 'alert-success-heading',
      textClass: 'alert-success-text',
    },
    warning: {
      icon: AlertTriangle,
      text: 'Warning',
      alertClass: 'alert-warning',
      iconClass: 'alert-warning-icon',
      headingClass: 'alert-warning-heading',
      textClass: 'alert-warning-text',
    },
    critical: {
      icon: AlertTriangle,
      text: 'Critical',
      alertClass: 'alert-error',
      iconClass: 'alert-error-icon',
      headingClass: 'alert-error-heading',
      textClass: 'alert-error-text',
    },
  };

  const currentStatus = statusConfig[status];
  const StatusIcon = currentStatus.icon;

  if (loading) {
    return (
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <div className="text-center text-sm text-gray-500">Loading retention settings...</div>
      </div>
    );
  }

  // Collapsed View
  if (isCollapsed) {
    return (
      <button
        type="button"
        className={`${currentStatus.alertClass} rounded-lg p-3 cursor-pointer w-full text-left`}
        onClick={() => setIsCollapsed(false)}
        aria-expanded="false"
        aria-label="Expand audit retention settings"
      >
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <StatusIcon className={`w-4 h-4 ${currentStatus.iconClass}`} aria-hidden="true" />
            <span className={`text-sm font-medium ${currentStatus.headingClass}`}>
              Retention: {metrics ? formatNumber(metrics.activeTable.count) : '-'} active • {metrics ? formatNumber(metrics.archiveTable.count) : '-'} archived • {currentStatus.text}
            </span>
          </div>
          <div className="flex items-center gap-2">
            {metrics?.nextArchivalDate && (
              <span className={`text-xs ${currentStatus.textClass}`}>
                Next archival: {formatDate(metrics.nextArchivalDate)}
              </span>
            )}
            <ChevronDown className={`w-4 h-4 ${currentStatus.iconClass}`} aria-hidden="true" />
          </div>
        </div>
      </button>
    );
  }

  // Expanded View
  return (
    <div className="space-y-3">
      {/* Header */}
      <div className="bg-white border border-gray-200 rounded-lg p-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <FileClock className="w-4 h-4 text-gray-700" />
            <h4 className="text-sm font-semibold text-gray-900">Audit Log Retention</h4>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={loadData}
              disabled={loading}
              className="btn-refresh-compact flex items-center space-x-1"
            >
              <RefreshCw size={12} className={loading ? 'animate-spin' : ''} />
              <span>Refresh</span>
            </button>
            <button
              onClick={() => setIsCollapsed(true)}
              className="p-1 hover:bg-gray-100 rounded"
            >
              <ChevronUp className="w-4 h-4 text-gray-600" />
            </button>
          </div>
        </div>
      </div>

      {/* Performance Warning */}
      {metrics?.performanceWarning && (
        <div className="alert-warning rounded-lg p-3 flex items-start gap-2">
          <AlertTriangle className="alert-warning-icon w-4 h-4 flex-shrink-0 mt-0.5" />
          <div>
            <h5 className="alert-warning-heading text-sm">Performance Warning</h5>
            <p className="alert-warning-text text-xs mt-1">
              Active audit log table is approaching the warning threshold ({policy?.activeTableWarningThreshold?.toLocaleString()} entries).
              Consider reducing the active retention period or investigating log volume.
            </p>
          </div>
        </div>
      )}

      {/* Archive Result */}
      {archiveResult && (
        <div className="alert-success rounded-lg p-3 flex items-start gap-2">
          <CheckCircle className="alert-success-icon w-4 h-4 flex-shrink-0 mt-0.5" />
          <div>
            <h5 className="alert-success-heading text-sm">Archival Completed</h5>
            <p className="alert-success-text text-xs mt-1">
              Archived {archiveResult.archived} entries and deleted {archiveResult.deleted} expired entries.
            </p>
          </div>
        </div>
      )}

      {/* Error */}
      {error && (
        <div className="alert-error rounded-lg p-3">
          <p className="alert-error-text text-sm">{error}</p>
        </div>
      )}

      {/* Retention Policy */}
      {policy && (
        <div className="bg-white border border-gray-200 rounded-lg p-3">
          <h5 className="text-xs font-semibold text-gray-900 mb-2">Retention Policy</h5>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-xs">
            <div>
              <div className="text-gray-500">Active Retention</div>
              <div className="text-sm font-semibold text-gray-900 mt-1">{policy.activeRetentionDays} days</div>
            </div>
            <div>
              <div className="text-gray-500">Archive Retention</div>
              <div className="text-sm font-semibold text-gray-900 mt-1">{policy.archiveRetentionDays} days</div>
            </div>
            <div>
              <div className="text-gray-500">Total Retention</div>
              <div className="text-sm font-semibold text-gray-900 mt-1">{policy.totalRetentionDays} days</div>
            </div>
            <div>
              <div className="text-gray-500">Auto Archival</div>
              <div className={`text-sm font-semibold mt-1 ${policy.enableAutoArchival ? 'text-success-bg' : 'text-danger-bg'}`}>
                {policy.enableAutoArchival ? 'Enabled' : 'Disabled'}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Active Table Metrics */}
      {metrics && (
        <div className="bg-white border border-gray-200 rounded-lg p-3">
          <div className="flex items-center justify-between mb-2">
            <h5 className="text-xs font-semibold text-gray-900">Active Table (Hot Storage)</h5>
            <div className="text-xs text-gray-500">Fast queries with full indexes</div>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-xs">
            <div>
              <div className="text-gray-500">Total Entries</div>
              <div className="text-sm font-semibold text-gray-900 mt-1">
                {formatNumber(metrics.activeTable.count)}
              </div>
            </div>
            <div>
              <div className="text-gray-500">Oldest Entry</div>
              <div className="text-sm font-semibold text-gray-900 mt-1">
                {formatDate(metrics.activeTable.oldestEntry)}
              </div>
            </div>
            <div>
              <div className="text-gray-500">Newest Entry</div>
              <div className="text-sm font-semibold text-gray-900 mt-1">
                {formatDate(metrics.activeTable.newestEntry)}
              </div>
            </div>
            <div>
              <div className="text-gray-500">Next Archival</div>
              <div className="text-sm font-semibold text-gray-900 mt-1 flex items-center gap-1">
                <Clock className="w-3 h-3" />
                {formatDate(metrics.nextArchivalDate)}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Archive Table Metrics */}
      {metrics && (
        <div className="bg-white border border-gray-200 rounded-lg p-3">
          <div className="flex items-center justify-between mb-2">
            <h5 className="text-xs font-semibold text-gray-900">Archive Table (Warm Storage)</h5>
            <div className="text-xs text-gray-500">Minimal indexes, slower queries</div>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-3 text-xs">
            <div>
              <div className="text-gray-500">Total Entries</div>
              <div className="text-sm font-semibold text-gray-900 mt-1">
                {formatNumber(metrics.archiveTable.count)}
              </div>
            </div>
            <div>
              <div className="text-gray-500">Oldest Entry</div>
              <div className="text-sm font-semibold text-gray-900 mt-1">
                {formatDate(metrics.archiveTable.oldestEntry)}
              </div>
            </div>
            <div>
              <div className="text-gray-500">Retention Period</div>
              <div className="text-sm font-semibold text-gray-900 mt-1">
                {metrics.archiveTable.retentionDays} days
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Actions */}
      <div className="bg-white border border-gray-200 rounded-lg p-3">
        <h5 className="text-xs font-semibold text-gray-900 mb-2">Manual Operations</h5>
        <div className="flex gap-2">
          <button
            onClick={runArchival}
            disabled={archiving}
            className="btn-compact bg-action text-white hover:bg-action-hover flex items-center space-x-1"
          >
            <Archive size={12} className={archiving ? 'animate-spin' : ''} />
            <span>{archiving ? 'Running Archival...' : 'Run Manual Archival'}</span>
          </button>
          <button
            onClick={exportArchive}
            className="btn-compact border border-odysseus-border bg-odysseus-surface text-odysseus-secondary hover:bg-odysseus-surface-hover hover:border-odysseus-primary flex items-center space-x-1"
          >
            <Download size={12} />
            <span>Export Archive</span>
          </button>
        </div>
        <p className="text-xs text-gray-500 mt-2">
          Manual archival will move logs older than {policy?.activeRetentionDays} days to the archive table
          and delete logs older than {policy?.totalRetentionDays} days.
        </p>
      </div>
    </div>
  );
}

/**
 * Password Reset Modal Component
 *
 * Two-tab modal for admin password reset operations:
 * 1. Direct reset - Admin sets password immediately
 * 2. Token generation - Admin generates 15-minute one-time link for user
 *
 * Features:
 * - Password strength indicator
 * - Show/hide password toggle
 * - "Require password change on next login" checkbox
 * - Copy-to-clipboard for reset links
 * - Loading states and error handling
 */

import { useState } from 'react';

import { X, Eye, EyeOff, Copy, Check } from 'lucide-react';
import toast from 'react-hot-toast';

import { useFocusTrap } from '@shared/hooks/useFocusTrap';

import { adminService } from '../../services/AdminService';


interface PasswordResetModalProps {
  userId: string;
  username: string;
  onClose: () => void;
  onSuccess: () => void;
}

export const PasswordResetModal: React.FC<PasswordResetModalProps> = ({
  userId,
  username,
  onClose,
  onSuccess
}) => {
  const [activeTab, setActiveTab] = useState<'direct' | 'token'>('direct');
  const [newPassword, setNewPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [requirePasswordChange, setRequirePasswordChange] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [resetUrl, setResetUrl] = useState<string | null>(null);
  const [expiresAt, setExpiresAt] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  // Focus trap with auto-focus on first input
  const trapRef = useFocusTrap({
    isOpen: true,
    restoreFocus: true,
    autoFocusFirstInput: true
  });

  const handleDirectReset = async () => {
    if (!newPassword || newPassword.length < 4) {
      toast.error('Password must be at least 4 characters');
      return;
    }

    setIsLoading(true);
    try {
      await adminService.resetUserPassword(userId, newPassword, requirePasswordChange);
      toast.success('Password reset successfully');
      onSuccess();
      onClose();
    } catch (error: any) {
      toast.error(error.message || 'Failed to reset password');
    } finally {
      setIsLoading(false);
    }
  };

  const handleGenerateToken = async () => {
    setIsLoading(true);
    try {
      const response = await adminService.generatePasswordResetToken(userId);
      setResetUrl(response.resetUrl);
      setExpiresAt(response.expiresAt);
      toast.success('Reset link generated successfully');
    } catch (error: any) {
      toast.error(error.message || 'Failed to generate reset link');
    } finally {
      setIsLoading(false);
    }
  };

  const handleCopyUrl = () => {
    if (resetUrl) {
      void (async () => {
        try {
          await navigator.clipboard.writeText(resetUrl);
          setCopied(true);
          toast.success('Reset link copied to clipboard');
          setTimeout(() => setCopied(false), 2000);
        } catch (error) {
          console.error('Failed to copy to clipboard:', error);
          toast.error('Failed to copy link. Please copy manually.');
        }
      })();
    }
  };

  const getPasswordStrength = (password: string): string => {
    if (password.length === 0) return '';
    if (password.length < 4) return 'Too short';
    if (password.length < 8) return 'Weak';
    if (password.length < 12) return 'Medium';
    return 'Strong';
  };

  const getPasswordStrengthColor = (password: string): string => {
    const strength = getPasswordStrength(password);
    if (strength === 'Too short' || strength === 'Weak') return 'text-red-600';
    if (strength === 'Medium') return 'text-yellow-600';
    if (strength === 'Strong') return 'text-green-600';
    return '';
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div ref={trapRef} className="bg-white rounded-lg p-6 w-full max-w-md">
        {/* Header */}
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-semibold">Reset Password</h2>
          <button
            onClick={onClose}
            className="text-gray-500 hover:text-gray-700 rounded focus-enhanced"
          >
            <X size={20} />
          </button>
        </div>

        <p className="text-sm text-gray-600 mb-4">
          Reset password for user: <span className="font-semibold text-action-hover">{username}</span>
        </p>

        {/* Tabs */}
        <div className="flex border-b mb-4">
          <button
            onClick={() => setActiveTab('direct')}
            className={`px-4 py-2 font-medium rounded focus-enhanced ${
              activeTab === 'direct'
                ? 'border-b-2 border-action-hover text-action-hover'
                : 'text-gray-600 hover:text-gray-800'
            }`}
          >
            Set Password
          </button>
          <button
            onClick={() => setActiveTab('token')}
            className={`px-4 py-2 font-medium rounded focus-enhanced ${
              activeTab === 'token'
                ? 'border-b-2 border-action-hover text-action-hover'
                : 'text-gray-600 hover:text-gray-800'
            }`}
          >
            Generate Link
          </button>
        </div>

        {/* Tab Content - Fixed height to prevent shifting */}
        <div className="min-h-[200px] flex flex-col">
        {activeTab === 'direct' ? (
          <div className="flex-1 flex flex-col">
            {/* Password Input */}
            <div className="mb-4">
              <div className={`auth-input-container ${
                newPassword.length >= 4 ? 'border-green-500' : 'border-gray-300'
              }`}>
                <label
                  htmlFor="newPassword"
                  className={`absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide transition-colors ${
                    newPassword.length >= 4 ? 'text-green-700' : 'text-gray-700'
                  }`}
                >
                  New Password
                </label>
                <div className="relative px-3 py-2">
                  <input
                    id="newPassword"
                    type={showPassword ? 'text' : 'password'}
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    className="pr-8 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                    placeholder="Enter new password"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-700 rounded focus-enhanced"
                  >
                    {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>
              {newPassword && (
                <p className={`text-xs mt-1 ml-1 ${getPasswordStrengthColor(newPassword)}`}>
                  Strength: {getPasswordStrength(newPassword)}
                </p>
              )}
            </div>

            {/* Require Password Change Toggle */}
            <div className="mb-4">
              <label className="flex items-center space-x-2 cursor-pointer group">
                <div className="relative inline-flex items-center cursor-pointer">
                  <input
                    type="checkbox"
                    checked={requirePasswordChange}
                    onChange={(e) => setRequirePasswordChange(e.target.checked)}
                    className="sr-only peer"
                  />
                  <div className="w-7 h-4 bg-gray-200 peer-focus:outline-none peer-focus:ring-2 peer-focus:ring-action/30 rounded-full peer peer-checked:after:translate-x-3 peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-3 after:w-3 after:transition-all peer-checked:bg-action"></div>
                </div>
                <span className="text-sm text-gray-700 group-hover:text-gray-900">
                  Require password change on next login
                </span>
              </label>
            </div>

            {/* Reset Button */}
            <div className="mt-auto">
              <button
                onClick={handleDirectReset}
                disabled={isLoading || !newPassword}
                className="w-full btn btn-primary h-11 text-base font-semibold disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isLoading ? 'Resetting...' : 'Reset Password'}
              </button>
            </div>
          </div>
        ) : (
          <div className="flex-1 flex flex-col">
            {!resetUrl ? (
              <div className="flex-1 flex flex-col">
                <p className="text-sm text-gray-600 mb-4">
                  Generate a one-time password reset link that expires in 15 minutes.
                  Share this link with the user to let them set their own password.
                </p>
                <div className="mt-auto">
                  <button
                    onClick={handleGenerateToken}
                    disabled={isLoading}
                    className="w-full btn btn-primary h-11 text-base font-semibold disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {isLoading ? 'Generating...' : 'Generate Reset Link'}
                  </button>
                </div>
              </div>
            ) : (
              <div>
                <p className="text-sm font-medium text-gray-700 mb-2">
                  Reset Link Generated
                </p>
                <div className="bg-gray-100 p-3 rounded-md mb-3 break-all text-sm">
                  {resetUrl}
                </div>
                <button
                  onClick={handleCopyUrl}
                  className="w-full btn btn-primary h-11 text-base font-semibold flex items-center justify-center gap-2 mb-3"
                >
                  {copied ? (
                    <>
                      <Check size={18} />
                      Copied!
                    </>
                  ) : (
                    <>
                      <Copy size={18} />
                      Copy Link
                    </>
                  )}
                </button>
                {expiresAt && (
                  <p className="text-xs text-gray-600 text-center">
                    Expires: {new Date(expiresAt).toLocaleString()}
                  </p>
                )}
                <p className="text-xs text-gray-600 mt-3">
                  Share this link with the user. They can use it once to set a new password.
                </p>
              </div>
            )}
          </div>
        )}
        </div>
      </div>
    </div>
  );
};

import { useState, useRef } from 'react';

import { zodResolver } from '@hookform/resolvers/zod';
import { createResearcherProfileSchema, type CreateResearcherProfile, type AdminResearcher } from '@odysseus/shared-schemas';
import { X, Plus, RefreshCw, User, Mail, Building2, Briefcase } from 'lucide-react';
import { useForm } from 'react-hook-form';

import { useFocusTrap } from '@shared/hooks/useFocusTrap';
import { ResearcherIcon } from '@shared/ui/components/icons';
import { notifications } from '@shared/utils';

export interface ResearcherModalProps {
  isOpen: boolean;
  onClose: () => void;
  mode: 'create-only' | 'select-or-create';
  username?: string;
  unlinkedResearchers?: AdminResearcher[];
  onSuccess: () => void;
  onCreateResearcher: (data: CreateResearcherProfile) => Promise<void>;
  onLinkExisting: (researcherId: string) => Promise<void>;
}

export function ResearcherModal({
  isOpen,
  onClose,
  mode,
  username,
  unlinkedResearchers = [],
  onSuccess,
  onCreateResearcher,
  onLinkExisting
}: ResearcherModalProps) {
  const [actionMode, setActionMode] = useState<'create' | 'select'>('create');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Autofocus on first name input
  const firstNameInputRef = useRef<HTMLInputElement>(null);

  // Focus trap with initial focus on first name field
  const trapRef = useFocusTrap({
    isOpen,
    restoreFocus: true,
    initialFocusRef: firstNameInputRef
  });

  const { register, handleSubmit, formState: { errors }, reset } = useForm<CreateResearcherProfile>({
    resolver: zodResolver(createResearcherProfileSchema)
  });

  const handleCreate = async (data: CreateResearcherProfile) => {
    setIsSubmitting(true);
    try {
      await onCreateResearcher(data);
      notifications.success('Researcher added successfully');
      reset();
      onSuccess();
      onClose();
    } catch (error: any) {
      notifications.error(error?.response?.data?.error || 'Failed to add researcher');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleLinkExisting = async (researcherId: string) => {
    setIsSubmitting(true);
    try {
      await onLinkExisting(researcherId);
      notifications.success('Researcher linked successfully');
      onSuccess();
      onClose();
    } catch (error: any) {
      notifications.error(error?.response?.data?.error || 'Failed to link researcher');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClose = () => {
    reset();
    setActionMode('create');
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-[2px] flex items-center justify-center z-50">
      <div ref={trapRef} className="bg-white rounded-lg shadow-xl border border-gray-200 w-full max-w-2xl mx-4 max-h-[90vh] overflow-hidden flex flex-col">
        {/* Header - Lab Coat Theme (Off-white) */}
        <div className="bg-gradient-to-r from-gray-50 to-gray-100 px-4 py-3 border-b border-gray-200 flex-shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <ResearcherIcon size={20} className="text-gray-700" />
              <h2 className="text-lg font-bold text-gray-800">
                {mode === 'create-only' ? 'Add Researcher' : `Link Researcher to ${username}`}
              </h2>
            </div>
            <button onClick={handleClose} className="text-gray-500 hover:text-gray-700 transition-colors">
              <X size={20} />
            </button>
          </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4">
          {mode === 'select-or-create' && (
            <div className="mb-4 flex space-x-4 border-b border-gray-200 pb-3">
              <label className="flex items-center space-x-2 cursor-pointer">
                <input
                  type="radio"
                  checked={actionMode === 'create'}
                  onChange={() => setActionMode('create')}
                  className="w-4 h-4"
                />
                <span className="text-sm font-medium text-gray-700">Add New Researcher</span>
              </label>
              <label className="flex items-center space-x-2 cursor-pointer">
                <input
                  type="radio"
                  checked={actionMode === 'select'}
                  onChange={() => setActionMode('select')}
                  className="w-4 h-4"
                />
                <span className="text-sm font-medium text-gray-700">Link Existing Researcher</span>
              </label>
            </div>
          )}

          {/* Create Form - Label-in-Border Theme */}
          {(mode === 'create-only' || actionMode === 'create') && (
            <form onSubmit={handleSubmit(handleCreate)} className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                {/* First Name */}
                <div>
                  <div className={`relative border rounded-lg transition-colors ${errors.firstName ? 'border-red-500' : 'border-gray-300'}`}>
                    <label
                      htmlFor="firstName"
                      className={`absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide ${errors.firstName ? 'text-red-600' : 'text-gray-700'}`}
                    >
                      First Name <span className="text-red-500">*</span>
                    </label>
                    <div className="relative px-3 py-2">
                      <User className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={16} />
                      <input
                        {...register('firstName', {
                          setValueAs: (v) => v
                        })}
                        ref={(element) => {
                          // Merge react-hook-form ref with custom ref for autofocus
                          register('firstName').ref(element);
                          if (firstNameInputRef.current !== element) {
                            (firstNameInputRef as React.MutableRefObject<HTMLInputElement | null>).current = element;
                          }
                        }}
                        id="firstName"
                        className="w-full pl-7 bg-transparent border-none outline-none focus:ring-0 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                        placeholder="First name"
                      />
                    </div>
                  </div>
                  {errors.firstName && <p className="text-xs text-red-600 mt-1 ml-1">{errors.firstName.message}</p>}
                </div>

                {/* Last Name */}
                <div>
                  <div className={`relative border rounded-lg transition-colors ${errors.lastName ? 'border-red-500' : 'border-gray-300'}`}>
                    <label
                      htmlFor="lastName"
                      className={`absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide ${errors.lastName ? 'text-red-600' : 'text-gray-700'}`}
                    >
                      Last Name <span className="text-red-500">*</span>
                    </label>
                    <div className="relative px-3 py-2">
                      <User className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={16} />
                      <input
                        {...register('lastName')}
                        id="lastName"
                        className="w-full pl-7 bg-transparent border-none outline-none focus:ring-0 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                        placeholder="Last name"
                      />
                    </div>
                  </div>
                  {errors.lastName && <p className="text-xs text-red-600 mt-1 ml-1">{errors.lastName.message}</p>}
                </div>
              </div>

              {/* Email */}
              <div>
                <div className={`relative border rounded-lg transition-colors ${errors.email ? 'border-red-500' : 'border-gray-300'}`}>
                  <label
                    htmlFor="email"
                    className={`absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide ${errors.email ? 'text-red-600' : 'text-gray-700'}`}
                  >
                    Email <span className="text-red-500">*</span>
                  </label>
                  <div className="relative px-3 py-2">
                    <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={16} />
                    <input
                      {...register('email')}
                      id="email"
                      type="email"
                      className="w-full pl-7 bg-transparent border-none outline-none focus:ring-0 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                      placeholder="name@institution.edu"
                    />
                  </div>
                </div>
                {errors.email && <p className="text-xs text-red-600 mt-1 ml-1">{errors.email.message}</p>}
              </div>

              <div className="grid grid-cols-2 gap-3">
                {/* Department - NOW BEFORE Position */}
                <div>
                  <div className="relative border border-gray-300 rounded-lg transition-colors">
                    <label
                      htmlFor="department"
                      className="absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide text-gray-700"
                    >
                      Department
                    </label>
                    <div className="relative px-3 py-2">
                      <Building2 className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={16} />
                      <input
                        {...register('department')}
                        id="department"
                        className="w-full pl-7 bg-transparent border-none outline-none focus:ring-0 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                        placeholder="Department name"
                      />
                    </div>
                  </div>
                </div>

                {/* Position */}
                <div>
                  <div className="relative border border-gray-300 rounded-lg transition-colors">
                    <label
                      htmlFor="position"
                      className="absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide text-gray-700"
                    >
                      Position
                    </label>
                    <div className="relative px-3 py-2">
                      <Briefcase className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={16} />
                      <input
                        {...register('position')}
                        id="position"
                        className="w-full pl-7 bg-transparent border-none outline-none focus:ring-0 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                        placeholder="Title or role"
                      />
                    </div>
                  </div>
                </div>
              </div>

              <div className="pt-2 flex justify-end space-x-2">
                <button
                  type="button"
                  onClick={handleClose}
                  className="px-4 py-2 text-sm text-gray-600 hover:text-gray-900 font-medium"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={isSubmitting}
                  className="btn btn-primary flex items-center space-x-2 text-sm"
                >
                  {isSubmitting ? <RefreshCw size={14} className="animate-spin" /> : <Plus size={14} />}
                  <span>{mode === 'create-only' ? 'Add' : 'Add & Link'}</span>
                </button>
              </div>
            </form>
          )}

          {/* Select List */}
          {mode === 'select-or-create' && actionMode === 'select' && (
            <div className="space-y-2">
              {unlinkedResearchers.length > 0 ? (
                unlinkedResearchers.map((researcher) => (
                  <div
                    key={researcher.id}
                    className="border border-gray-200 rounded p-3 flex items-center justify-between hover:bg-gray-50 transition-colors"
                  >
                    <div className="flex-1">
                      <div className="text-sm font-medium text-gray-900">
                        {researcher.firstName} {researcher.lastName}
                      </div>
                      {researcher.email && <div className="text-xs text-gray-500">{researcher.email}</div>}
                      {researcher.position && <div className="text-xs text-gray-500">{researcher.position}</div>}
                    </div>
                    <button
                      onClick={() => handleLinkExisting(researcher.id)}
                      disabled={isSubmitting}
                      className="btn btn-primary text-xs px-3 py-1"
                    >
                      Select
                    </button>
                  </div>
                ))
              ) : (
                <div className="text-center py-8">
                  <p className="text-sm text-gray-500">No unlinked researchers available</p>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * Researcher Management Tab Component
 *
 * Provides admin interface for managing researcher profiles including:
 * - Viewing all researchers with metadata (tube counts, linked users)
 * - Deleting orphaned researchers (zero tubes + no linked user)
 * - Visual indicators for deletion eligibility
 *
 * Part of the Admin Settings modal tab system.
 *
 * @module admin/ui/components/tabs
 */

import { useState, useEffect } from 'react';

import { RefreshCw, AlertCircle, Trash2, Plus } from 'lucide-react';

import { ResearcherIcon } from '@shared/ui/components/icons';
import { notifications } from '@shared/utils';

import { adminService } from '../../../services/AdminService';
import { ResearcherModal } from '../ResearcherModal';

import type { AdminResearcher, CreateResearcherProfile } from '@odysseus/shared-schemas';



/**
 * ResearcherManagementTab Props Interface
 *
 * @interface ResearcherManagementTabProps
 */
export interface ResearcherManagementTabProps {
  /** Callback invoked when researcher list should be refreshed (after deletion, etc.) */
  onResearcherUpdate?: () => void;
}

/**
 * Researcher Management Tab Component
 *
 * Renders researcher management interface with table of researchers and deletion controls.
 * All researcher modifications (deletions) are performed via adminService.
 *
 * @param {ResearcherManagementTabProps} props - Component props
 * @returns {JSX.Element} Researcher management interface
 *
 * @example
 * ```tsx
 * <ResearcherManagementTab
 *   onResearcherUpdate={loadResearchers}
 * />
 * ```
 */
export function ResearcherManagementTab({
  onResearcherUpdate,
}: ResearcherManagementTabProps) {
  const [researchers, setResearchers] = useState<AdminResearcher[]>([]);
  const [loading, setLoading] = useState(false);
  const [deleting, setDeleting] = useState<string | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);

  /**
   * Load researchers on component mount
   */
  useEffect(() => {
    void loadResearchers();
  }, []);

  /**
   * Fetch all researchers with metadata
   */
  const loadResearchers = async () => {
    setLoading(true);
    try {
      const response = await adminService.getResearchers();
      if (response.success) {
        // Sort researchers alphabetically by last name, then first name
        const sorted = [...response.researchers].sort((a, b) => {
          const lastNameCompare = a.lastName.localeCompare(b.lastName);
          if (lastNameCompare !== 0) return lastNameCompare;
          return a.firstName.localeCompare(b.firstName);
        });
        setResearchers(sorted);
      }
    } catch (error) {
      console.error('Failed to load researchers:', error);
      notifications.error('Failed to load researchers');
    } finally {
      setLoading(false);
    }
  };

  /**
   * Delete researcher with confirmation
   * Only allowed if researcher has zero tubes AND no linked user
   */
  const deleteResearcher = async (researcherId: string, researcherName: string) => {
    const researcher = researchers.find(r => r.id === researcherId);

    if (!researcher) {
      return;
    }

    // Check safety conditions
    if (researcher.tubeCount > 0) {
      notifications.error(`Cannot delete researcher with ${researcher.tubeCount} existing tubes`);
      return;
    }

    if (researcher.linkedUserId) {
      notifications.error(`Cannot delete researcher linked to user account "${researcher.linkedUsername}"`);
      return;
    }

    if (!confirm(`Are you sure you want to delete researcher "${researcherName}"? This action cannot be undone.`)) {
      return;
    }

    setDeleting(researcherId);
    try {
      const response = await adminService.deleteResearcher(researcherId);

      if (response.success) {
        notifications.success(`Researcher "${researcherName}" deleted successfully`);
        await loadResearchers();
        onResearcherUpdate?.();
      } else {
        notifications.error('Failed to delete researcher');
      }
    } catch (error: any) {
      console.error('Failed to delete researcher:', error);

      // Extract error message from API response
      const errorMessage = error?.response?.data?.error || 'Failed to delete researcher';
      notifications.error(errorMessage);
    } finally {
      setDeleting(null);
    }
  };

  /**
   * Check if researcher can be safely deleted
   */
  const canDelete = (researcher: AdminResearcher): boolean => {
    return researcher.tubeCount === 0 && !researcher.linkedUserId;
  };

  /**
   * Get deletion status message
   */
  const getDeletionStatus = (researcher: AdminResearcher): string => {
    if (researcher.tubeCount > 0 && researcher.linkedUserId) {
      return `Has ${researcher.tubeCount} tubes and linked to user`;
    }
    if (researcher.tubeCount > 0) {
      return `Has ${researcher.tubeCount} tubes`;
    }
    if (researcher.linkedUserId) {
      return `Linked to user "${researcher.linkedUsername}"`;
    }
    return 'Can be deleted';
  };

  /**
   * Create new researcher
   */
  const handleCreateResearcher = async (data: CreateResearcherProfile) => {
    await adminService.createResearcher(data);
    await loadResearchers();
    onResearcherUpdate?.();
  };

  return (
    <div className="space-y-2">
      {/* Header with Add and Refresh Buttons */}
      <div className="flex items-center justify-between pb-3 border-b border-gray-200 mb-4">
        <div className="flex items-center space-x-2">
          <ResearcherIcon size={22} className="text-gray-700" />
          <h3 className="text-xl font-semibold text-gray-900">Researcher Management</h3>
        </div>
        <div className="flex items-center space-x-2">
          <button
            onClick={() => setShowAddModal(true)}
            className="btn btn-primary flex items-center space-x-2 text-sm"
          >
            <Plus size={14} />
            <span>Add Researcher</span>
          </button>
          <button
            onClick={loadResearchers}
            disabled={loading}
            className="btn-refresh flex items-center space-x-2"
          >
            <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
            <span>Refresh</span>
          </button>
        </div>
      </div>

      {/* Researchers Table */}
      <div className="bg-white border border-gray-200 rounded-lg overflow-hidden overflow-x-auto">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-3 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Researcher
              </th>
              <th className="px-3 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Position
              </th>
              <th className="px-3 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Tubes
              </th>
              <th className="px-3 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Linked User
              </th>
              <th className="px-3 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Status
              </th>
              <th className="px-3 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Actions
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {researchers.length > 0 ? (
              researchers.map((researcher) => (
                <tr key={researcher.id} className="hover:bg-gray-50">
                  {/* Researcher Info Cell */}
                  <td className="px-3 py-2 whitespace-nowrap">
                    <div className="flex items-center">
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center mr-2">
                        <ResearcherIcon size={14} className="text-gray-600" />
                      </div>
                      <div>
                        <div className="text-sm font-medium text-gray-900">
                          {researcher.lastName}, {researcher.firstName}
                        </div>
                        <div className="text-xs text-gray-500">{researcher.email}</div>
                      </div>
                    </div>
                  </td>

                  {/* Position Cell */}
                  <td className="px-3 py-2 whitespace-nowrap">
                    <div className="text-sm text-gray-900">{researcher.position ?? '—'}</div>
                    {researcher.department && (
                      <div className="text-xs text-gray-500">{researcher.department}</div>
                    )}
                  </td>

                  {/* Tube Count Cell */}
                  <td className="px-3 py-2 whitespace-nowrap">
                    <span
                      className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${
                        researcher.tubeCount === 0
                          ? 'bg-gray-100 text-gray-600'
                          : 'bg-frost text-action-hover border border-action/30'
                      }`}
                    >
                      {researcher.tubeCount}
                    </span>
                  </td>

                  {/* Linked User Cell */}
                  <td className="px-3 py-2 whitespace-nowrap">
                    {researcher.linkedUserId ? (
                      <div>
                        <div className="text-sm font-medium text-gray-900">
                          {researcher.linkedUsername}
                        </div>
                        <div className="text-xs text-gray-500">Linked</div>
                      </div>
                    ) : (
                      <span className="text-sm text-gray-400">—</span>
                    )}
                  </td>

                  {/* Active Status Cell */}
                  <td className="px-3 py-2 whitespace-nowrap">
                    <span
                      className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${
                        researcher.active
                          ? 'bg-green-100 text-green-800'
                          : 'bg-gray-100 text-gray-600'
                      }`}
                    >
                      {researcher.active ? 'Active' : 'Inactive'}
                    </span>
                  </td>

                  {/* Actions Cell */}
                  <td className="px-3 py-2 whitespace-nowrap text-sm font-medium">
                    <button
                      onClick={() =>
                        deleteResearcher(
                          researcher.id,
                          `${researcher.lastName}, ${researcher.firstName}`
                        )
                      }
                      disabled={!canDelete(researcher) || deleting === researcher.id}
                      className="flex items-center space-x-1 px-2 py-1 bg-danger-bg text-white rounded-lg hover:bg-danger-hover transition-colors disabled:opacity-50 disabled:cursor-not-allowed text-xs font-medium"
                      title={!canDelete(researcher) ? getDeletionStatus(researcher) : 'Delete researcher'}
                    >
                      {deleting === researcher.id ? (
                        <RefreshCw size={12} className="animate-spin" />
                      ) : (
                        <Trash2 size={12} />
                      )}
                      <span>Delete</span>
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={6} className="px-3 py-4 text-center text-sm text-gray-500">
                  {loading ? 'Loading researchers...' : 'No researchers found'}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Statistics Summary */}
      <div className="grid grid-cols-3 gap-3">
        <div className="bg-gray-50 p-2.5 rounded-lg border border-gray-200">
          <div className="text-xs text-gray-600">Total Researchers</div>
          <div className="text-xl font-bold text-gray-900 mt-0.5">{researchers.length}</div>
        </div>
        <div className="bg-blue-50 p-2.5 rounded-lg border border-blue-200">
          <div className="text-xs text-blue-600">With Tubes</div>
          <div className="text-xl font-bold text-blue-900 mt-0.5">
            {researchers.filter(r => r.tubeCount > 0).length}
          </div>
        </div>
        <div className="bg-green-50 p-2.5 rounded-lg border border-green-200">
          <div className="text-xs text-green-600">Linked to Users</div>
          <div className="text-xl font-bold text-green-900 mt-0.5">
            {researchers.filter(r => r.linkedUserId).length}
          </div>
        </div>
      </div>

      {/* Safe Deletion Notice - Footnote */}
      <div className="pt-6 border-t border-gray-200">
        <div className="bg-frost border border-action/30 rounded-lg p-2">
          <div className="flex items-center space-x-1.5">
            <div className="w-4 h-4 rounded-full bg-action flex items-center justify-center flex-shrink-0">
              <AlertCircle size={10} className="text-white" />
            </div>
            <p className="text-xs text-action-hover/90">
              <strong className="text-action-hover">Safe Deletion:</strong> Researchers can only be deleted with zero tubes and no linked user.
            </p>
          </div>
        </div>
      </div>

      {/* Add Researcher Modal */}
      <ResearcherModal
        isOpen={showAddModal}
        onClose={() => setShowAddModal(false)}
        mode="create-only"
        onSuccess={() => {}}
        onCreateResearcher={handleCreateResearcher}
        onLinkExisting={async () => {}}
      />
    </div>
  );
}

/**
 * System Configuration Tab Component
 *
 * Provides admin interface for viewing system configuration including:
 * - System statistics (tubes, users, researchers, backups)
 * - Collaboration sync status (Firebase connection, workspace info)
 * - Audit settings (logging configuration)
 *
 * Part of the Admin Settings modal tab system.
 *
 * @module admin/ui/components/tabs
 */

import { RefreshCw, Gauge } from 'lucide-react';

import type { SecurityConfig, SystemMetrics, SyncStatus } from '@odysseus/shared-schemas';

/**
 * SystemConfigTab Props Interface
 *
 * @interface SystemConfigTabProps
 */
export interface SystemConfigTabProps {
  /** Current security configuration (for audit settings) */
  config: SecurityConfig;

  /** System statistics (tubes, users, researchers, backup info) */
  stats: SystemMetrics | null;

  /** Synchronization status (Firebase, workspace) */
  syncStatus: SyncStatus | null;

  /** Callback invoked when any security setting is changed */
  onChange: (field: keyof SecurityConfig, value: boolean | number | string) => void;

  /** Callback invoked to refresh sync status */
  onRefreshSync: () => void;
}

/**
 * System Configuration Tab Component
 *
 * Displays read-only system statistics, sync status, and audit controls.
 *
 * @param {SystemConfigTabProps} props - Component props
 * @returns {JSX.Element} System configuration interface
 *
 * @example
 * ```tsx
 * <SystemConfigTab
 *   config={config}
 *   stats={systemStats}
 *   syncStatus={syncStatus}
 *   onChange={handleConfigChange}
 *   onRefreshSync={loadSyncStatus}
 * />
 * ```
 */
export function SystemConfigTab({
  config,
  stats,
  syncStatus,
  onChange,
  onRefreshSync,
}: SystemConfigTabProps) {
  return (
    <div className="space-y-2">
      {/* Header */}
      <div className="flex items-center space-x-2 pb-3 border-b border-gray-200 mb-4">
        <Gauge size={22} className="text-gray-700" />
        <h3 className="text-xl font-semibold text-gray-900">System</h3>
      </div>

      {/* System Statistics Section */}
      <div>
        <h4 className="text-base font-semibold text-gray-900 mb-2">Statistics</h4>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          {/* Total Tubes */}
          <div className="bg-gray-50 p-2.5 rounded-lg">
            <div className="text-xl font-bold text-gray-900">{stats?.totalTubes ?? 0}</div>
            <div className="text-xs text-gray-600">Total Tubes</div>
          </div>

          {/* Total Users */}
          <div className="bg-gray-50 p-2.5 rounded-lg">
            <div className="text-xl font-bold text-gray-900">{stats?.totalUsers ?? 0}</div>
            <div className="text-xs text-gray-600">Total Users</div>
          </div>

          {/* Total Researchers */}
          <div className="bg-gray-50 p-2.5 rounded-lg">
            <div className="text-xl font-bold text-gray-900">{stats?.totalResearchers ?? 0}</div>
            <div className="text-xs text-gray-600">Researchers</div>
          </div>

          {/* Last Backup */}
          <div className="bg-gray-50 p-2.5 rounded-lg">
            <div className="text-xs text-gray-600">Last Backup</div>
            <div className="text-xs text-gray-600 font-medium">
              {stats?.lastBackup ? new Date(stats.lastBackup).toLocaleDateString() : 'Never'}
            </div>
          </div>
        </div>
      </div>

      {/* Collaboration & Sync Section */}
      <div>
        <h4 className="text-base font-semibold text-gray-900 mb-2">Collaboration & Sync</h4>
        <div className="space-y-1.5">
          {/* Sync Status */}
          <div className="bg-gray-50 p-2.5 rounded-lg">
            <h5 className="text-sm font-medium text-gray-900 mb-2">Sync Status</h5>

            <div className="flex items-center justify-between gap-4">
              {/* Sync Enabled Status */}
              <div className="flex items-center space-x-2 flex-1">
                <div className={`w-2.5 h-2.5 rounded-full ${syncStatus?.enabled ? 'bg-green-500' : 'bg-gray-400'}`}></div>
                <span className="text-xs text-gray-700">
                  {syncStatus?.enabled ? 'Sync Enabled' : 'Local Mode'}
                </span>
              </div>

              {/* Firebase Connection Status */}
              <div className="flex items-center space-x-2 flex-1">
                <div className={`w-2.5 h-2.5 rounded-full ${syncStatus?.firebase ? 'bg-green-500' : 'bg-gray-400'}`}></div>
                <span className="text-xs text-gray-700">
                  {syncStatus?.firebase ? 'Firebase Connected' : 'Firebase Offline'}
                </span>
              </div>

              {/* Refresh Button */}
              <button
                onClick={onRefreshSync}
                className="btn-refresh flex items-center space-x-2 flex-shrink-0"
              >
                <RefreshCw size={14} />
                <span>Refresh</span>
              </button>
            </div>

            {/* Workspace ID Display */}
            {syncStatus?.workspaceId && (
              <div className="mt-2 text-xs text-gray-600">
                Workspace: {syncStatus.workspaceId}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Audit & Monitoring Section */}
      <div>
        <h4 className="text-base font-semibold text-gray-900 mb-2">Audit & Monitoring</h4>
        <div className="space-y-1.5">
          {/* Detailed Logging Toggle */}
          <div className="flex items-center justify-between p-2.5 bg-gray-50 rounded-lg">
            <div>
              <h5 className="text-sm font-medium text-gray-900">Detailed Logging</h5>
              <p className="text-xs text-gray-600">Log all system operations</p>
            </div>
            <label className="relative inline-flex items-center cursor-pointer">
              <input
                type="checkbox"
                checked={config.enableDetailedLogging}
                onChange={(e) => onChange('enableDetailedLogging', e.target.checked)}
                className="sr-only peer"
                aria-label="Enable detailed logging for all system operations"
              />
              <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-danger-bg/30 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-danger-bg"></div>
            </label>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * User Management Tab Component
 *
 * Provides admin interface for managing users including:
 * - Viewing all users with details (username, role, last activity)
 * - Changing user roles (admin/user)
 * - Deleting users
 * - Creating invite codes for new users
 *
 * Part of the Admin Settings modal tab system.
 *
 * @module admin/ui/components/tabs
 */

import { useState, useEffect } from 'react';

import { RefreshCw, UserRound, CheckCircle, XCircle, Clock, UserRoundCheck, Unlink2, Trash2, Link2, UsersRound, KeyRound } from 'lucide-react';

import { notifications } from '@shared/utils';

import { adminService } from '../../../services/AdminService';
import { PasswordResetModal } from '../PasswordResetModal';
import { ResearcherModal } from '../ResearcherModal';

import type { AdminUser, CreateResearcherProfile, AdminResearcher } from '@odysseus/shared-schemas';


/**
 * UserManagementTab Props Interface
 *
 * @interface UserManagementTabProps
 */
export interface UserManagementTabProps {
  /** Array of users to display in the table */
  users: AdminUser[];

  /** Callback invoked when user list should be refreshed (after role change, deletion, etc.) */
  onUserUpdate: () => void;

  /** Current invite code for new users */
  inviteCode: string;

  /** Callback invoked to create new invite code */
  onCreateInvite: (role: 'admin' | 'user') => void;
}

/**
 * User Management Tab Component
 *
 * Renders user management interface with table of users and invite code section.
 * All user modifications (role changes, deletions) are performed via adminService
 * and trigger onUserUpdate callback to refresh the list.
 *
 * @param {UserManagementTabProps} props - Component props
 * @returns {JSX.Element} User management interface
 *
 * @example
 * ```tsx
 * <UserManagementTab
 *   users={users}
 *   onUserUpdate={loadUsers}
 *   inviteCode={inviteCode}
 *   onCreateInvite={createInviteCode}
 * />
 * ```
 */
export function UserManagementTab({
  users = [],
  onUserUpdate,
  inviteCode,
  onCreateInvite,
}: UserManagementTabProps) {
  const [updating, setUpdating] = useState<string | null>(null);
  const [pendingUsers, setPendingUsers] = useState<AdminUser[]>([]);
  const [_loadingPending, setLoadingPending] = useState(false);
  const [processingApproval, setProcessingApproval] = useState<string | null>(null);
  const [linkingUser, setLinkingUser] = useState<{ id: string; username: string } | null>(null);
  const [unlinkedResearchers, setUnlinkedResearchers] = useState<AdminResearcher[]>([]);
  const [passwordResetModal, setPasswordResetModal] = useState<{ userId: string; username: string } | null>(null);

  /**
   * Load pending users on component mount and when user list updates
   */
  useEffect(() => {
    void loadPendingUsers();
  }, [users]);

  /**
   * Fetch all pending users awaiting approval
   */
  const loadPendingUsers = async () => {
    setLoadingPending(true);
    try {
      const response = await adminService.getPendingUsers();
      if (response.success) {
        setPendingUsers(response.users);
      }
    } catch (error) {
      console.error('Failed to load pending users:', error);
    } finally {
      setLoadingPending(false);
    }
  };

  /**
   * Update user role (admin/user)
   * Shows loading state during update and refreshes list on success
   */
  const updateUserRole = async (userId: string, newRole: 'admin' | 'user') => {
    setUpdating(userId);
    try {
      const response = await adminService.updateUserRole(userId, newRole);

      if (response.success) {
        notifications.success(`User role updated to ${newRole}`);
        onUserUpdate(); // Refresh user list
      } else {
        notifications.error('Failed to update user role');
      }
    } catch (error) {
      console.error('Failed to update user role:', error);
      notifications.error('Failed to update user role');
    } finally {
      setUpdating(null);
    }
  };

  /**
   * Delete user with confirmation
   * Prompts for confirmation before deletion and refreshes list on success
   */
  const deleteUser = async (userId: string, username: string) => {
    if (!confirm(`Are you sure you want to delete user "${username}"? This action cannot be undone.`)) {
      return;
    }

    try {
      const response = await adminService.deleteUser(userId);

      if (response.success) {
        notifications.success(`User "${username}" deleted successfully`);
        onUserUpdate();
      } else {
        notifications.error('Failed to delete user');
      }
    } catch (error) {
      console.error('Failed to delete user:', error);
      notifications.error('Failed to delete user');
    }
  };

  /**
   * Approve pending user
   * User gains access to the system after approval
   */
  const approveUser = async (userId: string, username: string) => {
    setProcessingApproval(userId);
    try {
      const response = await adminService.approveUser(userId);

      if (response.success) {
        notifications.success(`User "${username}" approved successfully`);
        await loadPendingUsers();
        onUserUpdate();
      } else {
        notifications.error('Failed to approve user');
      }
    } catch (error) {
      console.error('Failed to approve user:', error);
      notifications.error('Failed to approve user');
    } finally {
      setProcessingApproval(null);
    }
  };

  /**
   * Reject pending user
   * User is denied access to the system
   */
  const rejectUser = async (userId: string, username: string) => {
    if (!confirm(`Are you sure you want to reject user "${username}"? They will not be able to access the system.`)) {
      return;
    }

    setProcessingApproval(userId);
    try {
      const response = await adminService.rejectUser(userId);

      if (response.success) {
        notifications.success(`User "${username}" rejected`);
        await loadPendingUsers();
        onUserUpdate();
      } else {
        notifications.error('Failed to reject user');
      }
    } catch (error) {
      console.error('Failed to reject user:', error);
      notifications.error('Failed to reject user');
    } finally {
      setProcessingApproval(null);
    }
  };

  /**
   * Unlink researcher profile from user
   * Preserves researcher record for tube history
   */
  const unlinkResearcher = async (userId: string, username: string) => {
    if (!confirm(`Unlink researcher profile from "${username}"? The researcher record will be preserved for tube history.`)) {
      return;
    }

    setUpdating(userId);
    try {
      const response = await adminService.unlinkResearcherFromUser(userId);

      if (response.success) {
        notifications.success(`Researcher unlinked from "${username}"`);
        onUserUpdate();
      } else {
        notifications.error('Failed to unlink researcher');
      }
    } catch (error) {
      console.error('Failed to unlink researcher:', error);
      notifications.error('Failed to unlink researcher');
    } finally {
      setUpdating(null);
    }
  };

  /**
   * Open link researcher modal
   */
  const openLinkModal = async (user: { id: string; username: string }) => {
    setLinkingUser(user);
    // Load unlinked researchers
    try {
      const response = await adminService.getUnlinkedResearchers();
      if (response.success) {
        setUnlinkedResearchers(response.researchers);
      }
    } catch (error) {
      console.error('Failed to load unlinked researchers:', error);
      notifications.error('Failed to load available researchers');
    }
  };

  /**
   * Link existing researcher to user
   */
  const handleLinkExisting = async (researcherId: string) => {
    if (!linkingUser) return;

    console.log('[DEBUG] Linking researcher to user:', {
      userId: linkingUser.id,
      username: linkingUser.username,
      researcherId
    });

    await adminService.linkResearcherToUser(linkingUser.id, researcherId);
    await onUserUpdate(); // Make sure to await the update
  };

  /**
   * Create new researcher and link to user
   */
  const handleCreateAndLink = async (data: CreateResearcherProfile) => {
    if (!linkingUser) return;

    console.log('[DEBUG] Creating and linking researcher to user:', {
      userId: linkingUser.id,
      username: linkingUser.username,
      researcherData: data
    });

    await adminService.createAndLinkResearcher(linkingUser.id, data);
    await onUserUpdate(); // Make sure to await the update
  };

  return (
    <div className="space-y-2">
      {/* Header with Refresh Button */}
      <div className="flex items-center justify-between pb-3 border-b border-gray-200 mb-4">
        <div className="flex items-center space-x-2">
          <UsersRound size={22} className="text-gray-700" />
          <h3 className="text-xl font-semibold text-gray-900">User Management</h3>
        </div>
        <button
          onClick={() => {
            onUserUpdate();
            void loadPendingUsers();
          }}
          className="btn-refresh flex items-center space-x-2"
        >
          <RefreshCw size={14} />
          <span>Refresh</span>
        </button>
      </div>

      {/* Pending Approvals Section */}
      {pendingUsers.length > 0 && (
        <div className="alert-warning p-2">
          <div className="flex items-center space-x-1.5 mb-2">
            <Clock size={14} className="alert-warning-icon" />
            <h4 className="text-xs font-semibold alert-warning-heading">
              Pending Approvals ({pendingUsers.length})
            </h4>
          </div>

          <div className="space-y-2">
            {pendingUsers.map((user) => (
              <div
                key={user.id}
                className="bg-white border border-warning-border rounded-lg p-2 flex items-center justify-between"
              >
                <div className="flex items-center space-x-2">
                  <div className="w-6 h-6 rounded-full bg-warning-light flex items-center justify-center">
                    <UserRound size={14} className="alert-warning-icon" />
                  </div>
                  <div>
                    <div className="text-sm font-medium text-gray-900">{user.username}</div>
                    <div className="text-xs text-gray-500">
                      Registered {new Date(user.createdAt).toLocaleDateString()}
                    </div>
                  </div>
                </div>

                <div className="flex items-center space-x-1.5">
                  <button
                    onClick={() => approveUser(user.id, user.username)}
                    disabled={processingApproval === user.id}
                    className="btn-approve-compact flex items-center space-x-1"
                  >
                    {processingApproval === user.id ? (
                      <RefreshCw size={12} className="animate-spin" />
                    ) : (
                      <CheckCircle size={12} />
                    )}
                    <span>Approve</span>
                  </button>
                  <button
                    onClick={() => rejectUser(user.id, user.username)}
                    disabled={processingApproval === user.id}
                    className="btn-danger-compact flex items-center space-x-1"
                  >
                    {processingApproval === user.id ? (
                      <RefreshCw size={12} className="animate-spin" />
                    ) : (
                      <XCircle size={12} />
                    )}
                    <span>Reject</span>
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* All Users Table */}
      <div className="bg-white border border-gray-200 rounded-lg overflow-hidden overflow-x-auto">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-3 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                User
              </th>
              <th className="px-3 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Role
              </th>
              <th className="px-3 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Linked Researcher
              </th>
              <th className="px-3 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Last Active
              </th>
              <th className="px-3 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Actions
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {(users?.length ?? 0) > 0 ? (
              users.map((user) => (
                <tr key={user.id} className="hover:bg-gray-50">
                  {/* User Info Cell */}
                  <td className="px-3 py-2 whitespace-nowrap">
                    <div className="flex items-center">
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center mr-2">
                        <UserRound size={14} className="text-gray-600" />
                      </div>
                      <div>
                        <div className="flex items-center gap-1">
                          <span className="text-sm font-medium text-gray-900">{user.username}</span>
                          {user.requirePasswordChange && (
                            <span
                              className="text-warning-text text-xs flex items-center gap-0.5"
                              title="Password change required on next login"
                            >
                              ⚠️
                            </span>
                          )}
                        </div>
                        <div className="text-[10px] text-gray-400">{user.id}</div>
                      </div>
                    </div>
                  </td>

                  {/* Role Select Cell */}
                  <td className="px-3 py-2 whitespace-nowrap">
                    <select
                      value={user.role || 'user'}
                      onChange={(e) => updateUserRole(user.id, e.target.value as 'admin' | 'user')}
                      disabled={updating === user.id}
                      className="select-sm px-1.5 py-0.5"
                    >
                      <option value="user">User</option>
                      <option value="admin">Admin</option>
                    </select>
                    {updating === user.id && (
                      <RefreshCw size={12} className="inline ml-2 animate-spin text-gray-400" />
                    )}
                  </td>

                  {/* Researcher Status Cell */}
                  <td className="px-3 py-2 whitespace-nowrap">
                    {user.researcherId ? (
                      <div className="flex items-center space-x-1 text-sm text-gray-900">
                        <span>Linked</span>
                        <UserRoundCheck size={14} className="text-green-600 flex-shrink-0" />
                      </div>
                    ) : (
                      <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-gray-100 text-gray-600">
                        None
                      </span>
                    )}
                  </td>

                  {/* Last Activity Cell */}
                  <td className="px-3 py-2 whitespace-nowrap text-sm text-gray-500">
                    {user.lastActivity ? new Date(user.lastActivity).toLocaleDateString() : 'Never'}
                  </td>

                  {/* Actions Cell */}
                  <td className="px-3 py-2 whitespace-nowrap text-sm font-medium">
                    <div className="flex items-center gap-2">
                      <button
                        onClick={() => setPasswordResetModal({ userId: user.id, username: user.username })}
                        className="btn-password-compact flex items-center space-x-1"
                        title="Reset password"
                      >
                        <KeyRound size={12} />
                        <span>Reset Password</span>
                      </button>
                      {user.researcherId ? (
                        <button
                          onClick={() => unlinkResearcher(user.id, user.username)}
                          className="btn-primary-compact flex items-center space-x-1"
                        >
                          <Unlink2 size={12} />
                          <span>Unlink</span>
                        </button>
                      ) : (
                        <button
                          onClick={() => openLinkModal({ id: user.id, username: user.username })}
                          className="btn-primary-compact flex items-center space-x-1"
                        >
                          <Link2 size={12} />
                          <span>Link</span>
                        </button>
                      )}
                      <button
                        onClick={() => deleteUser(user.id, user.username)}
                        className="btn-danger-compact flex items-center space-x-1"
                      >
                        <Trash2 size={12} />
                        <span>Delete</span>
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={5} className="px-3 py-4 text-center text-sm text-gray-500">
                  No users found
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Invite Section */}
      <div className="bg-gray-50 p-2.5 rounded-lg">
        <h4 className="text-sm font-medium text-gray-900 mb-2">Invite New Users</h4>

        <div className="grid grid-cols-2 gap-2 mb-3">
          <button
            onClick={() => onCreateInvite('user')}
            className="btn btn-secondary text-xs"
          >
            Create User Invite
          </button>
          <button
            onClick={() => onCreateInvite('admin')}
            className="btn btn-secondary text-xs"
          >
            Create Admin Invite
          </button>
        </div>

        {inviteCode && (
          <div className="bg-white border border-gray-200 rounded p-2">
            <div className="flex items-center justify-between">
              <div>
                <div className="text-xs font-medium text-gray-900">Latest Invite Code:</div>
                <div className="text-base font-mono text-blue-600">{inviteCode}</div>
                <div className="text-xs text-gray-600 mt-0.5">
                  Share this code with colleagues to invite them to your workspace
                </div>
              </div>
              <button
                onClick={() => navigator.clipboard.writeText(inviteCode)}
                className="btn btn-secondary text-xs"
              >
                Copy
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Link Researcher Modal */}
      {linkingUser && (
        <ResearcherModal
          isOpen={true}
          onClose={() => {
            setLinkingUser(null);
            setUnlinkedResearchers([]);
          }}
          mode="select-or-create"
          username={linkingUser.username}
          unlinkedResearchers={unlinkedResearchers}
          onSuccess={() => {}}
          onCreateResearcher={handleCreateAndLink}
          onLinkExisting={handleLinkExisting}
        />
      )}

      {/* Password Reset Modal */}
      {passwordResetModal && (
        <PasswordResetModal
          userId={passwordResetModal.userId}
          username={passwordResetModal.username}
          onClose={() => setPasswordResetModal(null)}
          onSuccess={() => {
            setPasswordResetModal(null);
            onUserUpdate();
          }}
        />
      )}
    </div>
  );
}

/**
 * Audit Log Formatters
 *
 * Utility functions for formatting audit log entry details for display.
 * Extracts formatting logic from AuditLogViewer component.
 */

import type { AuditLogEntry } from '@odysseus/shared-schemas';

/**
 * Format audit log entry details for display
 *
 * Parses the JSON details field and formats it based on entity type and action.
 * Returns a human-readable string describing what happened.
 *
 * @param entry - The audit log entry to format
 * @returns Formatted details string
 */
export function formatAuditDetails(entry: AuditLogEntry): string {
  try {
    const details = JSON.parse(entry.details);
    const action = entry.action;
    const entityType = entry.entityType;

    // TUBES: Show location or bulk update count
    if (entityType === 'tube') {
      if (action === 'tube_bulk_updated' && details.count) {
        return `${details.count} tube${details.count !== 1 ? 's' : ''} updated`;
      }
      if (details.displayLocation) return details.displayLocation;
      if (details.location) return details.location;
      return '-';
    }

    // TANK EVENTS
    if (entityType === 'tank') {
      if (action === 'tank_created') {
        const tankName = details.tankName || details.tankId || '';
        return `Tank '${tankName}'`;
      }
      if (action === 'tank_deleted') {
        const tankName = details.tankName || details.tankId || '';
        return `Tank '${tankName}'`;
      }
      if (action === 'tank_updated' && details.changes) {
        const nameChange = details.changes.find((c: any) => c.field === 'name');
        if (nameChange) {
          return `Tank '${nameChange.oldValue}' renamed to '${nameChange.newValue}'`;
        }
        const activeChange = details.changes.find((c: any) => c.field === 'isActive');
        if (activeChange) {
          const tankName = nameChange?.newValue || details.tankId || '';
          return `Tank '${tankName}' ${activeChange.newValue ? 'activated' : 'deactivated'}`;
        }
      }
      const tankName = details.tankId || '';
      return `Tank '${tankName}'`;
    }

    // RACK EVENTS
    if (entityType === 'rack') {
      const tankName = details.tankName || details.tankId || '';
      const rackName = details.rackName || `Rack ${details.rackId}` || '';
      const path = `${tankName}/${rackName}`;

      if (action === 'rack_created') {
        return path;
      }
      if (action === 'rack_deleted') {
        return path;
      }
      if (action === 'rack_updated' && details.changes) {
        const nameChange = details.changes.find((c: any) => c.field === 'name');
        if (nameChange) {
          const oldPath = `${tankName}/${nameChange.oldValue}`;
          return `${oldPath} renamed to '${nameChange.newValue}'`;
        }
        const activeChange = details.changes.find((c: any) => c.field === 'isActive');
        if (activeChange) {
          return `${path} ${activeChange.newValue ? 'activated' : 'deactivated'}`;
        }
      }
      return path;
    }

    // BOX EVENTS
    if (entityType === 'box') {
      const tankName = details.tankName || details.tankId || '';
      const rackName = details.rackName || `Rack ${details.rackId}` || '';
      const boxName = details.boxName || `Box ${details.boxId}` || '';
      const path = `${tankName}/${rackName}/${boxName}`;

      if (action === 'box_created') {
        return path;
      }
      if (action === 'box_deleted') {
        return path;
      }
      if (action === 'box_updated' && details.changes) {
        const nameChange = details.changes.find((c: any) => c.field === 'name');
        if (nameChange) {
          const oldPath = `${tankName}/${rackName}/Box ${nameChange.oldValue}`;
          return `${oldPath} renamed to 'Box ${nameChange.newValue}'`;
        }
        const rowChange = details.changes.find((c: any) => c.field === 'gridConfig.rows');
        const colChange = details.changes.find((c: any) => c.field === 'gridConfig.cols');
        if (rowChange && colChange) {
          return `${path} resized to ${rowChange.newValue}x${colChange.newValue}`;
        }
        const activeChange = details.changes.find((c: any) => c.field === 'isActive');
        if (activeChange) {
          return `${path} ${activeChange.newValue ? 'activated' : 'deactivated'}`;
        }
      }
      return path;
    }

    // LAB EVENTS
    if (entityType === 'lab') {
      if (action === 'lab_name_changed' && details.oldName && details.newName) {
        return `'${details.oldName}' renamed to '${details.newName}'`;
      }
      return details.newName || '-';
    }

    // RESEARCHER EVENTS
    if (entityType === 'researcher') {
      const researcherName = details.researcherName || '-';
      const createdBy = details.createdBy || '';
      const updatedBy = details.updatedBy || '';
      const deactivatedBy = details.deactivatedBy || '';
      const reactivatedBy = details.reactivatedBy || '';

      if (action === 'researcher_created') {
        const emailPart = details.email ? ` (${details.email})` : '';
        return `${researcherName}${emailPart} by ${createdBy}`;
      }
      if (action === 'researcher_updated' && details.changes) {
        const emailChange = details.changes.find((c: any) => c.field === 'email');
        if (emailChange) {
          return `${researcherName}: Email changed to ${emailChange.newValue} by ${updatedBy}`;
        }
        const positionChange = details.changes.find((c: any) => c.field === 'position');
        if (positionChange) {
          return `${researcherName}: Position changed to '${positionChange.newValue}' by ${updatedBy}`;
        }
        const firstNameChange = details.changes.find((c: any) => c.field === 'firstName');
        const lastNameChange = details.changes.find((c: any) => c.field === 'lastName');
        if (firstNameChange || lastNameChange) {
          return `${researcherName}: Name updated by ${updatedBy}`;
        }
        return `${researcherName} updated by ${updatedBy}`;
      }
      if (action === 'researcher_deactivated') {
        const tubeCount = details.tubesReassignedCount || 0;
        const tubeText = tubeCount > 0 ? ` (${tubeCount} tubes reassigned to Unknown)` : '';
        return `${researcherName}${tubeText} by ${deactivatedBy}`;
      }
      if (action === 'researcher_reactivated') {
        return `${researcherName} by ${reactivatedBy}`;
      }
      return researcherName;
    }

    // USER EVENTS
    if (entityType === 'user') {
      const username = details.username || '-';
      const changedBy = details.changedBy || '';
      const linkedBy = details.linkedBy || '';
      const unlinkedBy = details.unlinkedBy || '';
      const deletedBy = details.deletedBy || '';

      if (action === 'user_created') {
        const role = details.role || 'user';
        const isFirstUser = details.username && username === details.username && !changedBy;
        return isFirstUser ? `${username} (Role: ${role}) - First user setup` : `${username} (Role: ${role})`;
      }
      if (action === 'user_logged_in') {
        return username;
      }
      if (action === 'user_logged_out') {
        return username;
      }
      if (action === 'user_role_changed') {
        const newRole = details.newRole || '';
        return `Role changed to ${newRole}`;
      }
      if (action === 'user_password_changed') {
        return 'Password changed';
      }
      if (action === 'user_linked_to_researcher') {
        const researcherName = details.researcherName || '';
        return `${username} linked to researcher ${researcherName} by ${linkedBy}`;
      }
      if (action === 'user_unlinked_from_researcher') {
        const researcherName = details.researcherName || '';
        return `${username} unlinked from researcher ${researcherName} by ${unlinkedBy}`;
      }
      if (action === 'user_deleted') {
        return `${username} by ${deletedBy}`;
      }
      return username;
    }

    return '-';
  } catch {
    return '-';
  }
}

/**
 * Authentication React Query Hooks
 * 
 * Clean data fetching hooks that replace manual async state management.
 * Provides proper loading states, error handling, and caching.
 */
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';

import { queryKeys } from '@app/queryKeys';

import { authService } from '../services/AuthenticationService';

import type { AuthResponse, RegisterRequest, LoginRequest } from '../services/AuthenticationService';


/**
 * Query hook for session verification
 */
export function useAuthVerification() {
  return useQuery({
    queryKey: queryKeys.auth.verify(),
    queryFn: () => authService.verifySession(),
    retry: false, // Don't retry auth verification
    staleTime: 5 * 60 * 1000, // Consider fresh for 5 minutes
    meta: {
      errorMessage: 'Failed to verify session',
    },
  });
}

/**
 * Query hook for first-time setup check
 */
export function useFirstTimeCheck() {
  return useQuery({
    queryKey: queryKeys.auth.firstTime(),
    queryFn: () => authService.checkFirstTime(),
    staleTime: Infinity, // This won't change once false
    meta: {
      errorMessage: 'Failed to check first-time setup',
    },
  });
}

/**
 * Mutation hook for user registration
 */
export function useRegisterMutation() {
  const queryClient = useQueryClient();
  
  return useMutation({
    mutationFn: (request: RegisterRequest) => authService.register(request),
    onSuccess: (data: AuthResponse) => {
      // Update auth verification cache with new user data
      queryClient.setQueryData(queryKeys.auth.verify(), data);
      
      // Mark first-time as false since user is now registered
      queryClient.setQueryData(queryKeys.auth.firstTime(), false);
    },
    meta: {
      errorMessage: 'Registration failed',
    },
  });
}

/**
 * Mutation hook for user login
 */
export function useLoginMutation() {
  const queryClient = useQueryClient();
  
  return useMutation({
    mutationFn: (request: LoginRequest) => authService.login(request),
    onSuccess: (data: AuthResponse) => {
      // Update auth verification cache with logged-in user data
      queryClient.setQueryData(queryKeys.auth.verify(), data);
    },
    meta: {
      errorMessage: 'Login failed',
    },
  });
}

/**
 * Mutation hook for logout
 */
export function useLogoutMutation() {
  const queryClient = useQueryClient();
  
  return useMutation({
    mutationFn: () => authService.logout(),
    onSuccess: () => {
      // Clear all auth-related cache
      queryClient.removeQueries({ queryKey: ['auth'] });
      queryClient.removeQueries({ queryKey: ['tubes'] });
      queryClient.removeQueries({ queryKey: ['researchers'] });
    },
    meta: {
      errorMessage: 'Logout failed',
    },
  });
}

/**
 * Derived state hooks for UI components
 */
export function useAuthState() {
  const { data: authData, isLoading: isVerifying, error: authError } = useAuthVerification();
  const { data: isFirstTime, isLoading: isCheckingFirstTime } = useFirstTimeCheck();
  
  return {
    // Authentication state
    isAuthenticated: !!authData && !authError,
    user: authData?.user ?? null,
    permissions: authData?.user?.role === 'admin' ? ['admin'] : ['user'],
    
    // Loading states
    isLoading: isVerifying || isCheckingFirstTime,
    isVerifying,
    isCheckingFirstTime,
    
    // First-time setup
    isFirstTime: isFirstTime ?? false,
    
    // Error state
    error: authError,
  };
}

/**
 * Hook for auth actions (mutations)
 */
export function useAuthActions() {
  const registerMutation = useRegisterMutation();
  const loginMutation = useLoginMutation();
  const logoutMutation = useLogoutMutation();
  
  return {
    // Mutation functions
    register: registerMutation.mutate,
    login: loginMutation.mutate,
    logout: logoutMutation.mutate,
    
    // Async versions
    registerAsync: registerMutation.mutateAsync,
    loginAsync: loginMutation.mutateAsync,
    logoutAsync: logoutMutation.mutateAsync,
    
    // Loading states
    isRegistering: registerMutation.isPending,
    isLoggingIn: loginMutation.isPending,
    isLoggingOut: logoutMutation.isPending,
    
    // Error states
    registerError: registerMutation.error,
    loginError: loginMutation.error,
    logoutError: logoutMutation.error,
    
    // Reset functions
    resetRegisterError: registerMutation.reset,
    resetLoginError: loginMutation.reset,
    resetLogoutError: logoutMutation.reset,
  };
}

/**
 * User Settings React Query Hooks
 *
 * Clean data fetching hooks for user preferences and settings.
 * Provides proper loading states, error handling, and caching.
 */
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';

import { queryKeys } from '@app/queryKeys';
import { userSettingsService } from '@domains/users/services/UserSettingsService';

import type { UserSettings, PositionDisplayPreference } from '@odysseus/shared-schemas';

/**
 * Query hook for user settings
 *
 * Fetches the current user's settings from the server.
 * Settings include display preferences, theme, language, etc.
 *
 * @param options - Query options (e.g., { enabled: isAuthenticated })
 */
export function useUserSettingsQuery(options?: { enabled?: boolean }) {
  return useQuery({
    queryKey: queryKeys.users.settings(),
    queryFn: () => userSettingsService.getUserSettings(),
    staleTime: 5 * 60 * 1000, // Consider fresh for 5 minutes
    enabled: options?.enabled ?? true, // Default to enabled unless explicitly disabled
    meta: {
      errorMessage: 'Failed to load user settings',
    },
  });
}

/**
 * Mutation hook for updating user settings (full update)
 *
 * Updates all user settings at once. Use this for bulk updates
 * or when updating multiple settings fields together.
 */
export function useUpdateUserSettingsMutation() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (settings: UserSettings) => userSettingsService.updateUserSettings(settings),
    onSuccess: (updatedSettings) => {
      // Update the settings cache with new data
      queryClient.setQueryData(queryKeys.users.settings(), updatedSettings);
    },
    meta: {
      errorMessage: 'Failed to update user settings',
    },
  });
}

/**
 * Mutation hook for updating position display preference
 *
 * Convenience hook for updating only the position display preference.
 * This is the most common settings update operation.
 */
export function useUpdatePositionDisplayPreferenceMutation() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (preference: PositionDisplayPreference) =>
      userSettingsService.updatePositionDisplayPreference(preference),
    onSuccess: (updatedSettings) => {
      // Update the settings cache with new data
      queryClient.setQueryData(queryKeys.users.settings(), updatedSettings);
    },
    meta: {
      errorMessage: 'Failed to update position display preference',
    },
  });
}

/**
 * Derived state hook for UI components
 *
 * Provides convenient access to user settings state and loading indicators.
 * Use this in components that need read-only access to settings.
 */
export function useUserSettings() {
  const { data: settings, isLoading, error } = useUserSettingsQuery();

  return {
    // Settings data
    settings: settings ?? null,
    defaultPositionDisplay: settings?.defaultPositionDisplay ?? null,

    // Loading states
    isLoading,

    // Error state
    error,

    // Derived states
    hasSettings: !!settings,
  };
}

/**
 * Hook for user settings actions (mutations)
 *
 * Provides functions for updating user settings.
 * Use this in components that need to modify settings.
 */
export function useUserSettingsActions() {
  const updateSettingsMutation = useUpdateUserSettingsMutation();
  const updatePositionDisplayMutation = useUpdatePositionDisplayPreferenceMutation();

  return {
    // Mutation functions
    updateSettings: updateSettingsMutation.mutate,
    updatePositionDisplay: updatePositionDisplayMutation.mutate,

    // Async versions (return promises)
    updateSettingsAsync: updateSettingsMutation.mutateAsync,
    updatePositionDisplayAsync: updatePositionDisplayMutation.mutateAsync,

    // Loading states
    isUpdatingSettings: updateSettingsMutation.isPending,
    isUpdatingPositionDisplay: updatePositionDisplayMutation.isPending,
    isSaving: updateSettingsMutation.isPending || updatePositionDisplayMutation.isPending,

    // Error states
    updateSettingsError: updateSettingsMutation.error,
    updatePositionDisplayError: updatePositionDisplayMutation.error,

    // Reset functions
    resetUpdateSettingsError: updateSettingsMutation.reset,
    resetUpdatePositionDisplayError: updatePositionDisplayMutation.reset,
  };
}

