      await act(async () => {
        const isFirstTime = await result.current.checkFirstTime();
        expect(isFirstTime).toBe(true);
      });
    });
  });

  describe('State Persistence', () => {
    it('should persist authentication state', () => {
      const store = useAuthStore.getState();

      act(() => {
        store.setAuthData(mockUser, mockTokens);
      });

      // Simulate page reload - create new store instance
      const newStore = useAuthStore.getState();
      
      act(() => {
        newStore.initializeFromStorage();
      });

      // Should restore from SessionManager
      mockSessionManager.isAuthenticated.mockReturnValue(true);
      expect(newStore.isAuthenticated).toBe(true);
    });
  });
});

/**
 * Enhanced Authentication Store
 *
 * OAuth 2.0 dual-token architecture with automatic refresh.
 *
 * Key improvements:
 * - Single token → Dual token (access + refresh)
 * - Manual token passing → Automatic token injection
 * - Reactive failure handling → Proactive token renewal
 */

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

import { SessionManager, LocalStorageSessionStorage } from '@app/services/SessionManager';
import { authHttpClient } from '@infra/api/AuthHttpClient';
import { configureHttpClientWithSessionManager } from '@infra/api/httpClient';
import { env } from '@shared/config';

import { authService } from '../services/AuthenticationService';

import type { RegisterWithResearcherRequest } from '@odysseus/shared-schemas';
import type {
  TokenPair,
  SessionStatus} from '@shared/session/types';

// User interface (unchanged for compatibility)
export interface User {
  id: string;
  username: string;
  lastActivity: string;
  role?: 'admin' | 'user';
}

/**
 * Enhanced authentication state
 */
interface AuthState {
  // Core session data
  user: User | null;
  tokens: TokenPair | null;
  sessionStatus: SessionStatus;

  // UI state
  isLoading: boolean;
  error: string | null;
  logoutReason: 'idle_timeout' | 'token_expired' | 'manual_logout' | null;

  // Computed properties
  isAuthenticated: boolean;
}

/**
 * Authentication actions (clean API)
 */
interface AuthActions {
  // Primary authentication methods
  login: (username: string, password: string) => Promise<boolean>;
  register: (username: string, password: string) => Promise<boolean>;
  registerWithResearcher: (request: RegisterWithResearcherRequest) => Promise<{ success: boolean; status?: 'approved' | 'pending'; message?: string }>;
  logout: () => Promise<void>;
  verify: () => Promise<boolean>;
  checkFirstTime: () => Promise<boolean>;

  // Session management
  updateSessionStatus: () => void;
  initializeFromStorage: () => void;

  // Internal state management
  setAuthData: (user: User, tokens: TokenPair) => void;
  clearAuth: (reason?: 'idle_timeout' | 'token_expired' | 'manual_logout') => void;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  reset: () => void;

  // Development debugging
  getDebugInfo: () => any;
}

interface AuthStore extends AuthState, AuthActions {}

// Initialize session manager with AuthHttpClient to prevent circular dependency
const sessionStorage = new LocalStorageSessionStorage();

// Create session manager with callback for session expiration
// Callback pattern: SessionManager notifies auth store when session expires
const sessionManager = new SessionManager(
  authHttpClient,
  sessionStorage,
  (reason) => {
    // When session expires, clear auth store and trigger UI update
    useAuthStore.getState().clearAuth(reason);
  }
);

// Configure httpClient to use SessionManager for automatic token handling
configureHttpClientWithSessionManager(sessionManager);

/**
 * Enhanced authentication store with OAuth 2.0 dual-token architecture
 */
export const useAuthStore = create<AuthStore>()(
  persist(
    (set, get) => ({
      // STATE
      
      user: null,
      tokens: null,
      sessionStatus: 'unauthenticated',
      isLoading: false,
      error: null,
      logoutReason: null,

      // Authentication state (reactive to token changes)
      isAuthenticated: false,

      // AUTHENTICATION METHODS

      /**
       * Login with username and password (primary method)
       */
      login: async (username: string, password: string) => {
        set({ isLoading: true, error: null, logoutReason: null });

        try {
          const result = await authService.login({ username, password });

          // AuthService now returns AuthResponse directly (not wrapped in success object)
          // Set tokens in session manager (handles HTTP client + storage)
          sessionManager.setTokens(result.tokens);

          // Update store state
          set({
            user: {
              ...result.user,
              lastActivity: new Date().toISOString() // Ensure lastActivity is set
            },
            tokens: result.tokens,
            sessionStatus: 'authenticated',
            isAuthenticated: true, // Update reactive authentication state
            isLoading: false,
            error: null,
            logoutReason: null // Clear any previous logout reason
          });

          return true;
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Login error';
          console.error('❌ [AUTH STORE] Login exception:', error);
          
          set({
            error: errorMessage,
            isLoading: false
          });
          return false;
        }
      },

      /**
       * Register new user account
       */
      register: async (username: string, password: string) => {
        set({ isLoading: true, error: null });

        try {
          const result = await authService.register({ username, password });

          // AuthService now returns AuthResponse directly (not wrapped in success object)
          // Set tokens in session manager
          sessionManager.setTokens(result.tokens);

          // Update store state
          set({
            user: {
              ...result.user,
              lastActivity: new Date().toISOString() // Ensure lastActivity is set
            },
            tokens: result.tokens,
            sessionStatus: 'authenticated',
            isLoading: false,
            error: null
          });

          return true;
        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Registration error';
          console.error('❌ [AUTH STORE] Registration exception:', error);

          set({
            error: errorMessage,
            isLoading: false
          });
          return false;
        }
      },

      /**
       * Register with researcher profile (approval workflow)
       *
       * First user: Auto-approved as admin (authenticated immediately)
       * Subsequent users: Pending approval (awaiting admin action)
       */
      registerWithResearcher: async (request: RegisterWithResearcherRequest) => {
        set({ isLoading: true, error: null });

        try {
          const result = await authService.registerWithResearcher(request);

          // Case 1: Approved (first user) - Has tokens, authenticate immediately
          if (result.status === 'approved' && result.tokens) {
            sessionManager.setTokens(result.tokens);

            set({
              user: {
                ...result.user,
                lastActivity: new Date().toISOString()
              },
              tokens: result.tokens,
              sessionStatus: 'authenticated',
              isAuthenticated: true,
              isLoading: false,
              error: null
            });

            return {
              success: true,
              status: 'approved',
              message: result.message
            };
          }

          // Case 2: Pending (subsequent users) - No tokens, awaiting approval
          if (result.status === 'pending') {
            set({
              user: null, // Don't set user until approved
              tokens: null,
              sessionStatus: 'unauthenticated',
              isAuthenticated: false,
              isLoading: false,
              error: null
            });

            return {
              success: true,
              status: 'pending',
              message: result.message
            };
          }

          // Unexpected state
          throw new Error('Invalid registration response status');

        } catch (error) {
          const errorMessage = error instanceof Error ? error.message : 'Registration error';
          console.error('❌ [AUTH STORE] registerWithResearcher exception:', error);

          set({
            error: errorMessage,
            isLoading: false
          });

          return {
            success: false,
            message: errorMessage
          };
        }
      },

      /**
       * Verify existing session
       */
      verify: async () => {
        const tokens = sessionManager.getTokens();
        if (!tokens) {
          set({ sessionStatus: 'unauthenticated' });
          return false;
        }

        try {
          // Use SessionManager to get valid token (auto-refreshes if needed)
          const validToken = await sessionManager.getValidAccessToken();

          if (!validToken) {
            get().clearAuth();
            return false;
          }

          // Verify with backend
          const result = await authService.verifySession();

          // AuthService returns AuthResponse directly
          set({
            user: {
              ...result.user,
              lastActivity: new Date().toISOString() // Ensure lastActivity is set
            },
            tokens: sessionManager.getTokens(),
            sessionStatus: 'authenticated',
            error: null
          });
          return true;
        } catch (error) {
          console.error('❌ [AUTH STORE] Session verification error:', error);
          get().clearAuth();
          return false;
        }
      },

      /**
       * Check if this is first-time setup
       */
      checkFirstTime: async () => {
        try {
          const result = await authService.checkFirstTime();
          return result; // AuthService returns boolean directly
        } catch (error) {
          console.error('❌ [AUTH STORE] First time check failed:', error);
          return false;
        }
      },

      /**
       * Logout user and clear session
       */
      logout: async () => {
        set({ isLoading: true });

        try {
          // Attempt graceful logout with backend
          await authService.logout();
        } catch (error) {
          console.warn('⚠️ [AUTH STORE] Backend logout failed (clearing local session anyway):', error);
        }

        // Always clear local session regardless of backend response
        sessionManager.clearSession();
        get().clearAuth();
      },

      // SESSION MANAGEMENT

      /**
       * Update session status from SessionManager
       */
      updateSessionStatus: () => {
        const newStatus = sessionManager.getSessionStatus();
        const currentStatus = get().sessionStatus;

        if (newStatus !== currentStatus) {
          set({ sessionStatus: newStatus });
        }
      },

      /**
       * Initialize store from persistent storage
       */
      initializeFromStorage: () => {
        const tokens = sessionManager.getTokens();
        const user = sessionStorage.getUser();

        if (tokens && user) {
          set({
            user,
            tokens,
            sessionStatus: sessionManager.getSessionStatus()
          });
        } else {
          set({ sessionStatus: 'unauthenticated' });
        }
      },

      // INTERNAL STATE MANAGEMENT

      /**
       * Set authentication data (used by login/register)
       */
      setAuthData: (user: User, tokens: TokenPair) => {
        set({
          user,
          tokens,
          sessionStatus: 'authenticated',
          isLoading: false,
          error: null
        });
      },

      /**
       * Clear authentication state
       *
       * @param reason - Why the session is being cleared (for UX messaging)
       */
      clearAuth: (reason: 'idle_timeout' | 'token_expired' | 'manual_logout' = 'manual_logout') => {
        set({
          user: null,
          tokens: null,
          sessionStatus: 'unauthenticated',
          isAuthenticated: false, // Clear authentication state
          isLoading: false,
          error: null,
          logoutReason: reason
        });
      },

      /**
       * Set loading state
       */
      setLoading: (loading: boolean) => {
        set({ isLoading: loading });
      },

      /**
       * Set error state
       */
      setError: (error: string | null) => {
        set({ error });
      },

      /**
       * Reset store to initial state
       */
      reset: () => {
        sessionManager.clearSession();
        get().clearAuth();
      },

      /**
       * Development debugging information
       */
      getDebugInfo: () => {
        if (!env.isDev()) {
          return null;
        }

        const sessionDebug = sessionManager.getDebugInfo();
        const storeState = get();

        return {
          storeState: {
            hasUser: !!storeState.user,
            hasTokens: !!storeState.tokens,
            sessionStatus: storeState.sessionStatus,
            isLoading: storeState.isLoading,
            error: storeState.error
          },
          sessionManager: sessionDebug
        };
      }
    }),
    {
      name: 'odysseus-auth-enhanced',
      
      // Only persist user data, tokens handled by SessionManager
      partialize: (state) => ({
        user: state.user
      }),
      
      // Initialize session manager on rehydration
      onRehydrateStorage: () => (state) => {
        if (state) {
          // Let SessionManager handle token restoration
          const authStore = useAuthStore.getState();
          authStore.initializeFromStorage();
        }
      }
    }
  )
);

// Export session manager for HTTP client integration
export { sessionManager };

// Development-only global debugging (removed in production builds)
if (env.isDev()) {
  (globalThis as any).__ODYSSEUS_SESSION_DEBUG__ = () => {
    const authState = useAuthStore.getState();
    return authState.getDebugInfo();
  };
}

export interface User {
  id: string;
  username: string;
  lastActivity: string;
  role?: 'admin' | 'user';
}

export interface AuthCredentials {
  username: string;
  apiKey: string;
}

export interface AuthResponse {
  success: boolean;
  user?: User;
  message?: string;
}

/**
 * AuthGateway - Pure UI Authentication Router
 *
 * Pure UI routing component with zero business logic.
 * AppBootstrapService handles authentication initialization,
 * eliminating duplicate auth flows and race conditions.
 */
import React from 'react';

import { useBootstrapContext } from '@app/contexts/BootstrapContext';
import { useAuthStore } from '@domains/authentication/stores/authStore';

import { LoginModal } from './LoginModal';
import { RegisterModal } from './RegisterModal';

interface AuthGatewayProps {
  children?: React.ReactNode;
}

/**
 * Pure authentication router - no initialization logic
 * Uses BootstrapContext instead of direct useAppBootstrap()
 */
export function AuthGateway({ children }: AuthGatewayProps) {
  const { sessionStatus } = useAuthStore();
  const { isReady } = useBootstrapContext();
  
  // Wait for bootstrap to complete - no duplicate initialization
  if (!isReady) {
    return null; // AppBootstrapService/AppLoader handles loading UI
  }
  
  // Route based on auth state determined by AppBootstrapService
  if (sessionStatus === 'authenticated') {
    return <>{children}</>;
  }
  
  // For unauthenticated users, determine UI based on bootstrap result
  return <AuthUnauthenticatedRouter />;
}

/**
 * Router for unauthenticated users
 * Uses explicit flag from Bootstrap instead of parsing errors
 */
function AuthUnauthenticatedRouter() {
  const { flags } = useBootstrapContext();
  const [showRegister, setShowRegister] = React.useState(flags.firstTimeSetupRequired);

  // Bootstrap single source of truth: explicit flag for first-time setup
  if (showRegister) {
    return <RegisterModal onSwitchToLogin={() => setShowRegister(false)} />;
  }

  return <LoginModal onSwitchToRegister={() => setShowRegister(true)} />;
}

/**
 * Hook for components that need auth state
 */
export function useAuthGateway() {
  const { isAuthenticated, user } = useAuthStore();
  
  return {
    isAuthenticated,
    user,
    isAdmin: user?.role === 'admin',
    isUser: user?.role === 'user',
  };
}

import { useState, useRef } from 'react';

import { KeyRound, UserRound, Mail, Eye, EyeOff } from 'lucide-react';

import xcellbioLogo from '@shared/assets/frozen-xcellbio-logo.png';
import { useFocusTrap } from '@shared/hooks/useFocusTrap';
import { notifications } from '@shared/utils';

import { authService } from '../../services/AuthenticationService';
import { useAuthStore } from '../../stores/authStore';

// React Query will automatically fetch researchers when components mount

interface LoginModalProps {
  onSwitchToRegister?: () => void;
}

export function LoginModal({ onSwitchToRegister }: LoginModalProps) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [loginError, setLoginError] = useState<string | null>(null);
  const [isResending, setIsResending] = useState(false);
  const { login, logoutReason, error: authError } = useAuthStore();
  const usernameInputRef = useRef<HTMLInputElement>(null);

  // Focus trap with initial focus on username field
  const trapRef = useFocusTrap({
    isOpen: true,
    restoreFocus: true,
    initialFocusRef: usernameInputRef
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Clear previous error on new attempt
    setLoginError(null);

    if (!username.trim() || !password.trim()) {
      setLoginError('Please enter both username and password');
      return;
    }

    setIsLoading(true);

    try {
      const success = await login(username, password);

      if (success) {
        notifications.success('Login successful!');

        // Initial data loading is now handled by React Query in components automatically
        // Socket connection is now managed centrally by AppBootstrapService
      } else {
        // Use actual error from auth store for specific error messages
        setLoginError(authError || 'Incorrect username or password. Please try again.');
      }
    } catch (error) {
      setLoginError('Login failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleResendVerification = async () => {
    if (!username.trim()) {
      notifications.error('Please enter your username or email first');
      return;
    }

    setIsResending(true);
    try {
      await authService.resendVerificationEmail(username);
      notifications.success('Verification email sent! Check your inbox.');
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to resend verification email';
      notifications.error(errorMessage);
    } finally {
      setIsResending(false);
    }
  };

  // Check if error is about email verification
  const isEmailVerificationError = loginError?.toLowerCase().includes('email not verified') ||
                                    loginError?.toLowerCase().includes('verify your email');

  // Check if error is about password change requirement
  const isPasswordChangeRequired = loginError?.toLowerCase().includes('password change required');

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-[3px] flex items-center justify-center z-50 animate-in fade-in duration-150">
      <div ref={trapRef} className="bg-odysseus-surface rounded-2xl p-8 w-full max-w-md mx-4 shadow-2xl shadow-blue-500/20 border border-odysseus-border animate-zoom-in-95">
        <div className="text-center mb-8">
          <div className="w-16 h-16 mx-auto mb-4 flex items-center justify-center">
            <img src={xcellbioLogo} alt="XcellBio" className="w-full h-full object-contain" />
          </div>
          <h2 className="text-2xl font-bold text-odysseus-dark mb-2">Welcome Back</h2>
          <p className="text-odysseus-muted">Enter your credentials to access Odysseus</p>
        </div>

        {/* Session Timeout Banner */}
        {logoutReason === 'idle_timeout' && (
          <div className="mb-6 p-4 bg-yellow-50 border border-yellow-200 rounded-lg flex items-start gap-3 animate-in slide-in-from-top-2 duration-300">
            <svg className="w-5 h-5 text-yellow-600 flex-shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <div className="flex-1">
              <p className="text-sm font-semibold text-yellow-800">Session Timed Out</p>
              <p className="text-xs text-yellow-700 mt-1">Your session expired due to inactivity. Please log in again.</p>
            </div>
          </div>
        )}

        {/* Email Verification Error Banner */}
        {loginError && isEmailVerificationError && (
          <div className="mb-6 p-4 bg-blue-50 border border-blue-200 rounded-lg animate-in slide-in-from-top-2 duration-300">
            <div className="flex items-start gap-3 mb-3">
              <Mail className="w-5 h-5 text-blue-600 flex-shrink-0 mt-0.5" />
              <div className="flex-1">
                <p className="text-sm font-semibold text-blue-800">Email Verification Required</p>
                <p className="text-xs text-blue-700 mt-1">{loginError}</p>
              </div>
            </div>
            <button
              onClick={handleResendVerification}
              disabled={isResending}
              className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-action hover:bg-action-hover disabled:bg-gray-400 text-white text-sm font-medium rounded-lg transition-colors"
              type="button"
            >
              {isResending ? (
                <>
                  <div className="spinner w-4 h-4 border-white border-t-transparent"></div>
                  <span>Sending...</span>
                </>
              ) : (
                <>
                  <Mail className="w-4 h-4" />
                  <span>Resend Verification Email</span>
                </>
              )}
            </button>
          </div>
        )}

        {/* Password Change Required Banner */}
        {loginError && isPasswordChangeRequired && (
          <div className="mb-6 p-4 bg-yellow-50 border border-yellow-200 rounded-lg animate-in slide-in-from-top-2 duration-300">
            <div className="flex items-start gap-3">
              <svg className="w-5 h-5 text-yellow-600 flex-shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
              </svg>
              <div className="flex-1">
                <p className="text-sm font-semibold text-yellow-800">Password Change Required</p>
                <p className="text-xs text-yellow-700 mt-1">Your password must be changed. Please contact an administrator for a password reset link.</p>
              </div>
            </div>
          </div>
        )}

        {/* Generic Login Error Banner */}
        {loginError && !isEmailVerificationError && !isPasswordChangeRequired && (
          <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-start gap-3 animate-in slide-in-from-top-2 duration-300">
            <svg className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
            </svg>
            <div className="flex-1">
              <p className="text-sm font-semibold text-red-800">Login Failed</p>
              <p className="text-xs text-red-700 mt-1">{loginError}</p>
            </div>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Username or Email */}
          <div className={`auth-input-container ${loginError ? 'input-field-error' : 'border-gray-300'}`}>
            <label
              htmlFor="username"
              className={`absolute -top-2 left-3 bg-odysseus-surface px-1 text-[10px] font-semibold uppercase tracking-wide ${loginError ? 'text-validation-error-label' : 'text-gray-700'}`}
            >
              Username or Email
            </label>
            <div className="relative px-3 py-2">
              <UserRound className={`absolute left-3 top-1/2 transform -translate-y-1/2 ${loginError ? 'text-validation-error-icon' : 'text-odysseus-muted'}`} size={16} />
              <input
                ref={usernameInputRef}
                type="text"
                id="username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                className={`pl-7 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45 ${loginError ? 'text-validation-error-text' : ''}`}
                placeholder="Your username or email"
                required
                disabled={isLoading}
              />
            </div>
          </div>

          {/* Password */}
          <div className={`auth-input-container ${loginError ? 'input-field-error' : 'border-gray-300'}`}>
            <label
              htmlFor="password"
              className={`absolute -top-2 left-3 bg-odysseus-surface px-1 text-[10px] font-semibold uppercase tracking-wide ${loginError ? 'text-validation-error-label' : 'text-gray-700'}`}
            >
              Password
            </label>
            <div className="relative px-3 py-2">
              <KeyRound className={`absolute left-3 top-1/2 transform -translate-y-1/2 ${loginError ? 'text-validation-error-icon' : 'text-odysseus-muted'}`} size={16} />
              <input
                type={showPassword ? 'text' : 'password'}
                id="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className={`pl-7 pr-8 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45 ${loginError ? 'text-validation-error-text' : ''}`}
                placeholder="Your password"
                required
                disabled={isLoading}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-700 rounded focus-enhanced"
                aria-label={showPassword ? 'Hide password' : 'Show password'}
              >
                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
          </div>
          
          <button
            type="submit"
            disabled={isLoading}
            className="w-full btn btn-primary h-12 text-base font-bold shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isLoading ? (
              <div className="flex items-center justify-center space-x-2">
                <div className="spinner w-5 h-5"></div>
                <span>Authenticating...</span>
              </div>
            ) : (
              'Sign In'
            )}
          </button>
        </form>
        
        <div className="mt-3 p-2 bg-frost rounded-lg border border-action/30">
          <div className="flex items-start space-x-1.5">
            <div className="w-4 h-4 rounded-full bg-action flex items-center justify-center flex-shrink-0 mt-0.5">
              <svg className="w-2.5 h-2.5 text-white" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
              </svg>
            </div>
            <div>
              <h3 className="text-xs font-bold text-action-hover mb-0.5">Security Notice</h3>
              <p className="text-xs text-action-hover/90 leading-snug">
                Your credentials are encrypted and stored securely. Never share your password with unauthorized users.
              </p>
            </div>
          </div>
        </div>

        {onSwitchToRegister && (
          <div className="mt-4 text-center">
            <p className="text-xs text-odysseus-muted">
              Don&apos;t have an account?{' '}
              <button
                type="button"
                onClick={onSwitchToRegister}
                className="text-action-hover font-semibold hover:text-[#3d6a99] transition-colors focus-enhanced rounded px-1"
              >
                Register here
              </button>
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * PasswordRequirements Component
 *
 * Real-time password validation checklist that shows users which
 * password requirements are met as they type.
 */

import React, { useMemo } from 'react';

import { PasswordValidator, type PasswordRequirement } from '@odysseus/shared-schemas';

import type { PasswordRequirements as PasswordConfig } from '../../services/AuthenticationService';

export interface PasswordRequirementsProps {
  password: string;
  config: PasswordConfig;
  showError?: boolean; // Show red error state when true
  className?: string;
}

/**
 * PasswordRequirements Component
 *
 * Displays real-time password validation as a simple bullet list.
 * Shows green when met, gray when unmet, red when error state active.
 */
export function PasswordRequirements({ password, config, showError = false, className = '' }: PasswordRequirementsProps) {
  const requirements = useMemo(
    () => PasswordValidator.getRequirements(password, config),
    [password, config]
  );

  const getRequirementColor = (isMet: boolean) => {
    if (isMet) return 'text-green-700 font-medium';
    if (showError) return 'text-red-600';
    return 'text-gray-600';
  };

  return (
    <ul className={`space-y-0.5 mt-1.5 ${className}`}>
      {requirements.map((requirement: PasswordRequirement) => (
        <li
          key={requirement.id}
          className={`text-[10px] flex items-start ${getRequirementColor(requirement.isMet)}`}
        >
          <span className="mr-1">{requirement.isMet ? '✓' : '•'}</span>
          <span>{requirement.label}</span>
        </li>
      ))}
    </ul>
  );
}

/**
 * RegisterModal - First-time setup component
 *
 * Uses researcher profile registration with auto-generated usernames.
 * Delegates business logic to authStore and AuthService.
 */

import React, { useState, useRef, useEffect, useMemo } from 'react';

import { PasswordValidator } from '@odysseus/shared-schemas';
import { UserRound, KeyRound, Mail, Building2, BriefcaseBusiness, Info, Eye, EyeOff } from 'lucide-react';

import { authService, type PasswordRequirements as PasswordConfig } from '@domains/authentication/services/AuthenticationService';
import { useAuthStore } from '@domains/authentication/stores/authStore';
import xcellbioLogo from '@shared/assets/frozen-xcellbio-logo.png';
import { useFocusTrap } from '@shared/hooks/useFocusTrap';
import { notifications } from '@shared/utils';

import { PasswordRequirements } from './PasswordRequirements';
import { RegistrationSuccessModal } from './RegistrationSuccessModal';



interface RegisterModalProps {
  onSwitchToLogin?: () => void;
}

export function RegisterModal({ onSwitchToLogin }: RegisterModalProps) {
  // Researcher profile fields
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [department, setDepartment] = useState('');
  const [position, setPosition] = useState('');

  // Authentication fields
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // Researcher profile creation flag (defaults to true for backward compatibility)
  const [createResearcher, setCreateResearcher] = useState(true);

  // Password validation
  const [passwordConfig, setPasswordConfig] = useState<PasswordConfig | null>(null);

  // Field touched state for validation
  const [firstNameTouched, setFirstNameTouched] = useState(false);
  const [lastNameTouched, setLastNameTouched] = useState(false);
  const [emailTouched, setEmailTouched] = useState(false);
  const [passwordTouched, setPasswordTouched] = useState(false);

  // Email error state (for duplicate email errors from backend)
  const [emailError, setEmailError] = useState<string | null>(null);

  // Success modal state
  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const [registrationResult, setRegistrationResult] = useState<{
    username: string;
    email: string;
    status: 'approved' | 'pending';
  } | null>(null);

  const firstNameInputRef = useRef<HTMLInputElement>(null);

  // Focus trap with initial focus on first name field
  const trapRef = useFocusTrap({
    isOpen: true,
    restoreFocus: true,
    initialFocusRef: firstNameInputRef
  });

  const { registerWithResearcher } = useAuthStore();

  // Auto-generate username preview from researcher name
  const usernamePreview = useMemo(() => {
    if (!firstName.trim() || !lastName.trim()) {
      return '';
    }
    const cleanFirst = firstName.trim().toLowerCase().replace(/[^a-z]/g, '');
    const cleanLast = lastName.trim().toLowerCase().replace(/[^a-z]/g, '');
    if (!cleanFirst || !cleanLast) {
      return '';
    }
    return `${cleanFirst}.${cleanLast}`;
  }, [firstName, lastName]);

  // Fetch password requirements on mount
  useEffect(() => {
    async function loadPasswordRequirements() {
      try {
        const requirements = await authService.getPasswordRequirements();
        setPasswordConfig(requirements);
      } catch (error) {
        console.error('Failed to load password requirements:', error);
        // Keep default requirements on error
      }
    }
    void loadPasswordRequirements();
  }, []);

  // Helper function to get field border class for container
  const getFieldBorderClass = (touched: boolean, isValid: boolean) => {
    if (!touched) return 'border-gray-300';
    return isValid ? 'border-green-500' : 'input-field-error';
  };

  // Helper function to get label color class
  const getLabelColorClass = (touched: boolean, isValid: boolean) => {
    if (!touched) return 'text-gray-700';
    return isValid ? 'text-green-700' : 'text-validation-error-label';
  };

  // Validate email format
  const emailIsValid = useMemo(() => {
    if (!email.trim()) return false;
    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailPattern.test(email.trim());
  }, [email]);

  // Validate password meets all requirements using shared validator
  const passwordMeetsRequirements = useMemo(() => {
    if (!passwordConfig || !password) return false;
    return PasswordValidator.validate(password, passwordConfig).isValid;
  }, [password, passwordConfig]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Clear previous email error
    setEmailError(null);

    // Validation
    if (!firstName.trim() || !lastName.trim() || !email.trim() || !password.trim()) {
      notifications.error('Please fill in all required fields');
      return;
    }

    // Email format validation
    if (!emailIsValid) {
      setEmailTouched(true);
      notifications.error('Please enter a valid email address');
      return;
    }

    if (password !== confirmPassword) {
      notifications.error('Passwords do not match');
      return;
    }

    // Client-side password requirements validation
    if (!passwordMeetsRequirements) {
      setPasswordTouched(true); // Show red error state
      notifications.error('Password does not meet requirements');
      return;
    }

    setIsLoading(true);

    try {
      const result = await registerWithResearcher({
        firstName,
        lastName,
        email: email.trim(),
        department: department.trim() || undefined,
        position: position.trim() || undefined,
        password,
        createResearcher
      });

      if (result.success) {
        // Store registration result and show success modal
        setRegistrationResult({
          username: usernamePreview,
          email: email.trim(),
          status: result.status as 'approved' | 'pending'
        });
        setShowSuccessModal(true);
      } else {
        // Check if it's an email-specific error
        const errorMessage = result.message ?? 'Registration failed. Please check your information and try again.';
        if (errorMessage.toLowerCase().includes('email')) {
          setEmailError(errorMessage);
          setEmailTouched(true);
        } else {
          notifications.error(errorMessage);
        }
      }
    } catch (error) {
      notifications.error('Registration failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleSuccessModalClose = () => {
    setShowSuccessModal(false);
    // Redirect to login if needed
    if (onSwitchToLogin) {
      onSwitchToLogin();
    }
  };

  // Show success modal if registration was successful
  if (showSuccessModal && registrationResult) {
    return (
      <RegistrationSuccessModal
        username={registrationResult.username}
        status={registrationResult.status}
        onClose={handleSuccessModalClose}
      />
    );
  }

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-[3px] flex items-center justify-center z-50 animate-in fade-in duration-150">
      <div ref={trapRef} className="bg-odysseus-surface rounded-2xl p-6 w-full max-w-lg mx-4 shadow-2xl shadow-blue-500/20 border border-odysseus-border animate-zoom-in-95 max-h-[95vh] overflow-y-auto">
        <div className="text-center mb-5">
          <div className="w-16 h-16 mx-auto mb-3 flex items-center justify-center">
            <img src={xcellbioLogo} alt="XcellBio" className="w-full h-full object-contain" />
          </div>
          <h2 className="text-xl font-bold text-odysseus-dark mb-1">Welcome to Odysseus</h2>
          <p className="text-sm text-odysseus-muted">Set up your account to get started</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Name Fields Group */}
          <div className="grid grid-cols-2 gap-3 items-start">
            {/* First Name Column with Username */}
            <div className="space-y-1.5">
              <div className={`auth-input-container ${getFieldBorderClass(firstNameTouched, firstName.trim().length > 0)}`}>
                <label
                  htmlFor="firstName"
                  className={`absolute -top-2 left-3 bg-odysseus-surface px-1 text-[10px] font-semibold uppercase tracking-wide transition-colors ${getLabelColorClass(firstNameTouched, firstName.trim().length > 0)}`}
                >
                  First Name <span className="text-red-500">*</span>
                </label>
                <div className="relative px-3 py-2">
                  <UserRound className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
                  <input
                    ref={firstNameInputRef}
                    type="text"
                    id="firstName"
                    value={firstName}
                    onChange={(e) => setFirstName(e.target.value)}
                    onBlur={() => setFirstNameTouched(true)}
                    className="pl-7 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                    placeholder="First name"
                    required
                    disabled={isLoading}
                    maxLength={50}
                  />
                </div>
              </div>
              {/* Username Preview - Always visible */}
              <div className="min-h-[18px] ml-1">
                {usernamePreview ? (
                  <p className="text-[10px] text-gray-600">
                    Username: <span className="font-mono font-semibold text-blue-700">{usernamePreview}</span>
                  </p>
                ) : (
                  <p className="text-[10px] text-gray-400">Username:</p>
                )}
              </div>
            </div>

            {/* Last Name */}
            <div className={`auth-input-container ${getFieldBorderClass(lastNameTouched, lastName.trim().length > 0)}`}>
              <label
                htmlFor="lastName"
                className={`absolute -top-2 left-3 bg-odysseus-surface px-1 text-[10px] font-semibold uppercase tracking-wide transition-colors ${getLabelColorClass(lastNameTouched, lastName.trim().length > 0)}`}
              >
                Last Name <span className="text-red-500">*</span>
              </label>
              <div className="relative px-3 py-2">
                <UserRound className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
                <input
                  type="text"
                  id="lastName"
                  value={lastName}
                  onChange={(e) => setLastName(e.target.value)}
                  onBlur={() => setLastNameTouched(true)}
                  className="pl-7 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                  placeholder="Last name"
                  required
                  disabled={isLoading}
                  maxLength={50}
                />
              </div>
            </div>
          </div>

          {/* Contact & Work Info Group */}
          <div className="space-y-3">
            {/* Email */}
            <div className="space-y-1">
              <div className={`auth-input-container ${emailError ? 'input-field-error' : getFieldBorderClass(emailTouched, emailIsValid)}`}>
                <label
                  htmlFor="email"
                  className={`absolute -top-2 left-3 bg-odysseus-surface px-1 text-[10px] font-semibold uppercase tracking-wide transition-colors ${emailError ? 'text-validation-error-label' : getLabelColorClass(emailTouched, emailIsValid)}`}
                >
                  Email <span className="text-red-500">*</span>
                </label>
                <div className="relative px-3 py-2">
                  <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
                  <input
                    type="email"
                    id="email"
                    value={email}
                    onChange={(e) => {
                      setEmail(e.target.value);
                      setEmailError(null); // Clear error when user types
                    }}
                    onBlur={(e) => {
                      setEmail(e.target.value.trim());
                      setEmailTouched(true);
                    }}
                    className="pl-7 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                    placeholder="name@institution.edu"
                    required
                    disabled={isLoading}
                    maxLength={255}
                  />
                </div>
              </div>
              {/* Email error message */}
              {emailError && (
                <p className="text-[11px] text-validation-error-helper ml-1">{emailError}</p>
              )}
            </div>

            <div className="grid grid-cols-2 gap-3 items-start">
              {/* Department */}
              <div className="auth-input-container border-gray-300">
                <label
                  htmlFor="department"
                  className="absolute -top-2 left-3 bg-odysseus-surface px-1 text-[10px] font-semibold uppercase tracking-wide text-gray-700"
                >
                  Department
                </label>
                <div className="relative px-3 py-2">
                  <Building2 className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
                  <input
                    type="text"
                    id="department"
                    value={department}
                    onChange={(e) => setDepartment(e.target.value)}
                    className="pl-7 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                    placeholder="Department name"
                    disabled={isLoading}
                    maxLength={100}
                  />
                </div>
              </div>

              {/* Position */}
              <div className="auth-input-container border-gray-300">
                <label
                  htmlFor="position"
                  className="absolute -top-2 left-3 bg-odysseus-surface px-1 text-[10px] font-semibold uppercase tracking-wide text-gray-700"
                >
                  Position
                </label>
                <div className="relative px-3 py-2">
                  <BriefcaseBusiness className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
                  <input
                    type="text"
                    id="position"
                    value={position}
                    onChange={(e) => setPosition(e.target.value)}
                    className="pl-7 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                    placeholder="Title or role"
                    disabled={isLoading}
                    maxLength={100}
                  />
                </div>
              </div>
            </div>

            {/* Researcher Profile Toggle */}
            <div className="ml-1">
              <label className="flex items-center space-x-1.5 cursor-pointer group">
                <div className="relative inline-flex items-center cursor-pointer">
                  <input
                    type="checkbox"
                    checked={createResearcher}
                    onChange={(e) => setCreateResearcher(e.target.checked)}
                    disabled={isLoading}
                    className="sr-only peer"
                  />
                  <div className="w-7 h-4 bg-gray-200 peer-focus:outline-none peer-focus:ring-2 peer-focus:ring-action/30 rounded-full peer peer-checked:after:translate-x-3 peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-3 after:w-3 after:transition-all peer-checked:bg-action peer-disabled:opacity-50 peer-disabled:cursor-not-allowed"></div>
                </div>
                <span className="text-xs text-gray-700 group-hover:text-gray-900">
                  I am a researcher
                </span>
              </label>
            </div>
          </div>

          {/* Password Fields Group */}
          <div className="pt-4 border-t border-odysseus-border space-y-3.5">
            <div>
              <div className={`auth-input-container ${getFieldBorderClass(passwordTouched, passwordMeetsRequirements)}`}>
                <label
                  htmlFor="password"
                  className={`absolute -top-2 left-3 bg-odysseus-surface px-1 text-[10px] font-semibold uppercase tracking-wide transition-colors ${getLabelColorClass(passwordTouched, passwordMeetsRequirements)}`}
                >
                  Password <span className="text-red-500">*</span>
                </label>
                <div className="relative px-3 py-2">
                  <KeyRound className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
                  <input
                    type={showPassword ? 'text' : 'password'}
                    id="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    onBlur={() => setPasswordTouched(true)}
                    className="pl-7 pr-8 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                    placeholder="Choose a secure password"
                    required
                    disabled={isLoading}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-700 rounded focus-enhanced"
                    aria-label={showPassword ? 'Hide password' : 'Show password'}
                  >
                    {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>

              {/* Password Requirements - Always visible */}
              {passwordConfig && (
                <PasswordRequirements
                  password={password}
                  config={passwordConfig}
                  showError={passwordTouched && !passwordMeetsRequirements}
                  className="ml-2"
                />
              )}
            </div>

            {/* Confirm Password */}
            <div>
              <div className={`auth-input-container ${getFieldBorderClass(!!confirmPassword, password === confirmPassword)}`}>
                <label
                  htmlFor="confirmPassword"
                  className={`absolute -top-2 left-3 bg-odysseus-surface px-1 text-[10px] font-semibold uppercase tracking-wide transition-colors ${getLabelColorClass(!!confirmPassword, password === confirmPassword)}`}
                >
                  Confirm Password <span className="text-red-500">*</span>
                </label>
                <div className="relative px-3 py-2">
                  <KeyRound className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
                  <input
                    type={showConfirmPassword ? 'text' : 'password'}
                    id="confirmPassword"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    className="pl-7 pr-8 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                    placeholder="Confirm password"
                    required
                    disabled={isLoading}
                  />
                  <button
                    type="button"
                    onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                    className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-700 rounded focus-enhanced"
                    aria-label={showConfirmPassword ? 'Hide password' : 'Show password'}
                  >
                    {showConfirmPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>
            </div>
          </div>

          <button
            type="submit"
            disabled={isLoading}
            className="w-full btn btn-primary h-12 text-base font-bold shadow-lg disabled:opacity-50 disabled:cursor-not-allowed mt-2.5"
          >
            {isLoading ? (
              <div className="flex items-center justify-center space-x-2">
                <div className="spinner w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                <span>Creating your account...</span>
              </div>
            ) : (
              'Create Account'
            )}
          </button>
        </form>

        <div className="mt-3 p-2 bg-frost rounded-lg border border-action/30">
          <div className="flex items-start space-x-1.5">
            <div className="w-4 h-4 rounded-full bg-action flex items-center justify-center flex-shrink-0 mt-0.5">
              <Info className="w-2.5 h-2.5 text-white" />
            </div>
            <div>
              <h3 className="text-xs font-bold text-action-hover mb-0.5">Registration</h3>
              <p className="text-xs text-action-hover/90 leading-snug">
                New users require admin approval before accessing the system.
              </p>
            </div>
          </div>
        </div>

        {onSwitchToLogin && (
          <div className="mt-4 text-center">
            <p className="text-xs text-odysseus-muted">
              Already have an account?{' '}
              <button
                type="button"
                onClick={onSwitchToLogin}
                className="text-action-hover font-semibold hover:text-[#3d6a99] transition-colors focus-enhanced rounded px-1"
              >
                Sign in
              </button>
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * RegistrationSuccessModal - Post-registration confirmation
 *
 * Professional confirmation modal shown after successful registration.
 * Clearly displays username, account status, and next steps.
 *
 * Inspired by enterprise biotech apps (Benchling, LabArchives).
 */

import React, { useState } from 'react';

import { CheckCircle, Copy, Check, Clock } from 'lucide-react';

import { useFocusTrap } from '@shared/hooks/useFocusTrap';

export interface RegistrationSuccessModalProps {
  username: string;
  status: 'approved' | 'pending';
  onClose: () => void;
}

export function RegistrationSuccessModal({
  username,
  status,
  onClose
}: RegistrationSuccessModalProps) {
  const [copied, setCopied] = useState(false);

  // Focus trap for keyboard accessibility
  const trapRef = useFocusTrap({
    isOpen: true,
    restoreFocus: true
  });

  const handleCopyUsername = async () => {
    try {
      await navigator.clipboard.writeText(username);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      // Fallback for older browsers
      const textArea = document.createElement('textarea');
      textArea.value = username;
      document.body.appendChild(textArea);
      textArea.select();
      document.execCommand('copy');
      document.body.removeChild(textArea);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const isPending = status === 'pending';

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-[3px] flex items-center justify-center z-[60] animate-in fade-in duration-150">
      <div ref={trapRef} className="bg-odysseus-surface rounded-2xl p-8 w-full max-w-md mx-4 shadow-2xl shadow-blue-500/20 border border-odysseus-border animate-zoom-in-95">
        {/* Success Icon */}
        <div className="flex justify-center mb-6">
          <div className="w-16 h-16 rounded-full bg-gradient-to-br from-green-500 to-green-600 flex items-center justify-center shadow-lg">
            <CheckCircle className="w-10 h-10 text-white" />
          </div>
        </div>

        {/* Heading */}
        <div className="text-center mb-6">
          <h2 className="text-2xl font-bold text-odysseus-dark">
            Account Created Successfully
          </h2>
        </div>

        {/* Username Display with Copy */}
        <div className="mb-6">
          <div className="text-xs font-semibold uppercase tracking-wide text-gray-700 mb-2">
            Your Username
          </div>
          <div className="flex items-center gap-2 p-3 bg-gray-50 border border-gray-300 rounded-lg">
            <span className="flex-1 font-mono text-base font-semibold text-odysseus-dark" role="status" aria-label={`Your username is ${username}`}>
              {username}
            </span>
            <button
              onClick={handleCopyUsername}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-odysseus-primary hover:text-odysseus-accent hover:bg-info-light rounded transition-colors"
              type="button"
              aria-label={`Copy username ${username}`}
            >
              {copied ? (
                <>
                  <Check size={14} />
                  <span>Copied!</span>
                </>
              ) : (
                <>
                  <Copy size={14} />
                  <span>Copy</span>
                </>
              )}
            </button>
          </div>
          <p className="text-xs text-gray-600 mt-2">
            Please save this username for future login
          </p>
        </div>

        {/* Status Information */}
        <div className="space-y-3 mb-6">
          {isPending ? (
            <>
              {/* Email Verification Required - Not currently implemented */}
              {/* <div className="alert-info flex items-start gap-3">
                <Mail className="w-5 h-5 alert-info-icon flex-shrink-0 mt-0.5" />
                <div className="flex-1">
                  <h3 className="alert-info-heading mb-1">
                    Step 1: Verify Your Email
                  </h3>
                  <p className="alert-info-text leading-relaxed">
                    We've sent a verification link to <span className="font-medium">{email}</span>. Please check your inbox and click the link to verify your email address.
                  </p>
                </div>
              </div> */}

              {/* Pending Admin Approval */}
              <div className="alert-warning flex items-start gap-3">
                <Clock className="w-5 h-5 alert-warning-icon flex-shrink-0 mt-0.5" />
                <div className="flex-1">
                  <h3 className="alert-warning-heading mb-1">
                    Administrator Approval Required
                  </h3>
                  <p className="alert-warning-text leading-relaxed">
                    An administrator will review your account. You&apos;ll be notified when approved.
                  </p>
                </div>
              </div>
            </>
          ) : (
            /* Approved Status (First User) */
            <div className="alert-success flex items-start gap-3">
              <CheckCircle className="w-5 h-5 alert-success-icon flex-shrink-0 mt-0.5" />
              <div className="flex-1">
                <h3 className="alert-success-heading mb-1">
                  Account Approved
                </h3>
                <p className="alert-success-text leading-relaxed">
                  You&apos;re all set! You can now log in with your username and password.
                </p>
              </div>
            </div>
          )}
        </div>

        {/* Close Button */}
        <button
          onClick={onClose}
          className="w-full btn btn-primary h-12 text-base font-bold shadow-lg"
          type="button"
        >
          {isPending ? 'Close and Return to Login' : 'Continue to Login'}
        </button>

        {/* Footer Note */}
        {isPending && (
          <p className="text-xs text-center text-gray-500 mt-4">
            You can close this window. We&apos;ll notify you when your account is ready.
          </p>
        )}
      </div>
    </div>
  );
}

/**
 * Reset Password Page Component
 *
 * Public page for users to reset their password using a token.
 * Accessed via link shared by admin (no authentication required - token is the authentication).
 *
 * Features:
 * - Token validation from URL query parameter
 * - Password strength indicator
 * - Password confirmation
 * - Show/hide password toggle
 * - Auto-redirect to login on success
 */

import { useState, useRef, useEffect } from 'react';

import { Eye, EyeOff } from 'lucide-react';
import toast from 'react-hot-toast';
import { useSearchParams, useNavigate } from 'react-router-dom';

import { authenticationService } from '../../services/AuthenticationService';


export const ResetPasswordPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const token = searchParams.get('token');

  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Timer ref for cleanup on unmount
  const redirectTimerRef = useRef<number | null>(null);

  // Cleanup timer on unmount
  useEffect(() => {
    return () => {
      if (redirectTimerRef.current !== null) {
        clearTimeout(redirectTimerRef.current);
      }
    };
  }, []);

  if (!token) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-100">
        <div className="bg-white p-8 rounded-lg shadow-md max-w-md w-full">
          <h2 className="text-2xl font-bold text-red-600 mb-4">Invalid Reset Link</h2>
          <p className="text-gray-700 mb-4">
            This password reset link is invalid or has expired.
          </p>
          <button
            onClick={() => navigate('/login')}
            className="btn-primary w-full"
          >
            Back to Login
          </button>
        </div>
      </div>
    );
  }

  const getPasswordStrength = (password: string): string => {
    if (password.length === 0) return '';
    if (password.length < 4) return 'Too short';
    if (password.length < 8) return 'Weak';
    if (password.length < 12) return 'Medium';
    return 'Strong';
  };

  const getPasswordStrengthColor = (password: string): string => {
    const strength = getPasswordStrength(password);
    if (strength === 'Too short' || strength === 'Weak') return 'text-red-600';
    if (strength === 'Medium') return 'text-yellow-600';
    if (strength === 'Strong') return 'text-green-600';
    return '';
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    // Validation
    if (!newPassword || newPassword.length < 4) {
      setError('Password must be at least 4 characters');
      return;
    }

    if (newPassword !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }

    setIsLoading(true);
    try {
      await authenticationService.resetPasswordWithToken(token, newPassword);
      toast.success('Password reset successfully! Redirecting to login...');

      // Store timer ID for proper cleanup
      redirectTimerRef.current = window.setTimeout(() => {
        void navigate('/login');
      }, 2000);
    } catch (error: any) {
      setError(error.message || 'Failed to reset password');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100">
      <div className="bg-white p-8 rounded-lg shadow-md max-w-md w-full">
        <h2 className="text-2xl font-bold text-gray-800 mb-2">Reset Your Password</h2>
        <p className="text-gray-600 mb-6 text-sm">
          Enter your new password below.
        </p>

        <form onSubmit={handleSubmit}>
          {/* New Password */}
          <div className="mb-4">
            <label htmlFor="new-password" className="block text-sm font-medium text-gray-700 mb-1">
              New Password
            </label>
            <div className="relative">
              <input
                id="new-password"
                type={showPassword ? 'text' : 'password'}
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                className="input w-full"
                placeholder="Enter new password"
                required
                aria-describedby="password-strength"
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-700"
                aria-label={showPassword ? 'Hide password' : 'Show password'}
                aria-controls="new-password"
              >
                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
            {newPassword && (
              <p id="password-strength" className={`text-xs mt-1 ${getPasswordStrengthColor(newPassword)}`}>
                Strength: {getPasswordStrength(newPassword)}
              </p>
            )}
          </div>

          {/* Confirm Password */}
          <div className="mb-4">
            <label htmlFor="confirm-password" className="block text-sm font-medium text-gray-700 mb-1">
              Confirm Password
            </label>
            <div className="relative">
              <input
                id="confirm-password"
                type={showConfirmPassword ? 'text' : 'password'}
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                className="input w-full"
                placeholder="Confirm new password"
                required
              />
              <button
                type="button"
                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-700"
                aria-label={showConfirmPassword ? 'Hide password' : 'Show password'}
                aria-controls="confirm-password"
              >
                {showConfirmPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
          </div>

          {/* Error Message */}
          {error && (
            <div className="mb-4 p-3 bg-red-100 border border-red-400 text-red-700 rounded-md text-sm">
              {error}
            </div>
          )}

          {/* Submit Button */}
          <button
            type="submit"
            disabled={isLoading}
            className="btn-primary w-full mb-3"
          >
            {isLoading ? 'Resetting Password...' : 'Reset Password'}
          </button>

          {/* Back to Login */}
          <button
            type="button"
            onClick={() => navigate('/login')}
            className="w-full text-blue-600 hover:text-blue-800 text-sm"
          >
            Back to Login
          </button>
        </form>

        {/* Help Text */}
        <div className="mt-6 pt-6 border-t border-gray-200">
          <p className="text-xs text-gray-600">
            This reset link expires in 15 minutes and can only be used once.
          </p>
        </div>
      </div>
    </div>
  );
};

/**
 * User Settings Modal
 *
 * Modal for managing user-specific preferences and settings.
 * Extensible tab-based interface for future settings categories.
 */
import { useState, useEffect, lazy, Suspense } from 'react';

import { X, Save, RefreshCw, Cog, Table2, UserRound, Shield, AlertTriangle } from 'lucide-react';

import { TabSkeleton } from '@domains/admin/ui/components/TabSkeleton';
import { useFocusTrap } from '@shared/hooks/useFocusTrap';
import { notifications } from '@shared/utils';

import { useUserSettings, useUserSettingsActions } from '../../hooks/useUserSettings';

import type { UserSettings, PositionDisplayPreference } from '@odysseus/shared-schemas';


// Lazy-load tab components for code splitting
const PositionDisplayPreferenceTab = lazy(() =>
  import('./tabs/PositionDisplayPreferenceTab').then(m => ({ default: m.PositionDisplayPreferenceTab }))
);
const AccountTab = lazy(() =>
  import('./tabs/AccountTab').then(m => ({ default: m.AccountTab }))
);
const SecurityTab = lazy(() =>
  import('./tabs/SecurityTab').then(m => ({ default: m.SecurityTab }))
);

interface UserSettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function UserSettingsModal({ isOpen, onClose }: UserSettingsModalProps) {
  const [activeTab, setActiveTab] = useState<'account' | 'security' | 'display'>('account');
  const [localSettings, setLocalSettings] = useState<UserSettings>({});
  const [originalSettings, setOriginalSettings] = useState<UserSettings>({});

  // Fetch user settings
  const { settings, isLoading } = useUserSettings();
  const { updateSettings, isSaving } = useUserSettingsActions();

  // Focus trap (only active when modal is open)
  const trapRef = useFocusTrap({
    isOpen,
    restoreFocus: true,
    autoFocusFirstInput: false,
  });

  // Load settings when modal opens
  useEffect(() => {
    if (isOpen && settings) {
      setLocalSettings(settings);
      setOriginalSettings(settings);
    }
  }, [isOpen, settings]);

  const handlePositionDisplayChange = (preference: PositionDisplayPreference | undefined) => {
    setLocalSettings(prev => ({
      ...prev,
      defaultPositionDisplay: preference?.format ? preference : undefined,
    }));
  };

  const handleSave = async () => {
    try {
      await updateSettings(localSettings, {
        onSuccess: () => {
          notifications.success('Settings saved successfully');
          setOriginalSettings(localSettings);
          onClose();
        },
        onError: (error: Error) => {
          console.error('❌ [UserSettingsModal] Save failed:', error);
          notifications.error(`Failed to save settings: ${error.message}`);
        },
      });
    } catch (error) {
      console.error('❌ [UserSettingsModal] Failed to save settings:', error);
      notifications.error('Failed to save settings');
    }
  };

  if (!isOpen) return null;

  // Check if there are any unsaved changes
  const hasChanges = JSON.stringify(localSettings) !== JSON.stringify(originalSettings);

  const tabs = [
    { id: 'account', label: 'Account', icon: UserRound },
    { id: 'security', label: 'Security', icon: Shield },
    { id: 'display', label: 'Display Preferences', icon: Table2 },
  ] as const;

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-[2px] flex items-center justify-center z-50 animate-in fade-in duration-[180ms]">
      <div
        ref={trapRef}
        className="bg-white rounded-2xl shadow-2xl border border-gray-200 w-full max-w-4xl h-[75vh] mx-4 overflow-hidden animate-slide-up-fade flex flex-col"
      >
        {/* Header */}
        <div className="bg-gradient-to-r from-action-hover via-action to-action-hover px-6 py-3 text-white flex-shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <Cog className="w-6 h-6" />
              <div>
                <h2 className="text-lg font-bold">User Settings</h2>
                <p className="text-white/80 text-xs">Account & Personal Preferences</p>
              </div>
            </div>
            <button
              onClick={onClose}
              className="btn-header-menu text-white/80 hover:text-white hover:bg-primary-hover/50"
              aria-label="Close settings"
            >
              <X size={20} />
            </button>
          </div>
        </div>

        <div className="flex flex-1 min-h-0">
          {/* Sidebar (only show if multiple tabs in future) */}
          {tabs.length > 1 && (
            <div className="w-48 bg-gray-50 border-r border-gray-200 p-4">
              <nav className="space-y-2">
                {tabs.map(tab => {
                  const Icon = tab.icon;
                  return (
                    <button
                      key={tab.id}
                      onClick={() => setActiveTab(tab.id)}
                      className={`nav-tab ${
                        activeTab === tab.id
                          ? 'bg-primary-light text-primary-hover border border-primary-border'
                          : 'text-gray-600 hover:bg-gray-100 hover:text-gray-900'
                      }`}
                    >
                      <Icon size={20} />
                      <span className="font-medium text-sm">{tab.label}</span>
                    </button>
                  );
                })}
              </nav>
            </div>
          )}

          {/* Content */}
          <div className="flex-1 overflow-y-auto min-w-0">
            <div className="p-6 min-w-0">
              {isLoading ? (
                <TabSkeleton />
              ) : (
                <>
                  {activeTab === 'account' && (
                    <Suspense fallback={<TabSkeleton />}>
                      <AccountTab onSaveComplete={onClose} />
                    </Suspense>
                  )}
                  {activeTab === 'security' && (
                    <Suspense fallback={<TabSkeleton />}>
                      <SecurityTab />
                    </Suspense>
                  )}
                  {activeTab === 'display' && (
                    <Suspense fallback={<TabSkeleton />}>
                      <PositionDisplayPreferenceTab
                        defaultPositionDisplay={localSettings.defaultPositionDisplay}
                        savedPositionDisplay={originalSettings.defaultPositionDisplay}
                        onChange={handlePositionDisplayChange}
                      />
                    </Suspense>
                  )}
                </>
              )}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="border-t border-gray-200 px-6 py-3 bg-gray-50 flex-shrink-0">
          <div className="flex items-center justify-between gap-4">
            <div className="flex items-center space-x-2 text-xs text-gray-600 flex-shrink min-w-0">
              <AlertTriangle size={14} className="alert-warning-icon flex-shrink-0" />
              <span className="truncate">These settings apply only to your account.</span>
            </div>
            <div className="flex space-x-2 flex-shrink-0">
              <button onClick={onClose} className="btn-cancel">
                Cancel
              </button>
              <button
                onClick={handleSave}
                disabled={isSaving || !hasChanges}
                className="btn btn-primary flex items-center space-x-2 text-sm px-3 py-1.5 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isSaving ? (
                  <RefreshCw size={14} className="animate-spin" />
                ) : (
                  <Save size={14} />
                )}
                <span>{isSaving ? 'Saving...' : 'Save Changes'}</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * VerifyEmailPage - Email verification landing page
 *
 * Handles email verification when user clicks link from their email.
 * Reads token from URL, calls backend, shows status, then redirects to login.
 */

import React, { useEffect, useState, useRef } from 'react';

import { CheckCircle, XCircle, Loader2, ArrowRight } from 'lucide-react';
import { useSearchParams, useNavigate } from 'react-router-dom';

import { authService } from '../../services/AuthenticationService';

export function VerifyEmailPage() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const [status, setStatus] = useState<'verifying' | 'success' | 'error'>('verifying');
  const [error, setError] = useState<string>('');

  // Store timer ID for cleanup
  const redirectTimerRef = useRef<number | null>(null);

  useEffect(() => {
    const verifyEmail = async () => {
      const token = searchParams.get('token');

      if (!token) {
        setStatus('error');
        setError('Invalid verification link. Token is missing.');
        return;
      }

      try {
        await authService.verifyEmail(token);
        setStatus('success');

        // Redirect to home (login modal) after 3 seconds
        redirectTimerRef.current = window.setTimeout(() => {
          void navigate('/');
        }, 3000);
      } catch (err) {
        setStatus('error');
        setError(err instanceof Error ? err.message : 'Verification failed. Please try again.');
      }
    };

    void verifyEmail();

    // Cleanup timer on unmount
    return () => {
      if (redirectTimerRef.current !== null) {
        clearTimeout(redirectTimerRef.current);
      }
    };
  }, [searchParams, navigate]);

  if (status === 'verifying') {
    return (
      <div className="min-h-screen bg-gradient-to-br from-odysseus-primary via-blue-600 to-blue-700 flex items-center justify-center p-4">
        <div className="bg-odysseus-surface rounded-2xl p-8 w-full max-w-md mx-4 shadow-2xl border border-odysseus-border">
          <div className="flex flex-col items-center text-center">
            <Loader2 className="w-16 h-16 text-odysseus-primary animate-spin mb-4" />
            <h2 className="text-2xl font-bold text-odysseus-dark mb-2">
              Verifying Your Email
            </h2>
            <p className="text-gray-600">
              Please wait while we verify your email address...
            </p>
          </div>
        </div>
      </div>
    );
  }

  if (status === 'success') {
    return (
      <div className="min-h-screen bg-gradient-to-br from-odysseus-primary via-blue-600 to-blue-700 flex items-center justify-center p-4">
        <div className="bg-odysseus-surface rounded-2xl p-8 w-full max-w-md mx-4 shadow-2xl border border-odysseus-border">
          <div className="flex justify-center mb-6">
            <div className="w-16 h-16 rounded-full bg-gradient-to-br from-green-500 to-green-600 flex items-center justify-center shadow-lg">
              <CheckCircle className="w-10 h-10 text-white" />
            </div>
          </div>

          <div className="text-center mb-6">
            <h2 className="text-2xl font-bold text-odysseus-dark mb-2">
              Email Verified!
            </h2>
            <p className="text-gray-600">
              Your email has been successfully verified.
            </p>
          </div>

          <div className="bg-green-50 border border-green-200 rounded-lg p-4 mb-6">
            <p className="text-sm text-green-800 font-medium">
              Redirecting to login in 3 seconds...
            </p>
          </div>

          <button
            onClick={() => navigate('/')}
            className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-odysseus-primary hover:bg-odysseus-accent text-white font-medium rounded-lg transition-all duration-150 shadow-md hover:shadow-lg"
          >
            Go to Login Now
            <ArrowRight className="w-4 h-4" />
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-odysseus-primary via-blue-600 to-blue-700 flex items-center justify-center p-4">
      <div className="bg-odysseus-surface rounded-2xl p-8 w-full max-w-md mx-4 shadow-2xl border border-odysseus-border">
        <div className="flex justify-center mb-6">
          <div className="w-16 h-16 rounded-full bg-gradient-to-br from-red-500 to-red-600 flex items-center justify-center shadow-lg">
            <XCircle className="w-10 h-10 text-white" />
          </div>
        </div>

        <div className="text-center mb-6">
          <h2 className="text-2xl font-bold text-odysseus-dark mb-2">
            Verification Failed
          </h2>
          <p className="text-gray-600">
            {error}
          </p>
        </div>

        <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6">
          <p className="text-sm text-red-800 font-medium mb-2">
            Common reasons for failure:
          </p>
          <ul className="text-sm text-red-700 space-y-1 list-disc list-inside">
            <li>Verification link expired (48 hours)</li>
            <li>Link already used</li>
            <li>Invalid or corrupted token</li>
          </ul>
        </div>

        <button
          onClick={() => navigate('/')}
          className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-odysseus-primary hover:bg-odysseus-accent text-white font-medium rounded-lg transition-all duration-150 shadow-md hover:shadow-lg"
        >
          Back to Login
          <ArrowRight className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
}

/**
 * Account Tab
 *
 * User profile management with password confirmation requirement.
 * Uses label-in-border styling matching RegisterModal.
 */
import { useState, useEffect, useMemo } from 'react';

import { UserRound, Mail, Building2, BriefcaseBusiness, KeyRound, Save, RefreshCw } from 'lucide-react';

import { useUserProfile, useUserProfileActions } from '@domains/users/hooks/useUserProfile';
import { notifications } from '@shared/utils';

import type { UpdatePersonProfileWithPassword } from '@domains/users/services/PersonService';

interface AccountTabProps {
  onSaveComplete?: () => void;
}

export function AccountTab({ onSaveComplete }: AccountTabProps) {
  const { profile, isLoading } = useUserProfile();
  const { updateProfile, isUpdating } = useUserProfileActions();

  // Form fields
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [department, setDepartment] = useState('');
  const [position, setPosition] = useState('');
  const [currentPassword, setCurrentPassword] = useState('');

  // Touched state for validation
  const [firstNameTouched, setFirstNameTouched] = useState(false);
  const [lastNameTouched, setLastNameTouched] = useState(false);
  const [emailTouched, setEmailTouched] = useState(false);
  const [passwordTouched, setPasswordTouched] = useState(false);

  // Load profile data
  useEffect(() => {
    if (profile) {
      setFirstName(profile.firstName);
      setLastName(profile.lastName);
      setEmail(profile.email);
      setDepartment(profile.department ?? '');
      setPosition(profile.position ?? '');
    }
  }, [profile]);

  // Field border styling
  const getFieldBorderClass = (touched: boolean, isValid: boolean) => {
    if (!touched) return 'border-gray-300';
    return isValid ? 'border-green-500' : 'input-field-error';
  };

  // Label color styling
  const getLabelColorClass = (touched: boolean, isValid: boolean) => {
    if (!touched) return 'text-gray-700';
    return isValid ? 'text-green-700' : 'text-validation-error-label';
  };

  // Email validation
  const emailIsValid = useMemo(() => {
    if (!email.trim()) return false;
    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailPattern.test(email.trim());
  }, [email]);

  // Check if there are changes
  const hasChanges = useMemo(() => {
    if (!profile) return false;
    return (
      firstName !== profile.firstName ||
      lastName !== profile.lastName ||
      email !== profile.email ||
      department !== (profile.department ?? '') ||
      position !== (profile.position ?? '')
    );
  }, [profile, firstName, lastName, email, department, position]);

  const handleSave = async () => {
    // Validation
    if (!firstName.trim() || !lastName.trim() || !email.trim()) {
      notifications.error('First name, last name, and email are required');
      return;
    }

    if (!emailIsValid) {
      setEmailTouched(true);
      notifications.error('Please enter a valid email address');
      return;
    }

    if (!currentPassword.trim()) {
      setPasswordTouched(true);
      notifications.error('Current password is required to update your profile');
      return;
    }

    // Build update object
    const updateData: UpdatePersonProfileWithPassword = {
      currentPassword,
    };

    if (firstName !== profile?.firstName) updateData.firstName = firstName.trim();
    if (lastName !== profile?.lastName) updateData.lastName = lastName.trim();
    if (email !== profile?.email) updateData.email = email.trim();
    if (department !== (profile?.department ?? '')) updateData.department = department.trim() || undefined;
    if (position !== (profile?.position ?? '')) updateData.position = position.trim() || undefined;

    updateProfile(updateData, {
      onSuccess: () => {
        notifications.success('Profile updated successfully');
        setCurrentPassword(''); // Clear password field
        setPasswordTouched(false);
        if (onSaveComplete) {
          onSaveComplete();
        }
      },
      onError: (error: Error) => {
        console.error('❌ [AccountTab] Update failed:', error);
        if (error.message.includes('password')) {
          setPasswordTouched(true);
        }
        notifications.error(error.message || 'Failed to update profile');
      },
    });
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <RefreshCw className="w-6 h-6 animate-spin text-action" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center space-x-2 pb-3 border-b border-gray-200 mb-4">
        <UserRound size={22} className="text-gray-700" />
        <h3 className="text-xl font-semibold text-gray-900">Account Information</h3>
      </div>

      <div className="space-y-4 max-w-2xl">
        {/* Name Fields */}
        <div className="grid grid-cols-2 gap-3">
          {/* First Name */}
          <div className={`auth-input-container ${getFieldBorderClass(firstNameTouched, firstName.trim().length > 0)}`}>
            <label
              htmlFor="account-firstName"
              className={`absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide transition-colors ${getLabelColorClass(firstNameTouched, firstName.trim().length > 0)}`}
            >
              First Name <span className="text-red-500">*</span>
            </label>
            <div className="relative px-3 py-2">
              <UserRound className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
              <input
                type="text"
                id="account-firstName"
                value={firstName}
                onChange={(e) => setFirstName(e.target.value)}
                onBlur={() => setFirstNameTouched(true)}
                className="pl-7 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                placeholder="First name"
                required
                disabled={isUpdating}
                maxLength={50}
              />
            </div>
          </div>

          {/* Last Name */}
          <div className={`auth-input-container ${getFieldBorderClass(lastNameTouched, lastName.trim().length > 0)}`}>
            <label
              htmlFor="account-lastName"
              className={`absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide transition-colors ${getLabelColorClass(lastNameTouched, lastName.trim().length > 0)}`}
            >
              Last Name <span className="text-red-500">*</span>
            </label>
            <div className="relative px-3 py-2">
              <UserRound className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
              <input
                type="text"
                id="account-lastName"
                value={lastName}
                onChange={(e) => setLastName(e.target.value)}
                onBlur={() => setLastNameTouched(true)}
                className="pl-7 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                placeholder="Last name"
                required
                disabled={isUpdating}
                maxLength={50}
              />
            </div>
          </div>
        </div>

        {/* Email */}
        <div className={`auth-input-container ${getFieldBorderClass(emailTouched, emailIsValid)}`}>
          <label
            htmlFor="account-email"
            className={`absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide transition-colors ${getLabelColorClass(emailTouched, emailIsValid)}`}
          >
            Email <span className="text-red-500">*</span>
          </label>
          <div className="relative px-3 py-2">
            <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
            <input
              type="email"
              id="account-email"
              value={email}
              onChange={(e) => {
                setEmail(e.target.value);
              }}
              onBlur={(e) => {
                setEmail(e.target.value.trim());
                setEmailTouched(true);
              }}
              className="pl-7 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
              placeholder="name@institution.edu"
              required
              disabled={isUpdating}
              maxLength={255}
            />
          </div>
        </div>

        {/* Department & Position */}
        <div className="grid grid-cols-2 gap-3">
          {/* Department */}
          <div className="auth-input-container border-gray-300">
            <label
              htmlFor="account-department"
              className="absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide text-gray-700"
            >
              Department
            </label>
            <div className="relative px-3 py-2">
              <Building2 className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
              <input
                type="text"
                id="account-department"
                value={department}
                onChange={(e) => setDepartment(e.target.value)}
                className="pl-7 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                placeholder="Department name"
                disabled={isUpdating}
                maxLength={100}
              />
            </div>
          </div>

          {/* Position */}
          <div className="auth-input-container border-gray-300">
            <label
              htmlFor="account-position"
              className="absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide text-gray-700"
            >
              Position
            </label>
            <div className="relative px-3 py-2">
              <BriefcaseBusiness className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
              <input
                type="text"
                id="account-position"
                value={position}
                onChange={(e) => setPosition(e.target.value)}
                className="pl-7 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                placeholder="Title or role"
                disabled={isUpdating}
                maxLength={100}
              />
            </div>
          </div>
        </div>

        {/* Password Confirmation Section */}
        {hasChanges && (
          <div className="pt-4 border-t border-gray-200 space-y-2">
            <div className="mb-2">
              <p className="text-sm font-semibold text-gray-900">Confirm Changes</p>
              <p className="text-xs text-gray-600">Enter your current password to save changes</p>
            </div>

            <div className={`auth-input-container ${getFieldBorderClass(passwordTouched, currentPassword.trim().length > 0)}`}>
              <label
                htmlFor="account-currentPassword"
                className={`absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide transition-colors ${getLabelColorClass(passwordTouched, currentPassword.trim().length > 0)}`}
              >
                Current Password <span className="text-red-500">*</span>
              </label>
              <div className="relative px-3 py-2">
                <KeyRound className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
                <input
                  type="password"
                  id="account-currentPassword"
                  value={currentPassword}
                  onChange={(e) => setCurrentPassword(e.target.value)}
                  onBlur={() => setPasswordTouched(true)}
                  className="pl-7 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                  placeholder="Enter current password"
                  required
                  disabled={isUpdating}
                />
              </div>
            </div>

            {/* Save Button */}
            <button
              onClick={handleSave}
              disabled={isUpdating || !currentPassword.trim()}
              className="btn btn-primary flex items-center space-x-2 text-sm px-4 py-2 disabled:opacity-50 disabled:cursor-not-allowed mt-3"
            >
              {isUpdating ? (
                <RefreshCw size={14} className="animate-spin" />
              ) : (
                <Save size={14} />
              )}
              <span>{isUpdating ? 'Saving...' : 'Save Changes'}</span>
            </button>
          </div>
        )}

        {!hasChanges && (
          <div className="pt-4 border-t border-gray-200">
            <p className="text-sm text-gray-500 italic">No changes to save</p>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Position Display Preference Tab
 *
 * Allows users to set their default position display format preference.
 * This setting determines how position labels are displayed throughout the app,
 * unless overridden at the lab or box level.
 *
 * Note: User preferences store only the format (numeric/alphanumeric).
 * Full configs with grid-specific details are generated when applied to boxes.
 */
import { Table2 } from 'lucide-react';

import type { PositionDisplayPreference } from '@odysseus/shared-schemas';

interface PositionDisplayPreferenceTabProps {
  defaultPositionDisplay: PositionDisplayPreference | null | undefined;
  savedPositionDisplay: PositionDisplayPreference | null | undefined;
  onChange: (preference: PositionDisplayPreference | undefined) => void;
}

export function PositionDisplayPreferenceTab({
  defaultPositionDisplay,
  savedPositionDisplay,
  onChange,
}: PositionDisplayPreferenceTabProps) {
  const currentFormat = defaultPositionDisplay?.format ?? null;
  const savedFormat = savedPositionDisplay?.format ?? null;

  const handleFormatChange = (format: 'numeric' | 'alphanumeric' | null) => {
    if (format === null) {
      onChange(undefined);
    } else {
      onChange({ format });
    }
  };

  return (
    <div className="space-y-2">
      {/* Header */}
      <div className="flex items-center space-x-2 pb-3 border-b border-gray-200 mb-4">
        <Table2 size={22} className="text-gray-700" />
        <h3 className="text-xl font-semibold text-gray-900">Display Preferences</h3>
      </div>

      {/* Position Display Format Section */}
      <div>
        <h4 className="text-base font-semibold text-gray-900 mb-2">Position Display Format</h4>
        <p className="text-xs text-gray-600 mb-3">
          Choose how position labels are displayed throughout the application.
          This is your personal preference and won&apos;t affect other users.
        </p>

        {/* Segmented Control with Inline Descriptions */}
        <div className="grid grid-cols-3 gap-2">
          {/* Numeric Option */}
          <button
            type="button"
            onClick={() => handleFormatChange('numeric')}
            className={`px-3 py-2 rounded-lg border-2 text-left transition-all relative ${
              currentFormat === 'numeric'
                ? 'bg-action border-action text-white shadow-md'
                : 'bg-white border-gray-300 text-gray-700 hover:border-action hover:bg-action/10'
            }`}
          >
            {savedFormat === 'numeric' && (
              <span className={`absolute top-2 right-2 text-[10px] font-semibold px-2 py-0.5 rounded ${
                currentFormat === 'numeric'
                  ? 'bg-white/20 text-white'
                  : 'bg-action text-white'
              }`}>
                Active
              </span>
            )}
            <h5 className="text-sm font-semibold mb-1">Numeric</h5>
            <p className={`text-xs mb-2 ${currentFormat === 'numeric' ? 'text-white/80' : 'text-gray-600'}`}>
              Sequential numbers
            </p>
            <div className="flex items-center space-x-1 text-xs">
              <span className={`font-mono px-1.5 py-0.5 rounded ${
                currentFormat === 'numeric'
                  ? 'bg-action-hover text-white'
                  : 'bg-gray-100 text-gray-700'
              }`}>1</span>
              <span className={`font-mono px-1.5 py-0.5 rounded ${
                currentFormat === 'numeric'
                  ? 'bg-action-hover text-white'
                  : 'bg-gray-100 text-gray-700'
              }`}>2</span>
              <span>...</span>
              <span className={`font-mono px-1.5 py-0.5 rounded ${
                currentFormat === 'numeric'
                  ? 'bg-action-hover text-white'
                  : 'bg-gray-100 text-gray-700'
              }`}>81</span>
            </div>
          </button>

          {/* Alphanumeric Option */}
          <button
            type="button"
            onClick={() => handleFormatChange('alphanumeric')}
            className={`px-3 py-2 rounded-lg border-2 text-left transition-all relative ${
              currentFormat === 'alphanumeric'
                ? 'bg-action border-action text-white shadow-md'
                : 'bg-white border-gray-300 text-gray-700 hover:border-action hover:bg-action/10'
            }`}
          >
            {savedFormat === 'alphanumeric' && (
              <span className={`absolute top-2 right-2 text-[10px] font-semibold px-2 py-0.5 rounded ${
                currentFormat === 'alphanumeric'
                  ? 'bg-white/20 text-white'
                  : 'bg-action text-white'
              }`}>
                Active
              </span>
            )}
            <h5 className="text-sm font-semibold mb-1">Alphanumeric</h5>
            <p className={`text-xs mb-2 ${currentFormat === 'alphanumeric' ? 'text-white/80' : 'text-gray-600'}`}>
              Row letter + column
            </p>
            <div className="flex items-center space-x-1 text-xs">
              <span className={`font-mono px-1.5 py-0.5 rounded ${
                currentFormat === 'alphanumeric'
                  ? 'bg-action-hover text-white'
                  : 'bg-gray-100 text-gray-700'
              }`}>A1</span>
              <span className={`font-mono px-1.5 py-0.5 rounded ${
                currentFormat === 'alphanumeric'
                  ? 'bg-action-hover text-white'
                  : 'bg-gray-100 text-gray-700'
              }`}>B2</span>
              <span>...</span>
              <span className={`font-mono px-1.5 py-0.5 rounded ${
                currentFormat === 'alphanumeric'
                  ? 'bg-action-hover text-white'
                  : 'bg-gray-100 text-gray-700'
              }`}>I9</span>
            </div>
          </button>

          {/* System Default Option */}
          <button
            type="button"
            onClick={() => handleFormatChange(null)}
            className={`px-3 py-2 rounded-lg border-2 text-left transition-all relative ${
              !currentFormat
                ? 'bg-action border-action text-white shadow-md'
                : 'bg-white border-gray-300 text-gray-700 hover:border-action hover:bg-action/10'
            }`}
          >
            {!savedFormat && (
              <span className={`absolute top-2 right-2 text-[10px] font-semibold px-2 py-0.5 rounded ${
                !currentFormat
                  ? 'bg-white/20 text-white'
                  : 'bg-action text-white'
              }`}>
                Active
              </span>
            )}
            <h5 className="text-sm font-semibold mb-1">System Default</h5>
            <p className={`text-xs mb-2 ${!currentFormat ? 'text-white/80' : 'text-gray-600'}`}>
              Alphanumeric format
            </p>
            <div className="flex items-center space-x-1 text-xs">
              <span className={`font-mono px-1.5 py-0.5 rounded ${
                !currentFormat
                  ? 'bg-action-hover text-white'
                  : 'bg-gray-100 text-gray-700'
              }`}>A1</span>
              <span className={`font-mono px-1.5 py-0.5 rounded ${
                !currentFormat
                  ? 'bg-action-hover text-white'
                  : 'bg-gray-100 text-gray-700'
              }`}>B2</span>
              <span>...</span>
              <span className={`font-mono px-1.5 py-0.5 rounded ${
                !currentFormat
                  ? 'bg-action-hover text-white'
                  : 'bg-gray-100 text-gray-700'
              }`}>I9</span>
            </div>
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Security Tab
 *
 * Password management for authenticated users.
 * Requires current password verification for security.
 */
import { useState, useEffect, useMemo } from 'react';

import { PasswordValidator } from '@odysseus/shared-schemas';
import { KeyRound, Save, RefreshCw, Eye, EyeOff, Shield, MonitorSmartphone } from 'lucide-react';

import { authService } from '@domains/authentication/services/AuthenticationService';
import { useChangePassword } from '@domains/users/hooks/useChangePassword';
import { AnimatedCheckmark } from '@shared/components';
import { notifications } from '@shared/utils';

import { PasswordRequirements } from '../PasswordRequirements';

import { SessionListSection } from './SessionListSection';

import type { PasswordRequirements as PasswordConfig } from '@domains/authentication/services/AuthenticationService';

interface SecurityTabProps {
  onSaveComplete?: () => void;
}

export function SecurityTab({ onSaveComplete }: SecurityTabProps) {
  const { changePassword, isChanging, reset } = useChangePassword();

  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const [_currentPasswordTouched, setCurrentPasswordTouched] = useState(false);
  const [newPasswordTouched, setNewPasswordTouched] = useState(false);
  const [confirmPasswordTouched, setConfirmPasswordTouched] = useState(false);

  const [currentPasswordError, setCurrentPasswordError] = useState<string | null>(null);

  const [showCurrentPassword, setShowCurrentPassword] = useState(false);
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const [passwordRequirements, setPasswordRequirements] = useState<PasswordConfig | null>(null);
  const [showSuccess, setShowSuccess] = useState(false);

  useEffect(() => {
    const fetchRequirements = async () => {
      try {
        const requirements = await authService.getPasswordRequirements();
        setPasswordRequirements(requirements);
      } catch (error) {
        console.error('Failed to fetch password requirements:', error);
      }
    };
    void fetchRequirements();
  }, []);

  const getFieldBorderClass = (touched: boolean, isValid: boolean) => {
    if (!touched) return 'border-gray-300';
    return isValid ? 'border-green-500' : 'input-field-error';
  };

  const getLabelColorClass = (touched: boolean, isValid: boolean) => {
    if (!touched) return 'text-gray-700';
    return isValid ? 'text-green-700' : 'text-validation-error-label';
  };

  // Current password field styling - neutral (no green) with error state only
  const getCurrentPasswordBorderClass = () => {
    return currentPasswordError ? 'input-field-error' : 'border-gray-300';
  };

  const getCurrentPasswordLabelClass = () => {
    return currentPasswordError ? 'text-validation-error-label' : 'text-gray-700';
  };

  const newPasswordMeetsRequirements = useMemo(() => {
    if (!passwordRequirements || !newPassword) return false;
    const result = PasswordValidator.validate(newPassword, passwordRequirements);
    return result.isValid;
  }, [newPassword, passwordRequirements]);

  const passwordsMatch = useMemo(() => {
    return newPassword === confirmPassword && confirmPassword.length > 0;
  }, [newPassword, confirmPassword]);

  const newPasswordIsDifferent = useMemo(() => {
    return currentPassword !== newPassword || newPassword.length === 0;
  }, [currentPassword, newPassword]);

  const isFormValid = useMemo(() => {
    return (
      currentPassword.trim().length > 0 &&
      newPasswordMeetsRequirements &&
      passwordsMatch &&
      newPasswordIsDifferent
    );
  }, [currentPassword, newPasswordMeetsRequirements, passwordsMatch, newPasswordIsDifferent]);

  const handleSubmit = async () => {
    if (!isFormValid) {
      if (currentPassword.trim().length === 0) {
        setCurrentPasswordError('Current password is required');
        return;
      }
      if (!newPasswordMeetsRequirements) {
        setNewPasswordTouched(true);
        notifications.error('New password does not meet requirements');
        return;
      }
      if (!passwordsMatch) {
        setConfirmPasswordTouched(true);
        notifications.error('Passwords do not match');
        return;
      }
      if (!newPasswordIsDifferent) {
        setNewPasswordTouched(true);
        notifications.error('New password must be different from current password');
        return;
      }
      return;
    }

    changePassword(
      { currentPassword, newPassword },
      {
        onSuccess: () => {
          notifications.success('Password changed successfully');
          setCurrentPassword('');
          setNewPassword('');
          setConfirmPassword('');
          setCurrentPasswordTouched(false);
          setNewPasswordTouched(false);
          setConfirmPasswordTouched(false);
          setCurrentPasswordError(null);
          setShowSuccess(true);
          reset();
          if (onSaveComplete) {
            onSaveComplete();
          }
        },
        onError: (error: Error) => {
          console.error('❌ [SecurityTab] Password change failed:', error);
          // Check if error is due to incorrect password
          if (error.message.toLowerCase().includes('incorrect') || error.message.toLowerCase().includes('invalid')) {
            setCurrentPasswordError('Current password is incorrect');
          }
          notifications.error(error.message || 'Failed to change password');
        },
      }
    );
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center space-x-2 pb-3 border-b border-gray-200 mb-4">
        <Shield size={22} className="text-gray-700" />
        <h3 className="text-xl font-semibold text-gray-900">Password Management</h3>
      </div>

      <div className="space-y-4 max-w-2xl">
        <p className="text-sm text-gray-600">Change your password to keep your account secure</p>

        {/* Current Password */}
        <div className="space-y-1">
          <div className={`auth-input-container ${getCurrentPasswordBorderClass()}`}>
            <label
              htmlFor="security-currentPassword"
              className={`absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide transition-colors ${getCurrentPasswordLabelClass()}`}
            >
              Current Password <span className="text-red-500">*</span>
            </label>
            <div className="relative px-3 py-2">
              <KeyRound className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
              <input
                type={showCurrentPassword ? 'text' : 'password'}
                id="security-currentPassword"
                value={currentPassword}
                onChange={(e) => {
                  setCurrentPassword(e.target.value);
                  setShowSuccess(false);
                  // Clear error when user starts typing
                  if (currentPasswordError) {
                    setCurrentPasswordError(null);
                  }
                }}
                className="pl-7 pr-10 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                placeholder="Enter current password"
                required
                disabled={isChanging}
              />
              <button
                type="button"
                onClick={() => setShowCurrentPassword(!showCurrentPassword)}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted hover:text-odysseus-dark transition-colors"
                aria-label={showCurrentPassword ? 'Hide password' : 'Show password'}
                tabIndex={-1}
              >
                {showCurrentPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
          </div>

          {currentPasswordError && (
            <p className="text-[10px] text-red-600 ml-1 mt-1">
              {currentPasswordError}
            </p>
          )}
        </div>

        {/* New Password */}
        <div className="space-y-1">
          <div className={`auth-input-container ${getFieldBorderClass(newPasswordTouched, newPasswordMeetsRequirements && newPasswordIsDifferent)}`}>
            <label
              htmlFor="security-newPassword"
              className={`absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide transition-colors ${getLabelColorClass(newPasswordTouched, newPasswordMeetsRequirements && newPasswordIsDifferent)}`}
            >
              New Password <span className="text-red-500">*</span>
            </label>
            <div className="relative px-3 py-2">
              <KeyRound className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
              <input
                type={showNewPassword ? 'text' : 'password'}
                id="security-newPassword"
                value={newPassword}
                onChange={(e) => {
                  setNewPassword(e.target.value);
                  setShowSuccess(false);
                }}
                onBlur={() => setNewPasswordTouched(true)}
                className="pl-7 pr-10 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                placeholder="Enter new password"
                required
                disabled={isChanging}
              />
              <button
                type="button"
                onClick={() => setShowNewPassword(!showNewPassword)}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted hover:text-odysseus-dark transition-colors"
                aria-label={showNewPassword ? 'Hide password' : 'Show password'}
                tabIndex={-1}
              >
                {showNewPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
          </div>

          {passwordRequirements && (
            <PasswordRequirements
              password={newPassword}
              config={passwordRequirements}
              showError={newPasswordTouched && !newPasswordMeetsRequirements}
            />
          )}

          {!newPasswordIsDifferent && newPasswordTouched && (
            <p className="text-[10px] text-red-600 ml-1 mt-1">
              New password must be different from current password
            </p>
          )}
        </div>

        {/* Confirm Password */}
        <div className="space-y-1">
          <div className={`auth-input-container ${getFieldBorderClass(confirmPasswordTouched, passwordsMatch)}`}>
            <label
              htmlFor="security-confirmPassword"
              className={`absolute -top-2 left-3 bg-white px-1 text-[10px] font-semibold uppercase tracking-wide transition-colors ${getLabelColorClass(confirmPasswordTouched, passwordsMatch)}`}
            >
              Confirm Password <span className="text-red-500">*</span>
            </label>
            <div className="relative px-3 py-2">
              <KeyRound className="absolute left-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted" size={16} />
              <input
                type={showConfirmPassword ? 'text' : 'password'}
                id="security-confirmPassword"
                value={confirmPassword}
                onChange={(e) => {
                  setConfirmPassword(e.target.value);
                  setShowSuccess(false);
                }}
                onBlur={() => setConfirmPasswordTouched(true)}
                className="pl-7 pr-10 text-sm placeholder:text-[#9aa0a6] placeholder:opacity-45"
                placeholder="Confirm new password"
                required
                disabled={isChanging}
              />
              <button
                type="button"
                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-odysseus-muted hover:text-odysseus-dark transition-colors"
                aria-label={showConfirmPassword ? 'Hide password' : 'Show password'}
                tabIndex={-1}
              >
                {showConfirmPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
          </div>

          {confirmPasswordTouched && !passwordsMatch && confirmPassword.length > 0 && (
            <p className="text-[10px] text-red-600 ml-1 mt-1">
              Passwords do not match
            </p>
          )}
        </div>

        {/* Save Button and Success Banner */}
        <div className="pt-1 pb-2">
          <div className="flex items-center gap-3 min-h-[38px]">
            <button
              onClick={handleSubmit}
              disabled={!isFormValid || isChanging}
              className="btn btn-primary flex items-center space-x-2 text-sm px-4 py-2 disabled:opacity-50 disabled:cursor-not-allowed flex-shrink-0"
            >
              {isChanging ? (
                <RefreshCw size={14} className="animate-spin" />
              ) : (
                <Save size={14} />
              )}
              <span>{isChanging ? 'Changing Password...' : 'Change Password'}</span>
            </button>

            {/* Success Banner - Appears next to button */}
            {showSuccess && (
              <div className="bg-green-50 border border-green-200 rounded-lg px-3 py-1.5 flex items-center space-x-2 animate-in fade-in slide-in-from-right-2 duration-300">
                <AnimatedCheckmark size={24} />
                <span className="text-xs font-medium text-green-900">Password changed successfully</span>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Session Management Section */}
      <div className="pt-3 border-t border-gray-200">
        <div className="flex items-center space-x-2 pb-3 border-b border-gray-200 mb-4">
          <MonitorSmartphone size={22} className="text-gray-700" />
          <h3 className="text-xl font-semibold text-gray-900">Active Sessions</h3>
        </div>
        <div className="max-w-4xl">
          <p className="text-sm text-gray-600 mb-4">
            Manage your active sessions across all devices. You can revoke access from any device.
          </p>
          <SessionListSection />
        </div>
      </div>
    </div>
  );
}

/**
 * Session List Section
 *
 * Displays active sessions with revocation controls
 * Shows current session + 4 most recent sessions
 */

import { useState, useMemo } from 'react';

import { formatDistanceToNow, format } from 'date-fns';
import { Monitor, TabletSmartphone, MonitorCheck, LogOut, RefreshCw } from 'lucide-react';
import { UAParser } from 'ua-parser-js';

import { useUserSessions } from '@domains/users';
import { notifications } from '@shared/utils';

export function SessionListSection() {
  const {
    sessions,
    isLoading,
    revokeSession,
    isRevoking,
    revokeAll,
    isRevokingAll,
  } = useUserSessions();

  const [showRevokeAllConfirm, setShowRevokeAllConfirm] = useState(false);
  const [revokingSessionId, setRevokingSessionId] = useState<string | null>(null);

  const parseUserAgent = (userAgent: string | undefined) => {
    if (!userAgent) return { device: 'Unknown Device', type: 'desktop' };

    const parser = new UAParser(userAgent);
    const result = parser.getResult();

    const browser = result.browser.name ?? 'Unknown Browser';
    const browserVersion = result.browser.version?.split('.')[0] ?? '';
    const os = result.os.name ?? 'Unknown OS';
    const osVersion = result.os.version ?? '';
    const deviceType = result.device.type || 'desktop';

    const deviceName = `${browser}${browserVersion ? ' ' + browserVersion : ''} on ${os}${osVersion ? ' ' + osVersion : ''}`;

    return {
      device: deviceName,
      type: deviceType as 'desktop' | 'mobile' | 'tablet',
    };
  };

  const formatTimestamp = (date: Date) => {
    const relative = formatDistanceToNow(date, { addSuffix: true });
    const absolute = format(date, 'MMM d, yyyy, h:mm a');
    return { relative, absolute };
  };

  const displayedSessions = useMemo(() => {
    const sorted = [...sessions].sort((a, b) =>
      b.lastUsedAt.getTime() - a.lastUsedAt.getTime()
    );

    const current = sorted.find(s => s.isCurrentSession);
    const others = sorted.filter(s => !s.isCurrentSession).slice(0, 4);

    return current ? [current, ...others] : others.slice(0, 5);
  }, [sessions]);

  const otherSessionsCount = sessions.filter(s => !s.isCurrentSession).length;

  const handleRevokeSession = (sessionId: string) => {
    setRevokingSessionId(sessionId);
    revokeSession(sessionId, {
      onSuccess: () => {
        notifications.success('Logged out successfully');
        setRevokingSessionId(null);
      },
      onError: (error: Error) => {
        notifications.error(error.message || 'Failed to logout');
        setRevokingSessionId(null);
      },
    });
  };

  const handleRevokeAll = () => {
    revokeAll(undefined, {
      onSuccess: (revokedCount: number) => {
        notifications.success(`Logged out from ${revokedCount} device${revokedCount !== 1 ? 's' : ''} successfully`);
        setShowRevokeAllConfirm(false);
      },
      onError: (error: Error) => {
        notifications.error(error.message || 'Failed to logout from other devices');
        setShowRevokeAllConfirm(false);
      },
    });
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <RefreshCw className="animate-spin text-gray-400" size={24} />
        <span className="ml-2 text-sm text-gray-600">Loading sessions...</span>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <p className="text-sm text-gray-600">
          Showing {displayedSessions.length} of {sessions.length} active session{sessions.length !== 1 ? 's' : ''}
        </p>
        {otherSessionsCount > 0 && (
          <button
            onClick={() => setShowRevokeAllConfirm(true)}
            disabled={isRevokingAll}
            className="btn btn-danger flex items-center space-x-2 text-xs px-3 py-1.5 disabled:opacity-50"
          >
            {isRevokingAll ? (
              <RefreshCw size={12} className="animate-spin" />
            ) : (
              <LogOut size={12} />
            )}
            <span>{isRevokingAll ? 'Revoking...' : 'Logout All Other Devices'}</span>
          </button>
        )}
      </div>

      {/* Desktop Table View */}
      <div className="hidden md:block border border-gray-200 rounded-lg overflow-hidden">
        <table className="w-full">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                Device
              </th>
              <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                Location
              </th>
              <th className="px-4 py-3 text-left text-xs font-semibold text-gray-700 uppercase tracking-wider">
                Last Active
              </th>
              <th className="px-4 py-3 text-right text-xs font-semibold text-gray-700 uppercase tracking-wider">
                Actions
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {displayedSessions.map((session) => {
              const { device, type } = parseUserAgent(session.userAgent);
              const DeviceIcon = session.isCurrentSession
                ? MonitorCheck
                : (type === 'desktop' ? Monitor : TabletSmartphone);
              const timestamp = formatTimestamp(session.lastUsedAt);

              return (
                <tr key={session.id} className={session.isCurrentSession ? 'bg-green-50' : ''}>
                  <td className="px-4 py-3">
                    <div className="flex items-center space-x-3">
                      <DeviceIcon size={16} className="text-gray-400 flex-shrink-0" />
                      <div>
                        <p className="text-sm font-medium text-gray-900">{device}</p>
                        {session.isCurrentSession && (
                          <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-green-100 text-green-800 mt-1">
                            Current Session
                          </span>
                        )}
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-3">
                    <p className="text-sm text-gray-700">{session.ipAddress ?? 'Unknown'}</p>
                  </td>
                  <td className="px-4 py-3">
                    <div>
                      <p className="text-sm text-gray-900 font-medium">{timestamp.relative}</p>
                      <p className="text-xs text-gray-500">{timestamp.absolute}</p>
                    </div>
                  </td>
                  <td className="px-4 py-3 text-right">
                    {!session.isCurrentSession && (
                      <button
                        onClick={() => handleRevokeSession(session.id)}
                        disabled={isRevoking || revokingSessionId === session.id}
                        className="btn-danger-compact flex items-center space-x-1"
                        title="Logout from this session"
                      >
                        {revokingSessionId === session.id ? (
                          <RefreshCw size={12} className="animate-spin" />
                        ) : (
                          <LogOut size={12} />
                        )}
                        <span>Logout</span>
                      </button>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Mobile Card View */}
      <div className="md:hidden space-y-3">
        {displayedSessions.map((session) => {
          const { device, type } = parseUserAgent(session.userAgent);
          const DeviceIcon = session.isCurrentSession
            ? MonitorCheck
            : (type === 'desktop' ? Monitor : TabletSmartphone);
          const timestamp = formatTimestamp(session.lastUsedAt);

          return (
            <div
              key={session.id}
              className={`border rounded-lg p-4 ${session.isCurrentSession ? 'bg-green-50 border-green-200' : 'border-gray-200 bg-white'}`}
            >
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center space-x-3 flex-1 min-w-0">
                  <DeviceIcon size={20} className="text-gray-400 flex-shrink-0" />
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-gray-900 truncate">{device}</p>
                    {session.isCurrentSession && (
                      <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-green-100 text-green-800 mt-1">
                        Current Session
                      </span>
                    )}
                  </div>
                </div>
                {!session.isCurrentSession && (
                  <button
                    onClick={() => handleRevokeSession(session.id)}
                    disabled={isRevoking || revokingSessionId === session.id}
                    className="btn-danger-compact flex-shrink-0 ml-2 flex items-center space-x-1"
                    title="Logout from this session"
                  >
                    {revokingSessionId === session.id ? (
                      <RefreshCw size={12} className="animate-spin" />
                    ) : (
                      <LogOut size={12} />
                    )}
                  </button>
                )}
              </div>
              <div className="space-y-1 text-xs text-gray-600">
                <p><span className="font-medium">Location:</span> {session.ipAddress ?? 'Unknown'}</p>
                <div>
                  <span className="font-medium">Last Active:</span>
                  <p className="ml-0 mt-0.5">{timestamp.relative}</p>
                  <p className="text-[11px] text-gray-500 ml-0">{timestamp.absolute}</p>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Confirmation Dialog */}
      {showRevokeAllConfirm && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-[2px] flex items-center justify-center z-50 animate-in fade-in duration-200">
          <div className="bg-white rounded-lg shadow-xl max-w-md w-full mx-4 animate-in zoom-in-95 duration-200">
            <div className="px-6 py-4 border-b border-gray-200">
              <h3 className="text-lg font-semibold text-gray-900">Logout All Other Devices?</h3>
            </div>
            <div className="px-6 py-4">
              <p className="text-sm text-gray-600">
                This will end all other active sessions ({otherSessionsCount} device
                {otherSessionsCount !== 1 ? 's' : ''}). You will remain logged in on this device.
              </p>
            </div>
            <div className="px-6 py-4 bg-gray-50 flex justify-end space-x-3">
              <button
                onClick={() => setShowRevokeAllConfirm(false)}
                disabled={isRevokingAll}
                className="btn btn-secondary text-sm px-4 py-2"
              >
                Cancel
              </button>
              <button
                onClick={handleRevokeAll}
                disabled={isRevokingAll}
                className="btn btn-danger flex items-center space-x-2 text-sm px-4 py-2 disabled:opacity-50"
              >
                {isRevokingAll ? (
                  <>
                    <RefreshCw size={14} className="animate-spin" />
                    <span>Revoking...</span>
                  </>
                ) : (
                  <>
                    <LogOut size={14} />
                    <span>Logout All</span>
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Grid Domain
 */

export * from './services';
export * from '@shared/types/GridTypes';

import { useTubeStore } from '@domains/tubes';

export interface GridLocation {
  tankId: string;
  rackId: string;
  boxId: string;
}

export interface NavigationResult {
  success: boolean;
  error?: string;
  location: GridLocation;
}

/**
 * Grid Navigation Service
 * 
 * Provides atomic navigation operations that prevent race conditions
 * and ensure data consistency during location changes.
 * 
 * Key principles:
 * - Single atomic operation per navigation
 * - Automatic data loading coordination
 * - Error handling and recovery
 */
export class GridNavigationService {
  private static instance: GridNavigationService;
  private isNavigating = false;

  public static getInstance(): GridNavigationService {
    if (!GridNavigationService.instance) {
      GridNavigationService.instance = new GridNavigationService();
    }
    return GridNavigationService.instance;
  }

  /**
   * Navigate to a specific location atomically
   * This is the ONLY way navigation should happen - prevents race conditions
   */
  public async navigateToLocation(location: GridLocation): Promise<NavigationResult> {
    // Prevent concurrent navigation operations
    if (this.isNavigating) {
      return { success: false, error: 'Navigation in progress', location };
    }

    this.isNavigating = true;

    try {


      const tubeStore = useTubeStore.getState();

      // Atomic state update - all at once, no cascading
      tubeStore.setCurrentTank(location.tankId);
      tubeStore.setCurrentRack(location.rackId);
      tubeStore.setCurrentBox(location.boxId);

      // Force fresh load of ALL tubes to ensure state consistency
      const { useAuthStore } = await import('@/domains/authentication');
      const authStore = useAuthStore.getState();

      if (authStore.isAuthenticated) {
        // Note: Data loading is now handled by React Query in components
        // The React Query hooks will automatically refetch when the location changes
      } else {
        console.error(`❌ ATOMIC NAVIGATION: User not authenticated`);
        return { success: false, error: 'Authentication required', location };
      }



      return { success: true, location };

    } catch (error) {
      console.error('❌ ATOMIC NAVIGATION: Navigation failed:', error);
      return { 
        success: false, 
        error: error instanceof Error ? error.message : 'Navigation failed',
        location 
      };
    } finally {
      this.isNavigating = false;
    }
  }

  /**
   * Navigate to tank (selects first available rack and box)
   */
  public async navigateToTank(tankId: string): Promise<NavigationResult> {
    // Import configuration store to get first available rack/box
    const { useStorageStore } = await import('@/domains/storage');
    const { getCurrentRacks, getCurrentBoxes } = useStorageStore.getState();

    const racks = getCurrentRacks(tankId);
    if (racks.length === 0) {
      console.error(`🐛 DEBUG: No racks found for tank "${tankId}"`);
      return { success: false, error: 'No racks available in tank', location: { tankId, rackId: '1', boxId: 'A' } };
    }

    const boxes = getCurrentBoxes(tankId, racks[0].id);
    if (boxes.length === 0) {
      console.error(`🐛 DEBUG: No boxes found for tank "${tankId}", rack ${racks[0].id}`);
      return { success: false, error: 'No boxes available in rack', location: { tankId, rackId: String(racks[0].id), boxId: 'A' } };
    }

    return this.navigateToLocation({
      tankId,
      rackId: String(racks[0].id),
      boxId: boxes[0].id
    });
  }

  /**
   * Navigate to rack (selects first available box)
   */
  public async navigateToRack(tankId: string, rackId: string): Promise<NavigationResult> {
    const { useStorageStore } = await import('@/domains/storage');
    const { getCurrentBoxes } = useStorageStore.getState();

    const boxes = getCurrentBoxes(tankId, rackId);
    if (boxes.length === 0) {
      return { success: false, error: 'No boxes available in rack', location: { tankId, rackId, boxId: 'A' } };
    }

    return this.navigateToLocation({
      tankId,
      rackId,
      boxId: boxes[0].id
    });
  }

  /**
   * Get current location from store
   */
  public getCurrentLocation(): GridLocation {
    const { currentTank, currentRack, currentBox } = useTubeStore.getState();
    return {
      tankId: currentTank,
      rackId: currentRack,
      boxId: currentBox
    };
  }

  /**
   * Check if currently navigating (for UI feedback)
   */
  public getIsNavigating(): boolean {
    return this.isNavigating;
  }
}

// Export singleton instance for easy use
export const gridNavigationService = GridNavigationService.getInstance();

/**
 * Grid Domain Services
 */

export * from './GridNavigationService';

/**
 * React Query hooks for researcher data management
 * Provides type-safe server state management with automatic caching and invalidation
 */

import {
  type Researcher,
  type AdminResearcher,
  type CreateResearcherProfile,
  type UpdateResearcherProfile,
  formatResearcherDropdownDisplay,
  formatResearcherListDisplay,
  sortResearchers
} from '@odysseus/shared-schemas';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'react-hot-toast';

import { DOMAIN_QUERY_OPTIONS } from '@app/queryClient';
import { queryKeys } from '@app/queryKeys';

import { ResearcherService } from '../services/ResearcherService';

import type { UseQueryOptions } from '@tanstack/react-query';


/**
 * Hook to fetch all researchers (basic data only)
 * Use this for dropdowns, forms, and general display
 */
export function useResearchersQuery(options?: {
  filters?: { active?: boolean; search?: string };
  queryOptions?: Omit<UseQueryOptions<Researcher[]>, 'queryKey' | 'queryFn'>;
}) {
  const { filters, queryOptions } = options ?? {};

  return useQuery({
    queryKey: queryKeys.researchers.list(filters),
    queryFn: async (): Promise<Researcher[]> => {
      const researchers = await ResearcherService.list({ filters });
      return researchers.sort(sortResearchers);
    },
    ...DOMAIN_QUERY_OPTIONS.researchers,
    ...queryOptions
  });
}

/**
 * Hook to fetch all researchers with admin metadata
 * Use this for admin UI that needs tubeCount, linkedUserId, linkedUsername
 */
export function useAdminResearchersQuery(options?: {
  filters?: { active?: boolean; search?: string };
  queryOptions?: Omit<UseQueryOptions<AdminResearcher[]>, 'queryKey' | 'queryFn'>;
}) {
  const { filters, queryOptions } = options ?? {};

  return useQuery({
    queryKey: queryKeys.researchers.admin(filters),
    queryFn: async (): Promise<AdminResearcher[]> => {
      const researchers = await ResearcherService.list({ admin: true, filters });
      return researchers.sort(sortResearchers);
    },
    ...DOMAIN_QUERY_OPTIONS.researchers,
    ...queryOptions
  });
}

/**
 * Hook to fetch a single researcher by ID
 */
export function useResearcherQuery(researcherId: string, options?: {
  queryOptions?: Omit<UseQueryOptions<AdminResearcher>, 'queryKey' | 'queryFn'>;
}) {
  return useQuery({
    queryKey: queryKeys.researchers.detail(researcherId),
    queryFn: () => ResearcherService.get(researcherId),
    staleTime: 10 * 60 * 1000,
    enabled: !!researcherId,
    ...options?.queryOptions
  });
}

/**
 * Hook for creating a new researcher
 * Uses profile-only schema - separates profile data from auth/permissions
 */
export function useCreateResearcherMutation() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (researcherData: CreateResearcherProfile) => ResearcherService.create(researcherData),
    onSuccess: (newResearcher) => {
      void queryClient.invalidateQueries({ queryKey: queryKeys.researchers.all });
      toast.success(`Researcher "${formatResearcherDropdownDisplay(newResearcher)}" created successfully`);
    },
    onError: (error: any) => {
      toast.error(`Failed to create researcher: ${error.message || 'Unknown error'}`);
    }
  });
}

/**
 * Hook for updating an existing researcher
 * Uses profile-only schema - separates profile data from auth/permissions
 */
export function useUpdateResearcherMutation() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, data }: { id: string; data: UpdateResearcherProfile }) =>
      ResearcherService.update(id, data),
    onSuccess: (updatedResearcher, variables) => {
      queryClient.setQueryData(
        queryKeys.researchers.detail(updatedResearcher.id),
        updatedResearcher
      );
      void queryClient.invalidateQueries({ queryKey: queryKeys.researchers.all });

      // Show appropriate success message based on what was updated
      if (variables.data.active !== undefined) {
        const action = variables.data.active ? 'reactivated' : 'deactivated';
        toast.success(`Researcher "${formatResearcherListDisplay(updatedResearcher)}" ${action} successfully`);
      } else {
        toast.success(`Researcher "${formatResearcherListDisplay(updatedResearcher)}" updated successfully`);
      }
    },
    onError: (error: any) => {
      toast.error(`Failed to update researcher: ${error.message || 'Unknown error'}`);
    }
  });
}

/**
 * Hook for deleting a researcher
 */
export function useDeleteResearcherMutation() {
  const queryClient = useQueryClient();
  
  return useMutation({
    mutationFn: (researcherId: string) => ResearcherService.delete(researcherId),
    onSuccess: (_, researcherId) => {
      queryClient.removeQueries({ queryKey: queryKeys.researchers.detail(researcherId) });
      void queryClient.invalidateQueries({ queryKey: queryKeys.researchers.all });
      toast.success('Researcher deleted successfully');
    },
    onError: (error: any) => {
      toast.error(`Failed to delete researcher: ${error.message || 'Unknown error'}`);
    }
  });
}


/**
 * Hook to get active researchers only (commonly used in forms)
 *
 * Derives from base list via 'select' to eliminate duplicate API calls.
 * Uses client-side filtering for small-medium datasets.
 */
export function useActiveResearchersQuery(options?: {
  queryOptions?: Omit<UseQueryOptions<Researcher[], Error, Researcher[]>, 'queryKey' | 'queryFn' | 'select'>;
}) {
  return useQuery<Researcher[], Error, Researcher[]>({
    queryKey: queryKeys.researchers.lists(),
    queryFn: () => ResearcherService.list(),
    select: (researchers) => researchers.filter(r => r.active !== false),
    ...DOMAIN_QUERY_OPTIONS.researchers,
    ...options?.queryOptions
  });
}

