import type { TubeData, TubeMedia } from '@domains/tubes/types';
import type { GroupedResult} from '@odysseus/shared-schemas';

/**
 * Convert media object to string for searching
 */
const getMediaString = (media: TubeMedia | undefined): string => {
  if (!media) return '';
  
  // Combine all fields for searching
  return [media.type, media.supplements, media.selection]
    .filter(Boolean)
    .join(' ');
};

/**
 * Group tubes by relevance for search results
 * 
 * This function maintains the existing grouping logic from the original SearchStore
 * but is now extracted as a pure utility function.
 */
export const groupTubesByRelevance = (tubes: TubeData[], query: string): GroupedResult[] => {
  if (!query.trim()) {
    // Group by cell type when no query
    const groups = new Map<string, TubeData[]>();
    tubes.forEach(tube => {
      const key = tube.sample.cellType || 'Unknown';
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key)!.push(tube);
    });

    return Array.from(groups.entries()).map(([key, groupTubes]) => ({
      groupKey: key,
      groupType: 'cellType' as const,
      tubes: groupTubes,
      primaryLocation: getPrimaryLocation(groupTubes),
      totalCount: groupTubes.length
    }));
  }

  const groups = new Map<string, {
    tubes: TubeData[],
    type: GroupedResult['groupType'],
    matchedField: string
  }>();

  tubes.forEach(tube => {
    let groupType: GroupedResult['groupType'] = 'cellType';

    // Determine what field matched the query
    if (tube.sample.donorInternalId?.toLowerCase().includes(query.toLowerCase())) {
      groupType = 'donor';
    } else if (tube.sample.donorSourceId?.toLowerCase().includes(query.toLowerCase())) {
      groupType = 'donor';
    } else if (tube.sample.cellType?.toLowerCase().includes(query.toLowerCase())) {
      groupType = 'cellType';
    } else if (tube.researcherId?.toLowerCase().includes(query.toLowerCase())) {
      // Search by researcherId (ID-based, not name)
      // Note: This searches by ID string. To search by name, need to fetch researcher data separately
      groupType = 'researcher';
    } else if (tube.sample.lotNumber?.toLowerCase().includes(query.toLowerCase())) {
      groupType = 'lotNumber';
    } else if (tube.sample.media && getMediaString(tube.sample.media).toLowerCase().includes(query.toLowerCase())) {
      groupType = 'media';
    } else {
      groupType = 'cellType';
    }

    // Group by tube's CURRENT identifier, not what was matched
    const tankId = tube.location.tankId || NAMING_PATTERNS.TANK.ID_PATTERN(1);
    const currentGroupKey = tube.sample.donorInternalId || tube.sample.donorSourceId || tube.sample.lotNumber || tube.sample.cellType || 'Unknown';
    const locationKey = `${currentGroupKey}:${tankId}:${tube.location.rackId}:${tube.location.boxId}`;

    if (!groups.has(locationKey)) {
      groups.set(locationKey, { tubes: [], type: groupType, matchedField: currentGroupKey });
    }
    groups.get(locationKey)!.tubes.push(tube);
  });

  return Array.from(groups.entries())
    .map(([_key, { tubes: groupTubes, type, matchedField }]) => ({
      groupKey: matchedField,
      groupType: type,
      tubes: groupTubes,
      primaryLocation: getPrimaryLocation(groupTubes),
      totalCount: groupTubes.length
    }))
    .sort((a, b) => b.totalCount - a.totalCount);
};

/**
 * Get primary location for a group of tubes
 */
export const getPrimaryLocation = (tubes: TubeData[]): string => {
  if (tubes.length === 0) return 'No location';

  // Return raw location data - display names will be resolved in UI components
  const firstTube = tubes[0];
  const tankId = firstTube.location.tankId || NAMING_PATTERNS.TANK.ID_PATTERN(1);

  return `${tankId}:${firstTube.location.rackId}:${firstTube.location.boxId}`;
};

/**
 * Transform search result to SearchResults format
 * 
 * This maintains compatibility with the existing SearchResults interface
 */
export const transformSearchResult = (
  searchResult: { data: any[] }, // Accept flexible API response
  query: string
) => {
  // Convert API response tubes to proper TubeData format
  const tubes: TubeData[] = (searchResult.data || []).map((tube: any) => ({
    ...tube,
    sample: {
      ...tube.sample,
      // Convert concentration from string|number to number for storage consistency
      concentration: typeof tube.sample.concentration === 'string' 
        ? (tube.sample.concentration ? Number(tube.sample.concentration) : undefined)
        : tube.sample.concentration
    }
  }));
  
  const grouped = groupTubesByRelevance(tubes, query);
  
  return {
    tubes,
    grouped,
    total: tubes.length,
    query,
    hasResults: tubes.length > 0
  };
};

import {
  SearchResultSchema,
  AdvancedSearchOptionsSchema
} from '@odysseus/shared-schemas';

import { httpClient } from '@infra/api/httpClient';
import { InfrastructureError } from '@shared/errors/AppError';
import { normalizeDateString } from '@shared/utils/dateUtils';

import type {
  AdvancedSearchOptions,
  SearchResult} from '@odysseus/shared-schemas';

/**
 * Modern Search Service with Zod validation and proper error handling
 */
export class SearchService {
  /**
   * Perform advanced search across tubes
   */
  static async searchTubes(options: AdvancedSearchOptions): Promise<SearchResult> {
    try {
      const validatedOptions = AdvancedSearchOptionsSchema.parse(options);

      // Normalize date filters to YYYY-MM-DD format to prevent timezone bugs
      const normalizedFilters = validatedOptions.filters ? {
        ...validatedOptions.filters,
        ...(validatedOptions.filters.dateFrom && {
          dateFrom: normalizeDateString(validatedOptions.filters.dateFrom)
        }),
        ...(validatedOptions.filters.dateTo && {
          dateTo: normalizeDateString(validatedOptions.filters.dateTo)
        })
      } : undefined;

      const requestPayload = {
        query: validatedOptions.query,
        filters: normalizedFilters,
        limit: validatedOptions.limit || 50,
        offset: validatedOptions.offset ?? 0,
        sortBy: validatedOptions.sortBy,
        sortOrder: validatedOptions.sortOrder || 'desc'
      };

      const result = await httpClient.postData(
        '/search/tubes/advanced',
        requestPayload,
        SearchResultSchema
      );

      return result;
    } catch (error) {
      throw new InfrastructureError(
        'API_ERROR',
        'Failed to search tubes',
        { originalError: error, options }
      );
    }
  }
}

import { NAMING_PATTERNS } from '@odysseus/shared-schemas';
import { create } from 'zustand';

import { useTubeStore } from '@domains/tubes';
import { toPositionKey } from '@shared/types/grid';

import type { TubeData } from '@domains/tubes/types';
import type { SearchFilters} from '@odysseus/shared-schemas';

/**
 * UI-Only Search Store
 *
 * This store now only manages UI state:
 * - Search input and filters (form state)
 * - Search history (local UI state)
 * - Sort preferences (UI state)
 * - Navigation actions (UI behavior)
 *
 * Server state (search results, loading states) is now handled by React Query.
 */

export type SortField = 'location' | 'date' | 'cellType' | 'researcher' | 'lotNumber';
export type SortDirection = 'asc' | 'desc';

interface SearchUIState {
  // UI Form State
  query: string;
  filters: SearchFilters;

  // Sort State
  sortField: SortField;
  sortDirection: SortDirection;

  // Local UI State
  history: string[];
}

interface SearchUIActions {
  // Form State Actions
  setSearchQuery: (query: string) => void;
  setSearchFilters: (filters: SearchFilters) => void;
  clearSearch: () => void;

  // Sort Actions
  setSortField: (field: SortField) => void;
  setSortDirection: (direction: SortDirection) => void;
  toggleSortDirection: () => void;

  // Filter Helper Actions (for array-based filters)
  toggleFilterValue: <K extends keyof SearchFilters>(
    filterKey: K,
    value: string
  ) => void;
  hasActiveFilters: () => boolean;
  getActiveFilterCount: () => number;

  // History Actions
  addToSearchHistory: (query: string) => void;

  // Navigation Actions (UI Behavior)
  navigateToGroup: (tubes: TubeData[]) => Promise<void>;
}

interface SearchUIStore extends SearchUIState, SearchUIActions {}

/**
 * UI-Only Search Store Implementation
 *
 * Server state (search results, loading) is now handled by React Query hooks.
 * This store focuses purely on UI state and local storage.
 */

export const useSearchStore = create<SearchUIStore>((set, get) => ({
  // UI State
  query: '',
  filters: {},
  sortField: 'location',
  sortDirection: 'asc',
  history: [],

  // Form State Actions
  setSearchQuery: (query) => set({ query }),

  setSearchFilters: (filters) => set({ filters }),

  clearSearch: () => {
    set({
      query: '',
      filters: {},
    });
  },

  // Sort Actions
  setSortField: (field) => set({ sortField: field }),

  setSortDirection: (direction) => set({ sortDirection: direction }),

  toggleSortDirection: () => {
    const { sortDirection } = get();
    set({ sortDirection: sortDirection === 'asc' ? 'desc' : 'asc' });
  },

  // Filter Helper Actions (for checkbox toggle behavior)
  toggleFilterValue: (filterKey, value) => {
    const { filters } = get();
    const currentArray = (filters[filterKey] as string[] | undefined) ?? [];

    const newArray = currentArray.includes(value)
      ? currentArray.filter(v => v !== value) // Remove if exists
      : [...currentArray, value];              // Add if doesn't exist

    set({
      filters: {
        ...filters,
        [filterKey]: newArray.length > 0 ? newArray : undefined, // Remove key if empty
      }
    });
  },

  hasActiveFilters: () => {
    const { filters } = get();
    return Object.values(filters).some(value =>
      Array.isArray(value) ? value.length > 0 : value !== undefined
    );
  },

  getActiveFilterCount: () => {
    const { filters } = get();
    return Object.values(filters).reduce((count, value) => {
      if (Array.isArray(value)) {
        return count + value.length;
      }
      return value !== undefined ? count + 1 : count;
    }, 0);
  },

  // History Actions
  addToSearchHistory: (query) => {
    const { history } = get();
    const newHistory = [query, ...history.filter(h => h !== query)].slice(0, 10);
    set({ history: newHistory });
  },

  // Navigation Actions (UI Behavior)
  navigateToGroup: async (tubes) => {
    if (tubes.length === 0) return;

    // Get the first tube to determine navigation target
    const firstTube = tubes[0];
    const tankId = firstTube.location.tankId || NAMING_PATTERNS.TANK.ID_PATTERN(1);
    const rackId = firstTube.location.rackId;
    const boxId = firstTube.location.boxId;

    // Use atomic navigation service
    const { gridNavigationService } = await import('@domains/grid');
    await gridNavigationService.navigateToLocation({ tankId, rackId, boxId });

    const tubeStore = useTubeStore.getState();

    // Select the tubes for immediate visibility
    const positionKeys = tubes.map(tube =>
      toPositionKey(
        { tankId: tube.location.tankId || tankId, rackId: tube.location.rackId, boxId: tube.location.boxId },
        tube.location.position
      )
    );
    tubeStore.setSelection(new Set(positionKeys));
  },
}));

import { useMemo, useState, useCallback } from 'react';

import { formatResearcherDropdownDisplay } from '@odysseus/shared-schemas';
import {
  Users, Calendar, X,
  ChevronDown, ChevronRight,
  Microscope, Barcode, UserCircle, Fingerprint, FlaskConical, MapPin
} from 'lucide-react';

import { useActiveResearchersQuery } from '@domains/researchers';
import { useSearchStore } from '@domains/search';
import { useStorageStore } from '@domains/storage';
import { useTubes } from '@domains/tubes/hooks';
import { TankIcon, RackIcon, BoxIcon } from '@shared/ui/components/icons';
import { normalizeDateString } from '@shared/utils/dateUtils';

import type { TubeData, Researcher } from '@odysseus/shared-schemas';

interface FilterChipProps {
  label: string;
  isSelected: boolean;
  onClick: () => void;
  showRemove?: boolean;
}

function FilterChip({ label, isSelected, onClick, showRemove = false }: FilterChipProps) {
  return (
    <button
      onClick={onClick}
      className={`
        px-2 py-1 rounded-full text-xs font-medium transition-all
        ${isSelected
          ? 'bg-action text-white shadow-sm hover:bg-action-hover'
          : 'bg-gray-100 text-gray-700 hover:bg-gray-200 border border-gray-300'
        }
        ${showRemove ? 'flex items-center space-x-1.5' : ''}
      `}
    >
      <span>{label}</span>
      {showRemove && <X className="w-3 h-3" />}
    </button>
