import { httpClient } from '@infra/api/httpClient';
import { InfrastructureError } from '@shared/errors/AppError';

import type {
  ConfigurationResponse,
  DeleteTankResponse,
  SystemConfiguration,
  LabConfiguration,
  PositionDisplayConfig,
  POSITION_DISPLAY_PRESETS} from '@odysseus/shared-schemas';

/**
 * Modern Storage Service with Zod validation and proper error handling
 */
export class StorageService {
  /**
   * Load configuration from server
   */
  static async loadConfiguration(): Promise<ConfigurationResponse> {
    try {
      const response = await httpClient.getData('/configuration', ConfigurationResponseSchema);
      return response;
    } catch (error) {
      console.error('❌ [StorageService] Load configuration failed:', error);
      throw new InfrastructureError(
        'API_ERROR',
        'Failed to load configuration from server',
        { originalError: error }
      );
    }
  }

  /**
   * Save configuration to server
   */
  static async saveConfiguration(
    systemConfig: SystemConfiguration,
    currentLab: LabConfiguration
  ): Promise<void> {
    try {
      const requestData = SaveConfigurationRequestSchema.parse({
        configuration: { systemConfig, currentLab }
      });

      await httpClient.put('/configuration', requestData);
    } catch (error) {
      console.error('❌ [StorageService] Save configuration failed:', error);
      throw new InfrastructureError(
        'API_ERROR',
        'Failed to save configuration to server',
        { originalError: error, systemConfig, currentLab }
      );
    }
  }

  /**
   * Delete tank (with tubes cleanup)
   */
  static async deleteTank(tankId: string): Promise<DeleteTankResponse> {
    try {
      return await httpClient.deleteWithData(`/tanks/${tankId}`, DeleteTankResponseSchema);
    } catch (error) {
      throw new InfrastructureError(
        'API_ERROR',
        `Failed to delete tank ${tankId}`,
        { originalError: error, tankId }
      );
    }
  }

  /**
   * Check if configuration exists on server
   */
  static async checkConfigurationExists(): Promise<boolean> {
    try {
      const { exists } = await httpClient.getData(
        '/configuration/exists',
        z.object({ exists: z.boolean() })
      );
      return exists;
    } catch (error) {
      return false;
    }
  }

  /**
   * Get available position display presets from server
   *
   * Returns presets for numeric and alphanumeric position display formats.
   * These can be used to populate UI selectors for box position configuration.
   *
   * @returns Position display presets with descriptions
   */
  static async getPositionDisplayPresets(): Promise<{
    presets: typeof POSITION_DISPLAY_PRESETS;
    description: Record<string, string>;
  }> {
    try {
      const responseSchema = z.object({
        success: z.boolean(),
        presets: z.object({
          NUMERIC: z.any(),
          ALPHANUMERIC_STANDARD: z.any(),
          ALPHANUMERIC_REVERSE: z.any(),
        }),
        description: z.record(z.string(), z.string()),
      });

      const response = await httpClient.getData(
        '/configuration/position-display-presets',
        responseSchema
      );

      return {
        presets: response.presets as typeof POSITION_DISPLAY_PRESETS,
        description: response.description as Record<string, string>,
      };
    } catch (error) {
      console.error('❌ [StorageService] Get position display presets failed:', error);
      throw new InfrastructureError(
        'API_ERROR',
        'Failed to fetch position display presets',
        { originalError: error }
      );
    }
  }

  /**
   * Update position display configuration for a specific box
   *
   * Allows changing how position numbers are displayed (numeric vs alphanumeric).
   * Pass null to reset to system default (alphanumeric).
   *
   * @param tankId - Tank identifier
   * @param rackId - Rack identifier
   * @param boxId - Box identifier
   * @param positionDisplay - New position display config (null = reset to default)
   */
  static async updateBoxPositionDisplay(
    tankId: string,
    rackId: string,
    boxId: string,
    positionDisplay: PositionDisplayConfig | null
  ): Promise<void> {
    try {
      await httpClient.put('/configuration/box-position-display', {
        tankId,
        rackId,
        boxId,
        positionDisplay,
      });
    } catch (error) {
      console.error('❌ [StorageService] Update box position display failed:', error);
      throw new InfrastructureError(
        'API_ERROR',
        `Failed to update position display for box ${boxId}`,
        { originalError: error, tankId, rackId, boxId, positionDisplay }
      );
    }
  }

  /**
   * Update lab-wide default position display configuration
   *
   * Sets the default position display format for all boxes in the lab.
   * Boxes with custom overrides will not be affected.
   * Pass null to clear the lab default and fall back to system default (alphanumeric).
   *
   * @param positionDisplay - New lab default position display config (null = reset to system default)
   */
  static async updateLabDefaultPositionDisplay(
    positionDisplay: PositionDisplayConfig | null
  ): Promise<void> {
    try {
      await httpClient.put('/configuration/lab-position-display', {
        positionDisplay,
      });
    } catch (error) {
      console.error('❌ [StorageService] Update lab default position display failed:', error);
      throw new InfrastructureError(
        'API_ERROR',
        'Failed to update lab default position display',
        { originalError: error, positionDisplay }
      );
    }
  }
}

/**
 * Storage Store
 * State management for storage equipment configurations
 * Types from shared-schemas (single source of truth)
 */

import {
  EQUIPMENT_DEFAULTS,
  NAMING_PATTERNS,
  SYSTEM_DEFAULTS,
} from '@odysseus/shared-schemas';
import { create } from 'zustand';
import { persist } from 'zustand/middleware';

import {
  DEFAULT_GRID_CONFIG,
  GRID_TEMPLATES,
} from '../utils/gridHelpers';

import type {
  LabConfiguration,
  SystemConfiguration,
  TankConfiguration,
  RackConfiguration,
  BoxConfiguration,
  GridConfiguration,
  PositionDisplayConfig} from '@odysseus/shared-schemas';

interface ConfigurationState {
  // Current state
  systemConfig: SystemConfiguration;

  // Auto-synced from systemConfig.availableLabs
  // Single source of truth: availableLabs is authoritative, currentLab is auto-computed
  currentLab: LabConfiguration;

  // Actions
  setCurrentLab: (labId: string) => void;
  addLab: (lab: LabConfiguration) => void;
  updateLab: (labId: string, updates: Partial<LabConfiguration>) => void;
  deleteLab: (labId: string) => void;
  
  // Tank management
  addTank: (labId: string, tank: TankConfiguration) => void;
  updateTank: (labId: string, tankId: string, updates: Partial<TankConfiguration>) => void;
  deleteTank: (labId: string, tankId: string) => Promise<void>;
  deleteTankLocally: (labId: string, tankId: string) => void;

  // Equipment management
  addRack: (labId: string, tankId: string, rack: RackConfiguration) => void;
  updateRack: (labId: string, tankId: string, rackId: string, updates: Partial<RackConfiguration>) => void;
  deleteRack: (labId: string, tankId: string, rackId: string) => void;
  
  // Box management (individual customization)
  updateBox: (labId: string, tankId: string, rackId: string, boxId: string, updates: Partial<BoxConfiguration>) => void;
  addBoxToRack: (labId: string, tankId: string, rackId: string, box: BoxConfiguration) => void;
  deleteBox: (labId: string, tankId: string, rackId: string, boxId: string) => void;
  
  // Grid configuration
  updateBoxGridConfig: (labId: string, tankId: string, rackId: string, boxId: string, gridConfig: GridConfiguration) => void;
  getAvailableGridTemplates: () => readonly GridConfiguration[];
  
  // Utilities
  getCurrentTanks: () => TankConfiguration[];
  getCurrentRacks: (tankId?: string) => RackConfiguration[];
  getCurrentBoxes: (tankId: string, rackId: string) => BoxConfiguration[];
  getBox: (tankId: string, rackId: string, boxId: string) => BoxConfiguration | undefined;
  getBoxPositionDisplay: (tankId: string, rackId: string, boxId: string) => PositionDisplayConfig | undefined;
  resetToDefaults: () => void;
  
  // Server synchronization (now delegated to React Query)
  // Note: loadFromServer and saveToServer are deprecated - use React Query hooks instead
  loadFromServer: () => Promise<void>;
  saveToServer: () => Promise<void>;
  migrateConfigurationStructure: (config: any) => any;
  ensureDefaultConfiguration: () => void;
  initialize: () => void;
}

/**
 * Default Box Configuration
 */
const DEFAULT_BOX_CONFIG: BoxConfiguration = {
  id: 'default-box',
  name: 'Standard Box',
  gridConfig: DEFAULT_GRID_CONFIG,
  description: 'Standard laboratory storage box with 9x9 grid',
};

/**
 * Default Tank Configuration
 * Uses shared constants for naming and defaults
 */
const DEFAULT_TANK_CONFIG: TankConfiguration = {
  id: NAMING_PATTERNS.TANK.ID_PATTERN(1),
  name: NAMING_PATTERNS.TANK.DEFAULT_NAME(1),
  location: NAMING_PATTERNS.TANK.DEFAULT_LOCATION,
  isActive: true,
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
  defaultGridConfig: DEFAULT_GRID_CONFIG,
  racks: [
    {
      id: '1',
      name: NAMING_PATTERNS.RACK.DEFAULT_NAME(1),
      capacity: EQUIPMENT_DEFAULTS.BOXES_PER_RACK,
      location: NAMING_PATTERNS.TANK.DEFAULT_LOCATION,
      isActive: true,
      boxes: Array.from({ length: EQUIPMENT_DEFAULTS.BOXES_PER_RACK }, (_, i) => ({
        id: NAMING_PATTERNS.BOX.LETTER_NAME(i),
        name: NAMING_PATTERNS.BOX.DEFAULT_NAME(i),
        gridConfig: DEFAULT_GRID_CONFIG,
        position: i + 1,
      })),
    },
  ],
};

/**
 * Default Lab Configuration
 * Uses shared constants for system defaults
 */
const DEFAULT_LAB_CONFIG: LabConfiguration = {
  id: 'default-lab',
  name: SYSTEM_DEFAULTS.LAB.NAME,
  organization: SYSTEM_DEFAULTS.LAB.ORGANIZATION,
  isActive: true,
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
  equipment: {
    tanks: [DEFAULT_TANK_CONFIG],
    defaultBoxConfig: DEFAULT_BOX_CONFIG,
    defaultGridConfig: DEFAULT_GRID_CONFIG,
  },
  settings: {
    requireAuth: SYSTEM_DEFAULTS.SETTINGS.REQUIRE_AUTH,
    allowDataExport: true,
    enableRealTimeSync: SYSTEM_DEFAULTS.SETTINGS.ENABLE_REAL_TIME_SYNC,
  },
};

/**
 * Create default system configuration
 * Uses shared constants for all defaults
 */
const createDefaultSystemConfig = (): SystemConfiguration => ({
  currentLabId: DEFAULT_LAB_CONFIG.id,
  availableLabs: [DEFAULT_LAB_CONFIG],
  globalSettings: {
    theme: SYSTEM_DEFAULTS.SETTINGS.THEME,
    language: SYSTEM_DEFAULTS.SETTINGS.LANGUAGE,
    timezone: SYSTEM_DEFAULTS.SETTINGS.TIMEZONE,
    autoBackup: SYSTEM_DEFAULTS.SETTINGS.AUTO_BACKUP,
  },
  version: SYSTEM_DEFAULTS.CONFIGURATION.VERSION,
});

/**
 * Migrate old GridConfiguration format to new format
 * Old: {rows, columns, totalPositions, displayName}
 * New: {rows, cols, template}
 */
function migrateGridConfig(oldGrid: any): GridConfiguration {
  if (!oldGrid) return DEFAULT_GRID_CONFIG;

  // If already has new format, return as-is
  if (oldGrid.cols !== undefined && oldGrid.template !== undefined) {
    return oldGrid as GridConfiguration;
  }

  // If has old format, convert it
  if (oldGrid.columns !== undefined) {
    // Determine template based on dimensions
    let template = 'standard';
    if (oldGrid.rows === 8 && oldGrid.columns === 8) template = 'compact';
    else if (oldGrid.rows === 9 && oldGrid.columns === 9) template = 'standard';
    else if (oldGrid.rows === 10 && oldGrid.columns === 10) template = 'large';
    else if (oldGrid.rows === 12 && oldGrid.columns === 8) template = 'rectangular';

    return {
      rows: oldGrid.rows,
      cols: oldGrid.columns,
      template
    };
  }

  return DEFAULT_GRID_CONFIG;
}

export const useStorageStore = create<ConfigurationState>()(
  persist(
    (set, get) => {
      // Helper to derive currentLab from systemConfig
      const deriveCurrentLab = (systemConfig: SystemConfiguration): LabConfiguration => {
        const lab = systemConfig.availableLabs.find(
          l => l.id === systemConfig.currentLabId
        );
        return lab ?? DEFAULT_LAB_CONFIG;
      };

      // Wrapped set function that auto-syncs currentLab
      const syncedSet = (updates: Partial<ConfigurationState> | ((state: ConfigurationState) => Partial<ConfigurationState>)) => {
        if (typeof updates === 'function') {
          set((state) => {
            const partial = updates(state);
            // If systemConfig changed, auto-sync currentLab
            if (partial.systemConfig) {
              return {
                ...partial,
                currentLab: deriveCurrentLab(partial.systemConfig)
              };
            }
            return partial;
          });
        } else {
          // If systemConfig changed, auto-sync currentLab
          if (updates.systemConfig) {
            set({
              ...updates,
              currentLab: deriveCurrentLab(updates.systemConfig)
            });
          } else {
            set(updates);
          }
        }
      };

      const defaultSystemConfig = createDefaultSystemConfig();

      return {
        systemConfig: defaultSystemConfig,
        currentLab: deriveCurrentLab(defaultSystemConfig),

      setCurrentLab: (labId: string) => {
        const { systemConfig } = get();
        const lab = systemConfig.availableLabs.find(l => l.id === labId);
        if (lab) {
          syncedSet({
            systemConfig: {
              ...systemConfig,
              currentLabId: labId
            }
          });
          // currentLab automatically synced
        }
      },

      addLab: (lab: LabConfiguration) => {
        const { systemConfig } = get();
        const newLab = {
          ...lab,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString()
        };

        syncedSet({
          systemConfig: {
            ...systemConfig,
            availableLabs: [...systemConfig.availableLabs, newLab]
          }
        });
      },

      updateLab: (labId: string, updates: Partial<LabConfiguration>) => {
        const { systemConfig } = get();
        const updatedLabs = systemConfig.availableLabs.map(lab =>
          lab.id === labId
            ? { ...lab, ...updates, updatedAt: new Date().toISOString() }
            : lab
        );

        syncedSet({
          systemConfig: {
            ...systemConfig,
            availableLabs: updatedLabs
          }
        });
        // currentLab automatically synced
      },

      deleteLab: (labId: string) => {
        const { systemConfig } = get();
        const filteredLabs = systemConfig.availableLabs.filter(lab => lab.id !== labId);

        // If deleting current lab, switch to first available
        const newCurrentLabId = labId === systemConfig.currentLabId
          ? filteredLabs[0]?.id || DEFAULT_LAB_CONFIG.id
          : systemConfig.currentLabId;

        syncedSet({
          systemConfig: {
            ...systemConfig,
            availableLabs: filteredLabs,
            currentLabId: newCurrentLabId
          }
        });
        // currentLab automatically synced
      },

      addTank: (labId: string, tank: TankConfiguration) => {
        get().updateLab(labId, {
          equipment: {
            ...get().currentLab.equipment,
            tanks: [...get().currentLab.equipment.tanks, tank]
          }
        });
      },

      updateTank: (labId: string, tankId: string, updates: Partial<TankConfiguration>) => {
        const { systemConfig } = get();
        const lab = systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId ? { ...tank, ...updates, updatedAt: new Date().toISOString() } : tank
        );

        // Create the updated lab with new tank data
        const updatedLab = {
          ...lab,
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          },
          updatedAt: new Date().toISOString()
        };

        // Update availableLabs
        const updatedAvailableLabs = systemConfig.availableLabs.map(l =>
          l.id === labId ? updatedLab : l
        );

        syncedSet({
          systemConfig: {
            ...systemConfig,
            availableLabs: updatedAvailableLabs
          }
        });
        // currentLab automatically synced
      },

      deleteTank: async (labId: string, tankId: string) => {
        // Remove tank from local state
        // Server sync handled by caller via saveToServer()
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (lab?.equipment?.tanks) {
          const filteredTanks = lab.equipment.tanks.filter(tank => tank.id !== tankId);
          get().updateLab(labId, {
            equipment: {
              ...lab.equipment,
              tanks: filteredTanks
            }
          });
        }
      },

      deleteTankLocally: (labId: string, tankId: string) => {
        // Local tank deletion for use by React Query mutations
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (lab?.equipment?.tanks) {
          const filteredTanks = lab.equipment.tanks.filter(tank => tank.id !== tankId);
          get().updateLab(labId, {
            equipment: {
              ...lab.equipment,
              tanks: filteredTanks
            }
          });
        }
      },

      addRack: (labId: string, tankId: string, rack: RackConfiguration) => {
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId 
            ? { ...tank, racks: [...tank.racks, rack] }
            : tank
        );

        get().updateLab(labId, {
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          }
        });
      },

      updateRack: (labId: string, tankId: string, rackId: string, updates: Partial<RackConfiguration>) => {
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId
            ? {
                ...tank,
                racks: tank.racks.map(rack =>
                  rack.id === rackId ? { ...rack, ...updates } : rack
                )
              }
            : tank
        );

        get().updateLab(labId, {
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          }
        });
      },

      deleteRack: (labId: string, tankId: string, rackId: string) => {
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId
            ? { ...tank, racks: tank.racks.filter(rack => rack.id !== rackId) }
            : tank
        );

        get().updateLab(labId, {
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          }
        });
      },

      updateBox: (labId: string, tankId: string, rackId: string, boxId: string, updates: Partial<BoxConfiguration>) => {
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId
            ? {
                ...tank,
                racks: tank.racks.map(rack =>
                  rack.id === rackId
                    ? {
                        ...rack,
                        boxes: rack.boxes.map(box =>
                          box.id === boxId ? { ...box, ...updates } : box
                        )
                      }
                    : rack
                )
              }
            : tank
        );

        get().updateLab(labId, {
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          }
        });
      },

      addBoxToRack: (labId: string, tankId: string, rackId: string, box: BoxConfiguration) => {
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId
            ? {
                ...tank,
                racks: tank.racks.map(rack =>
                  rack.id === rackId
                    ? { ...rack, boxes: [...rack.boxes, box] }
                    : rack
                )
              }
            : tank
        );

        get().updateLab(labId, {
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          }
        });
      },

      deleteBox: (labId: string, tankId: string, rackId: string, boxId: string) => {
        const lab = get().systemConfig.availableLabs.find(l => l.id === labId);
        if (!lab?.equipment.tanks) return;

        const updatedTanks = lab.equipment.tanks.map(tank =>
          tank.id === tankId
            ? {
                ...tank,
                racks: tank.racks.map(rack =>
                  rack.id === rackId
                    ? { ...rack, boxes: rack.boxes.filter(box => box.id !== boxId) }
                    : rack
                )
              }
            : tank
        );

        get().updateLab(labId, {
          equipment: {
            ...lab.equipment,
            tanks: updatedTanks
          }
        });
      },

      updateBoxGridConfig: (labId: string, tankId: string, rackId: string, boxId: string, gridConfig: GridConfiguration) => {
        get().updateBox(labId, tankId, rackId, boxId, { gridConfig });
      },

      getAvailableGridTemplates: () => GRID_TEMPLATES,

      getCurrentTanks: () => {
        const state = get();
        const currentLab = state.currentLab || DEFAULT_LAB_CONFIG;
        const tanks = currentLab.equipment?.tanks || [];

        return tanks;
      },

      getCurrentRacks: (tankId?: string) => {
        const state = get();
        const currentLab = state.currentLab || DEFAULT_LAB_CONFIG;
        const equipment = currentLab.equipment;
        const tanks = equipment?.tanks || [];
        
        if (!tankId) {
          // Return all racks from all tanks for backwards compatibility
          const allRacks = tanks.flatMap(tank => tank.racks || []);

          return allRacks;
        }
        
        const tank = tanks.find(t => t.id === tankId);
        const racks = tank?.racks ?? [];

        return racks;
      },

      getCurrentBoxes: (tankId: string, rackId: string) => {
        const state = get();
        const currentLab = state.currentLab || DEFAULT_LAB_CONFIG;
        const equipment = currentLab.equipment;
        const tanks = equipment.tanks || [];
        const tank = tanks.find(t => t.id === tankId);
        const rack = tank?.racks?.find(r => r.id === rackId);
        return rack?.boxes ?? [];
      },

      getBox: (tankId: string, rackId: string, boxId: string) => {
        const equipment = get().currentLab.equipment;
        const tanks = equipment.tanks || [];
        const tank = tanks.find(t => t.id === tankId);
        const rack = tank?.racks?.find(r => r.id === rackId);
        const box = rack?.boxes?.find(b => b.id === boxId);
        return box;
      },

      getBoxPositionDisplay: (tankId: string, rackId: string, boxId: string) => {
        const equipment = get().currentLab.equipment;
        const tanks = equipment.tanks || [];
        const tank = tanks.find(t => t.id === tankId);
        const rack = tank?.racks?.find(r => r.id === rackId);
        const box = rack?.boxes?.find(b => b.id === boxId);
        return box?.positionDisplay;
      },

      resetToDefaults: () => {
        syncedSet({
          systemConfig: createDefaultSystemConfig()
        });
        // currentLab automatically synced
      },

      // Server synchronization methods (DEPRECATED - use React Query hooks)
      loadFromServer: async () => {
        console.warn('⚠️ ConfigurationStore.loadFromServer() is deprecated. Use useLoadConfigurationQuery() hook instead.');
        
        // Fallback to ensure defaults for legacy compatibility
        get().ensureDefaultConfiguration();
      },

      // Ensure we have a valid default configuration
      ensureDefaultConfiguration: () => {
        const { systemConfig } = get();
        const currentLab = get().currentLab; // Access via getter

        // If current lab doesn't have tanks structure, fix it
        if (!currentLab.equipment.tanks) {

          // Check if we have existing racks to migrate
          const existingRacks = (currentLab.equipment as any)?.racks;

          const tanks = existingRacks ? [
            {
              id: NAMING_PATTERNS.TANK.ID_PATTERN(1),
              name: NAMING_PATTERNS.TANK.DEFAULT_NAME(1),
              location: NAMING_PATTERNS.TANK.DEFAULT_LOCATION,
              isActive: true,
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString(),
              defaultGridConfig: DEFAULT_GRID_CONFIG,
              racks: existingRacks // Use existing racks
            }
          ] : [
            {
              id: NAMING_PATTERNS.TANK.ID_PATTERN(1),
              name: NAMING_PATTERNS.TANK.DEFAULT_NAME(1),
              location: NAMING_PATTERNS.TANK.DEFAULT_LOCATION,
              isActive: true,
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString(),
              defaultGridConfig: DEFAULT_GRID_CONFIG,
              racks: [
                {
                  id: 1,
                  name: NAMING_PATTERNS.RACK.DEFAULT_NAME(1),
                  capacity: EQUIPMENT_DEFAULTS.BOXES_PER_RACK,
                  location: NAMING_PATTERNS.TANK.DEFAULT_LOCATION,
                  isActive: true,
                  boxes: Array.from({ length: EQUIPMENT_DEFAULTS.BOXES_PER_RACK }, (_, i) => ({
                    id: NAMING_PATTERNS.BOX.LETTER_NAME(i),
                    name: NAMING_PATTERNS.BOX.DEFAULT_NAME(i),
                    gridConfig: DEFAULT_GRID_CONFIG,
                    position: i + 1
                  }))
                }
              ]
            }
          ];

          const updatedLab = {
            ...currentLab,
            equipment: {
              ...currentLab.equipment,
              tanks
            }
          };

          // Remove old racks property if it exists
          if ((updatedLab.equipment as any).racks) {
            delete (updatedLab.equipment as any).racks;
          }

          // Update in availableLabs (single source of truth)
          const updatedAvailableLabs = systemConfig.availableLabs.map(lab =>
            lab.id === currentLab.id ? updatedLab : lab
          );

          syncedSet({
            systemConfig: {
              ...systemConfig,
              availableLabs: updatedAvailableLabs
            }
          });
          // currentLab automatically synced
        }
      },

      // Migration helper to convert old racks structure to tanks structure
      migrateConfigurationStructure: (config: any) => {
        if (config.currentLab?.equipment?.racks && !config.currentLab?.equipment?.tanks) {


          // Create a default tank with the existing racks
          const defaultTank = {
            id: NAMING_PATTERNS.TANK.ID_PATTERN(1),
            name: NAMING_PATTERNS.TANK.DEFAULT_NAME(1),
            location: NAMING_PATTERNS.TANK.DEFAULT_LOCATION,
            isActive: true,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
            defaultGridConfig: DEFAULT_GRID_CONFIG,
            racks: config.currentLab.equipment.racks
          };

          // Update the structure
          config.currentLab.equipment.tanks = [defaultTank];
          delete config.currentLab.equipment.racks; // Remove old structure


        }
        return config;
      },

      saveToServer: async () => {
        console.warn('⚠️ ConfigurationStore.saveToServer() is deprecated. Use useSaveConfigurationMutation() hook instead.');
        
        // This method is now deprecated in favor of React Query mutations
        // Components should use useSaveConfigurationMutation() for consistent error handling and cache management
      },
      
      // Initialize and migrate data structure
      initialize: () => {
        get().ensureDefaultConfiguration();
      }
    };
  },
    {
      name: 'odysseus-configuration-store',
      version: 2, // Bumped version to trigger migration
      migrate: (persistedState: any, version: number) => {
        // Migrate from version 1 to version 2 (grid schema changes)
        if (version < 2) {
          const state = persistedState as any;

          // Migrate all grid configurations in the stored state
          if (state.currentLab?.equipment?.tanks) {
            state.currentLab.equipment.tanks = state.currentLab.equipment.tanks.map((tank: any) => ({
              ...tank,
              defaultGridConfig: migrateGridConfig(tank.defaultGridConfig),
              racks: tank.racks?.map((rack: any) => ({
                ...rack,
                boxes: rack.boxes?.map((box: any) => ({
                  ...box,
                  gridConfig: migrateGridConfig(box.gridConfig)
                }))
              }))
            }));
          }

          // Migrate default grid configs
          if (state.currentLab?.equipment?.defaultGridConfig) {
            state.currentLab.equipment.defaultGridConfig = migrateGridConfig(state.currentLab.equipment.defaultGridConfig);
          }

          if (state.currentLab?.equipment?.defaultBoxConfig?.gridConfig) {
            state.currentLab.equipment.defaultBoxConfig.gridConfig = migrateGridConfig(state.currentLab.equipment.defaultBoxConfig.gridConfig);
          }

          // Migrate all labs in systemConfig
          if (state.systemConfig?.availableLabs) {
            state.systemConfig.availableLabs = state.systemConfig.availableLabs.map((lab: any) => {
              if (!lab.equipment?.tanks) return lab;

              return {
                ...lab,
                equipment: {
                  ...lab.equipment,
                  defaultGridConfig: migrateGridConfig(lab.equipment.defaultGridConfig),
                  defaultBoxConfig: lab.equipment.defaultBoxConfig ? {
                    ...lab.equipment.defaultBoxConfig,
                    gridConfig: migrateGridConfig(lab.equipment.defaultBoxConfig.gridConfig)
                  } : undefined,
                  tanks: lab.equipment.tanks.map((tank: any) => ({
                    ...tank,
                    defaultGridConfig: migrateGridConfig(tank.defaultGridConfig),
                    racks: tank.racks?.map((rack: any) => ({
                      ...rack,
                      boxes: rack.boxes?.map((box: any) => ({
                        ...box,
                        gridConfig: migrateGridConfig(box.gridConfig)
                      }))
                    }))
                  }))
                }
              };
            });
          }
        }

        return persistedState;
      },
    }
  )
);

// Utility hooks for common operations
export const useCurrentLab = () => {
  const currentLab = useStorageStore(state => state.currentLab);
  return currentLab;
};

export const useCurrentTanks = () => {
  const getCurrentTanks = useStorageStore(state => state.getCurrentTanks);
  return getCurrentTanks();
};

export const useCurrentRacks = (tankId?: string) => {
  const getCurrentRacks = useStorageStore(state => state.getCurrentRacks);
  return getCurrentRacks(tankId);
};

export const useCurrentBoxes = (tankId: string, rackId: string) => {
  const getCurrentBoxes = useStorageStore(state => state.getCurrentBoxes);
  return getCurrentBoxes(tankId, rackId);
};

export const useGridTemplates = () => {
  const getAvailableGridTemplates = useStorageStore(state => state.getAvailableGridTemplates);
  return getAvailableGridTemplates();
};

/**
 * Position Display Selector Component
 *
 * Allows users to change position display format for a specific box.
 * Supports numeric (1-81) and alphanumeric (A1-I9) formats.
 */

import React from 'react';

import {
  usePositionDisplayPresetsQuery,
  useUpdateBoxPositionDisplayMutation,
} from '@domains/storage/hooks/useBoxPositionDisplay';
import { useStorageStore } from '@domains/storage/stores/storageStore';
import {
  getPositionDisplayForBox,
  hasCustomPositionDisplay,
} from '@domains/storage/utils/positionDisplayUtils';
import { Select, type SelectOption } from '@shared/ui/primitives/select/Select';

import type { GridConfiguration } from '@odysseus/shared-schemas';

export interface PositionDisplaySelectorProps {
  tankId: string;
  rackId: string;
  boxId: string;
  gridConfig: GridConfiguration;

  /**
   * Optional label for the selector
   * @default "Position Display Format"
   */
  label?: string;

  /**
   * Size variant
   * @default "md"
   */
  size?: 'sm' | 'md' | 'lg';

  /**
   * Optional callback when format changes
   */
  onChange?: (format: 'numeric' | 'alphanumeric' | null) => void;

  /**
   * Optional className for styling
   */
  className?: string;
}

/**
 * Position Display Selector Component
 *
 * @example
 * <PositionDisplaySelector
 *   tankId="tank-1"
 *   rackId="1"
 *   boxId="A"
 *   gridConfig={{ rows: 9, cols: 9, template: 'standard' }}
 * />
 */
export const PositionDisplaySelector: React.FC<PositionDisplaySelectorProps> = ({
  tankId,
  rackId,
  boxId,
  gridConfig,
  label = 'Position Display Format',
  size = 'md',
  onChange,
  className,
}) => {
  // Fetch available presets
  const { data: presetsData, isLoading: isLoadingPresets } = usePositionDisplayPresetsQuery();

  // Mutation for updating display format
  const updateMutation = useUpdateBoxPositionDisplayMutation();

  // Get current lab configuration to check for lab default
  const currentLab = useStorageStore((state) => state.currentLab);
  const labDefault = currentLab?.settings?.defaultPositionDisplay;

  // Get current display configuration
  const currentConfig = getPositionDisplayForBox(tankId, rackId, boxId, gridConfig);
  const hasCustomConfig = hasCustomPositionDisplay(tankId, rackId, boxId);

  // Build select options
  const options: SelectOption[] = React.useMemo(() => {
    if (!presetsData) return [];

    const opts: SelectOption[] = [
      {
        value: 'numeric',
        label: 'Numeric (1-81)',
        description: 'Simple numeric labels: 1, 2, 3, ..., 81',
        disabled: false,
      },
      {
        value: 'alphanumeric',
        label: 'Alphanumeric (A1-I9)',
        description: 'Excel-style labels: A1, A2, B1, B2, ..., I9',
        disabled: false,
      },
    ];

    // Add reset option if box has custom config
    if (hasCustomConfig) {
      const resetDescription = labDefault
        ? `Reset to lab default (${labDefault.format === 'numeric' ? 'Numeric' : 'Alphanumeric'})`
        : 'Reset to system default (Alphanumeric)';

      opts.push({
        value: 'default',
        label: 'Reset to Default',
        description: resetDescription,
        disabled: false,
      });
    }

    return opts;
  }, [presetsData, hasCustomConfig, labDefault]);

  // Determine current value
  const currentValue = currentConfig.format;

  // Handle selection change
  const handleChange = (value: string | number | (string | number)[] | null) => {
    if (Array.isArray(value) || value === null) return;

    const format = value as 'numeric' | 'alphanumeric' | 'default';

    // Handle reset to default
    if (format === 'default') {
      updateMutation.mutate({
        tankId,
        rackId,
        boxId,
        positionDisplay: null, // null = reset to default
      });
      onChange?.(null);
      return;
    }

    // Determine position display config
    let positionDisplay;

    if (format === 'numeric') {
      positionDisplay = presetsData?.presets.NUMERIC ?? { format: 'numeric' as const };
    } else {
      // Alphanumeric - use appropriate preset based on grid size
      const preset = presetsData?.presets.ALPHANUMERIC_STANDARD;
      if (preset) {
        // If grid size matches preset (9x9), use as-is
        positionDisplay = preset;
      } else {
        // For custom grid sizes, would need to generate config
        // For now, use standard preset
        positionDisplay = presetsData?.presets.ALPHANUMERIC_STANDARD ?? {
          format: 'alphanumeric' as const,
          alphanumericConfig: {
            rowLabels: ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I'],
            colLabels: ['1', '2', '3', '4', '5', '6', '7', '8', '9'],
            format: 'row-col' as const,
          },
        };
      }
    }

    updateMutation.mutate({
      tankId,
      rackId,
      boxId,
      positionDisplay,
    });

    onChange?.(format);
  };

  // Determine hierarchy description
  const getHierarchyDescription = (): string => {
    if (hasCustomConfig) {
      return 'Custom format for this box';
    }

    if (labDefault) {
      const formatName = labDefault.format === 'numeric' ? 'Numeric' : 'Alphanumeric';
      return `Using lab default (${formatName})`;
    }

    return 'Using system default (Alphanumeric)';
  };

  return (
    <Select
      label={label}
      options={options}
      value={currentValue}
      onChange={handleChange}
      disabled={isLoadingPresets || updateMutation.isPending}
      loading={isLoadingPresets || updateMutation.isPending}
      size={size}
      className={className}
      closeOnSelect={true}
      placeholder="Select position format..."
      description={getHierarchyDescription()}
    />
  );
};

import React, { useMemo, useState, createRef, useCallback } from 'react';

import { StorageNavigatorItem } from './StorageNavigatorItem';
import { TreeLineOverlay } from './TreeLineOverlay';
import { useStorageNavigation } from './useStorageNavigation';
import { useTreeKeyboardNavigation } from './useTreeKeyboardNavigation';

import type { StorageNavigatorProps, VisibleTreeNode } from './storageNavigatorTypes';

export const StorageNavigator: React.FC<StorageNavigatorProps> = ({
  data,
  selected,
  onSelect,
  className = '',
}) => {
  const {
    expandedTanks,
    expandedRacks,
    toggleTank,
    toggleRack,
    selectTank,
    selectRack,
    selectBox,
    isTankSelected,
    isRackSelected,
    isBoxSelected,
  } = useStorageNavigation(data, selected, onSelect);

  // Build flat list of visible nodes for keyboard navigation
  const visibleNodes = useMemo((): VisibleTreeNode[] => {
    const nodes: VisibleTreeNode[] = [];

    data.tanks.forEach((tank, tankIndex) => {
      const tankNode: VisibleTreeNode = {
        id: tank.id,
        name: tank.name,
        level: 'tank',
        tankId: tank.id,
        isExpanded: expandedTanks.has(tank.id),
        isSelected: isTankSelected(tank.id),
        hasChildren: tank.racks.length > 0,
        ref: createRef<HTMLButtonElement>(),
        ariaLevel: 1,
        ariaPosinset: tankIndex + 1,
        ariaSetsize: data.tanks.length,
      };
      nodes.push(tankNode);

      // Only include racks if tank is expanded
      if (expandedTanks.has(tank.id)) {
        tank.racks.forEach((rack, rackIndex) => {
          const compositeKey = `${tank.id}-${rack.id}`;
          const rackNode: VisibleTreeNode = {
            id: rack.id,
            name: rack.name,
            level: 'rack',
            tankId: tank.id,
            rackId: rack.id,
            isExpanded: expandedRacks.has(compositeKey),
            isSelected: isRackSelected(tank.id, rack.id),
            hasChildren: rack.boxes.length > 0,
            ref: createRef<HTMLButtonElement>(),
            ariaLevel: 2,
            ariaPosinset: rackIndex + 1,
            ariaSetsize: tank.racks.length,
          };
          nodes.push(rackNode);

          // Only include boxes if rack is expanded
          if (expandedRacks.has(compositeKey)) {
            rack.boxes.forEach((box, boxIndex) => {
              const boxNode: VisibleTreeNode = {
                id: box.id,
                name: box.name,
                level: 'box',
                tankId: tank.id,
                rackId: rack.id,
                boxId: box.id,
                isExpanded: false,
                isSelected: isBoxSelected(tank.id, rack.id, box.id),
                hasChildren: false,
                ref: createRef<HTMLButtonElement>(),
                ariaLevel: 3,
                ariaPosinset: boxIndex + 1,
                ariaSetsize: rack.boxes.length,
              };
              nodes.push(boxNode);
            });
          }
        });
      }
    });

    return nodes;
  }, [data, expandedTanks, expandedRacks, isTankSelected, isRackSelected, isBoxSelected]);

  // Track which node has keyboard focus
  const [focusedIndex, setFocusedIndex] = useState(() => {
    // Initialize to first selected node, or 0 if none selected
    const selectedIndex = visibleNodes.findIndex(node => node.isSelected);
    return selectedIndex >= 0 ? selectedIndex : 0;
  });

  // Handle node selection from keyboard
  const handleSelectNode = useCallback((node: VisibleTreeNode) => {
    if (node.level === 'tank') {
      toggleTank(node.id);
      selectTank(node.id);
    } else if (node.level === 'rack') {
      toggleRack(node.tankId, node.id);
      selectRack(node.tankId, node.rackId!);
    } else if (node.level === 'box') {
      selectBox(node.tankId, node.rackId!, node.boxId!);
    }
  }, [toggleTank, toggleRack, selectTank, selectRack, selectBox]);

  // Keyboard navigation
  const { handleKeyDown } = useTreeKeyboardNavigation({
    visibleNodes,
    focusedIndex,
    setFocusedIndex,
    onToggleTank: toggleTank,
    onToggleRack: toggleRack,
    onSelectNode: handleSelectNode,
  });

  return (
    <nav
      className={`w-full pl-2 pr-3 pb-2 flex flex-col gap-1 relative ${className}`}
      aria-label="Storage Navigator"
    >
      <div
        role="tree"
        aria-label="Storage hierarchy"
        onKeyDown={handleKeyDown}
        tabIndex={0}
        className="flex flex-col gap-1"
      >
        <TreeLineOverlay
          expandedTanks={expandedTanks}
          expandedRacks={expandedRacks}
        />
        {data.tanks.map((tank, _tankIndex) => {
        const tankExpanded = expandedTanks.has(tank.id);
        const tankSelected = isTankSelected(tank.id);
        const nodeIndex = visibleNodes.findIndex(n => n.id === tank.id && n.level === 'tank');
        const node = visibleNodes[nodeIndex];

        return (
          <StorageNavigatorItem
            key={tank.id}
            id={tank.id}
            name={tank.name}
            level="tank"
            isSelected={tankSelected}
            isExpanded={tankExpanded}
            onToggle={() => toggleTank(tank.id)}
            onSelect={() => {
              toggleTank(tank.id);
              selectTank(tank.id);
            }}
            tabIndex={nodeIndex === focusedIndex ? 0 : -1}
            buttonRef={node?.ref}
            onFocus={() => setFocusedIndex(nodeIndex)}
            ariaLevel={node?.ariaLevel}
            ariaPosinset={node?.ariaPosinset}
            ariaSetsize={node?.ariaSetsize}
          >
            {tank.racks.map((rack, _rackIndex) => {
              const compositeKey = `${tank.id}-${rack.id}`;
              const rackExpanded = expandedRacks.has(compositeKey);
              const rackSelected = isRackSelected(tank.id, rack.id);
              const nodeIndex = visibleNodes.findIndex(n => n.id === rack.id && n.level === 'rack');
              const node = visibleNodes[nodeIndex];

              return (
                <StorageNavigatorItem
                  key={rack.id}
                  id={rack.id}
                  name={rack.name}
                  level="rack"
                  isSelected={rackSelected}
                  isExpanded={rackExpanded}
                  onToggle={() => toggleRack(tank.id, rack.id)}
                  onSelect={() => {
                    toggleRack(tank.id, rack.id);
                    selectRack(tank.id, rack.id);
                  }}
                  tabIndex={nodeIndex === focusedIndex ? 0 : -1}
                  buttonRef={node?.ref}
                  onFocus={() => setFocusedIndex(nodeIndex)}
                  ariaLevel={node?.ariaLevel}
                  ariaPosinset={node?.ariaPosinset}
                  ariaSetsize={node?.ariaSetsize}
                >
                  {rack.boxes.map((box, _boxIndex) => {
                    const boxSelected = isBoxSelected(tank.id, rack.id, box.id);
                    const nodeIndex = visibleNodes.findIndex(n => n.id === box.id && n.level === 'box');
                    const node = visibleNodes[nodeIndex];

                    return (
                      <StorageNavigatorItem
                        key={box.id}
                        id={box.id}
                        name={box.name}
                        level="box"
                        isSelected={boxSelected}
                        isExpanded={false}
                        onToggle={() => {}}
                        onSelect={() => selectBox(tank.id, rack.id, box.id)}
                        tabIndex={nodeIndex === focusedIndex ? 0 : -1}
                        buttonRef={node?.ref}
                        onFocus={() => setFocusedIndex(nodeIndex)}
                        ariaLevel={node?.ariaLevel}
                        ariaPosinset={node?.ariaPosinset}
                        ariaSetsize={node?.ariaSetsize}
                      />
                    );
                  })}
                </StorageNavigatorItem>
              );
            })}
          </StorageNavigatorItem>
        );
      })}
      </div>
    </nav>
  );
};

import React from 'react';

import { refrigeratorFreezer } from '@lucide/lab';
import * as Collapsible from '@radix-ui/react-collapsible';
import { ChevronDown, Icon, Rows3, Box as BoxIcon } from 'lucide-react';

import type { StorageNavigatorItemProps } from './storageNavigatorTypes';
import './StorageNavigator.css';

export const StorageNavigatorItem: React.FC<StorageNavigatorItemProps> = ({
  id,
  name,
  level,
  isSelected,
  isExpanded,
  onToggle,
  onSelect,
  children,
  tabIndex = -1,
  buttonRef,
  onFocus,
  ariaLevel,
  ariaPosinset,
  ariaSetsize,
}) => {
  const hasChildren = !!children;

  const iconSize = level === 'tank' ? 20 : level === 'rack' ? 18 : 16;

  const LevelIcon = () => {
    if (level === 'tank') {
      return <Icon iconNode={refrigeratorFreezer} size={iconSize} />;
    } else if (level === 'rack') {
      return <Rows3 size={iconSize} />;
    } else {
      return <BoxIcon size={iconSize} />;
    }
  };

  return (
    <Collapsible.Root open={isExpanded} onOpenChange={onToggle}>
      <div className="w-full" data-level={level} data-id={id}>
        <button
          ref={buttonRef}
          onClick={onSelect}
          onFocus={onFocus}
          tabIndex={tabIndex}
          className={`storage-nav-button storage-nav-button--${level} ${isSelected ? 'selected' : ''}`}
          role="treeitem"
          aria-level={ariaLevel}
          aria-posinset={ariaPosinset}
          aria-setsize={ariaSetsize}
          aria-expanded={hasChildren ? isExpanded : undefined}
          aria-selected={isSelected}
          aria-label={`${level} ${name}`}
        >
          <div className="storage-nav-button__icon">
            <LevelIcon />
          </div>
          <span className="storage-nav-button__text">{name}</span>
          {hasChildren && (
            <ChevronDown
              size={14}
              className={`storage-nav-button__chevron ${isExpanded ? 'rotate-180' : ''}`}
            />
          )}
        </button>

        {hasChildren && (
          <Collapsible.Content className="overflow-visible data-[state=open]:animate-slideDown data-[state=closed]:animate-slideUp">
            <div className="mt-1 space-y-1">
              {children}
            </div>
          </Collapsible.Content>
        )}
      </div>
    </Collapsible.Root>
  );
};

import { useCallback, useEffect, useState } from 'react';

interface TreeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  strokeWidth: number;
  color: string;
  type: 'tank-vertical' | 'rack-branch' | 'rack-vertical' | 'box-branch';
}

interface TreeLineOverlayProps {
  expandedTanks: Set<string>;
  expandedRacks: Set<string>;
}

const LINE_OFFSET = 4; // Distance from left edge to connection point

export function TreeLineOverlay({
  expandedTanks,
  expandedRacks
}: TreeLineOverlayProps) {
  const [lines, setLines] = useState<TreeLine[]>([]);

  const calculateAllLines = useCallback(() => {
    const container = document.querySelector('[role="tree"]');
    if (!container) return;

    const containerRect = container.getBoundingClientRect();
    const allLines: TreeLine[] = [];

    // Find all tank items
    const tankItems = container.querySelectorAll('[data-level="tank"]');

    tankItems.forEach(tankItem => {
      const tankId = (tankItem as HTMLElement).dataset['id'];
      if (!tankId || !expandedTanks.has(tankId)) return;

      const tankButton = tankItem.querySelector('button');
      if (!tankButton) return;

      const tankRect = tankButton.getBoundingClientRect();
      const tankX = tankRect.left - containerRect.left + LINE_OFFSET;
      const tankBottomY = tankRect.bottom - containerRect.top;

      // Find all racks under this tank
      const rackItems = tankItem.querySelectorAll('[data-level="rack"]');
      let deepestY = tankBottomY;

      rackItems.forEach(rackItem => {
        const rackId = (rackItem as HTMLElement).dataset['id'];
        if (!rackId) return;

        const rackButton = rackItem.querySelector('button');
        if (!rackButton) return;

        const rackRect = rackButton.getBoundingClientRect();
        const rackX = rackRect.left - containerRect.left + LINE_OFFSET;
        const rackY = rackRect.top - containerRect.top + rackRect.height / 2;

        // Add horizontal branch from tank to rack
        allLines.push({
          id: `rack-branch-${tankId}-${rackId}`,
          x1: tankX,
          y1: rackY,
          x2: rackX,
          y2: rackY,
          strokeWidth: 3,
          color: 'var(--color-storage-tank-bg)',
          type: 'rack-branch'
        });

        deepestY = Math.max(deepestY, rackRect.bottom - containerRect.top);

        // Handle boxes if rack is expanded (using composite key)
        const compositeKey = `${tankId}-${rackId}`;
        if (expandedRacks.has(compositeKey)) {
          const boxItems = rackItem.querySelectorAll('[data-level="box"]');
          let deepestBoxY = rackRect.bottom - containerRect.top;

          boxItems.forEach(boxItem => {
            const boxButton = boxItem.querySelector('button');
            if (!boxButton) return;

            const boxRect = boxButton.getBoundingClientRect();
            const boxX = boxRect.left - containerRect.left + LINE_OFFSET;
            const boxY = boxRect.top - containerRect.top + boxRect.height / 2;

            // Add horizontal branch from rack to box
            allLines.push({
              id: `box-branch-${tankId}-${rackId}-${(boxItem as HTMLElement).dataset['id']}`,
              x1: rackX,
              y1: boxY,
              x2: boxX,
              y2: boxY,
              strokeWidth: 2,
              color: 'var(--color-storage-rack-bg)',
              type: 'box-branch'
            });

            deepestBoxY = Math.max(deepestBoxY, boxRect.bottom - containerRect.top);
          });

          // Add vertical line connecting boxes under this rack
          if (boxItems.length > 0) {
            allLines.push({
              id: `rack-vertical-${tankId}-${rackId}`,
              x1: rackX,
              y1: rackRect.bottom - containerRect.top,
              x2: rackX,
              y2: deepestBoxY,
              strokeWidth: 2,
              color: 'var(--color-storage-rack-bg)',
              type: 'rack-vertical'
            });
          }

          deepestY = Math.max(deepestY, deepestBoxY);
        }
      });

      // Add vertical line connecting racks under this tank
      if (rackItems.length > 0) {
        allLines.push({
          id: `tank-vertical-${tankId}`,
          x1: tankX,
          y1: tankBottomY,
          x2: tankX,
          y2: deepestY,
          strokeWidth: 3,
          color: 'var(--color-storage-tank-bg)',
          type: 'tank-vertical'
        });
      }
    });

    setLines(allLines);
  }, [expandedTanks, expandedRacks]);

  // Recalculate lines when expansion state changes
  useEffect(() => {
    // Wait for Radix Collapsible animation to complete
    const timer = setTimeout(() => {
      calculateAllLines();
    }, 350);

    return () => clearTimeout(timer);
  }, [expandedTanks, expandedRacks, calculateAllLines]);

  if (lines.length === 0) return null;

  return (
    <svg
      className="tree-line-overlay"
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        pointerEvents: 'none',
        zIndex: 0
      }}
    >
      <style>
        {`
          .tree-line {
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
          }
        `}
      </style>

      {lines.map((line) => (
        <line
          key={line.id}
          x1={line.x1}
          y1={line.y1}
          x2={line.x2}
          y2={line.y2}
          stroke={line.color}
          strokeWidth={line.strokeWidth}
          opacity={0.5}
          className="tree-line"
        />
      ))}
    </svg>
  );
}

export type {
  StorageHierarchy,
  Tank,
  Rack,
  Box,
  SelectedLocation,
  StorageNavigatorProps,
  StorageNavigatorItemProps,
  VisibleTreeNode,
} from './storageNavigatorTypes';

export { STORAGE_LEVEL_CONFIG, KEYBOARD_SHORTCUTS } from './storageNavigatorConstants';

export { useStorageNavigation } from './useStorageNavigation';
export { useTreeKeyboardNavigation } from './useTreeKeyboardNavigation';

export { StorageNavigator } from './StorageNavigator';
export { StorageNavigatorItem } from './StorageNavigatorItem';
export { TreeLineOverlay } from './TreeLineOverlay';

export interface StorageHierarchy {
  tanks: Tank[];
}

export interface Tank {
  id: string;
  name: string;
  racks: Rack[];
}

export interface Rack {
  id: string;
  name: string;
  boxes: Box[];
}

export interface Box {
  id: string;
  name: string;
  position: number;
}

export interface SelectedLocation {
  tankId: string | null;
  rackId: string | null;
  boxId: string | null;
}

export interface StorageNavigatorProps {
  data: StorageHierarchy;
  selected: SelectedLocation;
  onSelect: (location: SelectedLocation) => void;
  className?: string;
}

export interface StorageNavigatorItemProps {
  id: string;
  name: string;
  level: 'tank' | 'rack' | 'box';
  isSelected: boolean;
  isExpanded: boolean;
  onToggle: () => void;
  onSelect: () => void;
  children?: React.ReactNode;
  tabIndex?: -1 | 0;
  buttonRef?: React.RefObject<HTMLButtonElement>;
  onFocus?: () => void;
  ariaLevel?: number;
  ariaPosinset?: number;
  ariaSetsize?: number;
}

export interface VisibleTreeNode {
  id: string;
  name: string;
  level: 'tank' | 'rack' | 'box';
  tankId: string;
  rackId?: string;
  boxId?: string;
  isExpanded: boolean;
  isSelected: boolean;
  hasChildren: boolean;
  ref: React.RefObject<HTMLButtonElement>;
  ariaLevel: number;
  ariaPosinset: number;
  ariaSetsize: number;
}

import { useState, useCallback, useMemo } from 'react';

import type { StorageHierarchy, SelectedLocation } from './storageNavigatorTypes';

export const useStorageNavigation = (
  data: StorageHierarchy,
  selected: SelectedLocation,
  onSelect: (location: SelectedLocation) => void
) => {
  // Initialize with all tanks expanded by default (only runs once on mount)
  const [expandedTanks, setExpandedTanks] = useState<Set<string>>(() => {
    return new Set(data.tanks.map(tank => tank.id));
  });
  const [expandedRacks, setExpandedRacks] = useState<Set<string>>(new Set());

  const toggleTank = useCallback((tankId: string) => {
    setExpandedTanks((prev) => {
      const next = new Set(prev);
      if (next.has(tankId)) {
        next.delete(tankId);
      } else {
        next.add(tankId);
      }
      return next;
    });
  }, []);

  const toggleRack = useCallback((tankId: string, rackId: string) => {
    const compositeKey = `${tankId}-${rackId}`;
    setExpandedRacks((prev) => {
      const next = new Set(prev);
      if (next.has(compositeKey)) {
        next.delete(compositeKey);
      } else {
        next.add(compositeKey);
      }
      return next;
    });
  }, []);

  const selectTank = useCallback((tankId: string) => {
    const tank = data.tanks.find(t => t.id === tankId);
    if (!tank || tank.racks.length === 0) {
      console.warn('No racks available in tank:', tankId);
      return;
    }

    const firstRack = tank.racks[0];
    if (firstRack.boxes.length === 0) {
      console.warn('No boxes available in rack:', firstRack.id);
      return;
    }

    const firstBox = firstRack.boxes[0];
    onSelect({ tankId, rackId: firstRack.id, boxId: firstBox.id });
  }, [data, onSelect]);

  const selectRack = useCallback((tankId: string, rackId: string) => {
    const tank = data.tanks.find(t => t.id === tankId);
    const rack = tank?.racks.find(r => r.id === rackId);
    if (!rack || rack.boxes.length === 0) {
      console.warn('No boxes available in rack:', rackId);
      return;
    }

    const firstBox = rack.boxes[0];
    onSelect({ tankId, rackId, boxId: firstBox.id });
  }, [data, onSelect]);

  const selectBox = useCallback((tankId: string, rackId: string, boxId: string) => {
    onSelect({ tankId, rackId, boxId });
  }, [onSelect]);

  const isTankSelected = useCallback((tankId: string) => {
    return selected.tankId === tankId;
  }, [selected]);

  const isRackSelected = useCallback((tankId: string, rackId: string) => {
    return selected.tankId === tankId && selected.rackId === rackId;
  }, [selected]);

  const isBoxSelected = useCallback((tankId: string, rackId: string, boxId: string) => {
    return selected.tankId === tankId && selected.rackId === rackId && selected.boxId === boxId;
  }, [selected]);

  return {
    expandedTanks,
    expandedRacks,
    toggleTank,
    toggleRack,
    selectTank,
    selectRack,
    selectBox,
    isTankSelected,
    isRackSelected,
    isBoxSelected,
  };
};

import { useCallback, useState, useRef } from 'react';

import type { VisibleTreeNode } from './storageNavigatorTypes';

interface UseTreeKeyboardNavigationProps {
  visibleNodes: VisibleTreeNode[];
  focusedIndex: number;
  setFocusedIndex: (index: number) => void;
  onToggleTank: (id: string) => void;
  onToggleRack: (tankId: string, rackId: string) => void;
  onSelectNode: (node: VisibleTreeNode) => void;
}

function findParentIndex(nodes: VisibleTreeNode[], currentIndex: number): number {
  const current = nodes[currentIndex];

  // Search backwards for parent based on level hierarchy
  for (let i = currentIndex - 1; i >= 0; i--) {
    const candidate = nodes[i];

    if (current.level === 'rack' && candidate.level === 'tank' && candidate.id === current.tankId) {
      return i;
    }

    if (current.level === 'box' && candidate.level === 'rack' && candidate.id === current.rackId) {
      return i;
    }
  }

  return -1;
}

function findNextMatch(nodes: VisibleTreeNode[], startIndex: number, search: string): number {
  const searchLower = search.toLowerCase();

  // Search from startIndex + 1 to end
  for (let i = startIndex + 1; i < nodes.length; i++) {
    if (nodes[i].name.toLowerCase().startsWith(searchLower)) {
      return i;
    }
  }

  // Wrap around: search from 0 to startIndex
  for (let i = 0; i <= startIndex; i++) {
    if (nodes[i].name.toLowerCase().startsWith(searchLower)) {
      return i;
    }
  }

  return -1;
}

export function useTreeKeyboardNavigation({
  visibleNodes,
  focusedIndex,
  setFocusedIndex,
  onToggleTank,
  onToggleRack,
  onSelectNode,
}: UseTreeKeyboardNavigationProps) {
  const [searchString, setSearchString] = useState('');
  const searchTimeoutRef = useRef<NodeJS.Timeout>();

  const focusNode = useCallback((index: number) => {
    if (index >= 0 && index < visibleNodes.length) {
      setFocusedIndex(index);
      visibleNodes[index].ref.current?.focus();
    }
  }, [visibleNodes, setFocusedIndex]);

  const handleKeyDown = useCallback((event: React.KeyboardEvent) => {
    const node = visibleNodes[focusedIndex];
    if (!node) return;

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        focusNode(Math.min(focusedIndex + 1, visibleNodes.length - 1));
        break;

      case 'ArrowUp':
        event.preventDefault();
        focusNode(Math.max(focusedIndex - 1, 0));
        break;

      case 'Home':
        event.preventDefault();
        focusNode(0);
        break;

      case 'End':
        event.preventDefault();
        focusNode(visibleNodes.length - 1);
        break;

      case 'ArrowRight':
        event.preventDefault();
        if (node.hasChildren && !node.isExpanded) {
          // Closed node with children: open it
          if (node.level === 'tank') {
            onToggleTank(node.id);
          } else if (node.level === 'rack') {
            onToggleRack(node.tankId, node.id);
          }
        } else if (node.hasChildren && node.isExpanded) {
          // Open node with children: move to first child
          const nextIndex = focusedIndex + 1;
          if (nextIndex < visibleNodes.length) {
            focusNode(nextIndex);
          }
        }
        // End node: do nothing
        break;

      case 'ArrowLeft':
        event.preventDefault();
        if (node.hasChildren && node.isExpanded) {
          // Open node: close it
          if (node.level === 'tank') {
            onToggleTank(node.id);
          } else if (node.level === 'rack') {
            onToggleRack(node.tankId, node.id);
          }
        } else if (node.level !== 'tank') {
          // Child node (closed or end): move to parent
          const parentIndex = findParentIndex(visibleNodes, focusedIndex);
          if (parentIndex !== -1) {
            focusNode(parentIndex);
          }
        }
        // Root node (tank): do nothing
        break;

      case 'Enter':
      case ' ':
        event.preventDefault();
        onSelectNode(node);
        break;

      default:
        // Type-ahead search: any printable character
        if (event.key.length === 1 && !event.ctrlKey && !event.altKey && !event.metaKey) {
          event.preventDefault();

          // Clear previous timeout
          if (searchTimeoutRef.current) {
            clearTimeout(searchTimeoutRef.current);
          }

          // Append character to search string
          const newSearch = searchString + event.key.toLowerCase();
          setSearchString(newSearch);

          // Find next matching node (starting from current + 1, wrap around)
          const matchIndex = findNextMatch(visibleNodes, focusedIndex, newSearch);
          if (matchIndex !== -1) {
            focusNode(matchIndex);
          }

          // Clear search string after 500ms
          searchTimeoutRef.current = setTimeout(() => {
            setSearchString('');
          }, 500);
        }
        break;
    }
  }, [visibleNodes, focusedIndex, focusNode, onSelectNode, onToggleTank, onToggleRack, searchString]);

  return { handleKeyDown };
}

/**
 * Grid Configuration UI Helpers
 * Computed properties derived from domain model
