// VIRTUALIZED QUERIES

/**
 * Virtualized tubes query for large datasets
 * 
 * Optimizes for grid display by:
 * - Loading only essential data for rendering
 * - Transforming data into position-indexed format
 * - Supporting lazy loading patterns
 */
export const useVirtualizedTubes = (
  location: { tankId: string; rackId: string; boxId: string },
  options: Omit<UseQueryOptions<TubeData[], Error, Record<number, TubeData>>, 'queryKey' | 'queryFn' | 'select'> = {}
) => {
  return useQuery({
    queryKey: queryKeys.tubes.location(location.tankId, location.rackId, location.boxId),
    queryFn: async () => {
      console.log(`🚀 [Optimized Query] Loading virtualized tubes for ${location.tankId}/${location.rackId}/${location.boxId}`);
      
      // Load tubes with standard parameters
      return await TubeService.fetchTubesByLocation(
        location.tankId, 
        location.rackId, 
        location.boxId
      );
    },
    select: (tubes: TubeData[]) => {
      // Transform flat array into position-indexed object for O(1) lookups
      const positionMap: Record<number, TubeData> = {};
      tubes.forEach(tube => {
        if (tube.location.position) {
          positionMap[tube.location.position] = tube;
        }
      });
      
      console.log(`⚡ [Optimized Query] Transformed ${tubes.length} tubes into position map`);
      return positionMap;
    },
    staleTime: 5 * 60 * 1000, // 5 minutes - longer for virtualized views
    gcTime: 15 * 60 * 1000, // 15 minutes - keep in memory longer (renamed from cacheTime in v5)
    ...options
  });
};

/**
 * Essential tube data only (for lists, search results)
 *
 * Returns minimal tube data for performance in list views:
 * - id, position, tankId, rackId, boxId
 * - cellType, researcher (for display)
 * - Excludes notes, detailed metadata
 */
export const useEssentialTubes = (
  filters: {
    tankId?: string;
    rackId?: string;
    boxId?: string;
    searchTerm?: string;
  } = {},
  options: Omit<UseQueryOptions<TubeData[], Error, TubeData[]>, 'queryKey' | 'queryFn' | 'select'> = {}
) => {
  return useQuery<TubeData[], Error, TubeData[]>({
    queryKey: queryKeys.tubes.lists(),
    queryFn: async () => {
      console.log(`🚀 [Optimized Query] Loading tubes`);
      
      return await TubeService.fetchTubes();
    },
    select: (tubes: TubeData[]) => {
      let filtered = tubes;
      
      if (filters.tankId) {
        filtered = filtered.filter(t => t.location.tankId === filters.tankId);
      }
      if (filters.rackId !== undefined) {
        filtered = filtered.filter(t => t.location.rackId === filters.rackId);
      }
      if (filters.boxId) {
        filtered = filtered.filter(t => t.location.boxId === filters.boxId);
      }
      if (filters.searchTerm) {
        const search = filters.searchTerm.toLowerCase();
        filtered = filtered.filter(t =>
          t.sample.cellType?.toLowerCase().includes(search) ||
          t.researcherId?.toLowerCase().includes(search)
        );
      }
      
      return filtered;
    },
    staleTime: 2 * 60 * 1000,
    ...options
  });
};

// PREFETCHING HOOKS

/**
 * Prefetch adjacent locations for smooth navigation
 * 
 * Prefetches tube data for likely next navigation targets:
 * - Adjacent racks in same tank
 * - Adjacent boxes in same rack
 * - Popular locations based on usage patterns
 */
export const usePrefetchAdjacentLocations = () => {
  const queryClient = useQueryClient();

  return useCallback(
    (currentLocation: { tankId: string; rackId: string; boxId: string }) => {
      const { tankId, rackId, boxId } = currentLocation;
      
      // Prefetch adjacent racks - now handle string-based rack identifiers
      const rackNum = parseInt(rackId);
      const adjacentRacks = [rackNum - 1, rackNum + 1]
        .filter(rack => rack >= 1 && rack <= EQUIPMENT_DEFAULTS.MAX_RACKS_PER_TANK)
        .map(rack => rack.toString());  // Convert back to string
      adjacentRacks.forEach(rack => {
        void queryClient.prefetchQuery({
          queryKey: queryKeys.tubes.location(tankId, rack, boxId),
          queryFn: () => TubeService.fetchTubesByLocation(tankId, rack, boxId),
          staleTime: 5 * 60 * 1000, // 5 minutes
        });
      });
      
      // Prefetch adjacent boxes in same rack
      const boxIndex = boxId.charCodeAt(0) - 65; // A=0, B=1, etc.
      const maxBoxLetter = String.fromCharCode(65 + EQUIPMENT_DEFAULTS.BOXES_PER_RACK - 1);
      const adjacentBoxes = [
        String.fromCharCode(65 + boxIndex - 1), // Previous box
        String.fromCharCode(65 + boxIndex + 1)  // Next box
      ].filter(box => box >= 'A' && box <= maxBoxLetter);
      
      adjacentBoxes.forEach(box => {
        void queryClient.prefetchQuery({
          queryKey: queryKeys.tubes.location(tankId, rackId, box),
          queryFn: () => TubeService.fetchTubesByLocation(tankId, rackId, box),
          staleTime: 5 * 60 * 1000,
        });
      });
      
      console.log(`🔮 [Prefetch] Queued prefetch for ${adjacentRacks.length} racks, ${adjacentBoxes.length} boxes`);
    },
    [queryClient]
  );
};

/**
 * Smart prefetching based on user patterns
 * 
 * Prefetches data based on:
 * - Recently viewed locations
 * - User's typical navigation patterns
 * - High-traffic locations
 */
export const useSmartPrefetch = () => {
  const queryClient = useQueryClient();
  
  return useCallback(
    (userContext: {
      recentLocations?: Array<{ tankId: string; rackId: string; boxId: string }>;
      userRole?: string;
      timeOfDay?: string;
    }) => {
      const { recentLocations = [], userRole } = userContext;
      
      // Prefetch recently visited locations
      recentLocations.slice(0, 3).forEach(location => {
        void queryClient.prefetchQuery({
          queryKey: queryKeys.tubes.location(location.tankId, location.rackId, location.boxId),
          queryFn: () => TubeService.fetchTubesByLocation(location.tankId, location.rackId, location.boxId),
          staleTime: 10 * 60 * 1000, // 10 minutes for recent locations
        });
      });
      
      // Role-based prefetching (example: researchers might prefer certain tanks)
      if (userRole === 'researcher') {
        // Prefetch commonly used research tanks
        ['tank-1', 'tank-2'].forEach(tankId => {
          void queryClient.prefetchQuery({
            queryKey: queryKeys.tubes.location(tankId, '1', 'A'),
            queryFn: () => TubeService.fetchTubesByLocation(tankId, '1', 'A'),
            staleTime: 15 * 60 * 1000,
          });
        });
      }
      
      console.log(`🧠 [Smart Prefetch] Prefetched ${recentLocations.length} recent locations for ${userRole}`);
    },
    [queryClient]
  );
};

// BACKGROUND SYNC OPTIMIZATION

/**
 * Background refresh for active locations
 * 
 * Keeps frequently accessed tube data fresh without user interaction.
 * Useful for locations that are being actively modified by multiple users.
 */
export const useBackgroundRefresh = (
  location: { tankId: string; rackId: string; boxId: string },
  options: {
    enabled?: boolean;
    interval?: number; // milliseconds
  } = {}
) => {
  const { enabled = false, interval = 30000 } = options; // 30 seconds default
  const queryClient = useQueryClient();
  
  return useQuery({
    queryKey: [...queryKeys.tubes.location(location.tankId, location.rackId, location.boxId), 'background'],
    queryFn: async () => {
      console.log(`🔄 [Background Refresh] Syncing ${location.tankId}/${location.rackId}/${location.boxId}`);

      // Invalidate existing cache to force fresh fetch
      await queryClient.invalidateQueries({
        queryKey: queryKeys.tubes.location(location.tankId, location.rackId, location.boxId)
      });

      return new Date().toISOString();
    },
    enabled,
    refetchInterval: interval,
    refetchIntervalInBackground: true,
    refetchOnWindowFocus: false,
    select: () => null, // Don't return data, just trigger refresh
  });
};

// PERFORMANCE MONITORING

/**
 * Query performance metrics
 * 
 * Monitors React Query performance and provides insights:
 * - Cache hit/miss ratios
 * - Query timing
 * - Background update frequency
 */
export const useQueryPerformanceMetrics = () => {
  const queryClient = useQueryClient();
  
  return useCallback(() => {
    const cache = queryClient.getQueryCache();
    const queries = cache.getAll();
    
    const tubeQueries = queries.filter(query => 
      query.queryKey[0] === 'tubes'
    );
    
    const metrics = {
      totalQueries: tubeQueries.length,
      activeQueries: tubeQueries.filter(q => q.observers.length > 0).length,
      staleQueries: tubeQueries.filter(q => q.isStale()).length,
      errorQueries: tubeQueries.filter(q => q.state.status === 'error').length,
      cacheSize: cache.getAll().length,
      memoryUsage: tubeQueries.reduce((acc, q) => acc + JSON.stringify(q.state.data || {}).length, 0)
    };
    
    console.log('📊 [Performance Metrics] React Query Stats:', metrics);
    return metrics;
  }, [queryClient]);
};

/**
 * Tube Form Hook - Generic Factory Pattern
 *
 * Generic factory pattern for tube forms:
 * - Private generic implementation contains all logic (DRY)
 * - Public type-safe wrappers provide domain-specific APIs
 * - Full type safety with Zod input/output types
 *
 * Type Flow:
 * 1. User interacts with form → TInput (CreateTubeFormInput: concentration as string)
 * 2. Form submits → Zod validates and transforms → TOutput (CreateTubeRequest: concentration as number)
 * 3. API receives proper output type
 */

import { useCallback } from 'react';

import { zodResolver } from '@hookform/resolvers/zod';
import {
  createTubeRequestSchema,
  updateTubeRequestSchema,
  type CreateTubeRequest,
  type UpdateTubeRequest,
  type CreateTubeFormInput,
  type UpdateTubeFormInput,
  type TubeData
} from '@odysseus/shared-schemas';
import { useQueryClient } from '@tanstack/react-query';
import { useForm } from 'react-hook-form';

import { queryKeys } from '@app/queryKeys';

import {
  useCreateTubeMutation,
  useUpdateTubeMutation
} from './useTubeMutations';

import type { UseFormReturn, FieldValues } from 'react-hook-form';
import type { ZodType } from 'zod';

/**
 * Submit context for providing non-editable external data (e.g., location from grid selection)
 */
export interface SubmitContext {
  location?: TubeData['location'];
}

/**
 * Form submission result
 */
export interface TubeFormSubmissionResult {
  success: boolean;
  data?: TubeData;
  error?: string;
}

// PRIVATE GENERIC IMPLEMENTATION

/**
 * Generic tube form hook - private implementation
 *
 * Contains all form logic. Not exported directly.
 * Public wrappers (useCreateTubeForm, useEditTubeForm) provide type-safe APIs.
 *
 * @template TInput - Form input type (pre-Zod transformation, must be valid form values)
 * @template TOutput - API output type (post-Zod transformation)
 */
function useTubeForm<TInput extends FieldValues, TOutput extends CreateTubeRequest | UpdateTubeRequest>(
  schema: ZodType<TOutput>,
  config: {
    mode: 'create' | 'edit';
    tubeId?: string;
    initialData?: Partial<TInput>;
    onSuccess?: (data: TubeData) => void;
    onError?: (error: Error) => void;
  }
): {
  form: UseFormReturn<TInput>;
  submitTube: (data: TInput, ctx?: SubmitContext) => Promise<TubeFormSubmissionResult>;
  isSubmitting: boolean;
  submitError: Error | null;
} {
  const { mode, tubeId, initialData, onSuccess, onError } = config;
  const queryClient = useQueryClient();

  // React Hook Form with Zod validation
  // Type assertion needed for generic factory pattern - type safety enforced at public wrappers
  const form = useForm<TInput>({
    resolver: zodResolver(schema as any),
    defaultValues: initialData as any,
    mode: 'onChange' // Real-time validation for immediate feedback
  });

  // React Query mutations
  const createTubeMutation = useCreateTubeMutation();
  const updateTubeMutation = useUpdateTubeMutation();

  /**
   * Validate complete payload with business rules (duplicate position, warnings)
   *
   * @param payload - Validated payload (post-transformation)
   */
  const validateCompletePayload = useCallback((payload: TOutput): { warnings: Record<string, string> } => {
    const warnings: Record<string, string> = {};

    // Warning: Duplicate position check (only if we have location)
    if ('location' in payload && payload.location) {
      // Get existing tubes for duplicate validation (fresh on every validation)
      const existingTubes = queryClient.getQueryData<TubeData[]>(queryKeys.tubes.all) || [];

      const filteredTubes = mode === 'edit' && tubeId
        ? existingTubes.filter(tube => tube.id !== tubeId)
        : existingTubes;

      const duplicate = filteredTubes.find(tube =>
        tube.location.tankId === payload.location!.tankId &&
        tube.location.rackId === payload.location!.rackId &&
        tube.location.boxId === payload.location!.boxId &&
        tube.location.position === payload.location!.position
      );

      if (duplicate) {
        warnings['position'] = `Position ${payload.location!.position} in Tank ${payload.location!.tankId}, Rack ${payload.location!.rackId}, Box ${payload.location!.boxId} is already occupied`;
      }
    }

    return { warnings };
  }, [queryClient, mode, tubeId]);

  /**
   * Form submission handler with context support
   *
   * Proper type transformation:
   * - Form data is INPUT type (pre-transformation: concentration is string)
   * - Zod validates and transforms: INPUT → OUTPUT type
   * - Mutation receives OUTPUT type (post-transformation: concentration is number)
   */
  const submitTube = useCallback(async (data: TInput, ctx?: SubmitContext): Promise<TubeFormSubmissionResult> => {
    try {
      let result: TubeData;

      if (mode === 'create') {
        if (!ctx?.location) {
          throw new Error('Location is required for create mode');
        }

        // Merge form data with context location
        const formInputWithLocation = {
          ...data,
          location: ctx.location
        };

        // Zod validates and transforms INPUT → OUTPUT
        // Input: concentration as string ("1.5e6")
        // Output: concentration as number (1500000)
        const validatedPayload = schema.parse(formInputWithLocation) as TOutput;

        // Validate complete payload and show warnings (non-blocking)
        const { warnings } = validateCompletePayload(validatedPayload);
        if (Object.keys(warnings).length > 0) {
          console.warn('Tube creation warnings:', warnings);
        }

        // Type assertion: we know TOutput is CreateTubeRequest when mode === 'create'
        result = await createTubeMutation.mutateAsync(validatedPayload as CreateTubeRequest);

      } else {
        if (!tubeId) {
          throw new Error('Tube ID is required for edit mode');
        }

        // Merge form data with optional context location
        const formInputWithContext = {
          ...data,
          ...(ctx?.location && { location: ctx.location })
        };

        // Zod validates and transforms INPUT → OUTPUT
        const validatedPayload = schema.parse(formInputWithContext) as TOutput;

        // Validate complete payload and show warnings (non-blocking)
        const { warnings } = validateCompletePayload(validatedPayload);
        if (Object.keys(warnings).length > 0) {
          console.warn('Tube update warnings:', warnings);
        }

        // Type assertion: we know TOutput is UpdateTubeRequest when mode === 'edit'
        result = await updateTubeMutation.mutateAsync({
          id: tubeId,
          updates: validatedPayload as UpdateTubeRequest
        });
      }

      // Call success callback
      onSuccess?.(result);

      return {
        success: true,
        data: result
      };

    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'An unexpected error occurred';
      onError?.(error instanceof Error ? error : new Error(errorMessage));

      return {
        success: false,
        error: errorMessage
      };
    }
  }, [
    mode,
    tubeId,
    createTubeMutation,
    updateTubeMutation,
    validateCompletePayload,
    schema,
    onSuccess,
    onError
  ]);

  // Loading state
  const isSubmitting = createTubeMutation.isPending || updateTubeMutation.isPending;

  // Error state
  // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Cascading fallback chain, empty string should trigger next option
  const submitError = createTubeMutation.error || updateTubeMutation.error;

  return {
    form,          // Pure React Hook Form instance
    submitTube,    // Custom async submission logic
    isSubmitting,  // Combined loading state
    submitError    // Combined error state
  };
}

