/**
 * Field display components for read-only tube information
 *
 * Handles foreign key resolution (e.g., researcherId → researcher name)
 * using the Presenter/ViewModel pattern for clean separation of concerns.
 */

import React from 'react';

import {
  formatConcentrationDisplay,
  formatResearcherDropdownDisplay,
  type Researcher
} from '@odysseus/shared-schemas';

import { formatDateForDisplay } from '@shared/utils/dateFormatter';

import type { FieldConfig } from '../../../config/fieldConfig';

interface FieldDisplayProps {
  config: FieldConfig;
  value: string | number | undefined;
  unitValue?: string;
  researcherMap?: Map<string, Researcher>; // For resolving researcherId → researcher name
}

/**
 * Individual field display renderer
 */
export const FieldDisplay: React.FC<FieldDisplayProps> = ({ config, value, unitValue, researcherMap }) => {
  // Don't render if value is empty
  if (!value && value !== 0) return null;

  const displayValue = () => {
    switch (config.type) {
      case 'date':
        return formatDateForDisplay(String(value));
      case 'concentration':
        return formatConcentrationDisplay(
          typeof value === 'number' ? value : undefined,
          unitValue as 'c/v' | 'c/mL' | undefined
        );
      case 'select':
        // Resolve foreign keys (researcherId → researcher name)
        if (config.key === 'researcherId' && researcherMap) {
          const researcherId = String(value);
          const researcher = researcherMap.get(researcherId);
          if (researcher) {
            // Use shared formatter for consistent display across the app
            return formatResearcherDropdownDisplay(researcher);
          }
          // Fallback if researcher not found (edge case: deleted researcher)
          return `Unknown (ID: ${researcherId})`;
        }
        return String(value);
      default:
        return String(value);
    }
  };

  return (
    <div>
      {config.label && (
        <span className="font-medium text-odysseus-muted uppercase tracking-wider text-[10.5px]">
          {config.label}
        </span>
      )}
      <div className={`font-bold ${config.type === 'textarea' ? 'text-odysseus-secondary leading-snug' : 'text-odysseus-dark'} text-xs`}>
        {displayValue()}
      </div>
    </div>
  );
};

/**
 * Section display renderer
 */
interface SectionDisplayProps {
  title: string;
  borderColor: string;
  headerColor: string;
  fields: Array<{
    config: FieldConfig;
    value: string | number | undefined;
    unitValue?: string;
  }>;
  researcherMap?: Map<string, Researcher>; // Pass through for foreign key resolution
  columns?: number; // Number of columns for grid layout (default: 1 for vertical stacking)
}

export const SectionDisplay: React.FC<SectionDisplayProps> = ({
  title,
  borderColor,
  headerColor,
  fields,
  researcherMap,
  columns = 1
}) => {
  // Filter out empty fields
  const fieldsWithValues = fields.filter(({ value }) => value !== undefined && value !== null && value !== '');

  // Don't render section if no fields have values
  if (fieldsWithValues.length === 0) return null;

  // Map columns to grid class (explicit for Tailwind JIT)
  const gridColsClass = {
    1: 'grid-cols-1',
    2: 'grid-cols-2',
    3: 'grid-cols-3',
    4: 'grid-cols-4',
    6: 'grid-cols-6'
  }[columns] ?? 'grid-cols-1';

  const useGridLayout = columns > 1;

  return (
    <div className={`border-l-4 ${borderColor} pl-2.5 py-0.5`}>
      <div className={`font-bold ${headerColor} uppercase tracking-wider mb-0.5 text-xs`}>
        {title}
      </div>
      <div className={`${useGridLayout ? `grid ${gridColsClass} gap-x-3 gap-y-0.5` : 'flex flex-col'} pl-2`}>
        {fieldsWithValues.map(({ config, value, unitValue }, index) => {
          // Map gridSpan to col-span class (explicit for Tailwind JIT)
          const colSpanClass = config.gridSpan === 2 ? 'col-span-2' :
                               config.gridSpan === 3 ? 'col-span-3' :
                               config.gridSpan === 4 ? 'col-span-4' :
                               config.gridSpan === 5 ? 'col-span-5' :
                               config.gridSpan === 6 ? 'col-span-6' : '';

          // For single-column layouts: control spacing individually
          // Compact fields get minimal spacing (1px), normal fields get standard spacing (2px)
          const spacingClass = !useGridLayout && index > 0
            ? (config.compact ? 'mt-[1px]' : 'mt-0.5')
            : '';

          return (
            <div key={config.key} className={`${colSpanClass} ${config.indent ? 'pl-3' : ''} ${spacingClass}`}>
              <FieldDisplay
                config={config}
                value={value}
                unitValue={unitValue}
                researcherMap={researcherMap}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
};

/**
 * Tube Form Component
 *
 * Uses API schema directly, supports both create and edit modes:
 * - Form fields match CreateTubeRequest/UpdateTubeRequest
 * - No transformation needed
 * - Media uses structured object: { type, supplements, selection }
 * - Concentration handled by ConcentrationInput with Zod preprocessing
 *
 * Compact 4-row layout:
 * - Row 1: Donor Information (Cell Type*, Internal ID, Source ID)
 * - Row 2: Sample Information Part 1 (Concentration + Unit, Media Type, Supplements, Selection)
 * - Row 3: Sample Information Part 2 (Culture Condition, Lot #, Date, Researcher)
 * - Row 4: Notes
 *
 * * = Required field (only Cell Type)
 */

import {
  type CreateTubeRequest,
  type UpdateTubeRequest,
  type Researcher,
  formatResearcherDropdownDisplay
} from '@odysseus/shared-schemas';
import { Controller } from 'react-hook-form';

import { ValidatedInput } from '@shared/ui';

import { ConcentrationInput } from '../../inputs/ConcentrationInput';

import type { Control, UseFormRegister, FieldErrors, UseFormTrigger} from 'react-hook-form';

/**
 * Form values union - supports both create and edit modes
 */
type TubeFormValues = CreateTubeRequest | UpdateTubeRequest;

export interface TubeFormProps {
  control: Control<TubeFormValues>;
  register: UseFormRegister<TubeFormValues>;
  errors: FieldErrors<TubeFormValues>;
  trigger: UseFormTrigger<TubeFormValues>;
  researchers: Researcher[];
  isLoading: boolean;
}

export const TubeForm = ({
  control,
  register,
  errors,
  trigger,
  researchers,
  isLoading
}: TubeFormProps) => {
  // Helper function to get field errors from nested React Hook Form structure
  const getFieldError = (fieldPath: string, errors: FieldErrors<CreateTubeRequest>): string | undefined => {
    const pathParts = fieldPath.split('.');
    let currentError = errors as any;

    for (const part of pathParts) {
      if (currentError?.[part]) {
        currentError = currentError[part];
      } else {
        return undefined;
      }
    }

    return currentError?.message;
  };

  // Helper to get concentration field errors (checks both nested and refinement errors)
  const getConcentrationError = (): string | undefined => {
    // Check for direct concentration field error
    const directError = getFieldError('sample.concentration', errors);
    if (directError) return directError;

    // Check for concentrationUnit field error
    const unitError = getFieldError('sample.concentrationUnit', errors);
    if (unitError) return unitError;

    // Check for refinement error at sample level (concentration/unit invariant)
    const sampleError = (errors as any)?.sample;
    if (sampleError && typeof sampleError.message === 'string') {
      return sampleError.message;
    }

    return undefined;
  };

  return (
    <div className="space-y-3">
      {/* ROW 1: DONOR INFORMATION */}
      <div className="space-y-1.5">
        <h3 className="text-xs font-semibold text-storage-tank-hover tracking-wide uppercase">Donor Information</h3>
        <div className="grid grid-cols-3 gap-2.5">
          <ValidatedInput
            label="Cell Type"
            type="text"
            placeholder="e.g., Jurkat, HEK293"
            registration={register('sample.cellType')}
            error={Boolean(getFieldError('sample.cellType', errors))}
            helperText={getFieldError('sample.cellType', errors)}
            disabled={isLoading}
            required
          />
          <ValidatedInput
            label="Internal ID"
            type="text"
            placeholder="Internal tracking ID"
            registration={register('sample.donorInternalId')}
            error={Boolean(getFieldError('sample.donorInternalId', errors))}
            helperText={getFieldError('sample.donorInternalId', errors)}
            disabled={isLoading}
          />
          <ValidatedInput
            label="Source ID"
            type="text"
            placeholder="Original source ID"
            registration={register('sample.donorSourceId')}
            error={Boolean(getFieldError('sample.donorSourceId', errors))}
            helperText={getFieldError('sample.donorSourceId', errors)}
            disabled={isLoading}
          />
        </div>
      </div>

      {/* ROW 2: SAMPLE INFORMATION (PART 1) - Media Fields */}
      <div className="space-y-1.5">
        <h3 className="text-xs font-semibold text-storage-rack-hover tracking-wide uppercase">Sample Information</h3>
        <div className="grid grid-cols-4 gap-2.5">
          <div>
            <Controller
              name="sample.concentration"
              control={control}
              render={({ field: { value, onChange } }) => (
                <Controller
                  name="sample.concentrationUnit"
                  control={control}
                  render={({ field: { value: unitValue, onChange: onUnitChange } }) => (
                    <ConcentrationInput
                      label="Concentration"
                      value={String(value ?? '')}
                      unitValue={unitValue ?? ''}
                      onChange={onChange}
                      onUnitChange={async (newUnit) => {
                        onUnitChange(newUnit);
                        await trigger('sample');
                      }}
                      placeholder="e.g., 5e6"
                      disabled={isLoading}
                      validation={{
                        error: Boolean(getConcentrationError()),
                        warning: false,
                        helperText: getConcentrationError(),
                        onBlur: () => {}
                      }}
                    />
                  )}
                />
              )}
            />
          </div>
          <ValidatedInput
            label="Media Type"
            type="text"
            placeholder="e.g., RPMI-1640"
            registration={register('sample.media.type')}
            error={Boolean(getFieldError('sample.media.type', errors))}
            helperText={getFieldError('sample.media.type', errors)}
            disabled={isLoading}
          />
          <ValidatedInput
            label="Supplements"
            type="text"
            placeholder="e.g., 10% FBS"
            registration={register('sample.media.supplements')}
            error={Boolean(getFieldError('sample.media.supplements', errors))}
            helperText={getFieldError('sample.media.supplements', errors)}
            disabled={isLoading}
          />
          <ValidatedInput
            label="Selection"
            type="text"
            placeholder="e.g., Puromycin"
            registration={register('sample.media.selection')}
            error={Boolean(getFieldError('sample.media.selection', errors))}
            helperText={getFieldError('sample.media.selection', errors)}
            disabled={isLoading}
          />
        </div>
      </div>

      {/* ROW 3: SAMPLE INFORMATION (PART 2) */}
      <div className="grid grid-cols-4 gap-2.5">
        <ValidatedInput
          label="Culture Condition"
          type="text"
          placeholder="e.g., 5% O₂, 37°C"
          registration={register('sample.cultureCondition')}
          error={Boolean(getFieldError('sample.cultureCondition', errors))}
          helperText={getFieldError('sample.cultureCondition', errors)}
          disabled={isLoading}
        />
        <ValidatedInput
          label="Lot #"
          type="text"
          placeholder="LOT001"
          registration={register('sample.lotNumber')}
          error={Boolean(getFieldError('sample.lotNumber', errors))}
          helperText={getFieldError('sample.lotNumber', errors)}
          disabled={isLoading}
        />
        <ValidatedInput
          label="Date"
          type="date"
          registration={register('sample.date')}
          error={Boolean(getFieldError('sample.date', errors))}
          helperText={getFieldError('sample.date', errors)}
          disabled={isLoading}
        />
        <ValidatedInput
          label="Researcher"
          type="select"
          registration={register('researcherId')}
          error={Boolean(getFieldError('researcherId', errors))}
          helperText={getFieldError('researcherId', errors)}
          disabled={isLoading}
          options={[
            { value: '', label: 'Select researcher...' },
            ...researchers.map(r => ({
              value: r.id,
              label: formatResearcherDropdownDisplay(r)
            }))
          ]}
        />
      </div>

      {/* ROW 4: NOTES */}
      <div className="space-y-1.5">
        <h3 className="text-xs font-semibold text-storage-box-hover tracking-wide uppercase">Notes</h3>
        <ValidatedInput
          label=""
          type="textarea"
          maxLength={500}
          placeholder="Additional notes and observations..."
          registration={register('sample.notes')}
          error={Boolean(getFieldError('sample.notes', errors))}
          helperText={getFieldError('sample.notes', errors)}
          disabled={isLoading}
        />
      </div>
    </div>
  );
};

/**
 * Concentration Field Group Component
 *
 * Uses Zod validation from shared schemas.
 * Dependent field component implementing concentration/unit business rules.
 * Handles smart field dependencies with real-time validation and user feedback.
 */

import React, { useEffect } from 'react';

import { type CreateTubeRequest, type UpdateTubeRequest } from '@odysseus/shared-schemas';
import { Controller } from 'react-hook-form';

import type { UseFormReturn} from 'react-hook-form';

/**
 * Form values union - supports both create and edit modes
 */
type TubeFormValues = CreateTubeRequest | UpdateTubeRequest;

interface ConcentrationFieldGroupProps {
  form: UseFormReturn<TubeFormValues>;
  disabled?: boolean;
}

/**
 * Smart concentration field group with dependent validation
 * 
 * Business Rules:
 * 1. Concentration and unit must be provided together or both empty
 * 2. Auto-clear unit when concentration is cleared
 * 3. Auto-suggest default unit when concentration is entered
 * 4. Real-time validation feedback
 */
export const ConcentrationFieldGroup: React.FC<ConcentrationFieldGroupProps> = ({ 
  form, 
  disabled = false 
}) => {
  const concentration = form.watch('sample.concentration');
  const concentrationUnit = form.watch('sample.concentrationUnit');

  // Smart field dependency logic (UX convenience, not authoritative validation)
  useEffect(() => {
    // Number-safe check - concentration is number | undefined from Zod preprocessing
    const hasConcentration = concentration !== undefined && concentration !== null;
    const hasUnit = !!concentrationUnit;

    // Auto-clear unit when concentration is cleared
    if (!hasConcentration && hasUnit) {
      form.setValue('sample.concentrationUnit', undefined, { 
        shouldValidate: true,
        shouldDirty: true,
        shouldTouch: true
      });
    }

    // Auto-suggest default unit when concentration is entered
    if (hasConcentration && !hasUnit) {
      form.setValue('sample.concentrationUnit', 'c/v', { 
        shouldValidate: true,
        shouldDirty: true,
        shouldTouch: true
      });
    }
  }, [concentration, concentrationUnit, form]);

  return (
    <div className="space-y-4">
      {/* Concentration Field */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="space-y-2">
          <label 
            htmlFor="concentration" 
            className="block text-sm font-medium text-odysseus-text-primary"
          >
            Concentration
          </label>
          <div className="relative">
            <input
              {...form.register('sample.concentration', {
                // Zod preprocessor handles conversion - keep number | undefined type
                setValueAs: (v) => (v === '' || v === undefined || v === null ? undefined : Number(v)),
                // Validation handled by zodResolver - no manual validation needed
              })}
              id="concentration"
              type="text"
              placeholder="e.g., 5e6, 1.5E7, 5000000"
              disabled={disabled}
              className={`input-field w-full ${form.formState.errors.sample?.concentration ? 'input-field-error' : 'input-field-normal'}`}
            />
            {form.formState.errors.sample?.concentration && (
              <div className="absolute right-3 top-1/2 transform -translate-y-1/2">
                <div className="w-5 h-5 rounded-full bg-validation-error-icon flex items-center justify-center">
                  <span className="text-white text-xs font-bold">!</span>
                </div>
              </div>
            )}
          </div>
          {form.formState.errors.sample?.concentration && (
            <p className="text-sm text-validation-error-helper flex items-center mt-1">
              <span className="mr-1">⚠️</span>
              {form.formState.errors.sample?.concentration.message}
            </p>
          )}
        </div>

        {/* Concentration Unit Field */}
        <div className="space-y-2">
          <label 
            htmlFor="concentrationUnit" 
            className="block text-sm font-medium text-odysseus-text-primary"
          >
            Unit
            {/* Number-safe check - required when concentration is provided */}
            {(concentration !== undefined && concentration !== null) && (
              <span className="text-validation-error-required ml-1">*</span>
            )}
          </label>
          <div className="relative">
            <Controller
              control={form.control}
              name="sample.concentrationUnit"
              render={({ field }) => (
                <select
                  id="concentrationUnit"
                  disabled={disabled}
                  value={field.value ?? ''}
                  onChange={(e) => field.onChange(e.target.value || undefined)}
                  className={`input-field w-full ${form.formState.errors.sample?.concentrationUnit ? 'input-field-error' : 'input-field-normal'}`}
                >
                  <option value="">Select unit...</option>
                  <option value="c/v">c/v (cells per volume)</option>
                  <option value="c/mL">c/mL (cells per milliliter)</option>
                </select>
              )}
            />
            {form.formState.errors.sample?.concentrationUnit && (
              <div className="absolute right-8 top-1/2 transform -translate-y-1/2">
                <div className="w-5 h-5 rounded-full bg-validation-error-icon flex items-center justify-center">
                  <span className="text-white text-xs font-bold">!</span>
                </div>
              </div>
            )}
          </div>
          {form.formState.errors.sample?.concentrationUnit && (
            <p className="text-sm text-validation-error-helper flex items-center mt-1">
              <span className="mr-1">⚠️</span>
              {form.formState.errors.sample?.concentrationUnit.message}
            </p>
          )}
        </div>
      </div>

      {/* Smart Field Hint */}
      {concentration ?? concentrationUnit ? (
        <div className="flex items-center space-x-2 text-sm text-odysseus-text-secondary bg-odysseus-surface/50 rounded-lg p-3 border border-odysseus-border/50">
          <div className="w-4 h-4 rounded-full bg-blue-500 flex items-center justify-center flex-shrink-0">
            <span className="text-white text-xs">i</span>
          </div>
          <p>
            {concentration && concentrationUnit 
              ? `Concentration: ${concentration} ${concentrationUnit}`
              : 'Both concentration value and unit are required together'
            }
          </p>
        </div>
      ) : null}
    </div>
  );
};

