import { useCallback, useEffect, useState } from 'react';

import { useStorageStore } from '@domains/storage';

interface AnimatedTreeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  color: string;
  strokeWidth: number;
  type: 'tank-vertical' | 'rack-branch' | 'rack-vertical' | 'box-branch';
  retracted?: boolean; // For coordinate-based retraction
}

interface AnimatedTreeLineOverlayProps {
  expandedTanks: Set<string>;
  expandedRacks: Set<string>;
}

const LINE_OFFSET = 8; // Distance into button for connection point

export function AnimatedTreeLineOverlay({
  expandedTanks,
  expandedRacks
}: AnimatedTreeLineOverlayProps) {
  const [lines, setLines] = useState<AnimatedTreeLine[]>([]);

  // Get configuration methods
  const getCurrentTanks = useStorageStore(state => state.getCurrentTanks);

  const tanks = getCurrentTanks();

  // Calculate all lines at once - CSS transitions handle the animation
  const calculateAllLines = useCallback(() => {
    const container = document.querySelector('.storage-navigator');
    if (!container) return;

    const containerRect = container.getBoundingClientRect();
    const allLines: AnimatedTreeLine[] = [];

    tanks.forEach(tank => {
      const tankId = tank.id;
      if (!expandedTanks.has(tankId)) return;

      const tankButton = container.querySelector(`[data-tank-id="${tankId}"] .tank-button`) as HTMLElement;
      if (!tankButton) return;

      const tankRect = tankButton.getBoundingClientRect();
      const tankX = tankRect.left - containerRect.left + LINE_OFFSET;
      const tankBottomY = tankRect.bottom - containerRect.top;

      const rackElements = container.querySelectorAll(`[data-tank-id="${tankId}"] [data-rack-id]`);
      let deepestY = tankBottomY;

      rackElements.forEach(rackElement => {
        const rackId = (rackElement as HTMLElement).dataset['rackId'];
        if (!rackId) return;

        const rackButton = rackElement.querySelector('.rack-button') as HTMLElement;
        if (!rackButton) return;

        const rackRect = rackButton.getBoundingClientRect();
        const rackX = rackRect.left - containerRect.left + LINE_OFFSET;
        const rackY = rackRect.top - containerRect.top + rackRect.height / 2;

        // Add rack horizontal branch
        allLines.push({
          id: `rack-branch-${tankId}-${rackId}`,
          x1: tankX,
          y1: rackY,
          x2: rackX,
          y2: rackY,
          color: '#5987b6', // Tank color - matches tank button
          strokeWidth: 3,
          type: 'rack-branch'
        });

        deepestY = Math.max(deepestY, rackRect.bottom - containerRect.top);

        // Handle boxes if rack is expanded
        const rackKey = `${tankId}-${rackId}`;
        if (expandedRacks.has(rackKey)) {
          const boxElements = rackElement.querySelectorAll('.box-button');
          let deepestBoxY = rackRect.bottom - containerRect.top;

          boxElements.forEach((boxElement, boxIndex) => {
            const boxRect = boxElement.getBoundingClientRect();
            const boxX = boxRect.left - containerRect.left + LINE_OFFSET;
            const boxY = boxRect.top - containerRect.top + boxRect.height / 2;

            allLines.push({
              id: `box-branch-${tankId}-${rackId}-${boxIndex}`,
              x1: rackX,
              y1: boxY,
              x2: boxX,
              y2: boxY,
              color: '#7a9fc5', // Rack color - matches rack button
              strokeWidth: 1,
              type: 'box-branch'
            });

            deepestBoxY = Math.max(deepestBoxY, boxRect.bottom - containerRect.top);
          });

          if (boxElements.length > 0) {
            allLines.push({
              id: `rack-vertical-${tankId}-${rackId}`,
              x1: rackX,
              y1: rackRect.bottom - containerRect.top,
              x2: rackX,
              y2: deepestBoxY,
              color: '#7a9fc5', // Rack color - matches rack button
              strokeWidth: 1,
              type: 'rack-vertical'
            });
          }

          deepestY = Math.max(deepestY, deepestBoxY);
        }
      });

      // Add tank vertical line
      allLines.push({
        id: `tank-vertical-${tankId}`,
        x1: tankX,
        y1: tankBottomY,
        x2: tankX,
        y2: deepestY,
        color: '#5987b6', // Tank color - matches tank button
        strokeWidth: 3,
        type: 'tank-vertical'
      });
    });

    setLines(allLines);
  }, [expandedTanks, expandedRacks, tanks]);

  // Update lines when expansion state changes
  useEffect(() => {
    // Wait for animations to complete (350ms animation + 25ms buffer)
    const timer = setTimeout(() => {
      calculateAllLines();
    }, 375);

    return () => clearTimeout(timer);
  }, [expandedTanks, expandedRacks, tanks, calculateAllLines]);

  if (lines.length === 0) return null;

  return (
    <svg
      className="animated-tree-line-overlay"
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        pointerEvents: 'none',
        zIndex: 0
      }}
    >
      <style>
        {`
          .animated-tree-line {
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
          }
        `}
      </style>
      
      {lines.map((line) => (
        <line
          key={line.id}
          x1={line.x1}
          y1={line.y1}
          x2={line.x2}
          y2={line.y2}
          stroke={line.color}
          strokeWidth={line.strokeWidth}
          opacity={0.75}
          className="animated-tree-line"
        />
      ))}
    </svg>
  );
}

import React, { memo } from 'react';

import { useUserSettings } from '@domains/authentication/hooks/useUserSettings';
import { formatPositionForBox } from '@domains/storage/utils/positionDisplayUtils';
import { InlineEditInput } from '@shared/ui';

import { getTubeColor, getLotStyleForBox, getConditionStyleForBox, parseDonorInfo } from '../../../utils/colorSystem';

import type { GridConfiguration } from '@domains/storage';
import type { TubeData } from '@domains/tubes/types';
import '@shared/styles/legacy/colorIndicators.css';

// Helper functions for enhanced CSS class generation
function getPatternClass(pattern: string): string {
  switch (pattern) {
    case 'stripe': return 'striped';
    case 'dot': return 'dotted';
    case 'cross': return 'crossed';
    case 'checkered': return 'checkered';
    case 'waves': return 'waves';
    case 'hatched': return 'hatched';
    case 'gradient': return 'gradient';
    default: return '';
  }
}

function getColorClass(color: string): string {
  if (color === '#FFFF00') return 'yellow';
  if (color === '#FFFFFF') return 'white';
  return '';
}

interface GridPositionProps {
  position: number;
  tankId: string;
  rackId: string;
  boxId: string;
  tube: TubeData | null | undefined;
  selected: boolean;
  isDragPreview?: boolean; // Visual preview only, no animation
  isCut: boolean;
  isCopied: boolean;
  _isKeyboardFocused: boolean;
  animationKey?: number;
  quickEditMode: { position: number; field: string } | null;
  gridConfig: GridConfiguration;
  fontSize: { cellFont: number; donorFont: number; positionFont: number };
  onPositionClick: (position: number, event: React.MouseEvent) => void;
  onPositionRightClick: (position: number, event: React.MouseEvent) => void;
  onPositionDoubleClick?: (position: number, event: React.MouseEvent) => void;
  onMouseDown: (position: number, event: React.MouseEvent) => void;
  onMouseMove: (position: number) => void;
  onQuickEditSave: (position: number, field: string, value: string) => void;
  onQuickEditCancel: () => void;
}

export const GridPosition = memo<GridPositionProps>(({
  position,
  tankId,
  rackId,
  boxId,
  tube,
  selected,
  isDragPreview = false,
  isCut,
  isCopied,
  _isKeyboardFocused,
  animationKey = 0,
  quickEditMode,
  gridConfig,
  fontSize,
  onPositionClick,
  onPositionRightClick,
  onPositionDoubleClick,
  onMouseDown,
  onMouseMove,
  onQuickEditSave,
  onQuickEditCancel
}) => {
  const isQuickEdit = quickEditMode?.position === position;

  // Get user settings for 4-tier position display hierarchy
  const { settings } = useUserSettings();

  // Get color coding for this tube
  const colors = tube ? getTubeColor(tube) : null;
  const lotStyle = tube?.sample?.lotNumber ? getLotStyleForBox(tube.sample.lotNumber, rackId, boxId) : null;
  const conditionStyle = tube?.sample?.cultureCondition ? getConditionStyleForBox(tube.sample.cultureCondition, rackId, boxId) : null;
  const donorInfo = tube ? parseDonorInfo(tube) : { internal: '', source: '' };

  return (
    <div
      key={`${position}-${animationKey}`}
      onClick={(e) => onPositionClick(position, e)}
      onDoubleClick={(e) => onPositionDoubleClick?.(position, e)}
      onContextMenu={(e) => onPositionRightClick(position, e)}
      onMouseDown={(e) => onMouseDown(position, e)}
      onMouseMove={() => onMouseMove(position)}
      onKeyDown={(e) => {
        // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Boolean OR logic for keyboard event handling
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onPositionClick(position, e as any);
        }
      }}
      role="gridcell"
      aria-label={tube
        // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Empty cellType is validation failure, show fallback
        ? `Position ${position}, ${tube.sample?.cellType || 'Unknown sample'}, ${selected ? 'selected' : 'not selected'}`
        : `Position ${position}, empty, ${selected ? 'selected' : 'not selected'}`
      }
      aria-selected={selected}
      tabIndex={selected ? 0 : -1}
      className={`
        tube-position relative group cursor-pointer
        ${tube ? 'occupied' : 'empty'}
        ${selected ? 'selected' : ''}
        ${isDragPreview ? 'drag-preview' : ''}
        ${isCut ? 'cut-tube' : ''}
        ${isCopied ? 'copied-tube' : ''}
        rounded-lg
      `}
      style={{
        backgroundColor: colors?.backgroundColor ?? '#f8f9fa',
        color: colors?.textColor ?? (tube ? '#000' : '#999'),
        width: '100%',
        height: '100%',
        aspectRatio: '1',
        // CSS custom properties for dynamic theming
        '--border-color': colors?.borderColor ?? '#C4C4C4'
      } as React.CSSProperties}
      data-grid-size={`${gridConfig.rows}x${gridConfig.cols}`}
      data-position={position}
    >
      {/* Position number - compact responsive design */}
      <div
        className="absolute top-0.5 right-0.5 font-semibold bg-white/95 rounded text-gray-700 shadow-sm border border-gray-300 flex items-center justify-center leading-none"
        style={{
          width: `${fontSize.positionFont + 2}px`,
          height: `${fontSize.positionFont + 2}px`,
          fontSize: `${fontSize.positionFont}px`,
          zIndex: 3
        }}
      >
        {formatPositionForBox(position, tankId, rackId, boxId, gridConfig, settings)}
      </div>
      
      {/* Lot number indicator - top-left */}
      {tube && lotStyle && (
        <div
          className={`lot-indicator ${getPatternClass(lotStyle.pattern)} ${getColorClass(lotStyle.color)}`}
          style={{
            backgroundColor: lotStyle.color,
            border: lotStyle.color === '#FFFFFF' ? '2px solid #000000' : undefined,
            width: `${fontSize.positionFont + 2}px`,
            height: `${fontSize.positionFont + 2}px`
          }}
          title={`Lot #: ${tube.sample.lotNumber}`}
        />
      )}
      
      {/* Condition indicator - bottom-right */}
      {tube && conditionStyle && (
        <div
          className="condition-indicator"
          style={{
            backgroundColor: conditionStyle.color,
            width: `${fontSize.positionFont + 2}px`,
            height: `${fontSize.positionFont + 2}px`
          }}
          title={`Condition: ${tube.sample.cultureCondition}`}
        />
      )}
      
      {/* Tube content with breathing room */}
      {tube ? (
        <div className="tube-content p-2 flex flex-col items-center justify-center text-center">
          <div
            className="cell-line font-medium leading-tight"
            style={{ fontSize: `${fontSize.cellFont}px` }}
            // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Empty cellType is validation failure, show fallback
            title={tube.sample.cellType || 'Unknown'}
          >
            {/* eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing */}
            {tube.sample.cellType || 'Unknown'}
          </div>
          {donorInfo.internal && (
            <div 
              className="donor-internal leading-tight"
              style={{ fontSize: `${fontSize.donorFont}px` }}
              title={`Internal ID: ${donorInfo.internal}`}
            >
              {donorInfo.internal}
            </div>
          )}
          {donorInfo.source && (
            <div
              className="donor-source leading-tight"
              style={{ fontSize: `${fontSize.donorFont}px` }}
              // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Cascading fallback, empty string should trigger next option
              title={`Source ID: ${tube.sample.donorSourceId || donorInfo.source}`}
            >
              {donorInfo.source}
            </div>
          )}
        </div>
      ) : (
        <div className="tube-content p-2 flex flex-col items-center justify-center text-center">
          <div 
            className="empty-label font-medium leading-tight"
            style={{ fontSize: `${fontSize.cellFont}px` }}
          >
            Empty
          </div>
        </div>
      )}

      {/* Quick edit overlay */}
      {isQuickEdit && tube && quickEditMode && (
        <InlineEditInput
          initialValue={(tube as any)[quickEditMode.field] ?? ''}
          fieldName={quickEditMode.field}
          onSave={(value) => onQuickEditSave(position, quickEditMode.field, value)}
          onCancel={onQuickEditCancel}
          placeholder={`Edit ${quickEditMode.field}`}
        />
      )}
    </div>
  );
});

GridPosition.displayName = 'GridPosition';

/**
 * Storage Navigator
 *
 * Collapsible tree for navigating tank → rack → box hierarchy.
 *
 * Key Features:
 * - Click any level to navigate + expand/collapse
 * - Keyboard navigation support
 * - Performance optimized (single visibleItems calculation)
 * - Default state: Tank 1 → Rack 1 → Box A visible
 */

import { useState, useMemo, useCallback } from 'react';

import { ChevronDown, ChevronRight } from 'lucide-react';

import { gridNavigationService } from '@domains/grid';
import { useStorageStore , getGridDisplayName } from '@domains/storage';
import { useTubeStore } from '@domains/tubes';
import { useListKeyboardNavigation } from '@shared/hooks/keyboard';
import { TankIcon, RackIcon, BoxIcon } from '@shared/ui/components/icons';

import { AnimatedTreeLineOverlay } from './AnimatedTreeLineOverlay';

export function StorageNavigator() {
  const { currentTank, currentRack, currentBox } = useTubeStore();

  // Get configuration methods
  const getCurrentTanks = useStorageStore(state => state.getCurrentTanks);
  const getCurrentRacks = useStorageStore(state => state.getCurrentRacks);
  const getCurrentBoxes = useStorageStore(state => state.getCurrentBoxes);

  const tanks = getCurrentTanks();

  // Initialize with Tank 1 and Rack 1 expanded
  const [expandedTanks, setExpandedTanks] = useState<Set<string>>(() => {
    const firstTank = tanks[0];
    return firstTank ? new Set([firstTank.id]) : new Set();
  });

  const [expandedRacks, setExpandedRacks] = useState<Set<string>>(() => {
    const firstTank = tanks[0];
    if (!firstTank) return new Set();

    const firstRack = getCurrentRacks(firstTank.id)[0];
    if (!firstRack) return new Set();

    return new Set([`${firstTank.id}-${firstRack.id}`]);
  });


  // Click handlers: Navigate + Toggle expansion
  const handleTankClick = async (tankId: string) => {
    // Toggle expansion
    setExpandedTanks(prev => {
      const newSet = new Set(prev);
      if (newSet.has(tankId)) {
        newSet.delete(tankId);
      } else {
        newSet.add(tankId);
      }
      return newSet;
    });

    // Navigate to first rack/box in this tank
    const result = await gridNavigationService.navigateToTank(tankId);
    if (!result.success) {
      console.error('Failed to navigate to tank:', result.error);
    }
  };

  const handleRackClick = async (tankId: string, rackId: string) => {
    const rackKey = `${tankId}-${rackId}`;

    // Toggle expansion
    setExpandedRacks(prev => {
      const newSet = new Set(prev);
      if (newSet.has(rackKey)) {
        newSet.delete(rackKey);
      } else {
        newSet.add(rackKey);
      }
      return newSet;
    });

    // Navigate to first box in this rack
    const result = await gridNavigationService.navigateToRack(tankId, rackId);
    if (!result.success) {
      console.error('Failed to navigate to rack:', result.error);
    }
  };

  const handleBoxClick = async (tankId: string, rackId: string, boxId: string) => {
    const result = await gridNavigationService.navigateToLocation({ tankId, rackId, boxId });
    if (!result.success) {
      console.error('Failed to navigate to box:', result.error);
    }
  };

  // Build flat list of all visible items for keyboard navigation
  // Memoized to prevent recalculation on every render
  const visibleItems = useMemo(() => {
    const items: Array<{
      id: string;
      type: 'tank' | 'rack' | 'box';
      tankId: string;
      rackId?: string;
      boxName?: string;
      action: () => void;
    }> = [];

    tanks.forEach(tank => {
      // Tank item
      items.push({
        id: `tank-${tank.id}`,
        type: 'tank',
        tankId: tank.id,
        action: () => handleTankClick(tank.id)
      });

      // If tank is expanded, add rack items
      if (expandedTanks.has(tank.id)) {
        const tankRacks = getCurrentRacks(tank.id);

        tankRacks.forEach(rack => {
          const rackKey = `${tank.id}-${rack.id}`;

          // Rack item
          items.push({
            id: `rack-${tank.id}-${rack.id}`,
            type: 'rack',
            tankId: tank.id,
            rackId: rack.id,
            action: () => handleRackClick(tank.id, rack.id)
          });

          // If rack is expanded, add box items
          if (expandedRacks.has(rackKey)) {
            const rackBoxes = getCurrentBoxes(tank.id, rack.id);

            rackBoxes.forEach(box => {
              items.push({
                id: `box-${tank.id}-${rack.id}-${box.id}`,
                type: 'box',
                tankId: tank.id,
                rackId: rack.id,
                boxName: box.name,
                action: () => handleBoxClick(tank.id, rack.id, box.id)
              });
            });
          }
        });
      }
    });

    return items;
  }, [tanks, expandedTanks, expandedRacks, getCurrentRacks, getCurrentBoxes]);

  // Handle item selection from keyboard
  const handleItemSelect = useCallback((item: typeof visibleItems[number], _index: number) => {
    item.action();
  }, []);

  // Keyboard navigation hook
  const {
    getItemProps,
    getContainerProps,
  } = useListKeyboardNavigation(
    visibleItems,
    handleItemSelect,
    false // Single selection only
  );

  // Helper functions for selection state (uses current location from store)
  const isTankInSelectionPath = (tankId: string) => currentTank === tankId;
  const isRackInSelectionPath = (tankId: string, rackId: string) =>
    currentTank === tankId && currentRack === rackId;
  const isBoxSelected = (tankId: string, rackId: string, boxId: string) =>
    currentTank === tankId && currentRack === rackId && currentBox === boxId;

  return (
    <div
      className="storage-navigator"
      {...getContainerProps()}
    >
      <AnimatedTreeLineOverlay
        expandedTanks={expandedTanks}
        expandedRacks={expandedRacks}
      />
      {tanks.map((tank) => {
        const isExpanded = expandedTanks.has(tank.id);
        const isSelected = isTankInSelectionPath(tank.id);
        const tankRacks = getCurrentRacks(tank.id);

        return (
          <div
            key={tank.id}
            className={`selector-level tank-level ${isExpanded ? 'expanded' : ''}`}
            data-tank-id={tank.id}
            style={{'--rack-count': tankRacks.length} as React.CSSProperties}
          >
            <button
              onClick={() => handleTankClick(tank.id)}
              className={`selector-button tank-button ${isSelected ? 'selected' : ''}`}
              title={`${isExpanded ? 'Collapse' : 'Expand'} ${tank.name} - ${tank.location}`}
              data-button-id={`tank-${tank.id}`}
              {...getItemProps(visibleItems.findIndex(item => item.id === `tank-${tank.id}`))}
            >
              <div className="button-content">
                <TankIcon className="selector-icon" size={20} />
                <span className="selector-text">{tank.name}</span>
                <div className="expand-indicator">
                  {isExpanded ? (
                    <ChevronDown className="expand-icon" size={14} />
                  ) : (
                    <ChevronRight className="expand-icon" size={14} />
                  )}
                </div>
              </div>
            </button>

            <div className={`selector-children-wrapper ${isExpanded ? 'expanded' : ''}`}>
              <div className="selector-children-content">
                {tankRacks.map((rack) => {
                  const rackKey = `${tank.id}-${rack.id}`;
                  const isRackExpanded = expandedRacks.has(rackKey);
                  const isRackSelected = isRackInSelectionPath(tank.id, rack.id);
                  const rackBoxes = getCurrentBoxes(tank.id, rack.id);

                  return (
                    <div
                      key={rack.id}
                      className={`selector-level rack-level ${isRackExpanded ? 'expanded' : ''}`}
                      data-rack-id={rack.id}
                      style={{'--box-count': rackBoxes.length} as React.CSSProperties}
                    >
                      <button
                        onClick={() => handleRackClick(tank.id, rack.id)}
                        className={`selector-button rack-button ${isRackSelected ? 'selected' : ''}`}
                        title={rack.location ? `${isRackExpanded ? 'Collapse' : 'Expand'} ${rack.name} - ${rack.location}` : `${isRackExpanded ? 'Collapse' : 'Expand'} ${rack.name}`}
                        data-button-id={`rack-${tank.id}-${rack.id}`}
                        {...getItemProps(visibleItems.findIndex(item => item.id === `rack-${tank.id}-${rack.id}`))}
                      >
                        <div className="button-content">
                          <RackIcon className="selector-icon" size={18} />
                          <span className="selector-text">{rack.name}</span>
                          <div className="expand-indicator">
                            {isRackExpanded ? (
                              <ChevronDown className="expand-icon" size={12} />
                            ) : (
                              <ChevronRight className="expand-icon" size={12} />
                            )}
                          </div>
                        </div>
                      </button>

                      <div className={`selector-children-wrapper ${isRackExpanded ? 'expanded' : ''}`}>
                        <div className="selector-children-content">
                          {rackBoxes.map((box) => {
                            const boxSelected = isBoxSelected(tank.id, rack.id, box.id);

                            return (
                              <div
                                key={box.id}
                                className="selector-level box-level"
                                data-box-id={box.id}
                              >
                                <button
                                  onClick={() => handleBoxClick(tank.id, rack.id, box.id)}
                                  className={`selector-button box-button ${boxSelected ? 'selected' : ''}`}
                                  title={`${box.name} - ${getGridDisplayName(box.gridConfig)}`}
                                  data-button-id={`box-${tank.id}-${rack.id}-${box.id}`}
                                  {...getItemProps(visibleItems.findIndex(item => item.id === `box-${tank.id}-${rack.id}-${box.id}`))}
                                >
                                  <div className="button-content gap-0">
                                    <BoxIcon className="selector-icon" size={16} />
                                    <span className="box-text flex items-center gap-0">
                                      <span className="inline-block w-5 text-center">{box.id}</span>
                                      <span>({box.gridConfig.rows}×{box.gridConfig.cols})</span>
                                    </span>
                                  </div>
                                </button>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

import { useState, useRef, useEffect, useMemo } from 'react';

import { EQUIPMENT_DEFAULTS } from '@odysseus/shared-schemas';

import {
  useGridDragSelection,
  useGridKeyboardNavigation,
  useGridFontSizing
} from '@app/hooks/grid';
import { useStorageStore, getGridTotalPositions } from '@domains/storage';
import { useTubesByLocation } from '@domains/tubes/hooks';
import { useGridUiStore } from '@shared/stores/gridUiStore';
import { toPositionKey } from '@shared/types/grid';

import { ContextMenu } from '../../../../../shared/ui/primitives/shared/ContextMenu';

import { GridPosition } from './GridPosition';

import type { TubeData } from '@domains/tubes/types';
import type { PositionKey, GridControllerReturn } from '@shared/types/grid';

import '@shared/styles/legacy/colorIndicators.css';


/**
 * TubeGrid Props Interface
 */
interface TubeGridProps {
  tankId: string;
  rackId: string;
  boxId: string;
  selectedPositions: Set<PositionKey>;
  onSelectionChange: (positions: Set<PositionKey>) => void;
  _onEditTube?: (tubeId: string) => void;
  _onBatchEditTubes?: (tubeIds: string[]) => void;
  _onAddTubes?: (positions: PositionKey[]) => void;
  gridController: GridControllerReturn;
}

/**
 * TubeGrid - Configuration-driven grid component
 *
 * Supports individual box customization and dynamic grid sizes.
 */
export function TubeGrid({
  tankId,
  rackId,
  boxId,
  selectedPositions,
  onSelectionChange,
  _onEditTube,
  _onBatchEditTubes,
  _onAddTubes,
  gridController
}: TubeGridProps) {
  // Component manages its own selection via props, no need for store selection
  
  // Server state from React Query
  const {
    data: tubes = [],
    isLoading,
    error
  } = useTubesByLocation(tankId, rackId, boxId, {
    staleTime: 2 * 60 * 1000
  });
  const { getBox } = useStorageStore();
  // Auth store subscribed for reactive updates

  // Data loading is now handled by GridNavigationService
  // This component just displays the current data from the store
  
  // Use the specific tankId passed from parent
  const boxConfig = getBox(tankId, rackId, boxId);
  const gridConfig = boxConfig?.gridConfig ?? {
    rows: EQUIPMENT_DEFAULTS.GRID_ROWS,
    cols: EQUIPMENT_DEFAULTS.GRID_COLS,
    template: 'standard'
  };
  

  
  // Grid reference
  const gridRef = useRef<HTMLDivElement>(null);

  // Use grid controller passed from parent (single controller instance)
  const controller = gridController;

  // Clipboard access for Escape key clearing
  const setClipboard = useGridUiStore(state => state.setClipboard);

  // UI-related state only
  const [quickEditMode, setQuickEditMode] = useState<{ position: number; field: string } | null>(null);
  const [focusedPosition, setFocusedPosition] = useState<number>(1);

  // Custom hooks for separation of concerns
  const ctx = useMemo(() => ({ tankId, rackId, boxId }), [tankId, rackId, boxId]);

  // Drag selection hook (RAF-throttled rectangular selection)
  const dragSelection = useGridDragSelection({
    gridConfig,
    selectedPositions,
    onSelectionChange,
    ctx
  });

  // Keyboard navigation hook (arrow keys, shortcuts)
  const keyboardNav = useGridKeyboardNavigation({
    gridConfig,
    focusedPosition,
    setFocusedPosition,
    selectedPositions,
    onSelectionChange,
    controller: gridController,
    ctx,
    setClipboard
  });

  // Font sizing hook (responsive font calculation)
  const fontSizing = useGridFontSizing({
    gridRef,
    gridConfig
  });

  // Create dynamic grid based on configuration
  const positions = Array.from({ length: getGridTotalPositions(gridConfig) }, (_, i) => i + 1);
  
  // Tubes are already filtered by location from React Query hook
  const currentTubes = tubes;
  
  // Create lookup for quick access (memoized for performance)
  const tubesByPosition = useMemo(
    () => currentTubes.reduce((acc, tube) => {
      acc[tube.location.position] = tube;
      return acc;
    }, {} as Record<number, TubeData>),
    [currentTubes]
  );

  // Position click handler (delegates to grid controller)
  const handlePositionClick = (position: number, event: React.MouseEvent) => {
    setFocusedPosition(position); // Update keyboard focus on click
    controller.handlePositionClick(position, event, gridConfig.cols);
  };

  const handlePositionRightClick = (position: number, event: React.MouseEvent) => {
    event.preventDefault();

    // Add position to selection if not already selected
    if (!controller.isPositionSelected(position)) {
      controller.actions.select(position);
    }

    // Position menu relative to clicked tube
    const target = event.currentTarget as HTMLElement;
    const rect = target.getBoundingClientRect();

    controller.contextMenu.show(
      rect.left + rect.width / 2,
      rect.top + rect.height / 2
    );
  };

  // Focus grid on mount
  useEffect(() => {
    if (gridRef.current) {
      gridRef.current.focus();
    }
  }, []);

  // Sync animations on selection change (force reflow to restart animation)
  useEffect(() => {
    if (!gridRef.current) return;

    const selectedElements = gridRef.current.querySelectorAll('.selected');
    selectedElements.forEach((el) => {
      const element = el as HTMLElement;
      element.style.animation = 'none';
      element.offsetHeight; // Force reflow to restart animation
      element.style.animation = '';
    });
  }, [selectedPositions]);

  // Dynamic CSS grid based on configuration - Fixed for proper sizing
  const gridStyle = {
    display: 'grid',
    gridTemplateColumns: `repeat(${gridConfig.cols}, minmax(0, 1fr))`,
    gridAutoRows: '1fr',
    gap: 'var(--grid-gap, 4px)',
    width: 'min(100%, 80vh)', // Keeps grid inside viewport
    maxWidth: '100%',
    // Remove fixed height and aspectRatio - let children control their own aspect ratio
    placeItems: 'center'
  };

  // Loading state indicator
  if (isLoading) {
    return (
      <div className="w-full h-full flex flex-col items-center justify-center">
        <div className="flex items-center space-x-3 mb-4">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
          <span className="text-lg font-medium text-gray-700">Loading tubes...</span>
        </div>
        <div className="text-sm text-gray-500">
          {boxId ? `${tankId} › Rack ${rackId} › Box ${boxId}` : `${tankId} › Rack ${rackId}`}
        </div>
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className="w-full h-full flex flex-col items-center justify-center">
        <div className="text-red-600 mb-4">Failed to load tubes</div>
        <div className="text-sm text-gray-500">
          {boxId ? `${tankId} › Rack ${rackId} › Box ${boxId}` : `${tankId} › Rack ${rackId}`}
        </div>
      </div>
    );
  }

  return (
    <div className="w-full h-full flex flex-col">
      {/* Main Grid Container */}
      <div className="flex-1 flex items-center justify-center">
        <div
          ref={gridRef}
          className="tube-grid select-none focus:outline-none"
          style={{
            ...gridStyle,
            outline: 'none !important',
            outlineOffset: '0 !important',
            WebkitTapHighlightColor: 'transparent'
          }}
          role="grid"
          aria-label={`Tube storage grid for ${boxId ? `Box ${boxId}` : `Rack ${rackId}`}, ${positions.length} positions`}
          aria-multiselectable="true"
          tabIndex={0}
          onKeyDown={keyboardNav.handleGridKeyDown}
          onFocus={() => {
            // If no selection exists when grid receives focus, select position 1
            if (selectedPositions.size === 0) {
              const firstPositionKey = toPositionKey(ctx, 1);
              onSelectionChange(new Set([firstPositionKey]));
            }
          }}
        >
        {positions.map((position) => {
          const positionKey = toPositionKey(ctx, position);
          const tube = tubesByPosition[position];
          const selected = controller.isPositionSelected(position);
          const isCut = controller.clipboard.cutPositions.has(positionKey);
          const isCopied = controller.clipboard.copyPositions.has(positionKey);
          const inDragPreview = dragSelection.dragPreview.has(positionKey);
          const isKeyboardFocused = position === focusedPosition;

          return (
            <GridPosition
              key={position}
              position={position}
              tankId={tankId}
              rackId={rackId}
              boxId={boxId}
              tube={tube}
              selected={selected}
              isDragPreview={inDragPreview && !selected}
              isCut={isCut}
              isCopied={isCopied}
              _isKeyboardFocused={isKeyboardFocused}
              quickEditMode={quickEditMode}
              gridConfig={gridConfig}
              fontSize={fontSizing.fontSize}
              onPositionClick={handlePositionClick}
              onPositionRightClick={handlePositionRightClick}
              onPositionDoubleClick={controller.handlePositionDoubleClick}
              onMouseDown={dragSelection.handleMouseDown}
              onMouseMove={dragSelection.handleMouseMove}
              onQuickEditSave={() => {}}
              onQuickEditCancel={() => setQuickEditMode(null)}
            />
          );
        })}
        </div>
      </div>

      <ContextMenu
        isVisible={controller.contextMenu.isOpen}
        position={{ x: controller.contextMenu.x, y: controller.contextMenu.y }}
        selectedCount={selectedPositions.size}
        hasFilledSelection={controller.selection.hasFilledSelection}
        isMixedSelection={controller.selection.isMixed}
        clipboardCount={controller.clipboard.count}
        onClose={controller.contextMenu.hide}
        onOpen={controller.openModal}
        onDelete={controller.actions.delete}
        onCopy={controller.actions.copy}
        onCut={controller.actions.cut}
        onPaste={controller.actions.paste}
        canPaste={controller.clipboard.hasData}
      />
    </div>
  );
}

import React, { useMemo } from 'react';

import { formatConcentrationDisplay, formatResearcherDropdownDisplay, EQUIPMENT_DEFAULTS } from '@odysseus/shared-schemas';
import { MapPin } from 'lucide-react';

import { useFieldResolverQuery } from '@app/hooks';
import { useUserSettings } from '@domains/authentication';
import { useResearchersQuery } from '@domains/researchers';
import { useStorageStore, formatPositionRangesForBox } from '@domains/storage';
import { parsePositionKey } from '@shared/types/grid';
import { formatDateForDisplay } from '@shared/utils/dateFormatter';

import { useTubeStore } from '../../../stores/tubeStore';
import { FieldValue } from '../displays/FieldValue';
import { InfoSection } from '../displays/InfoSection';

import type { Researcher } from '@odysseus/shared-schemas';
import type { TubeData } from '@shared/types/tubeTypes';


interface TubeInfoPanelProps {
  selectedTubes: TubeData[];
}

export function TubeInfoPanel({ selectedTubes }: TubeInfoPanelProps) {
  // Use new React Query + Field Resolver hook
  const { getTubeValue, analyzeFieldConflicts, tubes } = useFieldResolverQuery();

  // Fetch researchers for foreign key resolution (researcherId → name)
  // Uses React Query for automatic caching - no extra network calls on re-renders
  const { data: researchers = [] } = useResearchersQuery();

  // Get user settings for position display preferences
  const { settings: userSettings } = useUserSettings();

  // Create researcher lookup map for O(1) resolution performance
  // Memoized to avoid recreation on every render
  const researcherMap = useMemo(() => {
    const map = new Map<string, Researcher>();
    researchers.forEach(researcher => {
      map.set(researcher.id, researcher);
    });
    return map;
  }, [researchers]);

  // Get current location and configuration
  const { currentTank, currentRack, currentBox, selectedPositions } = useTubeStore();
  const getCurrentTanks = useStorageStore(state => state.getCurrentTanks);
  const getBox = useStorageStore(state => state.getBox);
  const tanks = getCurrentTanks();
  const currentTankObj = tanks.find(tank => tank.id === currentTank);
  const currentRackObj = currentTankObj?.racks?.find(rack => rack.id === currentRack);
  const currentBoxObj = getBox(currentTank, currentRack, currentBox);

  // Get user-friendly names (not prefixed with "Tank" or "Rack")
  const tankName = currentTankObj?.name ?? 'Unknown Tank';
  const rackName = currentRackObj?.name ?? 'Unknown Rack';

  // Format position summary with flexible display
  // IMPORTANT: Must be before early return to comply with Rules of Hooks
  const positionSummary = useMemo(() => {
    if (selectedTubes.length === 0) return '';

    const firstTube = selectedTubes[0];
    const box = firstTube.location.boxId;
    const positions = selectedTubes.map(t => t.location.position);

    // Get grid config for position formatting
    const gridConfig = currentBoxObj?.gridConfig ?? {
      rows: EQUIPMENT_DEFAULTS.GRID_ROWS,
      cols: EQUIPMENT_DEFAULTS.GRID_COLS,
      template: 'standard' as const,
    };

    const formattedPositions = formatPositionRangesForBox(
      positions,
      firstTube.location.tankId,
      firstTube.location.rackId,
      firstTube.location.boxId,
      gridConfig,
      userSettings
    );

    const positionLabel = selectedTubes.length === 1 ? 'Position' : 'Positions';
    return `${rackName} • Box ${box} • ${positionLabel} ${formattedPositions}`;
  }, [selectedTubes, rackName, currentBoxObj, userSettings]);

  if (selectedTubes.length === 0) {
    // Show position info even when no tubes selected
    const positionCount = selectedPositions.size;

    // Extract position numbers from position keys
    const positions = Array.from(selectedPositions).map(key => {
      const parsed = parsePositionKey(key);
      return parsed.position;
    }).sort((a, b) => a - b);

    // Get grid config for position formatting
    const gridConfig = currentBoxObj?.gridConfig ?? {
      rows: EQUIPMENT_DEFAULTS.GRID_ROWS,
      cols: EQUIPMENT_DEFAULTS.GRID_COLS,
      template: 'standard' as const,
    };

    const formattedPositions = positions.length > 0
      ? formatPositionRangesForBox(positions, currentTank, currentRack, currentBox, gridConfig, userSettings)
      : '';

    const positionText = positionCount > 0
      ? `No tube${positionCount > 1 ? 's' : ''} at ${positionCount > 1 ? 'these' : 'this'} position${positionCount > 1 ? 's' : ''}`
      : 'Select a position to view tube information';

    return (
      <div style={{ minWidth: '280px' }}>
        <div className="space-y-1.5">
          {/* Position Display - Always Visible */}
          <div className="bg-gradient-to-br from-teal-50 to-cyan-50 rounded-lg px-1.5 py-2 border-2 border-teal-500 shadow-md text-center">
            <div className="font-bold text-teal-500 uppercase tracking-wider text-xs flex items-center justify-center gap-1">
              <MapPin className="w-3 h-3" />
              Position{positionCount > 1 ? 's' : ''}
            </div>
            <div className="font-semibold text-odysseus-dark mt-0.5 text-xs">
              {tankName}
            </div>
            <div className="font-bold text-odysseus-dark text-xs">
              {rackName} • Box {currentBox}
              {formattedPositions && (
                <span> • Position{positionCount > 1 ? 's' : ''} {formattedPositions}</span>
              )}
            </div>
          </div>

          {/* Placeholder Message */}
          <div className="text-center py-8">
            <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-gradient-to-br from-blue-100 to-indigo-100 flex items-center justify-center">
              <svg className="w-8 h-8 text-odysseus-muted" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
            </div>
            <p className="text-odysseus-muted font-medium text-xs">
              {positionText}
            </p>
          </div>
        </div>
      </div>
    );
  }

  // Get first tube for display (or common values if multiple selected)
  const firstTube = selectedTubes[0];

  // Helper to get common value or first tube's value
  const getDisplayValue = (path: string): string | number | null | undefined => {
    if (selectedTubes.length === 1) {
      return getTubeValue(firstTube, path);
    }
    // For multiple tubes, check if all have same value
    const analysis = analyzeFieldConflicts(selectedTubes, path);
    return analysis.hasConflict ? undefined : analysis.commonValue;
  };

  // Format values for display
  const cellType = getDisplayValue('sample.cellType');
  const donorInternalId = getDisplayValue('sample.donorInternalId');
  const donorSourceId = getDisplayValue('sample.donorSourceId');
  const cultureCondition = getDisplayValue('sample.cultureCondition');
  const lotNumber = getDisplayValue('sample.lotNumber');
  const mediaType = getDisplayValue('sample.media.type');
  const mediaSupplements = getDisplayValue('sample.media.supplements');
  const mediaSelection = getDisplayValue('sample.media.selection');
  const concentration = getDisplayValue('sample.concentration');
  const concentrationUnit = getDisplayValue('sample.concentrationUnit');
  const date = getDisplayValue('sample.date');
  const researcherId = getDisplayValue('researcherId');
  const createdByName = getDisplayValue('createdByName');
  const notes = getDisplayValue('sample.notes');

  // Format complex values
  const formattedConcentration = concentration !== undefined
    ? formatConcentrationDisplay(concentration as number, concentrationUnit as 'c/v' | 'c/mL' | undefined)
    : undefined;
  const formattedDate = date ? formatDateForDisplay(date as string | Date) : undefined;

  // Researcher display with historical name tracking
  const researcherDisplay = (() => {
    const currentName = researcherId && researcherMap.has(researcherId as string)
      ? formatResearcherDropdownDisplay(researcherMap.get(researcherId as string)!)
      : undefined;

    const historicalName = createdByName as string | undefined;

    // No researcher info at all
    if (!historicalName && !currentName) return undefined;

    // Only have historical name (researcher deleted or unlinked)
    if (!currentName) return historicalName;

    // Only have current name (old tube before Person entity implementation)
    if (!historicalName) return currentName;

    // Names match - no change
    if (historicalName === currentName) return currentName;

    // Names differ - show historical with current in parentheses
    return `${historicalName} (now ${currentName})`;
  })();

  // Detect if any fields have conflicts across selected tubes
  const hasConflicts = tubes.hasAnyConflicts(selectedTubes, [
    'sample.cellType',
    'sample.donorInternalId',
    'sample.donorSourceId',
    'sample.cultureCondition',
    'sample.lotNumber',
    'sample.media.type',
    'sample.media.supplements',
    'sample.media.selection',
    'sample.concentration',
    'sample.concentrationUnit',
    'sample.date',
    'researcherId',
    'sample.notes'
  ]);

  return (
    <div style={{ minWidth: '280px' }}>
      <div className="space-y-1.5">
        {/* Position - Compact */}
        <div className="bg-gradient-to-br from-teal-50 to-cyan-50 rounded-lg px-1.5 py-2 border-2 border-teal-500 shadow-md text-center">
          <div className="font-bold text-teal-500 uppercase tracking-wider text-xs flex items-center justify-center gap-1">
            <MapPin className="w-3 h-3" />
            Position{selectedTubes.length > 1 ? 's' : ''}
          </div>
          <div className="font-semibold text-odysseus-dark mt-0.5 text-xs">
            {tankName}
          </div>
          <div className="font-bold text-odysseus-dark text-xs">
            {positionSummary}
          </div>
          {selectedTubes.length > 1 && (
            <div className="text-odysseus-muted mt-0.5 text-xs">
              {selectedTubes.length} tube{selectedTubes.length > 1 ? 's' : ''} selected
              {hasConflicts && <span className="text-warning-text ml-1">• Some fields differ</span>}
            </div>
          )}
        </div>

        {/* Donor Information */}
        <InfoSection title="DONOR INFORMATION" color="primary">
          <div className="mt-2 border-l-2 border-gray-300 pl-2">
            <FieldValue label="Cell Type" value={cellType} />
          </div>
          <div className="flex flex-col gap-0.5 mt-3 border-l-2 border-gray-300 pl-2">
            <FieldValue label="Internal ID" value={donorInternalId} />
            <FieldValue label="Source ID" value={donorSourceId} />
          </div>
        </InfoSection>

        {/* Sample Information */}
        <InfoSection title="SAMPLE INFORMATION" color="secondary">
          {/* Group 1: Culture Condition + Lot # */}
          <div className="flex flex-col gap-0.5 mt-2 border-l-2 border-gray-300 pl-2">
            <FieldValue label="Culture Condition" value={cultureCondition} />
            <FieldValue label="Lot #" value={lotNumber} />
          </div>

          {/* Group 2: Media + Supplements + Selection */}
          <div className="flex flex-col gap-0.5 mt-3 border-l-2 border-gray-300 pl-2">
            <FieldValue label="Media" value={mediaType} />
            <FieldValue label="Supplements" value={mediaSupplements} />
            <FieldValue label="Selection" value={mediaSelection} />
          </div>

          {/* Group 3: Concentration + Date + Researcher */}
          <div className="flex flex-col gap-0.5 mt-3 border-l-2 border-gray-300 pl-2">
            <FieldValue label="Concentration" value={formattedConcentration} />
            <FieldValue label="Date" value={formattedDate} />
            <FieldValue label="Researcher" value={researcherDisplay} />
          </div>
        </InfoSection>

        {/* Notes */}
        {notes && (
          <InfoSection title="NOTES" color="gray">
            <div className="text-odysseus-secondary text-xs leading-tight pr-4">
              {notes}
            </div>
          </InfoSection>
        )}
      </div>
    </div>
  );
}

/**
 * BaseModal - Modal Wrapper with Focus Trapping
 *
 * Single source of truth for modal visual structure across tube modals.
 * Handles presentation and accessibility (focus trapping, WCAG 2.1 compliance).
 *
 * Pattern: Composition over configuration
 * - Visual consistency without rigid constraints
 * - Built-in focus trap for keyboard accessibility
 * - Each modal retains full control over behavior
 *
 * @example
 * <BaseModal
 *   icon={<Pencil />}
 *   title="Edit Tube"
 *   onClose={onClose}
 *   dataAttribute="data-tube-modal"
 * >
 *   <form>...</form>
 * </BaseModal>
 */

import React from 'react';

import { X } from 'lucide-react';

import { useFocusTrap } from '@shared/hooks/useFocusTrap';

export interface BaseModalProps {
  /** Modal title text */
  title: string;

  /** Icon component to display before title */
  icon: React.ReactNode;

  /** Close handler */
  onClose: () => void;

  /** Modal content */
  children: React.ReactNode;

  /** Optional data attribute for testing/tracking (e.g., "data-tube-modal") */
  dataAttribute?: string;

  /** Optional additional classes for container */
  className?: string;

  /** Optional mode identifier (e.g., "edit", "create") */
  mode?: string;
}

/**
 * BaseModal Component
 *
 * Provides consistent visual structure and accessibility:
 * - Backdrop with blur
 * - Header with icon, title, and close button
 * - Content area with controlled padding
 * - Standardized animations and shadows
 * - Built-in focus trapping (WCAG 2.1 compliant)
 */
export function BaseModal({
  title,
  icon,
  onClose,
  children,
  dataAttribute,
  className = '',
  mode
}: BaseModalProps) {
  // Focus trap for keyboard accessibility
  // Automatically restores focus to trigger element when modal closes
  // autoFocusFirstInput skips buttons and focuses first input/textarea/select
  const trapRef = useFocusTrap({
    isOpen: true,
    restoreFocus: true,
    autoFocusFirstInput: true
  });

  // Build data attributes object
  const dataAttrs: Record<string, string> = {};
  if (dataAttribute) {
    dataAttrs[dataAttribute] = '';
  }
  if (mode) {
    dataAttrs['data-mode'] = mode;
  }

  return (
    <>
      {/* Backdrop - Static, no animation, GPU accelerated */}
      <div
        className="fixed inset-0 bg-black/45 backdrop-blur-[2px] z-50"
        style={{ willChange: 'backdrop-filter' }}
      />

      {/* Modal Content - Animated separately */}
      <div className="fixed inset-0 flex items-center justify-center z-50 pointer-events-none">
        <div
          ref={trapRef}
          {...dataAttrs}
          className={`bg-odysseus-surface rounded-2xl w-full max-w-4xl mx-4 max-h-[90vh] overflow-y-auto shadow-2xl shadow-blue-500/20 border border-odysseus-border animate-zoom-in-98 pointer-events-auto ${className}`}
        >
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-3 bg-gradient-to-r from-edit-hover via-edit-bg to-edit-hover">
          <div className="flex items-center space-x-3">
            <div className="p-1.5">
              {icon}
            </div>
            <h2 className="text-xl font-bold text-white">
              {title}
            </h2>
          </div>
          <button
            onClick={onClose}
            className="btn-header-menu p-2 hover:bg-edit-hover text-white/80 hover:text-white"
            aria-label="Close modal"
          >
            <X size={24} />
          </button>
        </div>

        {/* Content */}
        <div className="px-6 py-3">
          {children}
        </div>
        </div>
      </div>
    </>
  );
}

import { useState, useMemo , useEffect } from 'react';

import { type CreateTubeFormInput, formatConcentrationDisplay, EQUIPMENT_DEFAULTS } from '@odysseus/shared-schemas';
import { AlertCircle, XCircle, RefreshCw, MapPin, Edit, Save, Trash2 } from 'lucide-react';

import { useFieldResolverQuery } from '@app/hooks/useFieldResolverQuery';
import { TUBE_FIELD_PATHS } from '@app/hooks/useSimpleFieldResolver';
import { useModalStore } from '@app/stores/modalStore';
import { useUserSettings } from '@domains/authentication';
import { useActiveResearchersQuery } from '@domains/researchers';
import { useStorageStore, formatPositionRangesForBox } from '@domains/storage';
import { useCreateTubeForm } from '@domains/tubes/hooks/useTubeForm';
import { useBulkUpdateTubesMutation, useBulkDeleteTubesMutation } from '@domains/tubes/hooks/useTubeMutations';
import { useTubes } from '@domains/tubes/hooks/useTubeQueries';
import { useModalKeyboardNav } from '@shared/hooks/keyboard/useModalKeyboardNav';
import { notifications } from '@shared/utils';
import { formatDateForInput } from '@shared/utils/dateFormatter';

import { TubeForm } from '../forms/TubeForm';

import { BaseModal } from './BaseModal';
import { BulkProgressModal } from './BulkProgressModal';
import { DeleteConfirmDialog } from './DeleteConfirmDialog';

import type { FieldConflictAnalysis } from '@app/hooks/useSimpleFieldResolver';
import type { BulkUpdateProgress, BulkUpdateResult } from '@shared/types/bulkOperations';
import type { TubeData } from '@shared/types/tubeTypes';



export interface BatchTubeEditorModalProps {
  tubeIds: string[];     // Accept IDs, fetch own data
  tubes?: TubeData[];     // Legacy support - will be removed
  onClose: () => void;
}

/**
 * Analysis object structure for all batch-editable fields
 *
 * Media fields use dot-notation string keys ('media.type')
 * and must be accessed with bracket notation: analysis['media.type']
 */
interface BatchEditConflictAnalysis {
  cellType: FieldConflictAnalysis<string>;
  donorInternalId: FieldConflictAnalysis<string>;
  donorSourceId: FieldConflictAnalysis<string>;
  concentration: FieldConflictAnalysis<number>;
  concentrationUnit: FieldConflictAnalysis<string>;
  date: FieldConflictAnalysis<string>;
  'media.type': FieldConflictAnalysis<string>;
  'media.supplements': FieldConflictAnalysis<string>;
  'media.selection': FieldConflictAnalysis<string>;
  cultureCondition: FieldConflictAnalysis<string>;
  lotNumber: FieldConflictAnalysis<string>;
  notes: FieldConflictAnalysis<string>;
  researcherId: FieldConflictAnalysis<string>;
}

/**
 * Convert TubeData to CreateTubeFormInput for form initialization
 * Only converts editable fields (sample + researcherId, no location)
 * Returns form INPUT type (pre-transformation)
 */
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function convertTubeDataToFormData(tubeData: TubeData): Partial<CreateTubeFormInput> {
  return {
    sample: {
      // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Cascading fallback chain, empty string should trigger next option
      cellType: tubeData.sample.cellType || '',
      donorInternalId: tubeData.sample.donorInternalId ?? '',
      // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Cascading fallback chain, empty string should trigger next option
      donorSourceId: tubeData.sample.donorSourceId || '',
      concentration: formatConcentrationDisplay(tubeData.sample.concentration) || undefined,
      concentrationUnit: tubeData.sample.concentrationUnit,
      date: tubeData.sample.date ?? '',
      media: tubeData.sample.media ?? { type: '', supplements: '', selection: '' },
      cultureCondition: tubeData.sample.cultureCondition ?? '',
      lotNumber: tubeData.sample.lotNumber ?? '',
      notes: tubeData.sample.notes ?? ''
    },
    researcherId: tubeData.researcherId
  };
}

/**
 * Convert TubeFormData to UpdateTubeRequest for API updates
 * Uses the standard transformToUpdateRequest for consistent PATCH semantics
 * Note: This local function was removed - now using centralized transform
 */

export default function BatchTubeEditorModal({ tubeIds, tubes: legacyTubes, onClose }: BatchTubeEditorModalProps) {
  const { data: researchers = [] } = useActiveResearchersQuery();
  const { analyzeFieldConflicts } = useFieldResolverQuery();
  const modalService = useModalStore();

  // Fetch tubes by IDs, with legacy support during transition
  const { data: allTubes = [] } = useTubes();
  // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Cascading fallback chain, empty string should trigger next option
  const tubes = legacyTubes || allTubes.filter(tube => tubeIds.includes(tube.id));

  // Focus return management - restore focus when modal unmounts
  // Skip restoration for batch operations to preserve multi-selection
  // IMPORTANT: Capture preserveSelection flag on mount to avoid race condition with hideTubeEditorModal
  const [shouldPreserveSelection] = useState(modalService.tubeEditorModal.preserveSelection);

  useEffect(() => {
    return () => {
      // Don't restore focus if preserveSelection is enabled (batch operations)
      // This prevents focus from returning to a specific position and clearing selection
      if (shouldPreserveSelection) {
        return;
      }

      const previousFocus = modalService.tubeEditorModal.previousFocusElement;
      if (previousFocus && typeof previousFocus.focus === 'function') {
        setTimeout(() => previousFocus.focus(), 0);
      }
    };
  }, [shouldPreserveSelection, modalService.tubeEditorModal.previousFocusElement]);

  // Unified keyboard navigation: Escape = close
  // (Enter naturally submits form)
  useModalKeyboardNav({
    onEscape: onClose,
    enabled: true
  });

  // Analyze all editable fields for conflicts across selected tubes
  const conflictAnalysis = useMemo(() => {
    const analysis = {
      cellType: analyzeFieldConflicts(tubes, TUBE_FIELD_PATHS.cellType),
      donorInternalId: analyzeFieldConflicts(tubes, TUBE_FIELD_PATHS.donorInternalId),
      donorSourceId: analyzeFieldConflicts(tubes, TUBE_FIELD_PATHS.donorSourceId),
      concentration: analyzeFieldConflicts(tubes, TUBE_FIELD_PATHS.concentration),
      concentrationUnit: analyzeFieldConflicts(tubes, TUBE_FIELD_PATHS.concentrationUnit),
      date: analyzeFieldConflicts(tubes, TUBE_FIELD_PATHS.date),
      'media.type': analyzeFieldConflicts(tubes, 'sample.media.type'),
      'media.supplements': analyzeFieldConflicts(tubes, 'sample.media.supplements'),
      'media.selection': analyzeFieldConflicts(tubes, 'sample.media.selection'),
      cultureCondition: analyzeFieldConflicts(tubes, TUBE_FIELD_PATHS.cultureCondition),
      lotNumber: analyzeFieldConflicts(tubes, TUBE_FIELD_PATHS.lotNumber),
      notes: analyzeFieldConflicts(tubes, TUBE_FIELD_PATHS.notes),
      researcherId: analyzeFieldConflicts(tubes, TUBE_FIELD_PATHS.researcherId)
    } satisfies BatchEditConflictAnalysis;

    // Extract conflicting fields
    const conflictingFields = Object.entries(analysis)
      .filter(([_, value]) => value.state === 'conflict')
      .map(([key, _]) => key);

    return { analysis, conflictingFields };
  }, [tubes, analyzeFieldConflicts]);

  // Build initial form data: use common/mixed values, clear only conflicting fields
  const resolvedData = useMemo(() => {
    const { analysis } = conflictAnalysis;

    return {
      sample: {
        // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing -- Empty cellType is validation failure, show empty for user to fill
        cellType: analysis.cellType.state !== 'conflict' ? analysis.cellType.commonValue || '' : '',
        donorInternalId: analysis.donorInternalId.state !== 'conflict' ? analysis.donorInternalId.commonValue ?? '' : '',
        donorSourceId: analysis.donorSourceId.state !== 'conflict' ? analysis.donorSourceId.commonValue || '' : '',
        concentration: analysis.concentration.state !== 'conflict'
          ? (analysis.concentration.commonValue ? formatConcentrationDisplay(analysis.concentration.commonValue) : undefined)
          : undefined,
        concentrationUnit: analysis.concentrationUnit.state !== 'conflict' ? analysis.concentrationUnit.commonValue : undefined,
        date: analysis.date.state !== 'conflict'
          ? (analysis.date.commonValue ? formatDateForInput(analysis.date.commonValue) : '')
          : '',
        media: {
          type: analysis['media.type'].state !== 'conflict' ? analysis['media.type'].commonValue ?? '' : '',
          supplements: analysis['media.supplements'].state !== 'conflict' ? analysis['media.supplements'].commonValue ?? '' : '',
          selection: analysis['media.selection'].state !== 'conflict' ? analysis['media.selection'].commonValue || '' : ''
        },
        cultureCondition: analysis.cultureCondition.state !== 'conflict' ? analysis.cultureCondition.commonValue ?? '' : '',
        lotNumber: analysis.lotNumber.state !== 'conflict' ? analysis.lotNumber.commonValue ?? '' : '',
        notes: analysis.notes.state !== 'conflict' ? analysis.notes.commonValue || '' : ''
      },
      researcherId: analysis.researcherId.state !== 'conflict' ? analysis.researcherId.commonValue || '' : ''
    };
  }, [conflictAnalysis]);

  const conflicts = conflictAnalysis.conflictingFields;

  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [showProgress, setShowProgress] = useState(false);
  const [progress, setProgress] = useState<BulkUpdateProgress>({
    current: 0,
    total: 0,
    completed: 0,
    phase: 'preparing',
    errors: []
  });
  const [result, setResult] = useState<BulkUpdateResult | null>(null);
  
  // Only using form for field editing UI, not the submit handler
  // Actual submission uses bulk mutations
  const { form, isSubmitting: formSubmitting } = useCreateTubeForm({
    initialData: resolvedData
  });

  // CRITICAL: Subscribe to formState by destructuring in render phase (React Hook Form v7 Proxy pattern)
  // Without this, component won't re-render when errors/dirtyFields change
  const { errors, dirtyFields } = form.formState;

  // Reset form when resolved data changes to update dirty tracking baseline
  // This ensures defaultValues stay in sync with current tube selection
  // IMPORTANT: Do NOT include `form` in deps - it changes every render and causes infinite reset loop
  useEffect(() => {
    form.reset(resolvedData);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [resolvedData]);

  // Bulk operations
  const bulkUpdateMutation = useBulkUpdateTubesMutation();
  const bulkDeleteMutation = useBulkDeleteTubesMutation();
  const isSubmitting = formSubmitting || bulkUpdateMutation.isPending || bulkDeleteMutation.isPending;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setShowProgress(true);
    setResult(null);

    try {
      // Get form data
      const formData = form.getValues();

      // Send all form data (simplicity > micro-optimization)
      const bulkResult = await bulkUpdateMutation.mutateAsync({
        tubeIds,
        // Type assertion safe here: form data validated by Zod, backend re-validates with same schemas
        // TODO: Align mutation types with CreateTubeFormInput to remove type assertion
        updates: formData as any,
        onProgress: (progress) => {
          setProgress({
            current: progress.completed,
            total: progress.total,
            completed: progress.completed,
            currentTubeId: progress.currentId,
            phase: 'updating',
            errors: []
          });
        }
      });

      setResult(bulkResult);

      // Show final result
      if (bulkResult.success) {
        notifications.update(`Updated ${tubeIds.length} tubes successfully`); // Minty Frost
        setShowProgress(false);
        onClose();
      } else {
        notifications.error('Some tubes failed to update');
      }
    } catch (error) {
      console.error('Batch update error:', error);
      notifications.error('Failed to update tubes');
      setShowProgress(false);
    }
  };

  const handleProgressClose = () => {
    setShowProgress(false);
    // Errors are already shown in the UI via result.errors
  };

  const handleRetryFailures = async () => {
    if (!result || result.success) return;

    const failedTubeIds = result.errors
      .map(error => error.itemId); // Note: retryable logic needs to be implemented if needed

    if (failedTubeIds.length === 0) {
      notifications.info('No retryable failures found');
      return;
    }

    // Retry only the failed tubes
    setShowProgress(true);
    setResult(null);

    try {
      // Get form data for retry
      const formData = form.getValues();

      // Send all form data (simplicity > micro-optimization)
      const retryResult = await bulkUpdateMutation.mutateAsync({
        tubeIds: failedTubeIds,
        // Type assertion safe here: form data validated by Zod, backend re-validates with same schemas
        // TODO: Align mutation types with CreateTubeFormInput to remove type assertion
        updates: formData as any,
        onProgress: (progress) => {
          setProgress({
            current: progress.completed,
            total: progress.total,
            completed: progress.completed,
            currentTubeId: progress.currentId,
            phase: 'updating',
            errors: []
          });
        }
      });
      setResult(retryResult);

      if (retryResult.success) {
        notifications.update(`Retry successful: Updated ${retryResult.successCount} tubes`); // Minty Frost
        setShowProgress(false);
        onClose();
      } else {
        notifications.warning(`⚠️ Retry completed: ${retryResult.successCount}/${retryResult.totalProcessed} successful`);
      }
    } catch (error) {
      console.error('Retry error:', error);
      notifications.error('Retry failed');
      setShowProgress(false);
    }
  };

  const handleBatchDelete = async () => {
    try {
      const deleteResult = await bulkDeleteMutation.mutateAsync({
        tubeIds,
        onProgress: (progress) => {
          setProgress({
            current: progress.completed,
            total: progress.total,
            completed: progress.completed,
            currentTubeId: progress.currentId,
            phase: 'updating',
            errors: []
          });
        }
      });

      if (deleteResult.success) {
        notifications.delete(`Deleted ${deleteResult.successCount} tubes successfully`);
        onClose();
      } else {
        notifications.error(`Deleted ${deleteResult.successCount} of ${deleteResult.totalProcessed} tubes`);
      }
    } catch (error) {
      console.error('Batch delete error:', error);
      notifications.error('Failed to delete tubes');
    } finally {
      setShowDeleteConfirm(false);
    }
  };

  const tankId = tubes[0]?.location.tankId || "";
  const rackId = tubes[0]?.location.rackId || "";
  const boxId = tubes[0]?.location.boxId || "";

  // Filter errors to only show errors for dirty fields
  // Special handling for cross-field validation (e.g., concentration + unit refinement)
  // NOTE: No useMemo - recalculates on every render, but this is fine (cheap object traversal)
  // This ensures filtered errors update immediately when validation runs
  const RELATED_FIELDS: Record<string, string[]> = {
    'concentration': ['concentrationUnit'],
    'concentrationUnit': ['concentration']
  };

  const isRelatedFieldDirty = (fieldKey: string, parentDirtyNode: any): boolean => {
    const relatedFields = RELATED_FIELDS[fieldKey] || [];
    return relatedFields.some(relatedKey => parentDirtyNode?.[relatedKey] === true);
  };

  const filterNode = (errorNode: any, dirtyNode: any, path = ''): any => {
    if (!errorNode || typeof errorNode !== 'object') return undefined;

    const filtered: any = {};
    let hasAnyErrors = false;

    for (const key in errorNode) {
      const errorValue = errorNode[key];
      const dirtyValue = dirtyNode?.[key];
      const currentPath = path ? `${path}.${key}` : key;

      // If this is an error leaf (has 'message' property)
      if (errorValue && typeof errorValue === 'object' && 'message' in errorValue) {
        // Include if field is dirty OR a related field is dirty
        const isRelated = isRelatedFieldDirty(key, dirtyNode);
        if (dirtyValue === true || isRelated) {
          filtered[key] = errorValue;
          hasAnyErrors = true;
        }
      }
      // If this is a nested object, recurse
      else if (typeof errorValue === 'object') {
        const nestedFiltered = filterNode(errorValue, dirtyValue, currentPath);
        if (nestedFiltered && Object.keys(nestedFiltered).length > 0) {
          filtered[key] = nestedFiltered;
          hasAnyErrors = true;
        }
      }
    }

    return hasAnyErrors ? filtered : undefined;
  };

  const filteredErrors = filterNode(errors, dirtyFields) || {};

  // Check if there are any relevant errors (for button state)
  const hasRelevantErrors = Object.keys(filteredErrors).length > 0;

  // Get user-friendly location names
  const getCurrentTanks = useStorageStore(state => state.getCurrentTanks);
  const getBox = useStorageStore(state => state.getBox);
  const tanks = getCurrentTanks();
  const currentTankObj = tanks.find(tank => tank.id === tankId);
  const currentRackObj = currentTankObj?.racks?.find(rack => rack.id === rackId);
  const tankName = currentTankObj?.name ?? 'Unknown Tank';
  const rackName = currentRackObj?.name || 'Unknown Rack';

  // Get user settings for position display preferences
  const { settings: userSettings } = useUserSettings();

  // Format position ranges for display with flexible formatting
  const boxObj = getBox(tankId, rackId, boxId);
  const gridConfig = boxObj?.gridConfig || {
    rows: EQUIPMENT_DEFAULTS.GRID_ROWS,
    cols: EQUIPMENT_DEFAULTS.GRID_COLS,
    template: 'standard' as const,
  };
  const positionRanges = formatPositionRangesForBox(
    tubes.map(t => t.location.position),
    tankId,
    rackId,
    boxId,
    gridConfig,
    userSettings
  );

  return (
    <>
    <BaseModal
      title={`Edit ${tubes.length} Tubes`}
      icon={<Edit className="w-5 h-5 text-white" />}
      onClose={onClose}
      dataAttribute="data-batch-edit-modal"
    >

        {conflicts.length > 0 && (
          <div className="alert-warning mb-3">
            <div className="flex items-center space-x-2 alert-warning-heading">
              <AlertCircle size={18} />
              <span>Conflicting Information Detected</span>
            </div>
            <p className="alert-warning-text mt-1">
              These fields differ across tubes and have been cleared.
            </p>
            <div className="mt-2 flex flex-wrap gap-2">
              {conflicts.map(field => {
                // Format field names for display
                const displayName = field
                  .replace('media.', 'Media ')
                  .replace(/([A-Z])/g, ' $1')
                  .replace(/^./, str => str.toUpperCase())
                  .replace(/ Id/g, ' ID')
                  .trim();

                return (
                  <span key={field} className="alert-warning-accent">
                    {displayName}
                  </span>
                );
              })}
            </div>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Position display - matches other modals */}
          <div className="flex items-center gap-2 px-3 py-2 bg-gradient-to-br from-teal-50 to-cyan-50 border-2 border-teal-500 rounded-lg shadow-md">
            <MapPin className="w-4 h-4 text-teal-500 flex-shrink-0" />
            <div className="flex items-center gap-2 text-sm font-medium text-odysseus-dark">
              <span className="font-semibold">{tankName}</span>
              <span className="text-odysseus-muted">•</span>
              <span>{rackName}</span>
              <span className="text-odysseus-muted">•</span>
              <span>Box {boxId}</span>
              <span className="text-odysseus-muted">•</span>
              <span className="font-semibold">Positions {positionRanges}</span>
            </div>
          </div>

          <TubeForm
            control={form.control as any}
            register={form.register as any}
            errors={filteredErrors as any}
            trigger={form.trigger as any}
            researchers={researchers}
            isLoading={isSubmitting}
          />

          <div className="flex justify-end space-x-4 pt-4 border-t border-odysseus-border">
            <button
              type="button"
              onClick={onClose}
              className="btn btn-secondary px-6"
              disabled={isSubmitting}
            >
              Cancel
            </button>
            <button
              type="button"
              className="btn btn-danger px-6"
              disabled={isSubmitting}
              onClick={() => setShowDeleteConfirm(true)}
            >
              <Trash2 className="w-4 h-4 mr-2" />
              Delete {tubes.length} Tubes
            </button>
            <button
              type="submit"
              className={`btn px-8 ${!hasRelevantErrors ? 'btn-primary' : 'btn-secondary'}`}
              disabled={isSubmitting || hasRelevantErrors}
            >
              {isSubmitting ? (
                <div className="flex items-center space-x-2">
                  <div className="spinner w-4 h-4"></div>
                  <span>Updating...</span>
                </div>
              ) : (
                <>
                  <Save className="w-4 h-4 mr-2" />
                  Update {tubes.length} Tubes
                </>
              )}
            </button>
          </div>
        </form>

        {/* Results Summary */}
        {result && !result.success && result.errors.length > 0 && !showProgress && (
          <div className="mt-6 p-4 bg-red-50 border border-red-200 rounded-lg">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center space-x-2">
                <XCircle size={20} className="text-red-500" />
                <span className="font-semibold text-red-800">
                  Update Issues ({result.errors.length})
                </span>
              </div>
              {result.errors.length > 0 && (
                <button
                  onClick={handleRetryFailures}
                  className="btn btn-sm btn-secondary flex items-center space-x-1"
                  disabled={isSubmitting}
                >
                  <RefreshCw size={14} />
                  <span>Retry</span>
                </button>
              )}
            </div>
            
            <div className="max-h-32 overflow-y-auto space-y-2">
              {result.errors.slice(0, 5).map((error, index) => (
                <div key={index} className="text-sm text-red-700 flex items-start space-x-2">
                  <div className="font-mono text-xs bg-red-100 px-2 py-1 rounded">
                    {error.itemId}
                  </div>
                  <div className="flex-1">
                    {error.error}
                    {error.field && (
                      <span className="ml-2 text-xs text-red-600">({error.field})</span>
                    )}
                  </div>
                </div>
              ))}
              {result.errors.length > 5 && (
                <div className="text-sm text-red-600 italic">
                  +{result.errors.length - 5} more errors...
                </div>
              )}
            </div>

            {result.duration && (
              <div className="mt-2 text-xs text-gray-600">
                Completed in {(result.duration / 1000).toFixed(1)}s
              </div>
            )}
          </div>
        )}
    </BaseModal>

    {/* Progress Modal */}
    <BulkProgressModal
      isOpen={showProgress}
      progress={progress}
      onClose={handleProgressClose}
      canClose={!isSubmitting && result !== null}
    />

    <DeleteConfirmDialog
      isOpen={showDeleteConfirm}
      title="Delete All Tubes"
      message={`Are you sure you want to delete all ${tubes.length} tubes? This action cannot be undone and will permanently remove all selected tubes from your inventory.`}
      confirmText={`Delete All ${tubes.length}`}
      onConfirm={handleBatchDelete}
      onCancel={() => setShowDeleteConfirm(false)}
      isLoading={isSubmitting}
    />
    </>
  );
}

// Named export for backward compatibility
export { BatchTubeEditorModal };

import { CheckCircle, XCircle, AlertCircle, Loader2 } from 'lucide-react';

import type { BulkUpdateProgress } from '@shared/types/bulkOperations';

interface BulkProgressModalProps {
  isOpen: boolean;
  progress: BulkUpdateProgress;
  onClose: () => void;
  canClose: boolean;
}

export function BulkProgressModal({ isOpen, progress, onClose, canClose }: BulkProgressModalProps) {
  if (!isOpen) return null;

  const getPhaseLabel = (phase: BulkUpdateProgress['phase']) => {
    switch (phase) {
      case 'preparing': return 'Preparing updates...';
      case 'validating': return 'Validating data...';
      case 'updating': return 'Updating tubes...';
      case 'completing': return 'Finalizing...';
      default: return 'Processing...';
    }
  };

  const getPhaseIcon = (phase: BulkUpdateProgress['phase']) => {
    switch (phase) {
      case 'preparing':
      case 'validating':
        return <Loader2 className="w-5 h-5 animate-spin text-blue-500" />;
      case 'updating':
        return <Loader2 className="w-5 h-5 animate-spin text-odysseus-primary" />;
      case 'completing':
        return <CheckCircle className="w-5 h-5 text-green-500" />;
      default:
        return <Loader2 className="w-5 h-5 animate-spin text-gray-500" />;
    }
  };

  const progressPercentage = progress.total > 0 ? (progress.current / progress.total) * 100 : 0;
  const hasErrors = progress.errors.length > 0;

  return (
    <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50">
      <div className="bg-odysseus-surface rounded-2xl p-6 w-full max-w-md mx-4 shadow-2xl border border-odysseus-border">
        <div className="text-center mb-6">
          <div className="mb-4">
            {getPhaseIcon(progress.phase)}
          </div>
          
          <h3 className="text-lg font-semibold text-odysseus-dark mb-2">
            {getPhaseLabel(progress.phase)}
          </h3>
          
          <div className="text-sm text-odysseus-muted">
            {progress.current} of {progress.total} tubes
            {progress.currentTubeId && (
              <div className="text-xs mt-1 text-gray-500">
                Processing: {progress.currentTubeId}
              </div>
            )}
          </div>
        </div>

        {/* Progress Bar */}
        <div className="mb-6">
          <div className="w-full bg-gray-200 rounded-full h-3 mb-2">
            <div 
              className="bg-odysseus-primary h-3 rounded-full transition-all duration-300 ease-out"
              style={{ width: `${progressPercentage}%` }}
            />
          </div>
          <div className="text-center text-sm text-odysseus-muted">
            {Math.round(progressPercentage)}% complete
          </div>
        </div>

        {/* Error Summary */}
        {hasErrors && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg">
            <div className="flex items-center space-x-2 text-red-800 mb-2">
              <AlertCircle size={16} />
              <span className="font-medium text-sm">
                {progress.errors.length} issue{progress.errors.length > 1 ? 's' : ''} encountered
              </span>
            </div>
            <div className="max-h-20 overflow-y-auto text-xs text-red-700 space-y-1">
              {progress.errors.slice(0, 3).map((error, index) => (
                <div key={index} className="flex items-start space-x-1">
                  <XCircle size={12} className="mt-0.5 flex-shrink-0" />
                  <span>
                    {error.tubeId}: {error.error}
                  </span>
                </div>
              ))}
              {progress.errors.length > 3 && (
                <div className="text-red-600 italic">
                  +{progress.errors.length - 3} more errors...
                </div>
              )}
            </div>
          </div>
        )}

        {/* Close button (only shown when operation is complete) */}
        {canClose && (
          <div className="text-center">
            <button
              onClick={onClose}
              className="btn btn-primary px-6"
            >
              {hasErrors ? 'View Results' : 'Complete'}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

import { useEffect } from 'react';

import { X, AlertTriangle } from 'lucide-react';

import { useModalStore } from '@app/stores/modalStore';
import { useModalFocusTrap } from '@shared/hooks/keyboard';
import { useModalKeyboardNav } from '@shared/hooks/keyboard/useModalKeyboardNav';

interface DeleteConfirmDialogProps {
  isOpen: boolean;
  title: string;
  message: string;
  confirmText?: string;
  onConfirm: () => void;
  onCancel: () => void;
  isLoading?: boolean;
}

export function DeleteConfirmDialog({
  isOpen,
  title,
  message,
  confirmText = "Delete",
  onConfirm,
  onCancel,
  isLoading = false
}: DeleteConfirmDialogProps) {
  const modalService = useModalStore();

  // Focus return management - restore focus when modal unmounts
  useEffect(() => {
    if (!isOpen) return;

    return () => {
      const previousFocus = modalService.deleteConfirm.previousFocusElement;
      if (previousFocus && typeof previousFocus.focus === 'function') {
        setTimeout(() => previousFocus.focus(), 0);
      }
    };
  }, [isOpen, modalService.deleteConfirm.previousFocusElement]);

  // Unified keyboard navigation: Escape = cancel
  // Enter naturally triggers focused button (delete button)
  useModalKeyboardNav({
    onEscape: () => {
      if (!isLoading) onCancel();
    },
    enabled: isOpen
  });

  // Industry-standard focus trap for modal accessibility
  const trapRef = useModalFocusTrap({ enabled: isOpen });

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 animate-in fade-in duration-300">
      <div ref={trapRef} className="bg-odysseus-surface rounded-2xl p-8 w-full max-w-md mx-4 shadow-2xl shadow-red-500/30 border border-red-200 animate-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-red-100 rounded-full">
              <AlertTriangle className="w-6 h-6 text-red-600" />
            </div>
            <h2 className="text-xl font-bold text-odysseus-dark">
              {title}
            </h2>
          </div>
          <button
            onClick={onCancel}
            disabled={isLoading}
            className="p-2 rounded-lg hover:bg-odysseus-surface-hover text-odysseus-muted hover:text-odysseus-dark transition-all duration-200 disabled:opacity-50"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="mb-8">
          <p className="text-odysseus-muted leading-relaxed">
            {message}
          </p>
        </div>

        <div className="flex justify-end space-x-3">
          <button
            onClick={onCancel}
            disabled={isLoading}
            className="btn btn-secondary px-6"
          >
            Cancel
          </button>
          <button
            onClick={onConfirm}
            disabled={isLoading}
            className="btn btn-danger px-6"
          >
            {isLoading ? (
              <div className="flex items-center space-x-2">
                <div className="spinner w-4 h-4"></div>
                <span>Deleting...</span>
              </div>
            ) : (
              confirmText
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';

import { X, AlertTriangle } from 'lucide-react';

import { useModalStore } from '@app/stores/modalStore';

interface OverwriteConfirmDialogProps {
  isOpen: boolean;
  title: string;
  message: string;
  confirmText?: string;
  onConfirm: () => void;
  onCancel: () => void;
  isLoading?: boolean;
}

export function OverwriteConfirmDialog({
  isOpen,
  title,
  message,
  confirmText = "Overwrite",
  onConfirm,
  onCancel,
  isLoading = false
}: OverwriteConfirmDialogProps) {
  const [isConfirming, setIsConfirming] = useState(false);
  const modalService = useModalStore();

  // Focus return management - restore focus when modal unmounts
  useEffect(() => {
    if (!isOpen) return;

    return () => {
      const previousFocus = modalService.overwriteConfirm.previousFocusElement;
      if (previousFocus && typeof previousFocus.focus === 'function') {
        setTimeout(() => previousFocus.focus(), 0);
      }
    };
  }, [isOpen, modalService.overwriteConfirm.previousFocusElement]);

  // Reset confirming state when modal opens or closes
  useEffect(() => {
    if (isOpen) {
      setIsConfirming(false);

      const handleKeyDown = (e: KeyboardEvent) => {
        const isProcessing = isLoading || isConfirming;
        if (e.key === 'Enter' && !isProcessing) {
          e.preventDefault();
          e.stopPropagation();
          setIsConfirming(true);
          onConfirm();
        } else if (e.key === 'Escape' && !isProcessing) {
          e.preventDefault();
          e.stopPropagation();
          onCancel();
        }
      };

      document.addEventListener('keydown', handleKeyDown, true);
      return () => {
        document.removeEventListener('keydown', handleKeyDown, true);
      };
    } else {
      // Reset state when modal closes
      setIsConfirming(false);
      // Return undefined explicitly to satisfy TypeScript
      return undefined;
    }
  }, [isOpen, onConfirm, onCancel, isLoading, isConfirming]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 animate-in fade-in duration-300">
      <div className="bg-odysseus-surface rounded-2xl p-8 w-full max-w-md mx-4 shadow-2xl shadow-yellow-500/30 border border-yellow-200 animate-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-yellow-100 rounded-full">
              <AlertTriangle className="w-6 h-6 text-yellow-600" />
            </div>
            <h2 className="text-xl font-bold text-odysseus-dark">
              {title}
            </h2>
          </div>
          <button
            onClick={onCancel}
            disabled={isLoading}
            className="p-2 rounded-lg hover:bg-odysseus-surface-hover text-odysseus-muted hover:text-odysseus-dark transition-all duration-200 disabled:opacity-50"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="mb-8">
          <p className="text-odysseus-muted leading-relaxed">
            {message}
          </p>
        </div>

        <div className="flex justify-end space-x-3">
          <button
            onClick={onCancel}
            disabled={isLoading || isConfirming}
            className="btn btn-secondary px-6"
          >
            Cancel
          </button>
          <button
            onClick={() => {
              if (!isConfirming) {
                setIsConfirming(true);
                onConfirm();
              }
            }}
            disabled={isLoading || isConfirming}
            className="btn bg-yellow-600 hover:bg-yellow-700 text-white border-yellow-600 hover:border-yellow-700 px-6"
          >
            {isLoading || isConfirming ? (
              <div className="flex items-center space-x-2">
                <div className="spinner w-4 h-4"></div>
                <span>Processing...</span>
              </div>
            ) : (
              confirmText
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';

import { NAMING_PATTERNS } from '@odysseus/shared-schemas';
import { Plus, Edit3, Trash2, Save, X, ChevronDown, ChevronRight } from 'lucide-react';

import { useModalStore } from '@app/stores/modalStore';
import {
  useStorageStore,
  useSaveStorageMutation,
  getGridTotalPositions,
  createTankFromDefaults,
  createRackFromDefaults,
  getNextTankNumber,
} from '@domains/storage';
import { TankIcon, RackIcon, BoxIcon } from '@shared/ui/components/icons';
import { notifications } from '@shared/utils/notifications';

import { DeleteConfirmDialog } from './DeleteConfirmDialog';

import type {
  TankConfiguration,
  RackConfiguration,
  BoxConfiguration,
  GridConfiguration} from '@domains/storage';

interface StorageManagementModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function StorageManagementModal({ isOpen, onClose }: StorageManagementModalProps) {
  // Use proper Zustand selectors for reactive updates
  const currentLab = useStorageStore(state => state.currentLab);
  

  const updateTank = useStorageStore(state => state.updateTank);
  const addTank = useStorageStore(state => state.addTank);
  const deleteTank = useStorageStore(state => state.deleteTank);
  const updateBox = useStorageStore(state => state.updateBox);
  const updateRack = useStorageStore(state => state.updateRack);
  const addRack = useStorageStore(state => state.addRack);
  const addBoxToRack = useStorageStore(state => state.addBoxToRack);
  const deleteBox = useStorageStore(state => state.deleteBox);
  const deleteRack = useStorageStore(state => state.deleteRack);
  const getAvailableGridTemplates = useStorageStore(state => state.getAvailableGridTemplates);
  // Auth store subscribed for reactive updates
  const modalService = useModalStore();

  // React Query mutation for server sync
  const saveConfigurationMutation = useSaveStorageMutation();
  
  // Helper function to save configuration to server
  const saveToServerWithReactQuery = async () => {
    const state = useStorageStore.getState();
    const { systemConfig, currentLab } = state;

    // Explicitly type the mutation parameters
    await saveConfigurationMutation.mutateAsync({
      systemConfig: systemConfig as any,
      currentLab: currentLab as any,
    });
  };
  
  const [editingTank, setEditingTank] = useState<TankConfiguration | null>(null);
  const [editingBox, setEditingBox] = useState<{ tankId: string; rackId: string; box: BoxConfiguration } | null>(null);
  const [editingRack, setEditingRack] = useState<{ tankId: string; rack: RackConfiguration } | null>(null);
  const [selectedGridTemplate, setSelectedGridTemplate] = useState<GridConfiguration | null>(null);
  const [collapsedTanks, setCollapsedTanks] = useState<Set<string>>(new Set());
  const [collapsedRacks, setCollapsedRacks] = useState<Set<string>>(() => {
    // Start with all racks collapsed
    const allRackKeys = new Set<string>();
    currentLab.equipment.tanks.forEach(tank => {
      tank.racks.forEach(rack => {
        allRackKeys.add(`${tank.id}-rack-${rack.id}`);
      });
    });
    return allRackKeys;
  });

  // Bulk add counts (per tank/rack)
  const [rackCountToAdd, setRackCountToAdd] = useState<Record<string, number>>({});
  const [boxCountToAdd, setBoxCountToAdd] = useState<Record<string, number>>({});

  const gridTemplates = getAvailableGridTemplates();

  const toggleTankCollapse = (tankId: string) => {
    setCollapsedTanks(prev => {
      const newSet = new Set(prev);
      if (newSet.has(tankId)) {
        newSet.delete(tankId);
      } else {
        newSet.add(tankId);
      }
      return newSet;
    });
  };

  const toggleRackCollapse = (rackKey: string) => {
    setCollapsedRacks(prev => {
      const newSet = new Set(prev);
      if (newSet.has(rackKey)) {
        newSet.delete(rackKey);
      } else {
        newSet.add(rackKey);
      }
      return newSet;
    });
  };

  if (!isOpen) return null;

  const handleCreateRack = async (tankId: string) => {
    const tank = currentLab.equipment.tanks.find(t => t.id === tankId);
    if (!tank) return;

    // Get count from state (default 1 if not set)
    const count = rackCountToAdd[tankId] || 1;
    const highestRackId = Math.max(0, ...tank.racks.map(r => Number(r.id) || 0));

    const newRackKeys: string[] = [];

    // Create N racks
    for (let i = 0; i < count; i++) {
      const newRackNumber = highestRackId + 1 + i;

      // Create rack from creator - ensures fresh defaults from EQUIPMENT_DEFAULTS
      const newRack = createRackFromDefaults(
        tankId,
        newRackNumber,
        currentLab.equipment.defaultGridConfig
      );

      addRack(currentLab.id, tankId, newRack);

      // Track for bulk collapse
      newRackKeys.push(`${tankId}-rack-${newRack.id}`);
    }

    // Collapse all newly created racks (better UX when adding many racks)
    setCollapsedRacks(prev => new Set([...prev, ...newRackKeys]));

    // Reset count to 1 for next operation
    setRackCountToAdd(prev => ({ ...prev, [tankId]: 1 }));

    // Save to server (SessionManager handles authentication automatically)
    await saveToServerWithReactQuery();
  };

  const handleAddBox = async (tankId: string, rackId: string) => {
    const tank = currentLab.equipment.tanks.find(t => t.id === tankId);
    const rack = tank?.racks.find(r => r.id === rackId);
    if (!rack) return;

    // Get count from state (default 1 if not set)
    const rackKey = `${tankId}-${rackId}`;
    const count = boxCountToAdd[rackKey] || 1;

    // Create N boxes
    for (let i = 0; i < count; i++) {
      const boxIndex = rack.boxes.length + i;
      const nextBoxLetter = NAMING_PATTERNS.BOX.LETTER_NAME(boxIndex);
      const newBox: BoxConfiguration = {
        id: nextBoxLetter,
        name: NAMING_PATTERNS.BOX.DEFAULT_NAME(boxIndex),
        gridConfig: currentLab.equipment.defaultGridConfig,
        position: boxIndex + 1 // Add position property (1-indexed)
      };

      addBoxToRack(currentLab.id, tankId, rackId, newBox);
    }

    // Reset count to 1 for next operation
    setBoxCountToAdd(prev => ({ ...prev, [rackKey]: 1 }));

    // Save to server (SessionManager handles authentication automatically)
    await saveToServerWithReactQuery();
  };

  const handleRemoveBox = async (tankId: string, rackId: string, boxId: string) => {
    modalService.showDeleteConfirm({
      title: 'Delete Box',
      message: `Are you sure you want to delete this box? This will remove all tubes in this box.`,
      onConfirm: async () => {
        try {
          deleteBox(currentLab.id, tankId, rackId, boxId);
          // Save to server (SessionManager handles authentication automatically)
          await saveToServerWithReactQuery();
        } finally {
          // Always close modal after mutation completes (success or error)
          modalService.hideDeleteConfirm();
        }
      }
    });
  };

  const handleUpdateBoxGrid = async (tankId: string, rackId: string, boxId: string, gridConfig: GridConfiguration) => {
    updateBox(currentLab.id, tankId, rackId, boxId, { gridConfig });
    setEditingBox(null);
    
    // Save to server (SessionManager handles authentication automatically)
    await saveToServerWithReactQuery();
  };

  const handleUpdateRack = async (tankId: string, rackId: string, updates: Partial<RackConfiguration>) => {
    updateRack(currentLab.id, tankId, rackId, updates);
    setEditingRack(null);
    
    // Save to server (SessionManager handles authentication automatically)
    await saveToServerWithReactQuery();
  };

  const handleDeleteRack = async (tankId: string, rackId: string) => {
    const tank = currentLab.equipment.tanks.find(t => t.id === tankId);
    if (!tank || tank.racks.length <= 1) {
      alert('Cannot delete the last rack in a tank');
      return;
    }

    modalService.showDeleteConfirm({
      title: 'Delete Rack',
      message: `Are you sure you want to delete this rack? This will remove all tubes in the rack.`,
      onConfirm: async () => {
        try {
          deleteRack(currentLab.id, tankId, rackId);
          // Save to server (SessionManager handles authentication automatically)
          await saveToServerWithReactQuery();
        } finally {
          // Always close modal after mutation completes (success or error)
          modalService.hideDeleteConfirm();
        }
      }
    });
  };

  const handleAddNewTank = async () => {
    // Get next available tank number
    const newTankNumber = getNextTankNumber(currentLab.equipment.tanks);

    // Create tank from factory - ensures fresh defaults from EQUIPMENT_DEFAULTS
    // No cloning old configuration - prevents data drift
    const newTank = createTankFromDefaults(
      newTankNumber,
      currentLab.equipment.defaultGridConfig,
      1 // Start with 1 rack (user can add more)
    );

    addTank(currentLab.id, newTank);

    // Collapse the new tank's rack by default (cleaner UI)
    const newRackKey = `${newTank.id}-rack-${newTank.racks[0].id}`;
    setCollapsedRacks(prev => new Set([...prev, newRackKey]));

    // Save to server (SessionManager handles authentication automatically)
    await saveToServerWithReactQuery();
  };

  const handleDeleteTank = async (tankId: string) => {
    if (currentLab.equipment.tanks.length <= 1) {
      alert('Cannot delete the last tank in the laboratory');
      return;
    }

    modalService.showDeleteConfirm({
      title: 'Delete Tank',
      message: `Are you sure you want to delete this tank? This will remove all racks, boxes, and tubes in this tank.`,
      onConfirm: async () => {
        try {
          // Update configuration state (remove tank)
          void deleteTank(currentLab.id, tankId);

          // Save to server via configuration update (Clean Architecture)
          await saveToServerWithReactQuery();

          notifications.success('Tank deleted successfully');
        } catch (error) {
          console.error('Failed to delete tank:', error);
          notifications.error('Failed to delete tank. Please try again.');
        } finally {
          modalService.hideDeleteConfirm();
        }
      }
    });
  };

  const handleUpdateTank = async (tankId: string, updates: Partial<TankConfiguration>) => {
    updateTank(currentLab.id, tankId, updates);
    setEditingTank(null);

    // Save to server (SessionManager handles authentication automatically)
    await saveToServerWithReactQuery();
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-[2px] flex items-center justify-center z-50 animate-in fade-in duration-[180ms]">
      <div className="bg-white rounded-xl shadow-2xl w-[60%] h-[85%] max-w-2xl max-h-[800px] flex flex-col animate-slide-up-fade">
        <div className="sticky top-0 bg-gradient-to-r from-slate-600 via-slate-400 to-slate-600 px-6 py-4 text-white rounded-t-xl">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-bold">Manage Storage</h2>
              <p className="text-sm text-white/90 mt-0.5">Configure liquid nitrogen storage tanks, racks, and boxes</p>
            </div>
            <button onClick={onClose} className="p-1 hover:bg-white/20 rounded-lg transition-colors">
              <X size={20} />
            </button>
          </div>
        </div>

        <div className="flex-1 p-3 overflow-y-auto">
          <div className="space-y-2">
            {/* Add New Tank Button */}
            <div className="flex justify-end">
              <button
                onClick={() => handleAddNewTank()}
                className="flex items-center gap-2 bg-slate-600 text-white px-3 py-1.5 rounded-lg hover:bg-slate-700 font-medium text-sm"
              >
                <Plus size={16} />
                Add New Tank
              </button>
            </div>

            {/* Tanks List */}
            <div className="space-y-1.5">
              {currentLab.equipment.tanks.map((tank) => (
                    <div key={tank.id} className="border border-gray-300 rounded-lg bg-white">
                      {/* Tank Header - Compact horizontal spacing */}
                      <div className="bg-slate-600 px-2 py-1.5 border-b border-slate-700 rounded-t-lg">
                        <div className="flex items-center gap-2">
                          <button
                            type="button"
                            onClick={() => toggleTankCollapse(tank.id)}
                            className="flex items-center gap-2 flex-1 min-w-0 cursor-pointer hover:bg-slate-700 -mx-1 px-1 py-1 rounded text-left"
                            aria-expanded={!collapsedTanks.has(tank.id)}
                            aria-controls={`tank-content-${tank.id}`}
                            aria-label={`${collapsedTanks.has(tank.id) ? 'Expand' : 'Collapse'} tank ${tank.name}`}
                          >
                            <div className="text-slate-200 flex-shrink-0" aria-hidden="true">
                              {collapsedTanks.has(tank.id) ? <ChevronRight size={16} /> : <ChevronDown size={16} />}
                            </div>
                            <div className="flex-1 min-w-0 flex items-center gap-1.5">
                              <TankIcon className="text-white flex-shrink-0" size={24} aria-hidden="true" />
                              <h3 className="text-base font-semibold text-white truncate min-w-[80px]">{tank.name}</h3>
                              <span className="text-xs px-2 py-1 bg-slate-700 rounded text-white flex items-center gap-1.5">
                                <span>{tank.location}</span>
                                <span>•</span>
                                <span>{tank.racks.length} {tank.racks.length === 1 ? 'rack' : 'racks'}</span>
                              </span>
                            </div>
                          </button>
                          <div className="flex items-center gap-0.5 flex-shrink-0">
                            <button
                              onClick={() => setEditingTank(tank)}
                              className="text-slate-200 hover:bg-slate-700 p-1 rounded"
                              title="Edit tank"
                            >
                              <Edit3 size={16} />
                            </button>
                            {currentLab.equipment.tanks.length > 1 && (
                              <button
                                onClick={() => handleDeleteTank(tank.id)}
                                className="text-red-300 hover:bg-red-900 p-1 rounded"
                                title="Delete tank"
                              >
                                <Trash2 size={16} />
                              </button>
                            )}
                          </div>
                        </div>
                      </div>

                      {/* Tank content - collapsible */}
                      {!collapsedTanks.has(tank.id) && (
                        <div id={`tank-content-${tank.id}`} className="p-2">
                          <div className="space-y-1.5">
                            {tank.racks.map((rack, rackIndex) => {
                              const rackKey = `${tank.id}-rack-${rack.id}`;
                              return (
                                <div key={rack.id} className="ml-2">
                                  {/* Rack Row - Tight horizontal spacing */}
                                  <div className="flex items-center gap-1.5 py-1 px-1.5 bg-slate-400 rounded border border-slate-500">
                                    <span className="text-slate-600 font-mono text-sm flex-shrink-0">
                                      {rackIndex === tank.racks.length - 1 ? '└' : '├'}
                                    </span>
                                    <button
                                      type="button"
                                      onClick={() => toggleRackCollapse(rackKey)}
                                      className="flex items-center gap-2 flex-1 min-w-0 cursor-pointer hover:bg-slate-500 -mx-1 px-1 py-0.5 rounded text-left"
                                      aria-expanded={!collapsedRacks.has(rackKey)}
                                      aria-controls={`rack-content-${rackKey}`}
                                      aria-label={`${collapsedRacks.has(rackKey) ? 'Expand' : 'Collapse'} ${rack.name}`}
                                    >
                                      <div className="text-white flex-shrink-0" aria-hidden="true">
                                        {collapsedRacks.has(rackKey) ? <ChevronRight size={12} /> : <ChevronDown size={12} />}
                                      </div>
                                      <RackIcon className="text-white flex-shrink-0" size={18} aria-hidden="true" />
                                      <span className="font-medium text-white text-sm inline-block min-w-[60px]">{rack.name}</span>
                                      <span className="text-xs px-2 py-0.5 bg-slate-500 rounded text-white">
                                        {rack.boxes.length} {rack.boxes.length === 1 ? 'box' : 'boxes'}
                                      </span>
                                    </button>
                                    <div className="flex items-center gap-1 flex-shrink-0">
                                      <button
                                        onClick={() => setEditingRack({ tankId: tank.id, rack })}
                                        className="text-slate-100 hover:bg-slate-500 p-1 rounded"
                                        title="Edit rack"
                                      >
                                        <Edit3 size={14} />
                                      </button>
                                      {tank.racks.length > 1 && (
                                        <button
                                          onClick={() => handleDeleteRack(tank.id, rack.id)}
                                          className="text-red-300 hover:bg-red-900 p-1 rounded"
                                          title="Delete rack"
                                        >
                                          <Trash2 size={14} />
                                        </button>
                                      )}
                                    </div>
                                  </div>

                                  {/* Boxes under this rack - collapsible */}
                                  {!collapsedRacks.has(rackKey) && (
                                    <div id={`rack-content-${rackKey}`} className="ml-5 mt-0.5 space-y-0.5">
                                      {rack.boxes.map((box, boxIndex) => (
                                        <div key={box.id} className="flex items-center gap-1.5 py-0.5 px-1.5 bg-slate-200 rounded border border-slate-300">
                                          <span className="text-slate-400 font-mono text-xs flex-shrink-0">
                                            {boxIndex === rack.boxes.length - 1 ? '└' : '├'}
                                          </span>
                                          <BoxIcon className="text-slate-700 flex-shrink-0" size={16} />
                                          <span className="font-medium text-slate-800 text-xs inline-block w-16">{box.name}</span>
                                          <span className="text-xs px-2 py-1 bg-slate-300 rounded text-slate-700">
                                            {box.gridConfig.rows}×{box.gridConfig.cols}
                                          </span>
                                          <div className="flex-1"></div>
                                          <div className="flex items-center gap-1 flex-shrink-0">
                                            <button
                                              onClick={() => setEditingBox({ tankId: tank.id, rackId: rack.id, box })}
                                              className="text-slate-700 hover:bg-slate-300 p-1 rounded"
                                              title="Change grid size"
                                            >
                                              <Edit3 size={12} />
                                            </button>
                                            {rack.boxes.length > 1 && (
                                              <button
                                                onClick={() => handleRemoveBox(tank.id, rack.id, box.id)}
                                                className="text-red-700 hover:bg-red-200 p-1 rounded"
                                                title="Remove this box"
                                              >
                                                <Trash2 size={12} />
                                              </button>
                                            )}
                                          </div>
                                        </div>
                                      ))}

                                      {/* Add Box Button with Bulk Input */}
                                      <div className="flex items-center gap-1.5 py-0.5 px-1.5">
                                        <span className="text-slate-400 font-mono text-xs">└</span>
                                        <div className="flex items-center gap-2">
                                          <input
                                            type="number"
                                            min="1"
                                            max="26"
                                            value={boxCountToAdd[`${tank.id}-${rack.id}`] || 1}
                                            onChange={(e) => setBoxCountToAdd(prev => ({
                                              ...prev,
                                              [`${tank.id}-${rack.id}`]: Math.max(1, Math.min(26, parseInt(e.target.value) || 1))
                                            }))}
                                            className="input-number-sm w-14 px-2 py-0.5"
                                            title="Number of boxes to add"
                                          />
                                          <button
                                            onClick={() => handleAddBox(tank.id, rack.id)}
                                            className="flex items-center gap-1 bg-slate-200 text-slate-800 px-2 py-1 rounded hover:bg-slate-300 text-xs"
                                          >
                                            <Plus size={12} />
                                            Add {(boxCountToAdd[`${tank.id}-${rack.id}`] || 1) > 1 ? 'Boxes' : 'Box'}
                                          </button>
                                        </div>
                                      </div>
                                    </div>
                                  )}
                                </div>
                              );
                            })}

                            {/* Add Rack Button with Bulk Input */}
                            <div className="ml-2 mt-1">
                              <div className="flex items-center gap-1.5 py-1 px-1.5">
                                <span className="text-gray-400 font-mono text-xs">└</span>
                                <div className="flex items-center gap-2">
                                  <input
                                    type="number"
                                    min="1"
                                    max="50"
                                    value={rackCountToAdd[tank.id] || 1}
                                    onChange={(e) => setRackCountToAdd(prev => ({
                                      ...prev,
                                      [tank.id]: Math.max(1, Math.min(50, parseInt(e.target.value) || 1))
                                    }))}
                                    className="input-number-sm w-14 px-2 py-1 text-sm"
                                    title="Number of racks to add"
                                  />
                                  <button
                                    onClick={() => handleCreateRack(tank.id)}
                                    className="flex items-center gap-1 bg-slate-400 text-white px-2 py-1 rounded hover:bg-slate-500 text-sm"
                                  >
                                    <Plus size={12} />
                                    Add {(rackCountToAdd[tank.id] || 1) > 1 ? 'Racks' : 'Rack'}
                                  </button>
                                </div>
                              </div>
                            </div>
                          </div>
                        </div>
                      )}
                    </div>
                  ))}
            </div>
          </div>
        </div>

        {editingBox && (
          <div
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-60"
            role="presentation"
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                const template = selectedGridTemplate || editingBox.box.gridConfig;
                void (async () => {
                  try {
                    await handleUpdateBoxGrid(editingBox.tankId, editingBox.rackId, editingBox.box.id, template);
                  } catch (error) {
                    console.error('Failed to update box grid:', error);
                    notifications.error('Failed to save changes. Please try again.');
                  }
                })();
              } else if (e.key === 'Escape') {
                e.preventDefault();
                setEditingBox(null);
              }
            }}
          >
            <div
              className="bg-white rounded-lg p-6 max-w-md w-full m-4"
              role="dialog"
              aria-labelledby="box-edit-title"
              aria-modal="true"
            >
              <h3 id="box-edit-title" className="text-lg font-semibold mb-4">
                Configure {editingBox.box.name} Grid Size
              </h3>
              
              <div className="space-y-4">
                <div>
                  <label htmlFor="box-grid-template" className="block text-sm font-medium mb-2">
                    Select Grid Template
                  </label>
                  <select
                    id="box-grid-template"
                    className="w-full border rounded-lg px-3 py-2"
                    value={`${editingBox.box.gridConfig.rows}x${editingBox.box.gridConfig.cols}`}
                    onChange={(e) => {
                      const [rows, cols] = e.target.value.split('x').map(Number);
                      const template = gridTemplates.find(t => t.rows === rows && t.cols === cols);
                      if (template) setSelectedGridTemplate(template);
                    }}
                    aria-label="Select grid template for box"
                  >
                    {gridTemplates.map((template) => (
                      <option
                        key={`${template.rows}x${template.cols}`}
                        value={`${template.rows}x${template.cols}`}
                      >
                        {template.rows}×{template.cols} Grid
                      </option>
                    ))}
                  </select>
                </div>
                
                <div className="flex justify-end gap-3">
                  <button
                    onClick={() => setEditingBox(null)}
                    className="btn-cancel"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={() => {
                      const template = selectedGridTemplate || editingBox.box.gridConfig;
                      void (async () => {
                        try {
                          await handleUpdateBoxGrid(editingBox.tankId, editingBox.rackId, editingBox.box.id, template);
                        } catch (error) {
                          console.error('Failed to update box grid:', error);
                          notifications.error('Failed to save changes. Please try again.');
                        }
                      })();
                    }}
                    className="btn-primary flex items-center gap-2"
                  >
                    <Save size={16} />
                    Save Changes
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Rack Editing Modal */}
        {editingRack && (
          <div
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-60"
            role="presentation"
            onKeyDown={(e) => {
              if (e.key === 'Enter' && editingRack.rack.name.trim()) {
                e.preventDefault();
                void (async () => {
                  try {
                    await handleUpdateRack(editingRack.tankId, editingRack.rack.id, {
                      name: editingRack.rack.name,
                      location: editingRack.rack.location,
                      description: editingRack.rack.description,
                      isActive: editingRack.rack.isActive
                    });
                  } catch (error) {
                    console.error('Failed to update rack:', error);
                    notifications.error('Failed to save changes. Please try again.');
                  }
                })();
              } else if (e.key === 'Escape') {
                e.preventDefault();
                setEditingRack(null);
              }
            }}
          >
            <div
              className="bg-white rounded-lg p-6 w-96 shadow-xl"
              role="dialog"
              aria-labelledby="rack-edit-title"
              aria-modal="true"
            >
              <div className="flex items-center justify-between mb-4">
                <h3 id="rack-edit-title" className="text-lg font-bold">Edit Rack</h3>
                <button onClick={() => setEditingRack(null)} className="p-1 hover:bg-gray-100 rounded">
                  <X size={16} />
                </button>
              </div>
              
              <div className="space-y-4">
                <div>
                  <label htmlFor="rack-name" className="block text-sm font-medium mb-2">
                    Rack Name
                  </label>
                  <input
                    id="rack-name"
                    type="text"
                    className="input w-full"
                    value={editingRack.rack.name}
                    onChange={(e) => setEditingRack({ ...editingRack, rack: { ...editingRack.rack, name: e.target.value } })}
                    placeholder="Rack 1"
                    required
                    aria-required="true"
                  />
                </div>

                <div>
                  <label htmlFor="rack-description" className="block text-sm font-medium mb-2">
                    Description
                  </label>
                  <textarea
                    id="rack-description"
                    className="input w-full resize-none"
                    rows={3}
                    value={editingRack.rack.description || ''}
                    onChange={(e) => setEditingRack({ ...editingRack, rack: { ...editingRack.rack, description: e.target.value } })}
                    placeholder="Optional description"
                  />
                </div>

                <div className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    id="rackActive"
                    checked={editingRack.rack.isActive}
                    onChange={(e) => setEditingRack({ ...editingRack, rack: { ...editingRack.rack, isActive: e.target.checked } })}
                  />
                  <label htmlFor="rackActive" className="text-sm font-medium">
                    Active (visible in rack selector)
                  </label>
                </div>
              </div>
              
              <div className="flex justify-end gap-3 mt-6">
                <button
                  onClick={() => setEditingRack(null)}
                  className="btn-cancel"
                >
                  Cancel
                </button>
                <button
                  onClick={() => handleUpdateRack(editingRack.tankId, editingRack.rack.id, {
                    name: editingRack.rack.name,
                    location: editingRack.rack.location,
                    description: editingRack.rack.description,
                    isActive: editingRack.rack.isActive
                  })}
                  className="btn-primary flex items-center gap-2"
                >
                  <Save size={16} />
                  Save Changes
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Tank Editing Modal - Enhanced */}
        {editingTank && (
          <div
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-60"
            role="presentation"
            onKeyDown={(e) => {
              if (e.key === 'Enter' && editingTank.name.trim()) {
                e.preventDefault();
                void (async () => {
                  try {
                    await handleUpdateTank(editingTank.id, {
                      name: editingTank.name.trim(),
                      location: editingTank.location?.trim() || '',
                      isActive: editingTank.isActive
                    });
                  } catch (error) {
                    console.error('Failed to update tank:', error);
                    notifications.error('Failed to save changes. Please try again.');
                  }
                })();
              } else if (e.key === 'Escape') {
                e.preventDefault();
                setEditingTank(null);
              }
            }}
          >
            <div
              className="bg-white rounded-lg p-6 w-[480px] shadow-xl"
              role="dialog"
              aria-labelledby="tank-edit-title"
              aria-modal="true"
            >
              <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-3">
                  <TankIcon className="text-odysseus-blue" size={22} />
                  <h3 id="tank-edit-title" className="text-lg font-bold">Edit Tank Configuration</h3>
                </div>
                <button onClick={() => setEditingTank(null)} className="p-1 hover:bg-gray-100 rounded">
                  <X size={16} />
                </button>
              </div>
              
              <div className="space-y-5">
                <div>
                  <label htmlFor="tank-name" className="block text-sm font-semibold mb-2 text-gray-700">
                    Tank Name *
                  </label>
                  <input
                    id="tank-name"
                    type="text"
                    className="input w-full text-lg font-medium"
                    value={editingTank.name}
                    onChange={(e) => setEditingTank({ ...editingTank, name: e.target.value })}
                    placeholder="Main Cryogenic Storage"
                    required
                    aria-required="true"
                    aria-invalid={!editingTank.name.trim()}
                  />
                  {!editingTank.name.trim() && (
                    <p id="tank-name-error" className="text-red-500 text-xs mt-1" role="alert">
                      Tank name is required
                    </p>
                  )}
                </div>

                <div>
                  <label htmlFor="tank-location" className="block text-sm font-semibold mb-2 text-gray-700">
                    Physical Location
                  </label>
                  <input
                    id="tank-location"
                    type="text"
                    className="input w-full"
                    value={editingTank.location || ''}
                    onChange={(e) => setEditingTank({ ...editingTank, location: e.target.value })}
                    placeholder="Lab Room 101, Building A"
                  />
                </div>

                <div className="bg-gray-50 p-4 rounded-lg">
                  <h4 className="font-medium text-gray-700 mb-2">Tank Status</h4>
                  <div className="flex items-center gap-3">
                    <input 
                      type="checkbox"
                      id="tankActive"
                      checked={editingTank.isActive}
                      onChange={(e) => setEditingTank({ ...editingTank, isActive: e.target.checked })}
                      className="w-4 h-4 text-blue-600"
                    />
                    <label htmlFor="tankActive" className="text-sm font-medium">
                      Active (tank is available for storage)
                    </label>
                  </div>
                  <p className="text-xs text-gray-500 mt-1">
                    Inactive tanks are hidden from selectors but data is preserved
                  </p>
                </div>

                <div className="bg-blue-50 p-4 rounded-lg">
                  <h4 className="font-medium text-blue-700 mb-1">Tank Statistics</h4>
                  <div className="text-sm text-blue-600 space-y-1">
                    <p>• {editingTank.racks.length} racks configured</p>
                    <p>• {editingTank.racks.reduce((total, rack) => total + rack.boxes.length, 0)} storage boxes</p>
                    <p>• {editingTank.racks.reduce((total, rack) => total + rack.boxes.reduce((rackTotal, box) => rackTotal + getGridTotalPositions(box.gridConfig), 0), 0)} total positions</p>
                  </div>
                </div>
              </div>
              
              <div className="flex justify-end gap-3 mt-8 pt-4 border-t">
                <button
                  onClick={() => setEditingTank(null)}
                  className="btn-cancel"
                >
                  Cancel
                </button>
                <button
                  onClick={() => {
                    if (editingTank.name.trim()) {
                      void (async () => {
                        try {
                          await handleUpdateTank(editingTank.id, {
                            name: editingTank.name.trim(),
                            location: editingTank.location?.trim() || '',
                            isActive: editingTank.isActive
                          });
                        } catch (error) {
                          console.error('Failed to update tank:', error);
                          notifications.error('Failed to save changes. Please try again.');
                        }
                      })();
                    }
                  }}
                  disabled={!editingTank.name.trim()}
                  className="btn-primary flex items-center gap-2"
                >
                  <Save size={16} />
                  Save Changes
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Delete Confirmation Dialog */}
        <DeleteConfirmDialog
          isOpen={modalService.deleteConfirm.isOpen}
          title={modalService.deleteConfirm.title}
          message={modalService.deleteConfirm.message}
          onConfirm={modalService.deleteConfirm.onConfirm}
          onCancel={modalService.deleteConfirm.onCancel}
        />
      </div>
    </div>
  );
}

/**
 * TubeEditorModal - Unified Tube Creation & Editing Modal
 *
 * Consolidated modal handling CREATE, EDIT, and MIXED modes.
 * - Handles CREATE (single/multiple empty positions)
 * - Handles EDIT (single tube by ID)
 * - Handles MIXED (create new + update existing positions)
 * - Form data = API data (no transformation)
 * - Smart component pattern (fetches own data when editing)
 *
 * @example
 * // Create mode (single position)
 * <TubeEditorModal selectedPositions={set} onClose={...} />
 *
 * // Edit mode (single tube)
 * <TubeEditorModal tubeId="123" onClose={...} />
 *
 * // Mixed mode (create + update)
 * <TubeEditorModal selectedPositions={set} onClose={...} />
 */

import React, { useMemo, useState, useEffect } from 'react';

import {
  type CreateTubeFormInput,
  type UpdateTubeFormInput,
  formatConcentrationDisplay,
  EQUIPMENT_DEFAULTS
} from '@odysseus/shared-schemas';
import { MapPin, AlertTriangle, Edit, Plus, Save, Trash2 } from 'lucide-react';

import { useModalStore } from '@app/stores/modalStore';
import { useUserSettings } from '@domains/authentication';
import { useActiveResearchersQuery } from '@domains/researchers';
import { useStorageStore, formatPositionRangesForBox } from '@domains/storage';
import { useCreateTubeForm, useEditTubeForm } from '@domains/tubes/hooks/useTubeForm';
import { useUpdateTubeMutation, useDeleteTubeMutation } from '@domains/tubes/hooks/useTubeMutations';
import { useTubesQuery, useTubeQuery } from '@domains/tubes/hooks/useTubesQuery';
import { useModalKeyboardNav } from '@shared/hooks/keyboard/useModalKeyboardNav';
import { parsePositionKey, type PositionKey } from '@shared/types/grid';
import { notifications } from '@shared/utils';
import { formatDateForInput } from '@shared/utils/dateFormatter';

import { LocationDisplay } from '../displays/LocationDisplay';
import { TubeForm } from '../forms/TubeForm';

import { BaseModal } from './BaseModal';

/**
 * TubeEditorModal Props
 * - For CREATE: provide selectedPositions
 * - For EDIT: provide tubeId
 * - Cannot provide both
 */
export interface TubeEditorModalProps {
  onClose: () => void;

  // Edit mode: Single tube ID
  tubeId?: string;

  // Create/Mixed mode: Multiple positions
  rackId?: string;
  boxId?: string;
  selectedPositions?: Set<PositionKey>;
}

/**
 * Unified Tube Editor Modal Component
 * Automatically detects mode based on props
 */
export function TubeEditorModal(props: TubeEditorModalProps) {
  const { tubeId, onClose } = props;

  // Mode detection
  const isEditMode = Boolean(tubeId);

  if (isEditMode) {
    return <EditModeContent tubeId={tubeId!} onClose={onClose} />;
  } else {
    return <CreateModeContent {...props} onClose={onClose} />;
  }
}

/**
 * Edit Mode Content
 * Fetches tube data and shows edit form with delete button
 */
interface EditModeContentProps {
  tubeId: string;
  onClose: () => void;
}

function EditModeContent({ tubeId, onClose }: EditModeContentProps) {
  const { data: researchers = [] } = useActiveResearchersQuery();
  const modalService = useModalStore();

  // Fetch tube data from React Query cache (always fresh)
  const { data: tube, isLoading: isFetchingTube } = useTubeQuery(tubeId);

  // Focus return management - restore focus when modal unmounts
  useEffect(() => {
    return () => {
      const previousFocus = modalService.tubeEditorModal.previousFocusElement;
      if (previousFocus && typeof previousFocus.focus === 'function') {
        setTimeout(() => {
          previousFocus.focus();
        }, 0);
      }
    };
  }, [modalService.tubeEditorModal.previousFocusElement]);

  // Unified keyboard navigation: Escape = close
  // (Enter naturally submits form)
  useModalKeyboardNav({
    onEscape: onClose,
    enabled: true
  });

  // Loading state while fetching tube
  if (isFetchingTube || !tube) {
    return (
      <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50">
        <div className="bg-odysseus-surface rounded-2xl p-8 w-full max-w-4xl mx-4">
          <div className="flex items-center justify-center py-12">
            <div className="spinner w-8 h-8"></div>
            <span className="ml-3 text-odysseus-muted">Loading tube data...</span>
          </div>
        </div>
      </div>
    );
  }

  // Use updatedAt timestamp as unique key to force form remount when data changes
  const formKey = `edit-tube-${tube.id}-${tube.timestamps.updatedAt}`;

  return (
    <EditModeForm
      key={formKey}
      tube={tube}
      tubeId={tubeId}
      researchers={researchers}
      onClose={onClose}
      modalService={modalService}
    />
  );
}

/**
 * Edit Mode Form
 * Inner component that remounts when tube data changes
 */
interface EditModeFormProps {
  tube: any;
  tubeId: string;
  researchers: any[];
  onClose: () => void;
  modalService: any;
}

function EditModeForm({ tube, tubeId, researchers, onClose, modalService }: EditModeFormProps) {
  // Build initialData from tube - uses FORM INPUT type (pre-transformation)
  // concentration as string, date as string
  const initialData: Partial<UpdateTubeFormInput> = {
    sample: {
      cellType: tube.sample.cellType ?? '',
      donorInternalId: tube.sample.donorInternalId ?? '',
      donorSourceId: tube.sample.donorSourceId ?? '',
      concentration: formatConcentrationDisplay(tube.sample.concentration) || undefined,
      concentrationUnit: tube.sample.concentrationUnit || undefined,
      date: tube.sample.date ? formatDateForInput(tube.sample.date) : '',
      media: {
        type: tube.sample.media?.type ?? '',
        supplements: tube.sample.media?.supplements ?? '',
        selection: tube.sample.media?.selection ?? ''
      },
      cultureCondition: tube.sample.cultureCondition ?? '',
      lotNumber: tube.sample.lotNumber ?? '',
      notes: tube.sample.notes ?? ''
    },
    researcherId: tube.researcherId ?? ''
  };

  // Use edit mode hook - fully type-safe wrapper
  const { form, submitTube, isSubmitting: formSubmitting } = useEditTubeForm(tubeId, {
    initialData
  });

  const deleteMutation = useDeleteTubeMutation();
  const isSubmitting = formSubmitting || deleteMutation.isPending;

  // Form submission handler
  // Receives form INPUT type, Zod transforms to OUTPUT type
  const handleFormSubmit = async (validatedData: UpdateTubeFormInput) => {
    try {
      // Send all form data (simplicity > micro-optimization)
      // submitTube handles Zod transformation: INPUT → OUTPUT
      const result = await submitTube(validatedData, { location: tube.location });

      if (result.success) {
        notifications.update('Tube updated successfully'); // Minty Frost
        onClose();
      } else {
        notifications.error(result.error ?? 'Failed to update tube');
      }
    } catch (error) {
      notifications.error('Failed to update tube');
    }
  };

  // Delete handler
  const handleDelete = async () => {
    try {
      await deleteMutation.mutateAsync(tubeId);
      notifications.delete('Tube deleted successfully');
      onClose();
    } catch (error) {
      notifications.error('Failed to delete tube');
    }
  };

  // Use React Hook Form's built-in validation state (more efficient)
  const isFormValid = form.formState.isValid;

  return (
    <BaseModal
      title="Edit Tube"
      icon={<Edit className="w-5 h-5 text-white" />}
      onClose={onClose}
      dataAttribute="data-tube-modal"
      mode="edit"
    >
      <form onSubmit={form.handleSubmit(handleFormSubmit)} className="space-y-4">
          <LocationDisplay
            tankId={tube.location.tankId}
            rackId={tube.location.rackId}
            boxId={tube.location.boxId}
            position={tube.location.position}
          />

          <TubeForm
            control={form.control as any}
            register={form.register as any}
            errors={form.formState.errors as any}
            trigger={form.trigger as any}
            researchers={researchers}
            isLoading={isSubmitting}
          />

          <div className="flex justify-end space-x-4 pt-4 border-t border-odysseus-border">
            <button
              type="button"
              onClick={onClose}
              className="btn btn-secondary px-6"
              disabled={isSubmitting}
            >
              Cancel
            </button>
            <button
              type="button"
              className="btn btn-danger px-6"
              disabled={isSubmitting}
              onClick={() => {
                modalService.showDeleteConfirm({
                  title: 'Delete Tube',
                  message: `Are you sure you want to delete this tube from Rack ${tube.location.rackId}, Box ${tube.location.boxId}, Position ${tube.location.position}? This action cannot be undone.`,
                  onConfirm: handleDelete
                });
              }}
            >
              <Trash2 className="w-4 h-4 mr-2" />
              Delete Tube
            </button>
            <button
              type="submit"
              className={`btn px-8 ${isFormValid ? 'btn-primary' : 'btn-secondary'}`}
              disabled={isSubmitting || !isFormValid}
            >
              {isSubmitting ? (
                <div className="flex items-center space-x-2">
                  <div className="spinner w-4 h-4"></div>
                  <span>Updating...</span>
                </div>
              ) : (
                <>
                  <Save className="w-4 h-4 mr-2" />
                  Update Tube
                </>
              )}
            </button>
          </div>
        </form>
    </BaseModal>
  );
}

/**
 * Create Mode Content
 * Handles single/multiple position creation and mixed create+update
 */
function CreateModeContent({
  onClose,
  _rackId,
  _boxId,
  selectedPositions
}: TubeEditorModalProps) {
  const { data: researchers = [] } = useActiveResearchersQuery();
  const { data: allTubes = [] } = useTubesQuery();
  const updateTubeMutation = useUpdateTubeMutation();
  const currentLab = useStorageStore(state => state.currentLab);
  const getBox = useStorageStore(state => state.getBox);
  const { settings: userSettings } = useUserSettings();
  const modalService = useModalStore();

  // State for overwrite confirmation
  const [allowOverwrite, setAllowOverwrite] = useState(false);

  // Focus return management - restore focus when modal unmounts
  // IMPORTANT: Capture preserveSelection flag on mount to avoid race condition with hideTubeEditorModal
  const [shouldPreserveSelection] = useState(modalService.tubeEditorModal.preserveSelection);

  useEffect(() => {
    return () => {
      // Don't restore focus if preserveSelection is enabled (batch operations)
      // This prevents focus from returning to a specific position and clearing selection
      if (shouldPreserveSelection) {
        return;
      }

      const previousFocus = modalService.tubeEditorModal.previousFocusElement;
      if (previousFocus && typeof previousFocus.focus === 'function') {
        setTimeout(() => {
          previousFocus.focus();
        }, 0);
      }
    };
  }, [shouldPreserveSelection, modalService.tubeEditorModal.previousFocusElement]);

  // Unified keyboard navigation: Escape = close
  // (Enter naturally submits form)
  useModalKeyboardNav({
    onEscape: onClose,
    enabled: true
  });

  // Parse selected positions from string format
  const parsedPositions = useMemo(() => {
    if (!selectedPositions) return [];
    return Array.from(selectedPositions).map(positionKey => {
      const { tankId, rackId, boxId, position } = parsePositionKey(positionKey);

      return {
        location: {
          tankId,
          rackId,
          boxId,
          position
        }
      };
    });
  }, [selectedPositions]);

  // Analyze which positions are occupied vs empty
  const positionAnalysis = useMemo(() => {
    const emptyPositions = [];
    const occupiedPositions = [];

    for (const parsed of parsedPositions) {
      const { tankId, rackId, boxId, position } = parsed.location;
      const existingTube = allTubes.find(t =>
        t.location.tankId === tankId &&
        t.location.rackId === rackId &&
        t.location.boxId === boxId &&
        t.location.position === position
      );

      if (existingTube) {
        occupiedPositions.push({ ...parsed, tubeId: existingTube.id });
      } else {
        emptyPositions.push(parsed);
      }
    }

    return {
      emptyPositions,
      occupiedPositions,
      hasEmpty: emptyPositions.length > 0,
      hasOccupied: occupiedPositions.length > 0,
      isMixed: emptyPositions.length > 0 && occupiedPositions.length > 0
    };
  }, [parsedPositions, allTubes]);

  // Get location display names for batch operations
  const batchLocationDisplay = useMemo(() => {
    if (parsedPositions.length === 0) return null;

    const firstLocation = parsedPositions[0].location;
    const tanks = currentLab.equipment?.tanks || [];
    const tank = tanks.find(t => t.id === firstLocation.tankId);
    const tankName = tank?.name ?? `Tank ${firstLocation.tankId}`;

    const rack = tank?.racks?.find(r => r.id === firstLocation.rackId);
    const rackName = rack?.name ?? `Rack ${firstLocation.rackId}`;

    const box = rack?.boxes?.find(b => b.id === firstLocation.boxId);
    const boxName = box?.name ?? `Box ${firstLocation.boxId}`;

    // Get box config for flexible position formatting
    const boxObj = getBox(firstLocation.tankId, firstLocation.rackId, firstLocation.boxId);
    const gridConfig = boxObj?.gridConfig ?? {
      rows: EQUIPMENT_DEFAULTS.GRID_ROWS,
      cols: EQUIPMENT_DEFAULTS.GRID_COLS,
      template: 'standard' as const,
    };

    const positions = parsedPositions.map(p => p.location.position);
    const positionRanges = formatPositionRangesForBox(
      positions,
      firstLocation.tankId,
      firstLocation.rackId,
      firstLocation.boxId,
      gridConfig,
      userSettings
    );

    return { tankName, rackName, boxName, positionRanges };
  }, [parsedPositions, currentLab, getBox, userSettings]);

  // Default values use FORM INPUT type (pre-transformation)
  const defaultValues = useMemo((): Partial<CreateTubeFormInput> => ({
    location: parsedPositions[0]?.location,
    sample: {
      cellType: '',
      donorInternalId: '',
      donorSourceId: '',
      concentration: undefined,
      concentrationUnit: undefined,
      date: '',
      media: {
        type: '',
        supplements: '',
        selection: ''
      },
      cultureCondition: '',
      lotNumber: '',
      notes: ''
    },
    researcherId: ''
  }), [parsedPositions]);

  // Use create mode hook
  // Only show individual notifications for single tube creation, not batch operations
  const isSingleTube = parsedPositions.length === 1;
  const { form, submitTube, isSubmitting } = useCreateTubeForm({
    initialData: defaultValues,
    onSuccess: isSingleTube ? (data) => {
      notifications.create(`Successfully created tube at position ${data.location.position}`); // Minty Frost
      onClose();
    } : undefined, // Batch mode: notification handled after all tubes are created
    onError: isSingleTube ? (error) => {
      notifications.error(`Failed to create tube: ${error.message}`);
    } : undefined // Batch mode: errors handled in handleFormSubmit
  });

  /**
   * Handle form submission for multiple positions
   * Supports create, update, and mixed operations
   * Receives form INPUT type, Zod transforms to OUTPUT type
   */
  const handleFormSubmit = async (formData: CreateTubeFormInput) => {
    try {
      if (parsedPositions.length === 0) {
        notifications.error('No valid positions selected');
        return;
      }

      if (parsedPositions.length === 1) {
        // Single position - pass location as context
        const result = await submitTube(formData, parsedPositions[0].location);

        if (result.success) {
          onClose();
        }
        return;
      }

      // Multiple positions - handle creates AND updates
      let successCount = 0;
      let errorCount = 0;
      const errors: string[] = [];

      // Process empty positions (creates)
      for (const { location } of positionAnalysis.emptyPositions) {
        try {
          const tubeDataWithLocation = { ...formData, location };
          const result = await submitTube(tubeDataWithLocation, location);

          if (result.success) {
            successCount++;
          } else {
            errorCount++;
            errors.push(`Position ${location.position}: ${result.error ?? 'Unknown error'}`);
          }
        } catch (error) {
          errorCount++;
          errors.push(`Position ${location.position}: ${error instanceof Error ? error.message : 'Unknown error'}`);
        }
      }

      // Process occupied positions (updates) - only if user explicitly allowed overwrite
      if (allowOverwrite) {
        for (const { location, tubeId } of positionAnalysis.occupiedPositions) {
          try {
            await updateTubeMutation.mutateAsync({
              id: tubeId,
              updates: {
                sample: formData.sample as any,
                researcherId: formData.researcherId as any
              }
            });
            successCount++;
          } catch (error) {
            errorCount++;
            errors.push(`Position ${location.position}: ${error instanceof Error ? error.message : 'Unknown error'}`);
          }
        }
      }

      // Provide comprehensive user feedback
      if (successCount === parsedPositions.length) {
        const createCount = positionAnalysis.emptyPositions.length;
        const updateCount = positionAnalysis.occupiedPositions.length;

        // Build position range display for notification
        const positionRange = batchLocationDisplay?.positionRanges ?? '';

        if (createCount > 0 && updateCount > 0) {
          notifications.create(`Successfully filled ${successCount} positions (${createCount} new, ${updateCount} updated) at ${positionRange}`); // Minty Frost
        } else if (createCount > 0) {
          const message = successCount > 1
            ? `Successfully created ${successCount} tubes at positions ${positionRange}`
            : `Successfully created tube at position ${positionRange}`;
          notifications.create(message); // Minty Frost
        } else {
          const message = successCount > 1
            ? `Successfully updated ${successCount} tubes at positions ${positionRange}`
            : `Successfully updated tube at position ${positionRange}`;
          notifications.update(message); // Minty Frost
        }
        onClose();
      } else if (successCount > 0) {
        notifications.warning(
          `Processed ${successCount} of ${parsedPositions.length} positions. ${errorCount} failed.`
        );
        if (errors.length > 0) {
          console.warn('Tube operation errors:', errors);
        }
      } else {
        notifications.error('Failed to process any positions');
        if (errors.length > 0) {
          notifications.error(errors[0]);
        }
      }

    } catch (error) {
      console.error('Tube creation error:', error);
      notifications.error('An unexpected error occurred during tube creation');
    }
  };

  // Use React Hook Form's built-in validation state (more efficient)
  const isFormValid = form.formState.isValid;

  return (
    <BaseModal
      title={`Add ${parsedPositions.length > 1 ? parsedPositions.length : ''} Tube${parsedPositions.length > 1 ? 's' : ''}`}
      icon={<Plus className="w-5 h-5 text-white" />}
      onClose={onClose}
      dataAttribute="data-tube-modal"
      mode="create"
    >
      <form onSubmit={form.handleSubmit(handleFormSubmit)} className="space-y-4">
            {/* Location Display */}
            {parsedPositions.length === 1 && parsedPositions[0] && (
              <LocationDisplay
                tankId={parsedPositions[0].location.tankId}
                rackId={parsedPositions[0].location.rackId}
                boxId={parsedPositions[0].location.boxId}
                position={parsedPositions[0].location.position}
              />
            )}
            {parsedPositions.length > 1 && batchLocationDisplay && (
              <div className="flex items-center gap-2 px-3 py-2 bg-gradient-to-br from-teal-50 to-cyan-50 border-2 border-teal-500 rounded-lg shadow-md">
                <MapPin className="w-4 h-4 text-teal-500 flex-shrink-0" />
                <div className="flex items-center gap-2 text-sm font-medium text-odysseus-dark">
                  <span className="font-semibold">{batchLocationDisplay.tankName}</span>
                  <span className="text-odysseus-muted">•</span>
                  <span>{batchLocationDisplay.rackName}</span>
                  <span className="text-odysseus-muted">•</span>
                  <span>{batchLocationDisplay.boxName}</span>
                  <span className="text-odysseus-muted">•</span>
                  <span className="font-semibold">Positions {batchLocationDisplay.positionRanges}</span>
                </div>
              </div>
            )}

            {/* Mixed Selection Warning */}
            {positionAnalysis.isMixed && (
              <div className="alert-warning">
                <div className="flex items-start space-x-3">
                  <AlertTriangle className="w-5 h-5 alert-warning-icon flex-shrink-0 mt-0.5" />
                  <div className="flex-1">
                    <h3 className="alert-warning-heading mb-1">
                      Mixed Selection Detected
                    </h3>
                    <p className="alert-warning-text mb-3">
                      You&apos;ve selected {positionAnalysis.emptyPositions.length} empty and {positionAnalysis.occupiedPositions.length} occupied position{positionAnalysis.occupiedPositions.length > 1 ? 's' : ''}.
                      By default, only empty positions will be filled.
                    </p>
                    <label className="flex items-center space-x-2 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={allowOverwrite}
                        onChange={(e) => setAllowOverwrite(e.target.checked)}
                        className="w-4 h-4 text-warning-text border-warning-border rounded focus:ring-warning-bg"
                      />
                      <span className="text-sm font-medium alert-warning-heading">
                        Overwrite occupied positions (this will replace existing tube data)
                      </span>
                    </label>
                  </div>
                </div>
              </div>
            )}

            <TubeForm
              control={form.control as any}
              register={form.register as any}
              errors={form.formState.errors as any}
              trigger={form.trigger as any}
              researchers={researchers}
              isLoading={isSubmitting}
            />

            {/* Form Actions */}
            <div className="flex justify-end space-x-4 pt-4 border-t border-odysseus-border">
              <button
                type="button"
                onClick={onClose}
                className="btn btn-secondary px-6"
                disabled={isSubmitting}
              >
                Cancel
              </button>
              <button
                type="submit"
                className={`btn px-8 ${isFormValid ? 'btn-primary' : 'btn-secondary'}`}
                disabled={isSubmitting || !isFormValid}
              >
                {isSubmitting ? (
                  <div className="flex items-center space-x-2">
                    <div className="spinner w-4 h-4"></div>
                    <span>Adding...</span>
                  </div>
                ) : (
                  <>
                    <Plus className="w-4 h-4 mr-2" />
                    {parsedPositions.length === 1 ? 'Add Tube' : `Add ${parsedPositions.length} Tubes`}
                  </>
                )}
              </button>
            </div>
          </form>
    </BaseModal>
  );
}

import React from 'react';

import { AlertCircle, AlertTriangle } from 'lucide-react';

import { formatToScientificNotation, isScientificNotationInput } from '@shared/utils/scientificNotation';

interface ConcentrationFieldProps {
  label: string;
  value: string;
  unitValue: string;
  onChange: (value: string) => void;
  onUnitChange: (unit: string) => void;
  placeholder?: string;
  disabled?: boolean;
  validation?: {
    error: boolean;
    warning: boolean;
    helperText: string | undefined;
    onBlur: () => void;
  };
  className?: string;
}

export function ConcentrationInput({
  label,
  value,
  unitValue,
  onChange,
  onUnitChange,
  placeholder = 'e.g., 5e6',
  disabled = false,
  validation,
  className = ''
}: ConcentrationFieldProps) {
  
  const unitOptions = [
    { value: '', label: '--' },
    { value: 'c/v', label: 'c/v' },
    { value: 'c/mL', label: 'c/mL' }
  ];

  const getInputClasses = () => {
    if (validation?.error) {
      return 'input-field input-field-error';
    } else if (validation?.warning) {
      return 'input-field border-2 border-validation-warning-border bg-validation-warning-bg text-validation-warning-text';
    } else if (value && !validation?.error && !validation?.warning) {
      return 'input-field input-field-normal border-validation-success-border bg-validation-success-bg';
    } else {
      return 'input-field input-field-normal';
    }
  };

  const getLabelClasses = () => {
    const baseClasses = 'block text-sm font-medium mb-1';

    if (validation?.error) {
      return `${baseClasses} text-validation-error-label`;
    } else if (validation?.warning) {
      return `${baseClasses} text-validation-warning-label`;
    } else {
      return `${baseClasses} text-odysseus-secondary`;
    }
  };

  // Format to scientific notation when appropriate
  const handleFormat = (inputValue: string): string => {
    if (!inputValue || inputValue.trim() === '') return inputValue;
    
    // If it's already in scientific notation format, keep it
    if (isScientificNotationInput(inputValue) || inputValue.includes('E')) {
      return inputValue;
    }
    
    // If it's a large number, format to scientific notation
    const numValue = parseFloat(inputValue);
    if (!isNaN(numValue) && numValue >= 1000) {
      return formatToScientificNotation(inputValue);
    }
    
    return inputValue;
  };

  const handleInputChange = (newValue: string) => {
    onChange(newValue);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      const target = e.target as HTMLInputElement;
      const formatted = handleFormat(target.value);
      if (formatted !== target.value) {
        onChange(formatted);
      }
    }
  };

  const handleBlur = () => {
    const formatted = handleFormat(value);
    if (formatted !== value) {
      onChange(formatted);
    }
    
    // Call validation onBlur if provided
    if (validation?.onBlur) {
      validation.onBlur();
    }
  };

  return (
    <div className={className}>
      <label className={getLabelClasses()}>
        {label}
      </label>
      
      <div className="flex gap-1">
        <input
          type="text"
          value={value}
          onChange={(e) => handleInputChange(e.target.value)}
          onBlur={handleBlur}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          disabled={disabled}
          className={`${getInputClasses()} flex-[7] min-w-0`}
        />
        
        <select
          value={unitValue}
          onChange={(e) => onUnitChange(e.target.value)}
          disabled={disabled}
          className={`${getInputClasses()} flex-[3] relative z-50`}
        >
          {unitOptions.map(option => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
      </div>
      
      {validation?.helperText && (
        <div className={`
          flex items-center mt-1 text-xs
          ${validation.error
            ? 'text-validation-error-helper'
            : validation.warning
            ? 'text-validation-warning-helper'
            : 'text-odysseus-muted'
          }
        `}>
          {validation.error && <AlertCircle className="w-4 h-4 mr-1 flex-shrink-0 text-validation-error-icon" />}
          {validation.warning && <AlertTriangle className="w-4 h-4 mr-1 flex-shrink-0 text-validation-warning-icon" />}
          <span>{validation.helperText}</span>
        </div>
      )}
    </div>
  );
}

