/**
 * Keyboard Navigation Hook
 *
 * Industry-standard keyboard navigation for grid components
 * Supports arrow key navigation, multi-selection, and accessibility
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { type PositionKey } from '@shared/types/grid';

// Grid position interface
export interface GridPosition {
  row: number;
  column: number;
}

// Selection range interface
export interface SelectionRange {
  start: GridPosition;
  end: GridPosition;
}

// Keyboard navigation configuration
export interface KeyboardNavigationConfig {
  // Grid dimensions
  rows: number;
  columns: number;
  
  // Behavior
  enableMultiSelect?: boolean;
  enableRangeSelect?: boolean;
  enableSelectAll?: boolean;
  wrapNavigation?: boolean; // Wrap to next/previous row
  
  // Callbacks
  onPositionChange?: (position: GridPosition) => void;
  onSelect?: (position: GridPosition, isSelected: boolean) => void;
  onMultiSelect?: (positions: GridPosition[]) => void;
  onRangeSelect?: (range: SelectionRange) => void;
  onSelectAll?: () => void;
  onClearSelection?: () => void;
  
  // Focus management
  autoFocus?: boolean;
  focusOnMount?: boolean;
  
  // Custom key bindings
  customKeys?: Record<string, (position: GridPosition, event: KeyboardEvent) => void>;
}

// Default configuration
const defaultConfig: Partial<KeyboardNavigationConfig> = {
  enableMultiSelect: true,
  enableRangeSelect: true,
  enableSelectAll: true,
  wrapNavigation: false,
  autoFocus: true,
  focusOnMount: false,
};

// Utility functions
const isValidPosition = (position: GridPosition, rows: number, columns: number): boolean => {
  return position.row >= 0 && position.row < rows && 
         position.column >= 0 && position.column < columns;
};

const getPositionsInRange = (start: GridPosition, end: GridPosition): GridPosition[] => {
  const positions: GridPosition[] = [];
  
  const minRow = Math.min(start.row, end.row);
  const maxRow = Math.max(start.row, end.row);
  const minCol = Math.min(start.column, end.column);
  const maxCol = Math.max(start.column, end.column);
  
  for (let row = minRow; row <= maxRow; row++) {
    for (let col = minCol; col <= maxCol; col++) {
      positions.push({ row, column: col });
    }
  }
  
  return positions;
};

// Main keyboard navigation hook
export const useKeyboardNavigation = (config: KeyboardNavigationConfig) => {
  // Memoize finalConfig to prevent infinite loops in hook dependencies
  const finalConfig = useMemo(
    () => ({ ...defaultConfig, ...config }),
    [config]
  );
  const containerRef = useRef<HTMLElement>(null);
  
  // Current focused position
  const [focusedPosition, setFocusedPosition] = useState<GridPosition>({ row: 0, column: 0 });
  
  // Range selection anchor (for shift+click selections)
  const [rangeAnchor, setRangeAnchor] = useState<GridPosition | null>(null);
  
  // Track modifier keys
  const [modifierKeys, setModifierKeys] = useState({
    shift: false,
    ctrl: false,
    alt: false,
  });
  
  // Update focused position with bounds checking
  const updateFocusedPosition = useCallback((newPosition: GridPosition) => {
    if (isValidPosition(newPosition, finalConfig.rows, finalConfig.columns)) {
      setFocusedPosition(newPosition);
      finalConfig.onPositionChange?.(newPosition);
      return true;
    }
    return false;
  }, [finalConfig]);
  
  // Navigate in a direction
  const navigate = useCallback((direction: 'up' | 'down' | 'left' | 'right') => {
    const { row, column } = focusedPosition;
    let newPosition: GridPosition;
    
    switch (direction) {
      case 'up':
        newPosition = { row: row - 1, column };
        break;
      case 'down':
        newPosition = { row: row + 1, column };
        break;
      case 'left':
        newPosition = { row, column: column - 1 };
        break;
      case 'right':
        newPosition = { row, column: column + 1 };
        break;
    }
    
    // Handle wrapping navigation
    if (finalConfig.wrapNavigation && !isValidPosition(newPosition, finalConfig.rows, finalConfig.columns)) {
      switch (direction) {
        case 'up':
          if (row === 0) {
            newPosition = { row: finalConfig.rows - 1, column };
          }
          break;
        case 'down':
          if (row === finalConfig.rows - 1) {
            newPosition = { row: 0, column };
          }
          break;
        case 'left':
          if (column === 0) {
            newPosition = { row, column: finalConfig.columns - 1 };
          }
          break;
        case 'right':
          if (column === finalConfig.columns - 1) {
            newPosition = { row, column: 0 };
          }
          break;
      }
    }
    
    return updateFocusedPosition(newPosition);
  }, [focusedPosition, finalConfig, updateFocusedPosition]);
  
  // Handle selection
  const handleSelect = useCallback((position: GridPosition, extend = false) => {
    if (extend && finalConfig.enableRangeSelect && rangeAnchor) {
      // Range selection - keep anchor, extend to new position
      const range: SelectionRange = {
        start: rangeAnchor,
        end: position,
      };

      const positions = getPositionsInRange(range.start, range.end);
      finalConfig.onMultiSelect?.(positions);
      finalConfig.onRangeSelect?.(range);
      // Don't update anchor during range selection
    } else {
      // Single selection - set new anchor
      finalConfig.onSelect?.(position, true);

      // Only set anchor when NOT extending (starting new selection)
      if (finalConfig.enableRangeSelect && !extend) {
        setRangeAnchor(position);
      }
    }
  }, [finalConfig, rangeAnchor]);
  
  // Handle keyboard events
  const handleKeyDown = useCallback((event: KeyboardEvent) => {
    // Update modifier key state
    setModifierKeys({
      shift: event.shiftKey,
      ctrl: event.ctrlKey || event.metaKey,
      alt: event.altKey,
    });
    
    // Handle navigation keys
    switch (event.key) {
      case 'ArrowUp':
        event.preventDefault();
        if (navigate('up') && event.shiftKey && finalConfig.enableRangeSelect) {
          handleSelect(focusedPosition, true);
        }
        break;
        
      case 'ArrowDown':
        event.preventDefault();
        if (navigate('down') && event.shiftKey && finalConfig.enableRangeSelect) {
          handleSelect(focusedPosition, true);
        }
        break;
        
      case 'ArrowLeft':
        event.preventDefault();
        if (navigate('left') && event.shiftKey && finalConfig.enableRangeSelect) {
          handleSelect(focusedPosition, true);
        }
        break;
        
      case 'ArrowRight':
        event.preventDefault();
        if (navigate('right') && event.shiftKey && finalConfig.enableRangeSelect) {
          handleSelect(focusedPosition, true);
        }
        break;
        
      case 'Enter':
      case ' ':
        event.preventDefault();
        handleSelect(focusedPosition, event.shiftKey);
        break;
        
      case 'Home':
        event.preventDefault();
        updateFocusedPosition({ row: 0, column: 0 });
        break;
        
      case 'End':
        event.preventDefault();
        updateFocusedPosition({ 
          row: finalConfig.rows - 1, 
          column: finalConfig.columns - 1 
        });
        break;
        
      case 'PageUp': {
        event.preventDefault();
        const pageUpRow = Math.max(0, focusedPosition.row - Math.floor(finalConfig.rows / 3));
        updateFocusedPosition({ ...focusedPosition, row: pageUpRow });
        break;
      }

      case 'PageDown': {
        event.preventDefault();
        const pageDownRow = Math.min(finalConfig.rows - 1, focusedPosition.row + Math.floor(finalConfig.rows / 3));
        updateFocusedPosition({ ...focusedPosition, row: pageDownRow });
        break;
      }
        
      case 'a':
      case 'A':
        if ((event.ctrlKey || event.metaKey) && finalConfig.enableSelectAll) {
          event.preventDefault();
          finalConfig.onSelectAll?.();
        }
        break;
        
      case 'Escape':
        event.preventDefault();
        finalConfig.onClearSelection?.();
        setRangeAnchor(null);
        break;
        
      default:
        // Handle custom key bindings
        if (finalConfig.customKeys?.[event.key]) {
          event.preventDefault();
          finalConfig.customKeys[event.key](focusedPosition, event);
        }
        break;
    }
  }, [navigate, handleSelect, focusedPosition, finalConfig, updateFocusedPosition]);
  
  // Handle keyboard events on key up to reset modifier state
  const handleKeyUp = useCallback((event: KeyboardEvent) => {
    setModifierKeys({
      shift: event.shiftKey,
      ctrl: event.ctrlKey || event.metaKey,
      alt: event.altKey,
    });
  }, []);
  
  // Attach event listeners
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    
    container.addEventListener('keydown', handleKeyDown);
    container.addEventListener('keyup', handleKeyUp);
    
    // Make container focusable
    if (!container.hasAttribute('tabindex')) {
      container.setAttribute('tabindex', '0');
    }
    
    // Focus on mount if configured
    if (finalConfig.focusOnMount) {
      container.focus();
    }
    
    return () => {
      container.removeEventListener('keydown', handleKeyDown);
      container.removeEventListener('keyup', handleKeyUp);
    };
  }, [handleKeyDown, handleKeyUp, finalConfig.focusOnMount]);
  
  // Focus cell programmatically
  const focusPosition = useCallback((position: GridPosition) => {
    updateFocusedPosition(position);
    
    // Focus the actual cell element if it exists
    const container = containerRef.current;
    if (container) {
      const cellSelector = `[data-grid-position="${position.row}-${position.column}"]`;
      const cellElement = container.querySelector(cellSelector) as HTMLElement;
      if (cellElement) {
        cellElement.focus();
      }
    }
  }, [updateFocusedPosition]);
  
  // Get position properties for a cell
  const getCellProps = useCallback((row: number, column: number) => {
    const position = { row, column };
    const isFocused = focusedPosition.row === row && focusedPosition.column === column;
    
    return {
      'data-grid-position': `${row}-${column}`,
      tabIndex: isFocused ? 0 : -1,
      role: 'gridcell',
      'aria-rowindex': row + 1, // 1-based for ARIA
      'aria-colindex': column + 1, // 1-based for ARIA
      onFocus: () => updateFocusedPosition(position),
      onClick: (e: React.MouseEvent) => {
        updateFocusedPosition(position);
        
        if (e.shiftKey && finalConfig.enableRangeSelect && rangeAnchor) {
          handleSelect(position, true);
        } else {
          handleSelect(position, e.ctrlKey || e.metaKey);
        }
      },
    };
  }, [focusedPosition, updateFocusedPosition, handleSelect, finalConfig.enableRangeSelect, rangeAnchor]);
  
  // Get container props
  const getContainerProps = useCallback(() => ({
    ref: containerRef,
    role: 'grid',
    'aria-rowcount': finalConfig.rows,
    'aria-colcount': finalConfig.columns,
    'aria-multiselectable': finalConfig.enableMultiSelect,
    tabIndex: 0,
    onFocus: () => {
      // Auto-focus first cell if no cell is focused
      if (finalConfig.autoFocus) {
        focusPosition(focusedPosition);
      }
    },
  }), [finalConfig, focusedPosition, focusPosition]);
  
  return {
    // State
    focusedPosition,
    modifierKeys,
    rangeAnchor,
    
    // Actions
    navigate,
    focusPosition,
    updateFocusedPosition,
    
    // Props helpers
    getCellProps,
    getContainerProps,
    
    // Ref
    containerRef,
  };
};

// Specialized hook for tube grid navigation
export const useTubeGridKeyboardNavigation = (
  rows: number = 9,
  columns: number = 9,
  selectedPositions: Set<PositionKey>,
  onSelectionChange: (positions: Set<PositionKey>) => void,
  positionIdGenerator: (row: number, column: number) => PositionKey
) => {
  // Convert grid positions to position IDs
  const handleSelect = useCallback((position: GridPosition, isSelected: boolean) => {
    const positionId = positionIdGenerator(position.row, position.column);
    const newSelection = new Set(selectedPositions);
    
    if (isSelected) {
      newSelection.add(positionId);
    } else {
      newSelection.delete(positionId);
    }
    
    onSelectionChange(newSelection);
  }, [selectedPositions, onSelectionChange, positionIdGenerator]);
  
  const handleMultiSelect = useCallback((positions: GridPosition[]) => {
    const newSelection = new Set(selectedPositions);
    
    positions.forEach(position => {
      const positionId = positionIdGenerator(position.row, position.column);
      newSelection.add(positionId);
    });
    
    onSelectionChange(newSelection);
  }, [selectedPositions, onSelectionChange, positionIdGenerator]);
  
  const handleSelectAll = useCallback(() => {
    const allPositions = new Set<PositionKey>();

    for (let row = 0; row < rows; row++) {
      for (let column = 0; column < columns; column++) {
        const positionId = positionIdGenerator(row, column);
        allPositions.add(positionId);
      }
    }

    onSelectionChange(allPositions);
  }, [rows, columns, positionIdGenerator, onSelectionChange]);
  
  const handleClearSelection = useCallback(() => {
    onSelectionChange(new Set());
  }, [onSelectionChange]);
  
  // Use base keyboard navigation
  const navigation = useKeyboardNavigation({
    rows,
    columns,
    enableMultiSelect: true,
    enableRangeSelect: true,
    enableSelectAll: true,
    onSelect: handleSelect,
    onMultiSelect: handleMultiSelect,
    onSelectAll: handleSelectAll,
    onClearSelection: handleClearSelection,
  });
  
  // Enhanced cell props for tube grid
  const getTubeCellProps = useCallback((row: number, column: number, tubeId?: string) => {
    const baseCellProps = navigation.getCellProps(row, column);
    const positionId = positionIdGenerator(row, column);
    const isSelected = selectedPositions.has(positionId);

    return {
      ...baseCellProps,
      'aria-selected': isSelected,
      'aria-label': tubeId
        ? `Tube ${tubeId} at position ${row + 1}-${column + 1}${isSelected ? ', selected' : ''}`
        : `Empty position ${row + 1}-${column + 1}${isSelected ? ', selected' : ''}`,
      'data-tube-id': tubeId,
      'data-position-id': positionId,
      'data-selected': isSelected,
    };
  }, [navigation, selectedPositions, positionIdGenerator]);
  
  return {
    ...navigation,
    getTubeCellProps,
    selectedCount: selectedPositions.size,
  };
};

// Hook for list/results keyboard navigation
export const useListKeyboardNavigation = <T, TElement extends HTMLElement = HTMLDivElement>(
  items: T[],
  onSelect: (item: T, index: number) => void,
  multiSelect = false
) => {
  const [focusedIndex, setFocusedIndex] = useState(0);
  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());
  const containerRef = useRef<TElement>(null);
  
  const handleKeyDown = useCallback((event: KeyboardEvent) => {
    switch (event.key) {
      case 'ArrowUp':
        event.preventDefault();
        setFocusedIndex(prev => Math.max(0, prev - 1));
        break;
        
      case 'ArrowDown':
        event.preventDefault();
        setFocusedIndex(prev => Math.min(items.length - 1, prev + 1));
        break;
        
      case 'Home':
        event.preventDefault();
        setFocusedIndex(0);
        break;
        
      case 'End':
        event.preventDefault();
        setFocusedIndex(items.length - 1);
        break;
        
      case 'Enter':
      case ' ':
        event.preventDefault();
        if (items[focusedIndex]) {
          onSelect(items[focusedIndex], focusedIndex);
          
          if (multiSelect) {
            const newSelection = new Set(selectedIndices);
            if (newSelection.has(focusedIndex)) {
              newSelection.delete(focusedIndex);
            } else {
              newSelection.add(focusedIndex);
            }
            setSelectedIndices(newSelection);
          }
        }
        break;
        
      case 'a':
      case 'A':
        if ((event.ctrlKey || event.metaKey) && multiSelect) {
          event.preventDefault();
          const allIndices = new Set(Array.from({ length: items.length }, (_, i) => i));
          setSelectedIndices(allIndices);
        }
        break;
        
      case 'Escape':
        event.preventDefault();
        setSelectedIndices(new Set());
        break;
    }
  }, [items, focusedIndex, onSelect, multiSelect, selectedIndices]);
  
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    
    container.addEventListener('keydown', handleKeyDown);
    
    if (!container.hasAttribute('tabindex')) {
      container.setAttribute('tabindex', '0');
    }
    
    return () => {
      container.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleKeyDown]);
  
  const getItemProps = useCallback((index: number) => ({
    'data-index': index,
    tabIndex: focusedIndex === index ? 0 : -1,
    role: 'option',
    'aria-selected': selectedIndices.has(index),
    onFocus: () => setFocusedIndex(index),
  }), [focusedIndex, selectedIndices]);
  
  const getContainerProps = useCallback(() => ({
    ref: containerRef,
    role: 'listbox',
    'aria-multiselectable': multiSelect,
    'aria-activedescendant': `item-${focusedIndex}`,
    tabIndex: 0,
  }), [multiSelect, focusedIndex]);
  
  return {
    focusedIndex,
    selectedIndices,
    getItemProps,
    getContainerProps,
    containerRef,
  };
};

/**
 * Modal Keyboard Navigation Hook
 *
 * Industry-standard keyboard shortcuts for modals:
 * - Escape: Close/Cancel
 * - Enter: Handled naturally by HTML <form> elements (not intercepted)
 *
 * Zero technical debt, follows existing keyboard navigation patterns
 *
 * Design Principle: Don't interfere with native browser behavior.
 * HTML forms handle Enter → submit naturally since 1993.
 * React Hook Form leverages this built-in behavior.
 * This hook only adds modal-specific enhancements (Escape to close).
 */

import { useEffect, useCallback } from 'react';

export interface ModalKeyboardNavConfig {
  onEnter?: () => void;  // Deprecated - forms should handle Enter naturally
  onEscape?: () => void;
  enabled?: boolean;
  preventDefaultEnter?: boolean;  // Deprecated
  preventDefaultEscape?: boolean;
}

/**
 * Hook for handling keyboard navigation in modals
 * @param config - Configuration for keyboard handlers
 */
export function useModalKeyboardNav(config: ModalKeyboardNavConfig) {
  const {
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    onEnter,
    onEscape,
    enabled = true,
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    preventDefaultEnter = true,
    preventDefaultEscape = true,
  } = config;

  const handleKeyDown = useCallback((event: KeyboardEvent) => {
    if (!enabled) return;

    switch (event.key) {
      case 'Escape':
        // Allow Escape to work even when focused on inputs
        if (preventDefaultEscape) {
          event.preventDefault();
        }
        onEscape?.();
        break;
    }
  }, [enabled, onEscape, preventDefaultEscape]);

  useEffect(() => {
    if (!enabled) return;

    // Attach to document to capture all keyboard events
    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [handleKeyDown, enabled]);

  return {
    enabled,
  };
}

/**
 * Tab Order Hook
 * 
 * Manages logical tab order for forms and complex interfaces
 * Ensures keyboard navigation follows intuitive patterns
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

// Tab order item interface
export interface TabOrderItem {
  id: string;
  element: HTMLElement;
  order: number;
  group?: string; // Optional grouping for complex forms
  disabled?: boolean;
}

// Tab order configuration
export interface TabOrderConfig {
  // Behavior
  autoManage?: boolean; // Automatically manage tab indices
  wrapAround?: boolean; // Wrap to first/last when reaching end
  respectGroups?: boolean; // Navigate within groups first

  // Custom navigation
  customNavigation?: Record<string, (currentItem: TabOrderItem, direction: 'forward' | 'backward') => TabOrderItem | null>;

  // Callbacks
  onTabOrderChange?: (items: TabOrderItem[]) => void;
  onFocusChange?: (item: TabOrderItem | null) => void;

  // Skip conditions
  skipDisabled?: boolean;
  skipHidden?: boolean;
}

// Default configuration
const defaultConfig: TabOrderConfig = {
  autoManage: true,
  wrapAround: false,
  respectGroups: false,
  skipDisabled: true,
  skipHidden: true,
};

// Main tab order hook
export const useTabOrder = (config: TabOrderConfig = {}) => {
  // Memoize finalConfig to prevent infinite loops in hook dependencies
  const finalConfig = useMemo(
    () => ({ ...defaultConfig, ...config }),
    [config]
  );
  const containerRef = useRef<HTMLElement>(null);
  const [tabOrderItems, setTabOrderItems] = useState<TabOrderItem[]>([]);
  const [currentFocusedItem, setCurrentFocusedItem] = useState<TabOrderItem | null>(null);
  const observerRef = useRef<MutationObserver | null>(null);

  // Check if element should be included in tab order
  const shouldIncludeElement = useCallback((element: HTMLElement): boolean => {
    if (finalConfig.skipDisabled && element.hasAttribute('disabled')) {
      return false;
    }

    if (finalConfig.skipHidden) {
      const style = window.getComputedStyle(element);
      if (style.display === 'none' || style.visibility === 'hidden') {
        return false;
      }

      if (element.offsetWidth === 0 && element.offsetHeight === 0) {
        return false;
      }
    }

    return true;
  }, [finalConfig.skipDisabled, finalConfig.skipHidden]);

  // Discover focusable elements and build tab order
  const buildTabOrder = useCallback(() => {
    const container = containerRef.current;
    if (!container) return [];

    const focusableElements = Array.from(
      container.querySelectorAll([
        'button',
        'input',
        'textarea', 
        'select',
        'a[href]',
        '[tabindex]',
        '[contenteditable="true"]',
      ].join(', '))
    ) as HTMLElement[];

    const items: TabOrderItem[] = [];

    focusableElements.forEach((element, index) => {
      if (!shouldIncludeElement(element)) return;

      const tabIndex = element.getAttribute('tabindex');
      const dataOrder = element.getAttribute('data-tab-order');
      const dataGroup = element.getAttribute('data-tab-group');

      // Determine tab order
      let order: number;
      if (dataOrder) {
        order = parseInt(dataOrder, 10);
      } else if (tabIndex && tabIndex !== '0') {
        order = parseInt(tabIndex, 10);
      } else {
        order = index; // Natural DOM order
      }

      items.push({
        id: element.id || `tab-item-${index}`,
        element,
        order,
        group: dataGroup || undefined,
        disabled: element.hasAttribute('disabled'),
      });
    });

    // Sort by order, then by group if respecting groups
    items.sort((a, b) => {
      if (finalConfig.respectGroups && a.group !== b.group) {
        if (!a.group) return 1;
        if (!b.group) return -1;
        return a.group.localeCompare(b.group);
      }
      return a.order - b.order;
    });

    return items;
  }, [shouldIncludeElement, finalConfig.respectGroups]);

  // Update tab order
  const updateTabOrder = useCallback(() => {
    const items = buildTabOrder();
    setTabOrderItems(items);
    finalConfig.onTabOrderChange?.(items);

    // Auto-manage tab indices if enabled
    if (finalConfig.autoManage) {
      items.forEach((item, index) => {
        item.element.setAttribute('tabindex', index === 0 ? '0' : '-1');
      });
    }

    return items;
  }, [buildTabOrder, finalConfig]);

  // Navigate to specific item
  const navigateToItem = useCallback((item: TabOrderItem) => {
    if (shouldIncludeElement(item.element)) {
      item.element.focus();
      setCurrentFocusedItem(item);
      finalConfig.onFocusChange?.(item);
    }
  }, [shouldIncludeElement, finalConfig]);

  // Navigate to next/previous item
  const navigate = useCallback((direction: 'forward' | 'backward') => {
    const currentIndex = currentFocusedItem 
      ? tabOrderItems.findIndex(item => item.id === currentFocusedItem.id)
      : -1;

    let nextIndex: number;

    if (direction === 'forward') {
      nextIndex = currentIndex + 1;
      if (nextIndex >= tabOrderItems.length) {
        nextIndex = finalConfig.wrapAround ? 0 : tabOrderItems.length - 1;
      }
    } else {
      nextIndex = currentIndex - 1;
      if (nextIndex < 0) {
        nextIndex = finalConfig.wrapAround ? tabOrderItems.length - 1 : 0;
      }
    }

    const nextItem = tabOrderItems[nextIndex];
    if (nextItem) {
      navigateToItem(nextItem);
    }
  }, [currentFocusedItem, tabOrderItems, finalConfig.wrapAround, navigateToItem]);

  // Navigate to first/last item
  const navigateToFirst = useCallback(() => {
    const firstItem = tabOrderItems[0];
    if (firstItem) {
      navigateToItem(firstItem);
    }
  }, [tabOrderItems, navigateToItem]);

  const navigateToLast = useCallback(() => {
    const lastItem = tabOrderItems[tabOrderItems.length - 1];
    if (lastItem) {
      navigateToItem(lastItem);
    }
  }, [tabOrderItems, navigateToItem]);

  // Navigate within group
  const navigateWithinGroup = useCallback((groupName: string, direction: 'forward' | 'backward') => {
    const groupItems = tabOrderItems.filter(item => item.group === groupName);
    const currentIndex = currentFocusedItem && currentFocusedItem.group === groupName
      ? groupItems.findIndex(item => item.id === currentFocusedItem.id)
      : -1;

    let nextIndex: number;

    if (direction === 'forward') {
      nextIndex = currentIndex + 1;
      if (nextIndex >= groupItems.length) {
        nextIndex = finalConfig.wrapAround ? 0 : groupItems.length - 1;
      }
    } else {
      nextIndex = currentIndex - 1;
      if (nextIndex < 0) {
        nextIndex = finalConfig.wrapAround ? groupItems.length - 1 : 0;
      }
    }

    const nextItem = groupItems[nextIndex];
    if (nextItem) {
      navigateToItem(nextItem);
    }
  }, [tabOrderItems, currentFocusedItem, finalConfig.wrapAround, navigateToItem]);

  // Setup mutation observer to watch for DOM changes
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Initial setup
    updateTabOrder();

    // Watch for DOM changes
    observerRef.current = new MutationObserver(() => {
      updateTabOrder();
    });

    observerRef.current.observe(container, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['disabled', 'tabindex', 'data-tab-order', 'data-tab-group'],
    });

    return () => {
      if (observerRef.current) {
        observerRef.current.disconnect();
      }
    };
  }, [updateTabOrder]);

  // Handle focus events to track current item
  useEffect(() => {
    const handleFocusIn = (event: FocusEvent) => {
      const target = event.target as HTMLElement;
      const item = tabOrderItems.find(item => item.element === target);

      if (item) {
        setCurrentFocusedItem(item);
        finalConfig.onFocusChange?.(item);
      }
    };

    const container = containerRef.current;
    if (container) {
      container.addEventListener('focusin', handleFocusIn);

      return () => {
        container.removeEventListener('focusin', handleFocusIn);
      };
    }

    // Return undefined explicitly when container is not available
    return undefined;
  }, [tabOrderItems, finalConfig]);

  // Get props for container
  const getContainerProps = useCallback(() => ({
    ref: containerRef,
  }), []);

  // Get props for tab order item
  const getItemProps = useCallback((id: string, order?: number, group?: string) => {
    const isCurrent = currentFocusedItem?.id === id;

    return {
      id,
      'data-tab-order': order,
      'data-tab-group': group,
      tabIndex: isCurrent ? 0 : -1,
      onFocus: () => {
        const foundItem = tabOrderItems.find(item => item.id === id);
        if (foundItem) {
          setCurrentFocusedItem(foundItem);
          finalConfig.onFocusChange?.(foundItem);
        }
      },
    };
  }, [tabOrderItems, currentFocusedItem, finalConfig]);

  return {
    // State
    tabOrderItems,
    currentFocusedItem,

    // Navigation
    navigate,
    navigateToFirst,
    navigateToLast,
    navigateWithinGroup,
    navigateToItem,

    // Management
    updateTabOrder,
    buildTabOrder,

    // Props helpers
    getContainerProps,
    getItemProps,

    // Refs
    containerRef,
  };
};

// Form-specific tab order hook
export const useFormTabOrder = (formRef: React.RefObject<HTMLFormElement>) => {
  const tabOrder = useTabOrder({
    autoManage: true,
    respectGroups: true,
    skipDisabled: true,
    skipHidden: true,
  });

  // Sync container ref with form ref - using mutable ref pattern
  useEffect(() => {
    if (formRef.current && tabOrder.containerRef) {
      // Use type assertion to bypass readonly restriction safely
      (tabOrder.containerRef as React.MutableRefObject<HTMLElement | null>).current = formRef.current;
    }
  }, [formRef, tabOrder.containerRef]);

  // Form-specific navigation
  const navigateToNextField = useCallback(() => {
    tabOrder.navigate('forward');
  }, [tabOrder]);

  const navigateToPreviousField = useCallback(() => {
    tabOrder.navigate('backward');
  }, [tabOrder]);

  const focusFirstInvalidField = useCallback(() => {
    const firstInvalid = formRef.current?.querySelector('[aria-invalid="true"]') as HTMLElement;
    if (firstInvalid) {
      firstInvalid.focus();
      return true;
    }
    return false;
  }, [formRef]);

  return {
    ...tabOrder,
    navigateToNextField,
    navigateToPreviousField,
    focusFirstInvalidField,
  };
};

export default {
  useTabOrder,
  useFormTabOrder,
};

