  value: number | string | { xs?: number | string; sm?: number | string; md?: number | string; lg?: number | string; xl?: number | string } | undefined,
  type: 'columns' | 'rows'
): string => {
  if (!value) return '';
  
  if (typeof value === 'number') {
    const prefix = type === 'columns' ? 'grid-cols' : 'grid-rows';
    return `${prefix}-${value}`;
