/**
 * Input Component Types
 * 
 * Type definitions for accessible Input primitive components
 * Includes text, number, search, and validation functionality
 */

import type { ComponentProps, ReactNode } from 'react';

// Input variant types
export type InputVariant = 
  | 'default'       // Standard input
  | 'filled'        // Filled background input
  | 'outlined'      // Outlined input (default)
  | 'underlined'    // Underlined input
  | 'ghost';        // Minimal input (no border)

// Input size types
export type InputSize = 
  | 'xs'            // Extra small (28px height)
  | 'sm'            // Small (32px height)
  | 'md'            // Medium (40px height) - default
  | 'lg'            // Large (48px height)
  | 'xl';           // Extra large (56px height)

// Input state types
export type InputState = 
  | 'default'       // Normal state
  | 'error'         // Error state
  | 'warning'       // Warning state
  | 'success';      // Success state

// Input types (HTML input types)
export type InputType = 
  | 'text'
  | 'email'
  | 'password'
  | 'number'
  | 'tel'
  | 'url'
  | 'search'
  | 'date'
  | 'time'
  | 'datetime-local'
  | 'month'
  | 'week';

// Validation result
export interface ValidationResult {
  isValid: boolean;
  message?: string;
  type?: 'error' | 'warning' | 'success';
}

// Validation function type
export type ValidationFunction = (value: string) => ValidationResult | Promise<ValidationResult>;

// Base input props (extends HTML input attributes)
export interface BaseInputProps extends Omit<ComponentProps<'input'>, 'size' | 'prefix'> {
  // Appearance
  variant?: InputVariant;
  size?: InputSize;
  state?: InputState;
  
  // Label and description
  label?: string;
  description?: string;
  placeholder?: string;
  
  // Icons and addons
  leftIcon?: ReactNode;
  rightIcon?: ReactNode;
  prefix?: string | ReactNode;
  suffix?: string | ReactNode;
  
  // Validation
  error?: string;
  warning?: string;
  success?: string;
  isRequired?: boolean;
  validate?: ValidationFunction | ValidationFunction[];
  validateOn?: 'blur' | 'change' | 'submit';
  
  // State
  isLoading?: boolean;
  isReadOnly?: boolean;
  isDisabled?: boolean;
  
  // Layout
  fullWidth?: boolean;
  
  // Accessibility
  'aria-label'?: string;
  'aria-describedby'?: string;
  'aria-invalid'?: boolean;
  'aria-required'?: boolean;
  
  // Custom styling
  className?: string;
  inputClassName?: string;
  labelClassName?: string;
  
  // Event handlers
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: ValidationResult) => void;
}

// Input ref type
export type InputRef = HTMLInputElement;

// Main input component props
export interface InputProps extends BaseInputProps {
  type?: InputType;
}

// Text input specific props
export interface TextInputProps extends BaseInputProps {
  type?: 'text' | 'email' | 'password' | 'url' | 'tel';
  autoComplete?: string;
  spellCheck?: boolean;
  maxLength?: number;
  minLength?: number;
  pattern?: string;
}

// Number input specific props
export interface NumberInputProps extends Omit<BaseInputProps, 'type'> {
  type?: 'number';
  min?: number;
  max?: number;
  step?: number | 'any';
  precision?: number;
  allowNegative?: boolean;
  allowDecimal?: boolean;
  thousandSeparator?: boolean;
  currency?: string;
  currencyPosition?: 'prefix' | 'suffix';
}

// Search input specific props
export interface SearchInputProps extends Omit<BaseInputProps, 'type'> {
  type?: 'search';
  onSearch?: (value: string) => void;
  onClear?: () => void;
  showClearButton?: boolean;
  searchDelay?: number; // Debounce delay in ms
  suggestions?: string[];
  onSuggestionSelect?: (suggestion: string) => void;
}

// Date input specific props
export interface DateInputProps extends Omit<BaseInputProps, 'type'> {
  type?: 'date' | 'time' | 'datetime-local' | 'month' | 'week';
  min?: string;
  max?: string;
  format?: string;
  locale?: string;
}

// Password input specific props
export interface PasswordInputProps extends Omit<BaseInputProps, 'type'> {
  type?: 'password';
  showPasswordToggle?: boolean;
  passwordStrength?: boolean;
  strengthIndicator?: 'bar' | 'text' | 'both';
  strengthRules?: {
    minLength?: number;
    requireUppercase?: boolean;
    requireLowercase?: boolean;
    requireNumbers?: boolean;
    requireSpecialChars?: boolean;
  };
}

// Input group props (for grouping related inputs)
export interface InputGroupProps {
  children: ReactNode;
  label?: string;
  description?: string;
  isRequired?: boolean;
  error?: string;
  orientation?: 'horizontal' | 'vertical';
  spacing?: 'none' | 'sm' | 'md' | 'lg';
  className?: string;
}

// Input addon props (for prefix/suffix addons)
export interface InputAddonProps {
  children: ReactNode;
  position: 'left' | 'right';
  className?: string;
}

// Input label props
export interface InputLabelProps {
  children: ReactNode;
  htmlFor?: string;
  isRequired?: boolean;
  className?: string;
}

// Input description props
export interface InputDescriptionProps {
  children: ReactNode;
  id?: string;
  className?: string;
}

// Input error message props
export interface InputErrorProps {
  children: ReactNode;
  id?: string;
  className?: string;
}

// Input style variants (for internal styling)
export interface InputStyleVariants {
  variant: Record<InputVariant, string>;
  size: Record<InputSize, string>;
  state: Record<InputState, string>;
}

// Input theme configuration
export interface InputTheme {
  // Base styles
  base: string;
  
  // Wrapper styles
  wrapper: string;
  
  // Input field styles
  input: string;
  
  // Variant styles
  variants: InputStyleVariants['variant'];
  
  // Size styles
  sizes: InputStyleVariants['size'];
  
  // State styles
  states: InputStyleVariants['state'];
  
  // Label styles
  label: {
    base: string;
    required: string;
    disabled: string;
  };
  
  // Description styles
  description: string;
  
  // Error message styles
  error: string;
  
  // Icon styles
  icons: {
    left: string;
    right: string;
    loading: string;
  };
  
  // Addon styles
  addons: {
    left: string;
    right: string;
  };
}

// Default props
export const defaultInputProps: Partial<InputProps> = {
  type: 'text',
  variant: 'outlined',
  size: 'md',
  state: 'default',
  validateOn: 'blur',
  fullWidth: false,
  isRequired: false,
  isDisabled: false,
  isReadOnly: false,
  isLoading: false,
  spellCheck: true,
};

// Type guards
export const isInputVariant = (value: string): value is InputVariant => {
  return ['default', 'filled', 'outlined', 'underlined', 'ghost'].includes(value);
};

export const isInputSize = (value: string): value is InputSize => {
  return ['xs', 'sm', 'md', 'lg', 'xl'].includes(value);
};

export const isInputState = (value: string): value is InputState => {
  return ['default', 'error', 'warning', 'success'].includes(value);
};

export const isInputType = (value: string): value is InputType => {
  return ['text', 'email', 'password', 'number', 'tel', 'url', 'search', 'date', 'time', 'datetime-local', 'month', 'week'].includes(value);
};

import React, { useState, useEffect, useRef, useCallback } from 'react';

import { Check, X } from 'lucide-react';

interface QuickEditFieldProps {
  initialValue: string;
  fieldName: string;
  onSave: (value: string) => void;
  onCancel: () => void;
  placeholder?: string;
}

export function InlineEditInput({ 
  initialValue, 
  fieldName, 
  onSave, 
  onCancel, 
  placeholder 
}: QuickEditFieldProps) {
  const [value, setValue] = useState(initialValue);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (inputRef.current) {
      inputRef.current.focus();
      inputRef.current.select();
    }
  }, []);

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    switch (e.key) {
      case 'Enter':
        e.preventDefault();
        e.stopPropagation();
        onSave(value);
        break;
      case 'Escape':
        e.preventDefault();
        e.stopPropagation();
        onCancel();
        break;
      case 'Tab':
        // Allow tab to work normally but save on tab out
        onSave(value);
        break;
    }
  }, [value, onSave, onCancel]);

  const handleBlur = useCallback(() => {
    // Auto-save on blur
    onSave(value);
  }, [value, onSave]);

  return (
    <div className="absolute inset-0 bg-white border-2 border-amber-400 rounded-lg shadow-lg z-30 flex items-center p-1">
      <input
        ref={inputRef}
        type="text"
        value={value}
        onChange={(e) => setValue(e.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={handleBlur}
        placeholder={placeholder || `Edit ${fieldName}`}
        className="flex-1 text-xs bg-transparent border-none outline-none px-1"
      />
      <div className="flex space-x-1 ml-1">
        <button
          onClick={(e) => {
            e.stopPropagation();
            onSave(value);
          }}
          className="p-0.5 rounded bg-green-100 text-green-600 hover:bg-green-200 transition-colors"
          title="Save (Enter)"
        >
          <Check size={10} />
        </button>
        <button
          onClick={(e) => {
            e.stopPropagation();
            onCancel();
          }}
          className="p-0.5 rounded bg-danger-light text-danger-text hover:bg-danger-border transition-colors"
          title="Cancel (Esc)"
        >
          <X size={10} />
        </button>
      </div>
    </div>
  );
}

import React, { useRef, useEffect } from 'react';

import { AlertTriangle, AlertCircle, CheckCircle } from 'lucide-react';

import type { UseFormRegisterReturn } from 'react-hook-form';

interface ValidationAwareInputProps {
  label: string;

  // Controlled mode (legacy)
  value?: string;
  onChange?: (value: string) => void;

  // Uncontrolled mode (React Hook Form register)
  registration?: UseFormRegisterReturn;

  onBlur?: () => void;
  type?: 'text' | 'email' | 'password' | 'number' | 'date' | 'select' | 'textarea';
  placeholder?: string;
  error?: boolean;
  warning?: boolean;
  helperText?: string;
  className?: string;
  disabled?: boolean;
  required?: boolean;
  maxLength?: number;
  children?: React.ReactNode;
  options?: Array<{ value: string; label: string }>; // For select type
  autoFocus?: boolean;
  'aria-invalid'?: boolean;
  'data-testid'?: string;
}

export function ValidatedInput({
  label,
  value,
  onChange,
  registration,
  onBlur,
  type = 'text',
  placeholder,
  error = false,
  warning = false,
  helperText,
  className = '',
  disabled = false,
  required = false,
  maxLength,
  children,
  options,
  autoFocus = false,
  ...ariaProps
}: ValidationAwareInputProps) {
  // Determine if controlled or uncontrolled
  const isUncontrolled = Boolean(registration);

  // Industry-standard programmatic focus using ref + useEffect
  // More reliable than HTML autoFocus attribute which depends on browser timing
  const inputRef = useRef<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>(null);

  useEffect(() => {
    if (autoFocus && inputRef.current) {
      // Industry standard: Wait for modal animation (500ms) before focusing
      // 150ms provides enough time without feeling sluggish to users
      setTimeout(() => {
        inputRef.current?.focus();
      }, 150);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); // Run once on mount when autoFocus is true

  const getInputClasses = () => {
    if (error) {
      return 'input-field input-field-error w-full';
    } else if (warning) {
      return 'input-field w-full border-2 border-validation-warning-border bg-validation-warning-bg text-validation-warning-text';
    } else if (!isUncontrolled && value && !error && !warning) {
      return 'input-field input-field-normal w-full border-validation-success-border bg-validation-success-bg';
    } else {
      return 'input-field input-field-normal w-full';
    }
  };

  const getLabelClasses = () => {
    const baseClasses = 'block text-sm font-medium mb-1';

    if (error) {
      return `${baseClasses} text-validation-error-label`;
    } else if (warning) {
      return `${baseClasses} text-validation-warning-label`;
    } else {
      return `${baseClasses} text-odysseus-secondary`;
    }
  };

  const getHelperTextClasses = () => {
    const baseClasses = 'flex items-center mt-1 text-xs';

    if (error) {
      return `${baseClasses} text-validation-error-helper`;
    } else if (warning) {
      return `${baseClasses} text-validation-warning-helper`;
    } else {
      return `${baseClasses} text-odysseus-muted`;
    }
  };

  const getIcon = () => {
    if (error) {
      return <AlertCircle className="w-4 h-4 mr-1 flex-shrink-0 text-validation-error-icon" />;
    } else if (warning) {
      return <AlertTriangle className="w-4 h-4 mr-1 flex-shrink-0 text-validation-warning-icon" />;
    } else if (!isUncontrolled && value && !error && !warning) {
      return <CheckCircle className="w-4 h-4 mr-1 flex-shrink-0 text-validation-success-icon" />;
    }
    return null;
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    if (onChange) {
      onChange(e.target.value);
    }
  };

  return (
    <div className={`${className}`}>
      <label className={getLabelClasses()}>
        {label}
        {required && <span className="text-validation-error-required ml-1">*</span>}
      </label>
      
      {type === 'select' ? (
        <select
          ref={inputRef as React.RefObject<HTMLSelectElement>}
          {...(isUncontrolled ? registration : { value, onChange: handleInputChange })}
          onBlur={onBlur}
          className={getInputClasses()}
          disabled={disabled}
          {...ariaProps}
        >
          {options?.map(option => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
          {children}
        </select>
      ) : type === 'textarea' ? (
        <textarea
          ref={inputRef as React.RefObject<HTMLTextAreaElement>}
          {...(isUncontrolled ? registration : { value, onChange: handleInputChange })}
          onBlur={onBlur}
          placeholder={placeholder}
          className={getInputClasses()}
          disabled={disabled}
          maxLength={maxLength}
          rows={2}
          {...ariaProps}
        />
      ) : (
        <input
          ref={inputRef as React.RefObject<HTMLInputElement>}
          type={type}
          {...(isUncontrolled ? registration : { value, onChange: handleInputChange })}
          onBlur={onBlur}
          placeholder={placeholder}
          className={getInputClasses()}
          disabled={disabled}
          maxLength={maxLength}
          {...ariaProps}
        />
      )}
      
      {helperText && (
        <div className={getHelperTextClasses()}>
          {getIcon()}
          <span>{helperText}</span>
        </div>
      )}
      
      {/* Character count for long fields */}
      {maxLength && !isUncontrolled && value && (
        <div className="text-xs text-gray-400 mt-1 text-right">
          {value.length}/{maxLength}
        </div>
      )}
    </div>
  );
}

