/**
 * Modal Component Types
 *
 * Type definitions for accessible Modal primitive components
 * Includes modal, modal header, modal footer, and modal body
 */

import type { ReactNode } from 'react';

// Modal size types
export type ModalSize = 
  | 'xs'            // Extra small (384px max-width)
  | 'sm'            // Small (512px max-width)
  | 'md'            // Medium (768px max-width) - default
  | 'lg'            // Large (1024px max-width)
  | 'xl'            // Extra large (1280px max-width)
  | 'full';         // Full screen

// Modal variant types
export type ModalVariant = 
  | 'default'       // Standard modal
  | 'centered'      // Centered modal (default)
  | 'drawer'        // Side drawer modal
  | 'fullscreen';   // Fullscreen modal

// Modal placement for drawer variant
export type ModalPlacement = 
  | 'top'
  | 'right'
  | 'bottom'
  | 'left';

// Modal animation types
export type ModalAnimation = 
  | 'fade'          // Fade in/out
  | 'scale'         // Scale up/down
  | 'slide'         // Slide from placement direction
  | 'none';         // No animation

// Modal backdrop types
export type ModalBackdrop = 
  | 'default'       // Dark backdrop
  | 'light'         // Light backdrop
  | 'blur'          // Blurred backdrop
  | 'none';         // No backdrop

// Base modal props
export interface BaseModalProps {
  // Visibility
  isOpen: boolean;
  onClose: () => void;
  
  // Content
  children: ReactNode;
  
  // Styling
  variant?: ModalVariant;
  size?: ModalSize;
  placement?: ModalPlacement; // For drawer variant
  animation?: ModalAnimation;
  backdrop?: ModalBackdrop;
  
  // Behavior
  closeOnEscape?: boolean;
  closeOnBackdropClick?: boolean;
  preventClose?: boolean; // Prevent closing (for loading states)
  autoFocus?: boolean;
  restoreFocus?: boolean;
  trapFocus?: boolean;
  lockBodyScroll?: boolean;
  
  // Accessibility
  'aria-label'?: string;
  'aria-labelledby'?: string;
  'aria-describedby'?: string;
  role?: 'dialog' | 'alertdialog';
  
  // Custom styling
  className?: string;
  backdropClassName?: string;
  contentClassName?: string;
  
  // Portal
  portalTarget?: Element | null;
  
  // Event handlers
  onOpen?: () => void;
  onOpened?: () => void;
  onClosing?: () => void;
  onClosed?: () => void;
  onBackdropClick?: (event: React.MouseEvent) => void;
  onEscapeKey?: (event: KeyboardEvent) => void;
}

// Modal ref type
export type ModalRef = HTMLDivElement;

// Main modal props
export interface ModalProps extends BaseModalProps {}

// Modal header props
export interface ModalHeaderProps {
  children: ReactNode;
  
  // Close button
  showCloseButton?: boolean;
  onClose?: () => void;
  closeButtonLabel?: string;
  
  // Styling
  className?: string;
  
  // Accessibility
  id?: string; // For aria-labelledby
}

// Modal body props
export interface ModalBodyProps {
  children: ReactNode;
  
  // Scrolling
  scrollable?: boolean;
  maxHeight?: string | number;
  
  // Padding
  padding?: 'none' | 'sm' | 'md' | 'lg' | 'xl';
  
  // Styling
  className?: string;
  
  // Accessibility
  id?: string; // For aria-describedby
}

// Modal footer props
export interface ModalFooterProps {
  children: ReactNode;
  
  // Layout
  justify?: 'start' | 'center' | 'end' | 'between' | 'around';
  spacing?: 'none' | 'sm' | 'md' | 'lg';
  
  // Styling
  className?: string;
}

// Modal overlay props
export interface ModalOverlayProps {
  children: ReactNode;
  isOpen: boolean;
  backdrop?: ModalBackdrop;
  onClick?: (event: React.MouseEvent) => void;
  className?: string;
}

// Modal content props
export interface ModalContentProps {
  children: ReactNode;
  variant?: ModalVariant;
  size?: ModalSize;
  placement?: ModalPlacement;
  animation?: ModalAnimation;
  className?: string;
}

// Modal portal props
export interface ModalPortalProps {
  children: ReactNode;
