  // Variant styles
  variants: ModalStyleVariants['variant'];
  
  // Size styles
  sizes: ModalStyleVariants['size'];
  
  // Placement styles (for drawer)
  placements: ModalStyleVariants['placement'];
  
  // Animation styles
  animations: ModalStyleVariants['animation'];
  
  // Backdrop styles
