const optionVariants = cva(
  [
    'px-3 py-2 cursor-pointer text-sm',
    'flex items-center gap-2',
    'transition-colors duration-150',
  ],
  {
    variants: {
      isSelected: {
        true: 'bg-primary-100 text-primary-900',
        false: 'text-neutral-900',
      },
      isHighlighted: {
        true: 'bg-primary-50',
        false: 'hover:bg-neutral-50',
      },
      isDisabled: {
        true: 'opacity-50 cursor-not-allowed',
        false: '',
      },
    },
    defaultVariants: {
      isSelected: false,
      isHighlighted: false,
      isDisabled: false,
    },
  }
);

// Simple Select Component (Basic Implementation)
export const Select = forwardRef<HTMLDivElement, SelectProps>(
  (
    {
      options,
      value,
      defaultValue,
      multiple = false,
      searchable = false,
      clearable = false,
      disabled = false,
      loading = false,
      variant = 'outlined',
      size = 'md',
      placeholder = 'Select an option...',
      label,
      description,
      error,
      onChange,
      onSearch,
      onOpen,
      onClose,
      'aria-label': ariaLabel,
      'aria-describedby': ariaDescribedBy,
      className,
      maxHeight = 240,
      closeOnSelect = !multiple,
      ...props
    },
    ref
  ) => {
    // State
    const [isOpen, setIsOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [highlightedIndex, setHighlightedIndex] = useState(-1);
    const [selectedValue, setSelectedValue] = useState(() => {
      if (value !== undefined) return value;
      if (defaultValue !== undefined) return defaultValue;
      return multiple ? [] : null;
    });
    
    // Refs
    const selectRef = useRef<HTMLDivElement>(null);
    const searchInputRef = useRef<HTMLInputElement>(null);
    const optionsRef = useRef<HTMLDivElement>(null);
    
    // IDs
    const id = useId();
    const labelId = `${id}-label`;
    const descriptionId = `${id}-description`;
    const errorId = `${id}-error`;
    
    // Filter options based on search query
    const filteredOptions = searchable && searchQuery
      ? options.filter(option => 
          option.label.toLowerCase().includes(searchQuery.toLowerCase())
        )
      : options;
    
    // Get selected options for display
    const getSelectedOptions = useCallback(() => {
      const currentValue = value !== undefined ? value : selectedValue;
      if (!currentValue) return [];
      
      const values = Array.isArray(currentValue) ? currentValue : [currentValue];
      return options.filter(option => values.includes(option.value));
    }, [value, selectedValue, options]);
    
    const selectedOptions = getSelectedOptions();
    
    // Handle option selection
    const handleOptionSelect = useCallback((option: SelectOption) => {
      if (option.disabled) return;
      
      let newValue: string | number | (string | number)[] | null;
      
      if (multiple) {
        const currentValues = Array.isArray(selectedValue) ? selectedValue : [];
        if (currentValues.includes(option.value)) {
          newValue = currentValues.filter(v => v !== option.value);
        } else {
          newValue = [...currentValues, option.value];
        }
      } else {
        newValue = option.value;
      }
      
      if (value === undefined) {
        setSelectedValue(newValue);
      }
      
      onChange?.(newValue);
      
      if (closeOnSelect) {
        setIsOpen(false);
        setSearchQuery('');
      }
    }, [multiple, selectedValue, value, onChange, closeOnSelect]);
    
    // Handle clear selection
    const handleClear = useCallback((e: React.MouseEvent) => {
      e.stopPropagation();
      const newValue = multiple ? [] : null;
      
      if (value === undefined) {
        setSelectedValue(newValue);
      }
      
      onChange?.(newValue);
    }, [multiple, value, onChange]);
    
    // Handle select toggle
    const handleToggle = useCallback(() => {
      if (disabled) return;
      
      const newIsOpen = !isOpen;
      setIsOpen(newIsOpen);
      
      if (newIsOpen) {
        onOpen?.();
        // Focus search input if searchable
        setTimeout(() => {
          if (searchable && searchInputRef.current) {
            searchInputRef.current.focus();
          }
        }, 0);
      } else {
        onClose?.();
        setSearchQuery('');
        setHighlightedIndex(-1);
      }
    }, [disabled, isOpen, onOpen, onClose, searchable]);
    
    // Handle keyboard navigation
    const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault();
          if (!isOpen) {
            setIsOpen(true);
            onOpen?.();
          } else {
            setHighlightedIndex(prev => 
              prev < filteredOptions.length - 1 ? prev + 1 : prev
            );
          }
          break;
          
        case 'ArrowUp':
          e.preventDefault();
          if (isOpen) {
            setHighlightedIndex(prev => prev > 0 ? prev - 1 : prev);
          }
          break;
          
        case 'Enter':
        case ' ':
          e.preventDefault();
          if (!isOpen) {
            setIsOpen(true);
            onOpen?.();
          } else if (highlightedIndex >= 0) {
            handleOptionSelect(filteredOptions[highlightedIndex]);
          }
          break;
          
        case 'Escape':
          if (isOpen) {
            e.preventDefault();
            setIsOpen(false);
            onClose?.();
            setSearchQuery('');
            selectRef.current?.focus();
          }
          break;
      }
    }, [isOpen, highlightedIndex, filteredOptions, handleOptionSelect, onOpen, onClose]);
    
    // Handle search input change
    const handleSearchChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
      const query = e.target.value;
      setSearchQuery(query);
      onSearch?.(query);
      setHighlightedIndex(0);
    }, [onSearch]);
    
    // Close dropdown on outside click
    React.useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
        if (selectRef.current && !selectRef.current.contains(event.target as Node)) {
          setIsOpen(false);
          setSearchQuery('');
        }
      };
      
      if (isOpen) {
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
      }
      
      // Return undefined explicitly when dropdown is not open
      return undefined;
    }, [isOpen]);
    
    // Generate classes
    const selectClasses = selectVariants({
      variant,
      size,
      isOpen,
      hasError: Boolean(error),
      className,
    });
    
    const dropdownClasses = dropdownVariants({ isOpen });
    
    // Render display value
    const renderDisplayValue = () => {
      if (loading) {
        return <span className="text-neutral-500">Loading...</span>;
      }
      
      if (selectedOptions.length === 0) {
        return <span className="text-neutral-400">{placeholder}</span>;
      }
      
      if (multiple && selectedOptions.length > 1) {
        return (
          <span className="text-neutral-900">
            {selectedOptions.length} items selected
          </span>
        );
      }
      
      const firstOption = selectedOptions[0];
      return (
        <span className="text-neutral-900 flex items-center gap-2">
          {firstOption.icon && <span>{firstOption.icon}</span>}
          {firstOption.label}
        </span>
      );
    };
    
    return (
      <div className="relative">
        {/* Label */}
        {label && (
          <label
            id={labelId}
            className="block text-sm font-medium text-neutral-700 mb-1.5"
          >
            {label}
          </label>
        )}
        
        {/* Select Container */}
        <div
          ref={(el) => {
            // Use type assertion to safely assign to mutable refs
            (selectRef as React.MutableRefObject<HTMLDivElement | null>).current = el;
            if (typeof ref === 'function') ref(el);
            else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = el;
          }}
          className={selectClasses}
          onClick={handleToggle}
          onKeyDown={handleKeyDown}
          role="combobox"
          aria-expanded={isOpen}
          aria-haspopup="listbox"
          aria-controls="select-listbox"
          aria-label={ariaLabel}
          aria-labelledby={label ? labelId : undefined}
          aria-describedby={[
            ariaDescribedBy,
            description ? descriptionId : null,
            error ? errorId : null,
          ].filter(Boolean).join(' ') || undefined}
          tabIndex={disabled ? -1 : 0}
          {...props}
        >
          {/* Display Value */}
          <div className="flex items-center justify-between">
            <div className="flex-1 truncate">
              {renderDisplayValue()}
            </div>
            
            <div className="flex items-center gap-1">
              {/* Clear Button */}
              {clearable && selectedOptions.length > 0 && !disabled && (
                <button
                  type="button"
                  onClick={handleClear}
                  className="p-1 hover:bg-neutral-200 rounded"
                  aria-label="Clear selection"
                >
                  <svg className="w-4 h-4" viewBox="0 0 24 24" fill="currentColor">
                    <path d="M19 6.41L17.59 5L12 10.59L6.41 5L5 6.41L10.59 12L5 17.59L6.41 19L12 13.41L17.59 19L19 17.59L13.41 12z"/>
                  </svg>
                </button>
              )}
              
              {/* Dropdown Arrow */}
              <svg
                className={`w-4 h-4 transition-transform duration-200 ${
                  isOpen ? 'rotate-180' : ''
                }`}
                viewBox="0 0 24 24"
                fill="currentColor"
              >
                <path d="M7.41 8.59L12 13.17l4.59-4.58L18 10l-6 6-6-6 1.41-1.41z"/>
              </svg>
            </div>
          </div>
          
          {/* Dropdown Menu */}
          <div className={dropdownClasses} style={{ maxHeight }}>
            {/* Search Input */}
            {searchable && isOpen && (
              <div className="px-3 py-2 border-b border-neutral-200">
                <input
                  ref={searchInputRef}
                  type="text"
                  value={searchQuery}
                  onChange={handleSearchChange}
                  placeholder="Search options..."
                  className="input w-full px-2 py-1 text-sm border border-neutral-300 rounded"
                />
              </div>
            )}
            
            {/* Options */}
            <div ref={optionsRef} role="listbox" id="select-listbox" aria-label={`${label || 'Select'} options`}>
              {filteredOptions.length === 0 ? (
                <div className="px-3 py-2 text-sm text-neutral-500">
                  No options found
                </div>
              ) : (
                filteredOptions.map((option, index) => {
                  const isSelected = selectedOptions.some(
                    selected => selected.value === option.value
                  );
                  const isHighlighted = index === highlightedIndex;
                  
                  return (
                    <div
                      key={option.value}
                      className={optionVariants({
                        isSelected,
                        isHighlighted,
                        isDisabled: option.disabled,
                      })}
                      onClick={() => handleOptionSelect(option)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' || e.key === ' ') {
                          e.preventDefault();
                          handleOptionSelect(option);
                        }
                      }}
                      role="option"
                      aria-selected={isSelected}
                      aria-disabled={option.disabled}
                      tabIndex={isHighlighted ? 0 : -1}
                    >
                      {multiple && (
                        <div className="flex items-center">
                          <input
                            type="checkbox"
                            checked={isSelected}
                            readOnly
                            className="mr-2"
                          />
                        </div>
                      )}
                      
                      {option.icon && (
                        <span className="flex-shrink-0">{option.icon}</span>
                      )}
                      
                      <div className="flex-1 min-w-0">
                        <div className="truncate">{option.label}</div>
                        {option.description && (
                          <div className="text-xs text-neutral-500 truncate">
                            {option.description}
                          </div>
                        )}
                      </div>
                      
                      {!multiple && isSelected && (
                        <svg className="w-4 h-4 text-primary-600" viewBox="0 0 24 24" fill="currentColor">
                          <path d="M9 16.17L4.83 12l-1.42 1.41L9 19L21 7l-1.41-1.41z"/>
                        </svg>
                      )}
                    </div>
                  );
                })
              )}
            </div>
          </div>
        </div>
        
        {/* Description */}
        {description && (
          <p id={descriptionId} className="text-xs text-neutral-500 mt-1">
            {description}
          </p>
        )}
        
        {/* Error Message */}
        {error && (
          <p id={errorId} className="text-xs text-error-600 mt-1" role="alert">
            {error}
          </p>
        )}
      </div>
    );
  }
);

Select.displayName = 'Select';

export type SelectVariantsProps = VariantProps<typeof selectVariants>;

import { useEffect, useRef } from 'react';

import { Plus, Edit, Trash2, Copy, Scissors, ClipboardPaste, X } from 'lucide-react';

interface ContextMenuProps {
  isVisible: boolean;
  position: { x: number; y: number };
  selectedCount: number;
  hasFilledSelection: boolean;
  isMixedSelection: boolean;
  clipboardCount: number;
  onClose: () => void;
  onOpen: () => void; // Unified modal opener
  onDelete: () => void;
  onCopy: () => void;
  onCut: () => void;
  onPaste: () => void;
  canPaste?: boolean;
}

export function ContextMenu({
  isVisible,
  position,
  selectedCount,
  hasFilledSelection,
  isMixedSelection,
  clipboardCount,
  onClose,
  onOpen,
  onDelete,
  onCopy,
  onCut,
  onPaste,
  canPaste = false,
}: ContextMenuProps) {
  const menuRef = useRef<HTMLDivElement>(null);

  // Calculate position once to keep menu in viewport
  const adjustedPosition = (() => {
    // Use fixed size estimation to avoid recalculation
    const estimatedWidth = 200;
    const estimatedHeight = 300;
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let { x, y } = position;

    // Adjust horizontal position
    if (x + estimatedWidth > viewportWidth) {
      x = Math.max(10, viewportWidth - estimatedWidth - 10);
    }

    // Adjust vertical position  
    if (y + estimatedHeight > viewportHeight) {
      y = Math.max(10, viewportHeight - estimatedHeight - 10);
    }

    return { x, y };
  })();

  // Handle click outside to close
  useEffect(() => {
    if (!isVisible) return;

    const handleClickOutside = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        onClose();
      }
    };

    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleEscape);

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleEscape);
    };
  }, [isVisible, onClose]);

  if (!isVisible) return null;

  // Helper: Generate dynamic action labels
  const getLabel = (action: string, count: number): string => {
    if (count === 0) return action;
    if (count === 1) return `${action} Tube`;
    return `${action} ${count} Tubes`;
  };

  // Unified action label based on selection type
  const getOpenLabel = () => {
    if (isMixedSelection) {
      return selectedCount === 1 ? 'Add Tube' : `Add ${selectedCount} Tubes`;
    } else if (hasFilledSelection) {
      return selectedCount === 1 ? 'Edit Tube' : `Edit ${selectedCount} Tubes`;
    } else {
      return selectedCount === 1 ? 'Add Tube' : `Add ${selectedCount} Tubes`;
    }
  };

  const getOpenIcon = () => {
    return hasFilledSelection && !isMixedSelection ? Edit : Plus;
  };

  // Smart action list - only show relevant actions
  const actions = [
    // Unified Open action - always show when positions selected (Edit/Add)
    ...(selectedCount > 0 ? [{
      icon: getOpenIcon(),
      label: getOpenLabel(),
      shortcut: 'Enter',
      onClick: onOpen,
      variant: 'edit' as const, // Minty Frost - matches update/edit/add operations
      disabled: false,
    }] : []),

    // Delete, Copy, Cut - only for tubes that exist
    ...(hasFilledSelection ? [
      {
        icon: Trash2,
        label: getLabel('Delete', selectedCount),
        shortcut: 'Del',
        onClick: onDelete,
        variant: 'danger' as const,
        disabled: false,
      },
      {
        icon: Copy,
        label: getLabel('Copy', selectedCount),
        shortcut: 'Ctrl+C',
        onClick: () => {
          onCopy();
          onClose(); // Close menu after copy
        },
        variant: 'copy' as const, // Icy Blue - matches copy operation
        disabled: false,
      },
      {
        icon: Scissors,
        label: getLabel('Cut', selectedCount),
        shortcut: 'Ctrl+X',
        onClick: () => {
          onCut();
          onClose(); // Close menu after cut
        },
        variant: 'cut' as const, // Light Amber - matches cut/move operations
        disabled: false,
      },
    ] : []),

    // Paste - show when clipboard has data and positions are selected
    ...(canPaste && selectedCount > 0 ? [{
      icon: ClipboardPaste,
      label: getLabel('Paste', clipboardCount),
      shortcut: 'Ctrl+V',
      onClick: () => {
        onPaste();
        onClose(); // Close menu after paste
      },
      variant: 'copy' as const, // Icy Blue - matches copy/paste operations
      disabled: false,
    }] : []),
  ];

  return (
    <div
      ref={menuRef}
      className="fixed z-50 bg-odysseus-surface rounded-xl shadow-2xl border border-odysseus-border p-2 min-w-48 animate-in slide-in-from-top-2 duration-200"
      style={{
        left: adjustedPosition.x,
        top: adjustedPosition.y,
      }}
    >
      {/* Header */}
      <div className="flex items-center justify-between p-3 border-b border-odysseus-border">
        <span className="text-sm font-bold text-odysseus-dark">
          {selectedCount} {selectedCount === 1 ? 'Tube' : 'Tubes'} Selected
        </span>
        <button
          onClick={onClose}
          className="p-1 rounded-lg hover:bg-odysseus-surface-hover text-odysseus-muted hover:text-odysseus-dark transition-all duration-200"
        >
          <X size={14} />
        </button>
      </div>

      {/* Actions */}
      <div className="p-2 space-y-2">
        {actions.map(({ icon: Icon, label, shortcut, onClick, variant, disabled = false }) => {
          const baseClasses = "w-full flex items-center justify-between py-2 px-3 rounded-lg text-sm font-medium transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed";

          const variantClasses = {
            edit: "bg-edit-bg text-white hover:bg-edit-hover",
            copy: "bg-copy-bg text-white hover:bg-copy-hover",
            cut: "bg-cut-bg text-white hover:bg-cut-hover",
            danger: "bg-danger-bg text-white hover:bg-danger-hover",
          };

          return (
            <button
              key={label}
              onClick={onClick}
              disabled={disabled}
              className={`${baseClasses} ${variantClasses[variant]}`}
            >
              <div className="flex items-center space-x-3 flex-1">
                <Icon size={16} />
                <span>{label}</span>
              </div>
              {shortcut && (
                <span className="text-xs text-white/80 font-mono bg-black/20 px-2 py-1 rounded ml-4">
                  {shortcut.toLowerCase()}
                </span>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

import { AlertTriangle, X, Copy } from 'lucide-react';

interface ErrorDisplayProps {
  errors: string[];
  onClear: () => void;
}

export function ErrorBanner({ errors, onClear }: ErrorDisplayProps) {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    setIsVisible(errors.length > 0);
  }, [errors]);

  const copyErrors = () => {
    const errorText = errors.join('\n\n');
    void (async () => {
      try {
        await navigator.clipboard.writeText(errorText);
      } catch (error) {
        console.error('Failed to copy errors to clipboard:', error);
      }
    })();
  };

  if (!isVisible) return null;

  return (
    <div className="fixed top-4 left-4 right-4 z-50 max-w-2xl mx-auto">
      <div className="bg-red-50 border border-red-200 rounded-lg p-4 shadow-lg">
        <div className="flex items-start justify-between">
          <div className="flex items-start space-x-3">
            <AlertTriangle className="text-red-500 mt-0.5" size={20} />
            <div className="flex-1">
              <h3 className="text-sm font-medium text-red-800 mb-2">
                Connection Errors ({errors.length})
              </h3>
              <div className="space-y-2 max-h-32 overflow-y-auto">
                {errors.slice(-3).map((error, index) => (
                  <div key={index} className="text-xs text-red-700 font-mono bg-red-100 p-2 rounded">
                    {error}
                  </div>
                ))}
              </div>
              <div className="flex space-x-2 mt-3">
                <button
                  onClick={copyErrors}
                  className="flex items-center space-x-1 text-xs text-red-600 hover:text-red-800"
                >
                  <Copy size={12} />
                  <span>Copy All Errors</span>
                </button>
                <button
                  onClick={onClear}
                  className="text-xs text-red-600 hover:text-red-800"
                >
                  Clear
                </button>
              </div>
            </div>
          </div>
          <button
            onClick={() => setIsVisible(false)}
            className="text-red-400 hover:text-red-600"
          >
            <X size={16} />
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Table Component
 * 
 * Accessible table primitive with sorting, selection, and responsive design
 * Supports virtualization for large datasets and full WCAG AA compliance
 */

import React, { forwardRef, createContext, useContext } from 'react';

import { cva, type VariantProps } from 'class-variance-authority';

// Table column definition
export interface TableColumn<T = any> {
  id: string;
  header: string;
  accessor?: keyof T | ((row: T) => React.ReactNode);
  width?: string | number;
  minWidth?: string | number;
  sortable?: boolean;
  align?: 'left' | 'center' | 'right';
  sticky?: boolean;
  render?: (value: any, row: T, index: number) => React.ReactNode;
}

// Table row data
export interface TableRow {
  id: string | number;
  [key: string]: any;
}

// Sort configuration
export interface SortConfig {
  columnId: string;
  direction: 'asc' | 'desc';
}

// Table component props
export interface TableProps<T = TableRow> {
  // Data
  columns: TableColumn<T>[];
  data: T[];
  
  // Features
  sortable?: boolean;
  selectable?: boolean;
  multiSelect?: boolean;
  striped?: boolean;
  hoverable?: boolean;
  
  // State
  selectedRows?: (string | number)[];
  sortConfig?: SortConfig;
  loading?: boolean;
  
  // Appearance
  variant?: 'default' | 'bordered' | 'borderless';
  size?: 'sm' | 'md' | 'lg';
  stickyHeader?: boolean;
  
  // Pagination
  pagination?: {
    page: number;
    pageSize: number;
    total: number;
  };
  
  // Event handlers
  onSort?: (config: SortConfig) => void;
  onSelectionChange?: (selectedIds: (string | number)[]) => void;
  onRowClick?: (row: T, index: number) => void;
  
  // Empty state
  emptyMessage?: string;
  loadingMessage?: string;
  
  // Accessibility
  'aria-label'?: string;
  
  // Styling
  className?: string;
  headerClassName?: string;
  bodyClassName?: string;
  rowClassName?: string | ((row: T, index: number) => string);
  
  // Advanced
  maxHeight?: string | number;
  virtualized?: boolean;
}

// Table context
interface TableContextValue {
  selectable: boolean;
  multiSelect: boolean;
  selectedRows: (string | number)[];
  onSelectionChange: (selectedIds: (string | number)[]) => void;
  sortConfig?: SortConfig;
  onSort?: (config: SortConfig) => void;
}

const TableContext = createContext<TableContextValue | null>(null);

const useTableContext = () => {
  const context = useContext(TableContext);
  if (!context) {
    throw new Error('Table components must be used within a Table');
  }
  return context;
};

// Table styling
const tableVariants = cva(
  ['w-full border-collapse'],
  {
    variants: {
      variant: {
        default: 'border border-neutral-200',
        bordered: 'border-2 border-neutral-300',
        borderless: '',
      },
      size: {
        sm: 'text-sm',
        md: 'text-base',
        lg: 'text-lg',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'md',
    },
  }
);

// Header styling
const headerVariants = cva(
  [
    'px-4 py-3 text-left font-semibold text-neutral-900',
    'border-b border-neutral-200 bg-neutral-50',
  ],
  {
    variants: {
      sortable: {
        true: 'cursor-pointer hover:bg-neutral-100 select-none',
        false: '',
      },
      sticky: {
