// Table Header component
export const TableHeader = <T,>({ 
  columns, 
  className = '' 
}: { 
  columns: TableColumn<T>[];
  className?: string;
}) => {
  const { 
    selectable, 
    multiSelect, 
    selectedRows, 
    onSelectionChange, 
    sortConfig, 
    onSort 
  } = useTableContext();
  
  const handleSelectAll = (checked: boolean) => {
    // This would need access to all row IDs
    // In a real implementation, you'd pass this through context
    onSelectionChange(checked ? [] : []); // Simplified
  };
  
  const handleSort = (columnId: string) => {
    if (!onSort) return;
    
    const newDirection = 
      sortConfig?.columnId === columnId && sortConfig.direction === 'asc'
        ? 'desc'
        : 'asc';
    
    onSort({ columnId, direction: newDirection });
  };
  
  return (
    <thead className={className}>
      <tr>
        {selectable && (
          <th className={headerVariants({})}>
            {multiSelect && (
              <TableCheckbox
                checked={selectedRows.length > 0}
                indeterminate={selectedRows.length > 0 && selectedRows.length < 100} // Simplified
                onChange={handleSelectAll}
                aria-label="Select all rows"
              />
            )}
          </th>
        )}
        
        {columns.map(column => {
          const isSorted = sortConfig?.columnId === column.id;
          const sortDirection = isSorted ? sortConfig.direction : undefined;
          
          return (
            <th
              key={column.id}
              className={headerVariants({
                sortable: column.sortable,
                sticky: column.sticky,
                align: column.align,
              })}
              style={{
                width: column.width,
                minWidth: column.minWidth,
              }}
              onClick={column.sortable ? () => handleSort(column.id) : undefined}
              role={column.sortable ? 'columnheader button' : 'columnheader'}
              aria-sort={
                isSorted 
                  ? sortDirection === 'asc' ? 'ascending' : 'descending'
                  : column.sortable ? 'none' : undefined
              }
            >
              <div className="flex items-center">
                {column.header}
                {column.sortable && (
                  <SortIndicator direction={sortDirection} />
                )}
              </div>
            </th>
          );
        })}
      </tr>
    </thead>
  );
};

// Table Body component
export const TableBody = <T extends TableRow>({ 
  columns,
  data,
  striped = false,
  hoverable = false,
  rowClassName,
  onRowClick,
  className = ''
}: {
  columns: TableColumn<T>[];
  data: T[];
  striped?: boolean;
  hoverable?: boolean;
  rowClassName?: string | ((row: T, index: number) => string);
  onRowClick?: (row: T, index: number) => void;
  className?: string;
}) => {
  const { selectable, selectedRows, onSelectionChange } = useTableContext();
  
  const handleRowSelect = (rowId: string | number, checked: boolean) => {
    const newSelection = checked
      ? [...selectedRows, rowId]
      : selectedRows.filter(id => id !== rowId);
    
    onSelectionChange(newSelection);
  };
  
  const getCellValue = (column: TableColumn<T>, row: T) => {
    if (column.render) {
      return column.render(
        column.accessor ? 
          (typeof column.accessor === 'function' ? column.accessor(row) : row[column.accessor]) 
          : undefined,
        row,
        0 // index would be passed from parent
      );
    }
    
    if (column.accessor) {
      return typeof column.accessor === 'function' 
        ? column.accessor(row)
        : row[column.accessor];
    }
    
    return null;
  };
  
  return (
    <tbody className={className}>
      {data.map((row, index) => {
        const isSelected = selectedRows.includes(row.id);
        const finalRowClassName = typeof rowClassName === 'function'
          ? rowClassName(row, index)
          : rowClassName ?? '';
        
        return (
          <tr
            key={row.id}
            className={rowVariants({
              striped,
              hoverable: hoverable || Boolean(onRowClick),
              selectable,
              selected: isSelected,
              className: finalRowClassName,
            })}
            onClick={onRowClick ? () => onRowClick(row, index) : undefined}
          >
            {selectable && (
              <td className={cellVariants({})}>
                <TableCheckbox
                  checked={isSelected}
                  onChange={(checked) => handleRowSelect(row.id, checked)}
                  aria-label={`Select row ${index + 1}`}
                />
              </td>
            )}
            
            {columns.map(column => (
              <td
                key={column.id}
                className={cellVariants({ align: column.align })}
                style={{
                  width: column.width,
                  minWidth: column.minWidth,
                }}
              >
                {getCellValue(column, row)}
              </td>
            ))}
          </tr>
        );
      })}
    </tbody>
  );
};

// Main Table component
export const Table = forwardRef<HTMLTableElement, TableProps>(
  (
    {
      columns,
      data,
      sortable = false,
      selectable = false,
      multiSelect = false,
      striped = false,
      hoverable = true,
      selectedRows = [],
      sortConfig,
      loading = false,
      variant = 'default',
      size = 'md',
      stickyHeader = false,
      pagination: _pagination,
      onSort,
      onSelectionChange = () => {},
      onRowClick,
      emptyMessage = 'No data available',
      loadingMessage = 'Loading...',
      'aria-label': ariaLabel,
      className,
      headerClassName,
      bodyClassName,
      rowClassName,
      maxHeight,
      virtualized: _virtualized = false,
      ...props
    },
    ref
  ) => {
    // Table classes
    const tableClasses = tableVariants({ variant, size, className });
    
    // Context value
    const contextValue: TableContextValue = {
      selectable,
      multiSelect,
      selectedRows,
      onSelectionChange,
      sortConfig,
      onSort: sortable ? onSort : undefined,
    };
    
    // Loading state
    if (loading) {
      return (
        <div className="flex items-center justify-center py-8">
          <div className="text-neutral-500">{loadingMessage}</div>
        </div>
      );
    }
    
    // Empty state
    if (data.length === 0) {
      return (
        <div className="flex items-center justify-center py-8">
          <div className="text-neutral-500">{emptyMessage}</div>
        </div>
      );
    }
    
    const tableContent = (
      <TableContext.Provider value={contextValue}>
        <table
          ref={ref}
          className={tableClasses}
          role="table"
          aria-label={ariaLabel}
          {...props}
        >
          <TableHeader columns={columns} className={headerClassName} />
          <TableBody
            columns={columns}
            data={data}
            striped={striped}
            hoverable={hoverable}
            rowClassName={rowClassName}
            onRowClick={onRowClick}
            className={bodyClassName}
          />
        </table>
      </TableContext.Provider>
    );
    
    // Wrap in container for max height or sticky header
    if (maxHeight ?? stickyHeader) {
      return (
        <div
          className={`overflow-auto ${stickyHeader ? 'relative' : ''}`}
          style={{ maxHeight }}
        >
          {tableContent}
        </div>
      );
    }
    
    return tableContent;
  }
);

Table.displayName = 'Table';

export type TableVariantsProps = VariantProps<typeof tableVariants>;

/**
 * Enhanced concentration conversion utilities
 * Handles all scientific notation formats scientists use
 * 
 * ⚠️ DEPRECATED - Use utilities from @odysseus/shared-schemas instead
 * 
 * Phase 5 Migration:
 * - For display: Use formatConcentrationDisplay() from @odysseus/shared-schemas
 * - For parsing: Use parseConcentration() from @odysseus/shared-schemas
 * - For validation: Use Zod schema validation (concentrationPreprocessor)
 * 
 * This file kept for backward compatibility during migration.
 * Will be removed in future cleanup phase.
 */

// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { formatToScientificNotation } from './scientificNotation';

/**
 * Comprehensive concentration parser supporting all common scientific formats:
 * - 5e6, 5E6, 5.0e6, 5.0E6
 * - 5e+6, 5E+6, 5.0e+6, 5.0E+6  
 * - 5e06, 5E06, 5.0e06, 5.0E06
 * - 5000000 (regular numbers)
 * - "5e6" (string formats)
 */
export function normalizeConcentration(value: string | number | undefined): number | undefined {
  if (value === undefined || value === null || value === '') return undefined;

  // Handle zero explicitly
  if (value === 0 || value === '0') return 0;

  // If already a number, validate and return
  if (typeof value === 'number') {
    return isNaN(value) ? undefined : value;
  }

  // Handle string input
  const stringValue = String(value).trim();
  if (!stringValue) return undefined;

  // Remove commas and spaces that might be in user input
  const cleanValue = stringValue.replace(/[,\s]/g, '');

  // Handle scientific notation patterns
  const scientificPatterns = [
    /^(\d*\.?\d+)[eE]([+-]?\d+)$/, // Standard: 5e6, 5.0E+06
    /^(\d*\.?\d+)[eE]([+-]?0*\d+)$/, // With leading zeros: 5e06
  ];

  for (const pattern of scientificPatterns) {
    const match = cleanValue.match(pattern);
    if (match) {
      const mantissa = parseFloat(match[1]);
      const exponent = parseInt(match[2]);

      if (!isNaN(mantissa) && !isNaN(exponent)) {
        return mantissa * Math.pow(10, exponent);
      }
    }
  }

  // Fallback to regular number parsing
  const parsed = parseFloat(cleanValue);
  return isNaN(parsed) ? undefined : parsed;
}

/**
 * Convert concentration for storage (server expects number)
 */
export function concentrationForStorage(input: string | number | undefined): number | undefined {
  return normalizeConcentration(input);
}

/**
 * Convert concentration for display (consistent formatting)
 */
export function concentrationForDisplay(
  value: number | undefined, 
  unit?: 'c/v' | 'c/mL'
): string {
  if (value === undefined || value === null) return '';
  if (value === 0) return '0';

  const formatted = formatToScientificNotation(value);
  return unit ? `${formatted} ${unit}` : formatted;
}

/**
 * Validate concentration input
 */
export function validateConcentrationInput(value: string | number | undefined): {
  isValid: boolean;
  normalized?: number;
  error?: string;
} {
  if (value === '' || value === undefined || value === null) {
    return { isValid: true }; // Optional field
  }

  const normalized = normalizeConcentration(value);

  if (normalized === undefined) {
    return {
      isValid: false,
      error: 'Invalid concentration format. Use numbers or scientific notation (e.g., 5e6, 1.5E+07)'
    };
  }

  if (normalized < 0) {
    return {
      isValid: false,
      error: 'Concentration cannot be negative'
    };
  }

  if (normalized > Number.MAX_SAFE_INTEGER) {
    return {
      isValid: false, 
      error: 'Concentration value too large'
    };
  }

  return {
    isValid: true,
    normalized
  };
}

/**
 * Type guard for concentration values
 */
export function isValidConcentration(value: any): value is number {
  return typeof value === 'number' && !isNaN(value) && value >= 0;
}

/**
 * Batch normalize concentrations (useful for import/migration)
 */
export function normalizeConcentrationBatch(
  values: Array<{ id: string; concentration?: string | number }>
): Array<{ id: string; concentration?: number; error?: string }> {
  return values.map(({ id, concentration }) => {
    const validation = validateConcentrationInput(concentration);

    return {
      id,
      concentration: validation.normalized,
      ...(validation.error && { error: validation.error })
    };
  });
}

/**
 * Grid coordinate utilities
 */
import { EQUIPMENT_DEFAULTS } from '@odysseus/shared-schemas';

/**
 * Get all positions within a rectangular selection
 */
export function getPositionsInRectangle(
  start: GridCoordinates, 
  end: GridCoordinates, 
  gridCols: number = 9
): number[] {
  const positions: number[] = [];

  const minRow = Math.min(start.row, end.row);
  const maxRow = Math.max(start.row, end.row);
  const minCol = Math.min(start.col, end.col);
  const maxCol = Math.max(start.col, end.col);

  for (let row = minRow; row <= maxRow; row++) {
    for (let col = minCol; col <= maxCol; col++) {
      const position = row * gridCols + col + 1;
      positions.push(position);
    }
  }

  return positions;
}

export interface GridCoordinates {
  row: number;
  col: number;
}

export interface PositionInfo {
  position: number;
  row: number;
  col: number;
  x: number;
  y: number;
}

/**
 * Convert 1-based position to grid coordinates
 * @param position 1-based position (1-81 for 9x9 grid)
 * @param gridSize Number of columns (default 9)
 * @returns Grid coordinates (0-based)
 */
export function positionToCoordinates(position: number, gridSize: number = 9): GridCoordinates {
  const zeroBasedPosition = position - 1;
  return {
    row: Math.floor(zeroBasedPosition / gridSize),
    col: zeroBasedPosition % gridSize
  };
}

/**
 * Convert grid coordinates to 1-based position
 * @param row 0-based row
 * @param col 0-based column
 * @param gridSize Number of columns (default 9)
 * @returns 1-based position
 */
export function coordinatesToPosition(row: number, col: number, gridSize: number = 9): number {
  return row * gridSize + col + 1;
}

/**
 * Get pixel coordinates for grid position
 * @param position 1-based position
 * @param cellSize Size of each cell in pixels
 * @param gridSize Number of columns (default 9)
 * @returns Pixel coordinates
 */
export function getPixelCoordinates(position: number, cellSize: number, gridSize: number = 9): { x: number; y: number } {
  const coords = positionToCoordinates(position, gridSize);
  return {
    x: coords.col * cellSize,
    y: coords.row * cellSize
  };
}

/**
 * Check if position is valid for grid
 * @param position 1-based position
 * @param maxPositions Maximum positions (defaults to standard equipment configuration)
 * @returns Whether position is valid
 */
export function isValidPosition(position: number, maxPositions: number = EQUIPMENT_DEFAULTS.POSITIONS_PER_BOX): boolean {
  return position >= 1 && position <= maxPositions && Number.isInteger(position);
}

/**
 * Get all positions in a rectangular selection
 * @param startPos Start position (1-based)
 * @param endPos End position (1-based)
 * @param gridSize Number of columns (default 9)
 * @returns Array of selected positions
 */
export function getSelectionRange(startPos: number, endPos: number, gridSize: number = 9): number[] {
  const start = positionToCoordinates(startPos, gridSize);
  const end = positionToCoordinates(endPos, gridSize);

  const minRow = Math.min(start.row, end.row);
  const maxRow = Math.max(start.row, end.row);
  const minCol = Math.min(start.col, end.col);
  const maxCol = Math.max(start.col, end.col);

  const positions: number[] = [];
  for (let row = minRow; row <= maxRow; row++) {
    for (let col = minCol; col <= maxCol; col++) {
      positions.push(coordinatesToPosition(row, col, gridSize));
    }
  }

  return positions;
}

/**
 * Date formatting utilities
 *
 * DEPRECATED: This file is being phased out in favor of dateUtils.ts
 * which provides timezone-safe date-only handling. Use dateUtils.ts for new code.
 *
 * @deprecated Use dateUtils.ts instead
 */

import { normalizeDateString, formatDateForDisplay as newFormatDateForDisplay } from './dateUtils';

/**
 * Format date string for display (M/D/YYYY format)
 *
 * @deprecated Use formatDateForDisplay from dateUtils.ts instead
 * @param dateStr - YYYY-MM-DD string or Date object
 * @returns Formatted date string (M/D/YYYY)
 */
export function formatDateForDisplay(dateStr: string | Date | null | undefined): string {
  // Use new timezone-safe implementation
  return newFormatDateForDisplay(normalizeDateString(dateStr));
}

/**
 * Format date for HTML input[type="date"] (YYYY-MM-DD format)
 *
 * @deprecated Use normalizeDateString or formatDateForInput from dateUtils.ts instead
 * @param dateStr - Any date string format
 * @returns YYYY-MM-DD string
 */
export function formatDateForInput(dateStr: string | Date | null | undefined): string {
  return normalizeDateString(dateStr);
}

/**
 * Get current date as ISO string
 *
 * @deprecated Use getTodayDateString from dateUtils.ts for date-only fields
 * @returns ISO string with time component
 */
export function getCurrentDateISO(): string {
  return new Date().toISOString();
}

/**
 * Date utility functions for date-only fields (no time/timezone handling)
 *
 * ARCHITECTURAL PRINCIPLE: Treat date-only fields as strings, never Date objects
 * This eliminates timezone bugs used by Airbnb, Stripe, and modern SaaS applications.
 *
 * Storage:    YYYY-MM-DD strings in database
 * Transport:  YYYY-MM-DD strings in API
 * Comparison: Direct string comparison
 * Display:    Format using Intl.DateTimeFormat
 */

/**
 * Date string type (YYYY-MM-DD format)
 * Using branded type for extra type safety
 */
export type DateString = string & { readonly __brand: 'DateString' };

/**
 * ISO date regex for YYYY-MM-DD validation
 */
const ISO_DATE_REGEX = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Normalize any date input to YYYY-MM-DD string format
 * Handles: Date objects, ISO strings, input[type="date"] values
 *
 * @param input - Date object, ISO string, or YYYY-MM-DD string
 * @returns Normalized YYYY-MM-DD string, or empty string if invalid
 */
export function normalizeDateString(input: string | Date | null | undefined): string {
  if (!input) return '';

  try {
    // Already in YYYY-MM-DD format
    if (typeof input === 'string' && ISO_DATE_REGEX.test(input)) {
      return input;
    }

    // Convert Date object or ISO string to YYYY-MM-DD
    // Use UTC methods to avoid timezone shifting
    const date = input instanceof Date ? input : new Date(input);

    if (isNaN(date.getTime())) {
      console.warn('Invalid date input:', input);
      return '';
    }

    // Extract components using UTC to prevent timezone shifts
    const year = date.getUTCFullYear();
    const month = String(date.getUTCMonth() + 1).padStart(2, '0');
    const day = String(date.getUTCDate()).padStart(2, '0');

    return `${year}-${month}-${day}`;
  } catch (error) {
    console.error('Error normalizing date:', error);
    return '';
  }
}

/**
 * Compare two date strings for equality
 * Safe for use with dates from different sources
 *
 * @param a - First date string
 * @param b - Second date string
 * @returns true if dates are equal, false otherwise
 */
export function areDatesEqual(a: string | null | undefined, b: string | null | undefined): boolean {
  // Normalize both inputs
  const dateA = normalizeDateString(a || '');
  const dateB = normalizeDateString(b || '');

  // Empty dates are not equal to anything (including each other)
  if (!dateA || !dateB) return false;

  return dateA === dateB;
}

/**
 * Format date string for display using locale-aware formatting
 *
 * @param dateString - YYYY-MM-DD format string
 * @param locale - Locale for formatting (default: 'en-US')
 * @param options - Intl.DateTimeFormat options
 * @returns Formatted date string for display
 */
export function formatDateForDisplay(
  dateString: string | null | undefined,
  locale: string = 'en-US',
  options: Intl.DateTimeFormatOptions = { year: 'numeric', month: 'numeric', day: 'numeric' }
): string {
  const normalized = normalizeDateString(dateString || '');
  if (!normalized) return '';

  try {
    // Parse YYYY-MM-DD components directly (no Date object conversion to avoid timezone issues)
    const [year, month, day] = normalized.split('-').map(Number);

    // Create date in UTC to prevent timezone shifting
    const date = new Date(Date.UTC(year, month - 1, day));

    return new Intl.DateTimeFormat(locale, { ...options, timeZone: 'UTC' }).format(date);
  } catch (error) {
    console.error('Error formatting date for display:', error);
    return normalized; // Fallback to raw string
  }
}

/**
 * Validate YYYY-MM-DD format string
 *
 * @param value - String to validate
 * @returns true if valid YYYY-MM-DD format
 */
export function isValidDateString(value: string | null | undefined): boolean {
  if (!value || typeof value !== 'string') return false;

  if (!ISO_DATE_REGEX.test(value)) return false;

  // Check if it's a real calendar date
  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/**
 * Get today's date as YYYY-MM-DD string in local timezone
 *
 * @returns Today's date in YYYY-MM-DD format
 */
export function getTodayDateString(): string {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');

  return `${year}-${month}-${day}`;
}

/**
 * Parse input[type="date"] value to YYYY-MM-DD
 * HTML date inputs always return YYYY-MM-DD format, but this provides type safety
 *
 * @param value - Value from date input
 * @returns Normalized YYYY-MM-DD string
 */
export function parseDateInputValue(value: string): string {
  return normalizeDateString(value);
}

