/**
 * Form Utilities - Industry-Standard Partial Update Helpers
 *
 * Implements dirty field tracking for proper PATCH semantics.
 * Only sends fields that were actually modified by the user.
 *
 * Pattern: GraphQL-style precision updates
 * - Prevents accidental data loss in batch operations
 * - Clear user intent: touched = update, untouched = preserve
 * - Futureproof: works with any form structure
 */

import type { FieldValues } from 'react-hook-form';

/**
 * Extract only dirty (modified) fields from form data
 *
 * @param formData - Complete form data from form.getValues()
 * @param dirtyFields - Dirty fields tracking from form.formState.dirtyFields
 * @returns Object containing only the fields user modified
 *
 * @example
 * const formData = { name: 'John', age: 30, email: 'john@example.com' };
 * const dirtyFields = { name: true, age: true }; // email not touched
 * const result = extractDirtyFields(formData, dirtyFields);
 * // result = { name: 'John', age: 30 } // email excluded
 *
 * @example Nested objects
 * const formData = { sample: { cellType: 'Jurkat', media: { type: 'RPMI' } } };
 * const dirtyFields = { sample: { media: { type: true } } }; // Only media.type touched
 * const result = extractDirtyFields(formData, dirtyFields);
 * // result = { sample: { media: { type: 'RPMI' } } } // Only modified nested field
 */
export function extractDirtyFields<T extends FieldValues>(
  formData: T,
  dirtyFields: Partial<Record<keyof T, any>>
): Partial<T> {
  // Base case: if no dirty fields, return empty object
  if (!dirtyFields || Object.keys(dirtyFields).length === 0) {
    return {};
  }

  const result: any = {};

  for (const key in dirtyFields) {
    if (Object.prototype.hasOwnProperty.call(dirtyFields, key)) {
      const isDirty = dirtyFields[key];
      const value = formData[key];

      // If the field is marked as dirty (boolean true), include it
      if (isDirty === true) {
        result[key] = value;
      }
      // If it's an object (nested dirtyFields), recursively extract
      else if (typeof isDirty === 'object' && isDirty !== null && !Array.isArray(isDirty)) {
        // Only recurse if the value is also an object
        if (typeof value === 'object' && value !== null) {
          const nestedDirty = extractDirtyFields(value, isDirty);
          // Only include nested object if it has dirty fields
          if (Object.keys(nestedDirty).length > 0) {
            result[key] = nestedDirty;
          }
        }
      }
      // Handle arrays - if array is dirty, include entire array
      else if (Array.isArray(isDirty) && Array.isArray(value)) {
        // For arrays, if any element is dirty, include the whole array
        // This is standard behavior for form arrays
        const hasDirtyElements = isDirty.some(item =>
          typeof item === 'boolean' ? item : Object.keys(item || {}).length > 0
        );
        if (hasDirtyElements) {
          result[key] = value;
        }
      }
    }
  }

  return result;
}

/**
 * Check if any fields are dirty in a form
 * Useful for showing "unsaved changes" warnings
 */
export function hasAnyDirtyFields(dirtyFields: Record<string, any>): boolean {
  if (!dirtyFields) return false;

  for (const key in dirtyFields) {
    if (Object.prototype.hasOwnProperty.call(dirtyFields, key)) {
      const value = dirtyFields[key];
      if (value === true) return true;
      if (typeof value === 'object' && hasAnyDirtyFields(value)) return true;
    }
  }

  return false;
}

/**
 * Extract only non-empty fields from form data
 *
 * Specifically for batch edit scenarios where:
 * - Conflicting fields start as empty strings/undefined
 * - User fills in ONLY what they want to change
 * - Empty/undefined fields should be excluded from update
 *
 * Different from extractDirtyFields: works with 'create' mode forms that don't track dirty state
 *
 * @param formData - Complete form data from form.getValues()
 * @returns Object containing only non-empty fields
 *
 * @example Batch edit scenario
 * const formData = {
 *   sample: { cellType: '', media: { type: 'RPMI-1640' } },
 *   researcherId: 'researcher_123'
 * };
 * const result = extractNonEmptyFields(formData);
 * // result = { sample: { media: { type: 'RPMI-1640' } }, researcherId: 'researcher_123' }
 * // cellType excluded because empty
 */
export function extractNonEmptyFields<T extends FieldValues>(formData: T): Partial<T> {
  const result: any = {};

  for (const key in formData) {
    if (Object.prototype.hasOwnProperty.call(formData, key)) {
      const value = formData[key];

      // Skip undefined or null values
      if (value === undefined || value === null) {
        continue;
      }

      // Handle nested objects (like sample)
      if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        // Check if it's a Date object (type assertion needed for generic type parameter)
        if ((value as any) instanceof Date) {
          result[key] = value;
        } else {
          const nestedResult = extractNonEmptyFields(value);
          // Only include nested object if it has non-empty fields
          if (Object.keys(nestedResult).length > 0) {
            result[key] = nestedResult;
          }
        }
      }
      // Handle arrays - include if not empty
      else if (Array.isArray(value)) {
        if (value.length > 0) {
          result[key] = value;
        }
      }
      // Handle strings - include if not empty
      else if (typeof value === 'string') {
        if (value.trim() !== '') {
          result[key] = value;
        }
      }
      // Handle other primitives (numbers, booleans, dates) - always include
      else {
        result[key] = value;
      }
    }
  }

  return result;
}

/**
 * Grid Clipboard Utilities
 * OS clipboard integration with safe fallback patterns for laboratory tube management
 */

import type { ClipboardData } from '@shared/types/clipboard';

const CLIPBOARD_MARKER = 'OdysseusGrid/Tubes@v1';

/**
 * Serialize clipboard data for OS clipboard storage
 */
export const serializeClipboard = (clipboard: ClipboardData): string => {
  return JSON.stringify({ 
    __type: CLIPBOARD_MARKER, 
    data: clipboard 
  });
};

/**
 * Parse clipboard text and extract structured data
 */
export const tryParseClipboard = (text: string): ClipboardData | null => {
  try {
    const parsed = JSON.parse(text);
    if (parsed?.__type === CLIPBOARD_MARKER && parsed?.data) {
      return parsed.data as ClipboardData;
    }
  } catch {
    // Ignore parse errors - not our format
  }
  return null;
};

/**
 * Write clipboard data to OS clipboard (with graceful fallback)
 */
export const writeClipboardOS = async (clipboard: ClipboardData): Promise<void> => {
  const text = serializeClipboard(clipboard);

  if (navigator?.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      // Ignore OS clipboard errors - we have in-app clipboard as fallback
    }
  }
};

/**
 * Read clipboard data from OS clipboard (with graceful fallback)
 */
export const readClipboardOS = async (): Promise<ClipboardData | null> => {
  if (navigator?.clipboard?.readText) {
    try {
      const text = await navigator.clipboard.readText();
      return tryParseClipboard(text);
    } catch {
      // Ignore read errors - may require user gesture
    }
  }
  return null;
};

/**
 * Grid Position Manager
 * 
 * Centralized position management service that provides a single source of truth
 * for the current focused position in the grid. Handles validation, bounds checking,
 * and event emission for position changes from any source (mouse, keyboard, programmatic).
 */

import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';

export type PositionSource = 'mouse' | 'keyboard' | 'programmatic' | 'search';

interface GridPositionState {
  currentPosition: number;
  lastSource: PositionSource;
  gridContext: {
    tankId: string;
    rackId: string;
    boxId: string;
    gridSize: number;
  } | null;
}

interface GridPositionActions {
  setPosition: (position: number, source: PositionSource) => void;
  setGridContext: (context: GridPositionState['gridContext']) => void;
  validatePosition: (position: number) => boolean;
  resetToDefault: () => void;
}

type GridPositionStore = GridPositionState & GridPositionActions;

/**
 * Zustand store for grid position management
 * Uses subscribeWithSelector middleware for fine-grained subscriptions
 */
const useGridPositionStore = create<GridPositionStore>()(
  subscribeWithSelector((set, get) => ({
    // Initial state
    currentPosition: 1,
    lastSource: 'programmatic',
    gridContext: null,

    // Actions
    setPosition: (position: number, source: PositionSource) => {
      const state = get();

      // Validate position bounds
      if (!state.validatePosition(position)) {
        console.warn(`Invalid grid position: ${position}. Keeping current: ${state.currentPosition}`);
        return;
      }

      // Only update if position actually changed
      if (state.currentPosition !== position) {
        set({ 
          currentPosition: position, 
          lastSource: source 
        });
      }
    },

    setGridContext: (context: GridPositionState['gridContext']) => {
      const state = get();
      set({ gridContext: context });

      // Reset position to 1 when context changes (new box/rack/tank)
      if (context && (
        !state.gridContext ||
        state.gridContext.tankId !== context.tankId ||
        state.gridContext.rackId !== context.rackId ||
        state.gridContext.boxId !== context.boxId
      )) {
        set({ currentPosition: 1, lastSource: 'programmatic' });
      }
    },

    validatePosition: (position: number): boolean => {
      const { gridContext } = get();
      if (!gridContext) return true; // Allow any position if no context set

      const maxPosition = gridContext.gridSize * gridContext.gridSize;
      return position >= 1 && position <= maxPosition && Number.isInteger(position);
    },

    resetToDefault: () => {
      set({ currentPosition: 1, lastSource: 'programmatic' });
    }
  }))
);

/**
 * Grid Position Manager Service
 * Provides a clean API for position management with additional utilities
 */
export class GridPositionManager {
  private static instance: GridPositionManager;

  public static getInstance(): GridPositionManager {
    if (!GridPositionManager.instance) {
      GridPositionManager.instance = new GridPositionManager();
    }
    return GridPositionManager.instance;
  }

  /**
   * Set the current grid position
   */
  public setPosition(position: number, source: PositionSource = 'programmatic'): void {
    useGridPositionStore.getState().setPosition(position, source);
  }

  /**
   * Get the current grid position
   */
  public getCurrentPosition(): number {
    return useGridPositionStore.getState().currentPosition;
  }

  /**
   * Set the grid context (tank/rack/box/size)
   */
  public setGridContext(tankId: string, rackId: string, boxId: string, gridSize: number): void {
    useGridPositionStore.getState().setGridContext({
      tankId,
      rackId, 
      boxId,
      gridSize
    });
  }

  /**
   * Subscribe to position changes
   */
  public subscribe(callback: (position: number, source: PositionSource) => void): () => void {
    return useGridPositionStore.subscribe(
      (state) => ({ position: state.currentPosition, source: state.lastSource }),
      ({ position, source }) => callback(position, source),
      { equalityFn: (a, b) => a.position === b.position }
    );
  }

  /**
   * Validate if a position is within bounds
   */
  public isValidPosition(position: number): boolean {
    return useGridPositionStore.getState().validatePosition(position);
  }

  /**
   * Reset position to default (1)
   */
  public resetPosition(): void {
    useGridPositionStore.getState().resetToDefault();
  }

  /**
   * Get current grid context
   */
  public getGridContext() {
    return useGridPositionStore.getState().gridContext;
  }
}

