// LAB color space utilities for perceptually uniform color generation
// This ensures equal visual distances between colors for optimal distinction

export interface LABColor {
  L: number; // Lightness 0-100
  A: number; // Green-Red axis -128 to 127
  B: number; // Blue-Yellow axis -128 to 127
}

export interface RGBColor {
  r: number; // 0-255
  g: number; // 0-255
  b: number; // 0-255
}

export interface HSLColor {
  h: number; // 0-360
  s: number; // 0-100
  l: number; // 0-100
}

// Convert RGB to XYZ color space (intermediate step for LAB)
function rgbToXYZ(rgb: RGBColor): { x: number; y: number; z: number } {
  let { r, g, b } = rgb;

  // Normalize RGB values
  r /= 255;
  g /= 255;
  b /= 255;

  // Apply gamma correction
  r = r > 0.04045 ? Math.pow((r + 0.055) / 1.055, 2.4) : r / 12.92;
  g = g > 0.04045 ? Math.pow((g + 0.055) / 1.055, 2.4) : g / 12.92;
  b = b > 0.04045 ? Math.pow((b + 0.055) / 1.055, 2.4) : b / 12.92;

  // Convert to XYZ using sRGB matrix
  const x = r * 0.4124564 + g * 0.3575761 + b * 0.1804375;
  const y = r * 0.2126729 + g * 0.7151522 + b * 0.0721750;
  const z = r * 0.0193339 + g * 0.1191920 + b * 0.9503041;

  return { x: x * 100, y: y * 100, z: z * 100 };
}

// Convert XYZ to LAB color space
function xyzToLAB(xyz: { x: number; y: number; z: number }): LABColor {
  // D65 illuminant reference values
  const xn = 95.047;
  const yn = 100.000;
  const zn = 108.883;

  let { x, y, z } = xyz;
  x /= xn;
  y /= yn;
  z /= zn;

  // Apply LAB transformation
  const fx = x > 0.008856 ? Math.pow(x, 1/3) : (7.787 * x + 16/116);
  const fy = y > 0.008856 ? Math.pow(y, 1/3) : (7.787 * y + 16/116);
  const fz = z > 0.008856 ? Math.pow(z, 1/3) : (7.787 * z + 16/116);

  const L = 116 * fy - 16;
  const A = 500 * (fx - fy);
  const B = 200 * (fy - fz);

  return { L, A, B };
}

// Convert LAB to XYZ color space
function labToXYZ(lab: LABColor): { x: number; y: number; z: number } {
  const { L, A, B } = lab;

  // D65 illuminant reference values
  const xn = 95.047;
  const yn = 100.000;
  const zn = 108.883;

  const fy = (L + 16) / 116;
  const fx = A / 500 + fy;
  const fz = fy - B / 200;

  const x = fx > 0.206897 ? Math.pow(fx, 3) : (fx - 16/116) / 7.787;
  const y = fy > 0.206897 ? Math.pow(fy, 3) : (fy - 16/116) / 7.787;
  const z = fz > 0.206897 ? Math.pow(fz, 3) : (fz - 16/116) / 7.787;

  return {
    x: x * xn,
    y: y * yn,
    z: z * zn
  };
}

// Convert XYZ to RGB color space
function xyzToRGB(xyz: { x: number; y: number; z: number }): RGBColor {
  let { x, y, z } = xyz;

  // Normalize XYZ values
  x /= 100;
  y /= 100;
  z /= 100;

  // Convert to RGB using sRGB matrix (inverse)
  let r = x *  3.2404542 + y * -1.5371385 + z * -0.4985314;
  let g = x * -0.9692660 + y *  1.8760108 + z *  0.0415560;
  let b = x *  0.0556434 + y * -0.2040259 + z *  1.0572252;

  // Apply inverse gamma correction
  r = r > 0.0031308 ? 1.055 * Math.pow(r, 1/2.4) - 0.055 : 12.92 * r;
  g = g > 0.0031308 ? 1.055 * Math.pow(g, 1/2.4) - 0.055 : 12.92 * g;
  b = b > 0.0031308 ? 1.055 * Math.pow(b, 1/2.4) - 0.055 : 12.92 * b;

  // Clamp to valid RGB range
  r = Math.max(0, Math.min(1, r));
  g = Math.max(0, Math.min(1, g));
  b = Math.max(0, Math.min(1, b));

  return {
    r: Math.round(r * 255),
    g: Math.round(g * 255),
    b: Math.round(b * 255)
  };
}

// Convert RGB to LAB (full pipeline)
export function rgbToLAB(rgb: RGBColor): LABColor {
  const xyz = rgbToXYZ(rgb);
  return xyzToLAB(xyz);
}

// Convert LAB to RGB (full pipeline)
export function labToRGB(lab: LABColor): RGBColor {
  const xyz = labToXYZ(lab);
  return xyzToRGB(xyz);
}

// Calculate Delta E (CIE76) - perceptual color difference
export function calculateDeltaE(color1: LABColor, color2: LABColor): number {
  const deltaL = color1.L - color2.L;
  const deltaA = color1.A - color2.A;
  const deltaB = color1.B - color2.B;

  return Math.sqrt(deltaL * deltaL + deltaA * deltaA + deltaB * deltaB);
}

// Convert RGB to CSS hex string
export function rgbToHex(rgb: RGBColor): string {
  const { r, g, b } = rgb;
  return `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`;
}

// Convert hex to RGB
export function hexToRGB(hex: string): RGBColor {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  if (!result) throw new Error('Invalid hex color');

  return {
    r: parseInt(result[1], 16),
    g: parseInt(result[2], 16),
    b: parseInt(result[3], 16)
  };
}

// Seeded random number generator for deterministic color generation
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state * 1664525 + 1013904223) % 0x100000000;
    return state / 0x100000000;
  };
}

// Generate deterministic perceptually uniform color palette
export function generateOptimalColorPalette(options: {
  count: number;
  minDistance: number;
  lightRange: [number, number];
  chromaRange: [number, number];
  attempts?: number;
  seed?: number;
}): string[] {
  const { count, minDistance, lightRange, chromaRange, attempts = 1000, seed = 42 } = options;
  const colors: LABColor[] = [];
  const random = seededRandom(seed);

  // Generate colors with maximum perceptual distance
  for (let i = 0; i < count; i++) {
    let bestColor: LABColor | null = null;
    let bestMinDistance = 0;

    for (let attempt = 0; attempt < attempts; attempt++) {
      // Generate deterministic random color in LAB space
      const L = lightRange[0] + random() * (lightRange[1] - lightRange[0]);
      const angle = random() * 2 * Math.PI;
      const chroma = chromaRange[0] + random() * (chromaRange[1] - chromaRange[0]);

      const A = Math.cos(angle) * chroma;
      const B = Math.sin(angle) * chroma;

      const candidate: LABColor = { L, A, B };

      // Check if this color can be represented in RGB
      const rgb = labToRGB(candidate);
      if (rgb.r < 0 || rgb.r > 255 || rgb.g < 0 || rgb.g > 255 || rgb.b < 0 || rgb.b > 255) {
        continue;
      }

      // Calculate minimum distance to existing colors
      let minDistanceToExisting = Infinity;
      for (const existing of colors) {
        const distance = calculateDeltaE(candidate, existing);
        minDistanceToExisting = Math.min(minDistanceToExisting, distance);
      }

      // Keep the candidate with the maximum minimum distance
      if (minDistanceToExisting > bestMinDistance) {
        bestMinDistance = minDistanceToExisting;
        bestColor = candidate;
      }

      // If we found a good enough color, use it
      if (bestMinDistance >= minDistance) {
        break;
      }
    }

    if (bestColor) {
      colors.push(bestColor);
    }
  }

  // Convert to hex strings
  return colors.map(lab => rgbToHex(labToRGB(lab)));
}

// Calculate luminance for contrast ratio
export function getLuminance(rgb: RGBColor): number {
  const { r, g, b } = rgb;

  const sR = r / 255;
  const sG = g / 255;
  const sB = b / 255;

  const rL = sR <= 0.03928 ? sR / 12.92 : Math.pow((sR + 0.055) / 1.055, 2.4);
  const gL = sG <= 0.03928 ? sG / 12.92 : Math.pow((sG + 0.055) / 1.055, 2.4);
  const bL = sB <= 0.03928 ? sB / 12.92 : Math.pow((sB + 0.055) / 1.055, 2.4);

  return 0.2126 * rL + 0.7152 * gL + 0.0722 * bL;
}

// Calculate contrast ratio between two colors
export function getContrastRatio(color1: RGBColor, color2: RGBColor): number {
  const lum1 = getLuminance(color1);
  const lum2 = getLuminance(color2);

  const lighter = Math.max(lum1, lum2);
  const darker = Math.min(lum1, lum2);

  return (lighter + 0.05) / (darker + 0.05);
}

// Convert RGB string (hex or rgb()) to LAB color space
export function rgbStringToLAB(colorString: string): LABColor {
  const rgb = hexToRGB(colorString);
  return rgbToLAB(rgb);
}

// Convert LAB color to RGB hex string
export function labToRGBString(lab: LABColor): string {
  const rgb = labToRGB(lab);
  return rgbToHex(rgb);
}

// Find optimal text color for maximum contrast
export function getOptimalTextColor(backgroundColor: string): string {
  const bgRGB = hexToRGB(backgroundColor);
  const whiteRGB: RGBColor = { r: 255, g: 255, b: 255 };
  const blackRGB: RGBColor = { r: 0, g: 0, b: 0 };

  const whiteContrast = getContrastRatio(bgRGB, whiteRGB);
  const blackContrast = getContrastRatio(bgRGB, blackRGB);

  return whiteContrast > blackContrast ? '#ffffff' : '#000000';
}

/**
 * Preload Helpers for Lazy-Loaded Components
 *
 * @module PreloadHelpers
 * @category Utilities - Lazy Loading
 * @architecture Code Splitting / Performance Optimization
 *
 * ARCHITECTURAL PURPOSE:
 * =====================
 * Provides reusable utilities for smart preloading of lazy-loaded components.
 * Implements industry-standard patterns for anticipatory loading to reduce
 * perceived latency and improve user experience.
 *
 * DESIGN PHILOSOPHY:
 * - DRY (Don't Repeat Yourself): Extract common preload patterns
 * - Type-safe: Full TypeScript support with generics
 * - Performance-focused: Non-blocking, deduplication-aware
 * - User intent-driven: Preload based on behavioral signals
 * - Framework-agnostic: Works with any React lazy component
 *
 * USAGE PATTERNS:
 * ```typescript
 * // Pattern 1: Create preload hook for any lazy component
 * const useLazyModal = createPreloadHook(() => import('./MyModal'));
 * const { preload, triggerProps, isPreloaded } = useLazyModal();
 *
 * // Pattern 2: Smart selection-based preloading
 * const { preload } = useLazyModal();
 * usePreloadOnSelection(selectedItems.length, 2, preload);
 *
 * // Pattern 3: Attach to trigger button
 * <button {...triggerProps} onClick={openModal}>Open Modal</button>
 * ```
 */

import { useCallback, useState, useMemo, useEffect } from 'react';

/**
 * Create a preload hook for any lazy-loaded component
 *
 * CHARACTERISTICS:
 * - Generic: Works with any component type
 * - Idempotent: Safe to call multiple times (deduplication handled by browser)
 * - Non-blocking: Preload happens in background
 * - Error-tolerant: Failures don't throw (component lazy loads normally instead)
 * - State-tracking: Tracks whether preload succeeded
 *
 * TYPE SAFETY:
 * - T: The props type of the lazy component
 * - Uses generic to ensure type safety when using the hook
 *
 * IMPLEMENTATION NOTES:
 * - Browser automatically deduplicates identical dynamic imports
 * - HTTP/2 multiplexing ensures no blocking of critical resources
 * - Failed preloads gracefully fall back to normal lazy loading
 * - React caches successful lazy loads automatically
 *
 * @param importFn - Dynamic import function for the component
 * @returns Hook that provides preload utilities
 *
 * @example
 * ```typescript
 * // Create a reusable hook for your lazy component
 * const useLazyTubeEditor = createPreloadHook(
 *   () => import('./TubeEditorModal')
 * );
 *
 * // Use in component
 * function Dashboard() {
 *   const { preload, triggerProps, isPreloaded } = useLazyTubeEditor();
 *
 *   return <button {...triggerProps}>Add Tube</button>;
 * }
 * ```
 */
export function createPreloadHook<T = any>(
  importFn: () => Promise<T>
) {
  return function usePreload() {
    const [isPreloaded, setIsPreloaded] = useState(false);

    /**
     * Manually trigger preload
     *
     * WHEN TO CALL:
     * - User hovers over trigger button
     * - User focuses trigger button (accessibility)
     * - Selection count meets threshold
     * - Navigation to section containing component
     * - User role indicates likely usage (e.g., admin preloading admin modals)
     *
     * SAFETY:
     * - Non-throwing: Errors are logged, not thrown
     * - Idempotent: Multiple calls are safe
     * - Non-blocking: Returns immediately
     *
     * @returns Promise that resolves when chunk is loaded (optional to await)
     */
    const preload = useCallback(async () => {
      if (isPreloaded) return;

      try {
        await importFn();
        setIsPreloaded(true);
      } catch (error) {
        console.warn('[PreloadHelpers] Preload failed, will lazy load on render:', error);
        // Don't throw - component will lazy load normally on render
        // This handles transient network errors gracefully
      }
    }, [isPreloaded]);

    /**
     * Props to attach to trigger element for anticipatory loading
     *
     * USAGE:
     * Spread these props onto buttons or links that open the lazy component.
     * They will preload the chunk when user shows intent (hover/focus).
     *
     * EVENTS:
     * - onMouseEnter: Desktop users hovering (primary UX improvement)
     * - onFocus: Keyboard users tabbing (accessibility + UX)
     *
     * BENEFITS:
     * - Reduces perceived latency by 50-100ms
     * - Chunk downloads while user decides to click
     * - No impact on initial bundle size
     *
     * @returns Props object to spread onto trigger element
     *
     * @example
     * ```typescript
     * const { triggerProps } = usePreload();
     * <button {...triggerProps} onClick={openModal}>
     *   Add Tube
     * </button>
     * ```
     */
    const triggerProps = useMemo(() => ({
      onMouseEnter: preload,
      onFocus: preload,
    }), [preload]);

    return {
      /** Manually trigger preload (for programmatic use) */
      preload,

      /** Props to attach to trigger button for anticipatory loading */
      triggerProps,

      /** Whether component chunk has been successfully preloaded */
      isPreloaded,
    };
  };
}

/**
 * Hook for smart preloading based on selection count
 *
 * HEURISTIC:
 * - Preloads component when selection count meets or exceeds threshold
 * - Common pattern: Batch operations require higher selection counts
 * - Avoids unnecessary preloading for casual browsing/single selections
 *
 * USE CASES:
 * - Grid selection: Preload batch editor when 2+ items selected
 * - Table selection: Preload bulk actions when multiple rows selected
 * - File upload: Preload processor when multiple files added
 *
 * PERFORMANCE:
 * - Only triggers preload when threshold crossed (not on every selection change)
 * - Idempotent: Safe to call on every selection change
 *
 * @param selectedCount - Current number of selected items
 * @param threshold - Minimum selection count to trigger preload (default: 2)
 * @param preloadFn - Preload function to call when threshold met
 *
 * @example
 * ```typescript
 * const { preload } = useLazyBatchEditor();
 *
 * // In component
 * const selectedIds = useSelectedTubeIds();
 * usePreloadOnSelection(selectedIds.length, 2, preload);
 * ```
 */
export function usePreloadOnSelection(
  selectedCount: number,
  threshold: number = 2,
  preloadFn: () => void | Promise<void>
) {
  useEffect(() => {
    if (selectedCount >= threshold) {
      void preloadFn();
    }
  }, [selectedCount, threshold, preloadFn]);
}

/**
 * Create trigger props for anticipatory preloading
 *
 * USAGE:
 * Functional alternative to hook-based triggerProps for static contexts.
 * Useful when you don't need the full preload hook.
 *
 * EVENTS:
 * - onMouseEnter: Preload on hover (desktop users)
 * - onFocus: Preload on focus (keyboard users)
 *
 * @param preloadFn - Preload function to call on interaction
 * @returns Props object to spread onto trigger element
 *
 * @example
 * ```typescript
 * const props = createTriggerProps(() => import('./MyModal'));
 * <button {...props} onClick={openModal}>Open</button>
 * ```
 */
export function createTriggerProps(preloadFn: () => void | Promise<void>) {
  return {
    onMouseEnter: preloadFn,
    onFocus: preloadFn,
  };
}

/**
 * Hook for preloading on route/tab navigation
 *
 * USAGE:
 * Preload components when user navigates to a route or tab where
 * the component is likely to be used.
 *
 * PATTERN:
 * - Call in route/tab component
 * - Preloads happen in background during navigation transition
 * - By the time user interacts, component is ready
 *
 * @param preloadFn - Preload function to call on mount
 * @param condition - Optional condition to gate preloading (default: true)
 *
 * @example
 * ```typescript
 * function AdminDashboard() {
 *   const { preload } = useLazyAdminSettings();
 *
 *   // Preload admin settings modal when admin dashboard loads
 *   usePreloadOnMount(preload, userRole === 'admin');
 *
 *   return <div>...</div>;
 * }
 * ```
 */
export function usePreloadOnMount(
  preloadFn: () => void | Promise<void>,
  condition: boolean = true
) {
  useEffect(() => {
    if (condition) {
      void preloadFn();
    }
  }, [preloadFn, condition]);
}

/**
 * Hook for preloading after idle timeout
 *
 * USAGE:
 * Preload low-priority components after user has been idle for a period.
 * Uses requestIdleCallback for optimal performance.
 *
 * PATTERN:
 * - Waits for specified delay
 * - Uses requestIdleCallback if available (runs during browser idle time)
 * - Fallback to setTimeout for older browsers
 * - Doesn't preload if component already mounted
 *
 * @param preloadFn - Preload function to call after idle
 * @param delayMs - Delay in milliseconds before preloading (default: 2000)
 *
 * @example
 * ```typescript
 * function App() {
 *   const { preload: preloadSettings } = useLazySettings();
 *
 *   // Preload settings modal after 2 seconds of idle time
 *   usePreloadOnIdle(preloadSettings, 2000);
 * }
 * ```
 */
export function usePreloadOnIdle(
  preloadFn: () => void | Promise<void>,
  delayMs: number = 2000
) {
  useEffect(() => {
    const timer = setTimeout(() => {
      if ('requestIdleCallback' in window) {
        requestIdleCallback(() => void preloadFn());
      } else {
        void preloadFn();
      }
    }, delayMs);

    return () => clearTimeout(timer);
  }, [preloadFn, delayMs]);
}

/**
 * Batch preload multiple components
 *
 * USAGE:
 * Preload multiple related components at once (e.g., when navigating to a section).
 * Uses Promise.allSettled to ensure one failure doesn't block others.
 *
 * PATTERN:
 * - All preloads happen in parallel
 * - Failures are logged but don't throw
 * - Returns array of results (fulfilled/rejected)
 *
 * @param importFns - Array of import functions to preload
 * @returns Promise that resolves when all preloads complete (success or failure)
 *
 * @example
 * ```typescript
 * // Preload all admin modals when entering admin section
 * await batchPreload([
 *   () => import('./AdminSettings'),
 *   () => import('./UserManagement'),
 *   () => import('./SystemLogs'),
 * ]);
 * ```
 */
export async function batchPreload(importFns: Array<() => Promise<any>>): Promise<PromiseSettledResult<any>[]> {
  const results = await Promise.allSettled(importFns.map(fn => fn()));

  // Log failures in development
  if (process.env['NODE_ENV'] === 'development') {
    results.forEach((result, index) => {
      if (result.status === 'rejected') {
        console.warn(`[PreloadHelpers] Batch preload failed for import #${index}:`, result.reason);
      }
    });
  }

  return results;
}

/**
 * PreloadHelpers namespace for organized exports
 *
 * USAGE:
 * ```typescript
 * import { PreloadHelpers } from '@shared/utils/lazy/PreloadHelpers';
 *
 * const useLazyModal = PreloadHelpers.createHook(() => import('./Modal'));
 * PreloadHelpers.useOnSelection(count, 2, preload);
 * ```
 */
export const PreloadHelpers = {
  createHook: createPreloadHook,
  createTriggerProps,
  useOnSelection: usePreloadOnSelection,
  useOnMount: usePreloadOnMount,
  useOnIdle: usePreloadOnIdle,
  batchPreload,
} as const;

/**
 * Lazy Component Utilities
 *
 * Utilities for managing lazy component loading, preloading, and performance monitoring
 */

import type { ComponentType } from 'react';
import { lazy } from 'react';

import { env } from '@shared/config';

// Lazy loading configuration
export interface LazyLoadConfig {
  // Preloading
  preloadDelay?: number; // Delay before auto-preloading (ms)
  preloadOnHover?: boolean; // Preload on hover
  preloadOnFocus?: boolean; // Preload on focus
  preloadOnViewport?: boolean; // Preload when component enters viewport
  
  // Performance
  timeout?: number; // Loading timeout (ms)
  retryAttempts?: number; // Number of retry attempts
  
  // Caching
  cacheComponents?: boolean; // Cache loaded components
  
  // Monitoring
  enableMetrics?: boolean; // Enable performance metrics
}

// Default configuration
const defaultConfig: LazyLoadConfig = {
  preloadDelay: 0,
  preloadOnHover: true,
  preloadOnFocus: true,
  preloadOnViewport: false,
  timeout: 10000,
  retryAttempts: 3,
  cacheComponents: true,
  enableMetrics: env.isDev(),
};

// Component cache for lazy loaded components
const componentCache = new Map<string, ComponentType<any>>();

// Performance metrics
interface LazyLoadMetrics {
  componentName: string;
  loadTime: number;
  attempts: number;
  success: boolean;
  timestamp: number;
  error?: string;
}

const metricsCollection: LazyLoadMetrics[] = [];

// Enhanced lazy loading function
export const createLazyComponent = <T extends ComponentType<any>>(
  importFn: () => Promise<{ default: T } | T>,
  componentName: string,
  config: LazyLoadConfig = {}
) => {
  const finalConfig = { ...defaultConfig, ...config };
  const cacheKey = componentName;
  
  // Check cache first
  if (finalConfig.cacheComponents && componentCache.has(cacheKey)) {
    return componentCache.get(cacheKey)!;
  }
  
  // Create lazy component with enhanced error handling and retries
  const LazyComponent = lazy(async () => {
    const startTime = performance.now();
    let lastError: Error | null = null;
    
    for (let attempt = 1; attempt <= (finalConfig.retryAttempts || 3); attempt++) {
      try {
        // Add timeout handling
        const loadPromise = importFn();
        const timeoutPromise = new Promise<never>((_, reject) => {
          setTimeout(() => {
            reject(new Error(`Lazy loading timeout after ${finalConfig.timeout}ms`));
          }, finalConfig.timeout);
        });
        
        const result = await Promise.race([loadPromise, timeoutPromise]);
        const endTime = performance.now();
        const loadTime = endTime - startTime;
        
        // Handle different module formats
        const component = 'default' in result ? result.default : result;
        
        // Cache the component
        if (finalConfig.cacheComponents) {
          componentCache.set(cacheKey, component);
        }
        
        // Record metrics
        if (finalConfig.enableMetrics) {
          metricsCollection.push({
            componentName,
            loadTime,
            attempts: attempt,
            success: true,
            timestamp: Date.now(),
          });
          
          console.log(`Lazy loaded ${componentName} in ${loadTime.toFixed(2)}ms (attempt ${attempt})`);
        }
        
        return { default: component };
      } catch (error) {
        lastError = error as Error;
        
        if (finalConfig.enableMetrics) {
          console.warn(`⚠️ Failed to load ${componentName} (attempt ${attempt}/${finalConfig.retryAttempts}):`, error);
        }
        
        // Wait before retry (exponential backoff)
        if (attempt < (finalConfig.retryAttempts || 3)) {
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt - 1) * 1000));
        }
      }
    }
    
    // All attempts failed
    const endTime = performance.now();
    const totalTime = endTime - startTime;
    
    if (finalConfig.enableMetrics) {
      metricsCollection.push({
        componentName,
        loadTime: totalTime,
        attempts: finalConfig.retryAttempts || 3,
        success: false,
        timestamp: Date.now(),
        error: lastError?.message,
      });
      
      console.error(`❌ Failed to load ${componentName} after ${finalConfig.retryAttempts} attempts in ${totalTime.toFixed(2)}ms`);
    }
    
    throw lastError || new Error(`Failed to load ${componentName} after ${finalConfig.retryAttempts} attempts`);
  });
  
  // Set displayName for debugging - type assertion for LazyExoticComponent
  (LazyComponent as any).displayName = `Lazy(${componentName})`;
  
  return LazyComponent;
};

// Preloading utilities
export class PreloadManager {
  private static preloadPromises = new Map<string, Promise<void>>();
  private static preloadedComponents = new Set<string>();
  
  static async preload(
    importFn: () => Promise<any>,
    componentName: string,
    priority: 'high' | 'medium' | 'low' = 'medium'
  ): Promise<void> {
    if (this.preloadedComponents.has(componentName)) {
      return;
    }
    
    if (this.preloadPromises.has(componentName)) {
      return this.preloadPromises.get(componentName);
    }
    
    const preloadPromise = this.executePreload(importFn, componentName, priority);
    this.preloadPromises.set(componentName, preloadPromise);
    
    return preloadPromise;
  }
  
  private static async executePreload(
    importFn: () => Promise<any>,
    componentName: string,
    priority: 'high' | 'medium' | 'low'
  ): Promise<void> {
    try {
      const startTime = performance.now();
      
      // Delay for lower priority preloads to not block critical resources
      const delay = priority === 'high' ? 0 : priority === 'medium' ? 100 : 500;
      if (delay > 0) {
        await new Promise(resolve => setTimeout(resolve, delay));
      }
      
      await importFn();
      
      const endTime = performance.now();
      const loadTime = endTime - startTime;
      
      this.preloadedComponents.add(componentName);
      this.preloadPromises.delete(componentName);
      
      if (env.isDev()) {
        console.log(`🚀 Preloaded ${componentName} in ${loadTime.toFixed(2)}ms (priority: ${priority})`);
      }
    } catch (error) {
      this.preloadPromises.delete(componentName);
      
      if (env.isDev()) {
        console.warn(`Failed to preload ${componentName}:`, error);
      }
    }
  }
  
  // Batch preload multiple components
  static async batchPreload(
    components: Array<{
      importFn: () => Promise<any>;
      name: string;
      priority?: 'high' | 'medium' | 'low';
    }>
  ): Promise<void> {
    const preloadPromises = components.map(({ importFn, name, priority }) =>
      this.preload(importFn, name, priority)
    );
    
    try {
      await Promise.allSettled(preloadPromises);
    } catch (error) {
      if (env.isDev()) {
        console.warn('Some components failed to preload during batch operation:', error);
      }
    }
  }
  
  // Preload components based on user interaction patterns
  static preloadOnInteraction(
    element: HTMLElement,
    importFn: () => Promise<any>,
    componentName: string,
    options: {
      onHover?: boolean;
      onFocus?: boolean;
      onViewport?: boolean;
      delay?: number;
    } = {}
  ): () => void {
    const { onHover = true, onFocus = true, onViewport = false, delay = 0 } = options;
    const listeners: Array<() => void> = [];
    
    const preloadWithDelay = () => {
      setTimeout(() => {
        void this.preload(importFn, componentName, 'medium');
      }, delay);
    };
    
    if (onHover) {
      const hoverHandler = () => preloadWithDelay();
      element.addEventListener('mouseenter', hoverHandler);
      listeners.push(() => element.removeEventListener('mouseenter', hoverHandler));
    }
    
    if (onFocus) {
      const focusHandler = () => preloadWithDelay();
      element.addEventListener('focus', focusHandler);
      listeners.push(() => element.removeEventListener('focus', focusHandler));
    }
    
    if (onViewport && 'IntersectionObserver' in window) {
      const observer = new IntersectionObserver(
        (entries) => {
          if (entries[0].isIntersecting) {
            preloadWithDelay();
            observer.disconnect();
          }
        },
        { threshold: 0.1 }
      );
      
      observer.observe(element);
      listeners.push(() => observer.disconnect());
    }
    
    // Return cleanup function
    return () => {
      listeners.forEach(cleanup => cleanup());
    };
  }
  
  // Get preload status
  static getPreloadStatus(): {
    preloaded: string[];
    loading: string[];
    total: number;
  } {
    return {
      preloaded: Array.from(this.preloadedComponents),
      loading: Array.from(this.preloadPromises.keys()),
      total: this.preloadedComponents.size + this.preloadPromises.size,
    };
  }
}

// Performance metrics utilities
export const LazyLoadMetrics = {
  // Get all metrics
  getMetrics(): LazyLoadMetrics[] {
    return [...metricsCollection];
  },
  
  // Get metrics for a specific component
  getComponentMetrics(componentName: string): LazyLoadMetrics[] {
    return metricsCollection.filter(m => m.componentName === componentName);
  },
  
  // Get performance summary
  getSummary() {
    const successful = metricsCollection.filter(m => m.success);
    const failed = metricsCollection.filter(m => !m.success);
    
    const avgLoadTime = successful.length > 0
      ? successful.reduce((sum, m) => sum + m.loadTime, 0) / successful.length
      : 0;
    
    return {
      total: metricsCollection.length,
      successful: successful.length,
      failed: failed.length,
      successRate: metricsCollection.length > 0 
        ? (successful.length / metricsCollection.length) * 100 
        : 0,
      averageLoadTime: avgLoadTime,
      slowestComponent: successful.reduce((slowest, current) => 
        current.loadTime > slowest.loadTime ? current : slowest, 
        successful[0] || { componentName: 'none', loadTime: 0 }
      ),
    };
  },
  
  // Clear metrics
  clear() {
    metricsCollection.length = 0;
  },
  
  // Export metrics to JSON
  export() {
    return JSON.stringify({
      metrics: metricsCollection,
      summary: this.getSummary(),
      timestamp: Date.now(),
    }, null, 2);
  },
};

// Development utilities
if (env.isDev()) {
  (window as any).lazyLoadUtils = {
    preloadManager: PreloadManager,
    metrics: LazyLoadMetrics,
    componentCache,
  };
}

